-- GOI_Pt: 31102 verses. Generated by sqlite/build_buffet.py
INSERT INTO verses (goi, conical, edition_id, version, language_subtag, book, chapter, verse, testament, verse_text) VALUES
(1, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 1, 'OT', 'No princípio, Deus criou os céus e a terra.'),
(2, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 2, 'OT', 'A terra, porém, era sem forma e vazia; e havia trevas sobre a face do abismo; e o Espírito de Deus pairava sobre a face das águas.'),
(3, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 3, 'OT', 'E disse Deus: Haja luz; e houve luz.'),
(4, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 4, 'OT', 'E viu Deus que a luz era boa; e Deus separou a luz das trevas.'),
(5, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 5, 'OT', 'E Deus chamou à luz "Dia", e às trevas chamou "Noite". E houve tarde e houve manhã: o primeiro dia.'),
(6, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 6, 'OT', 'E disse Deus: Haja um firmamento no meio das águas, e haja separação entre águas e águas.'),
(7, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 7, 'OT', 'E fez Deus o firmamento, e separou as águas que estavam debaixo do firmamento das águas que estavam acima do firmamento; e assim foi.'),
(8, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 8, 'OT', 'E chamou Deus à expansão Céus, e houve tarde e houve manhã, dia segundo.'),
(9, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 9, 'OT', 'Ajuntem-se as águas debaixo dos céus num só lugar, e apareça a porção seca. E assim foi.'),
(10, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 10, 'OT', 'E chamou Deus à porção seca Terra, e ao ajuntamento das águas chamou Mares; e viu Deus que era bom.'),
(11, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 11, 'OT', 'E disse Deus: Produza a terra relva, erva que dê semente, árvore frutífera que dê fruto segundo a sua espécie, cuja semente está nela sobre a terra; e assim foi.'),
(12, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 12, 'OT', 'E a terra produziu relva, erva que dá semente conforme a sua espécie, e árvore que dá fruto, cuja semente está nela, conforme a sua espécie; e viu Deus que era bom.'),
(13, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 13, 'OT', 'E houve tarde, e houve manhã, o terceiro dia.'),
(14, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 14, 'OT', 'E disse Deus: Haja luminares na expansão dos céus, para separar o dia da noite; e sirvam de sinais e de estações, e de dias e anos.'),
(15, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 15, 'OT', 'E sejam para luminares na expansão dos céus, para iluminar a terra; e assim foi.'),
(16, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 16, 'OT', 'E Deus fez os dois grandes luminares: o luminar maior para governar o dia, e o luminar menor para governar a noite; e as estrelas.'),
(17, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 17, 'OT', 'E Deus os colocou na expansão dos céus para iluminar a terra,'),
(18, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 18, 'OT', 'e para governar o dia e a noite, e para separar a luz das trevas. E Deus viu que isso era bom.'),
(19, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 19, 'OT', 'E houve tarde, e houve manhã, o quarto dia.'),
(20, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 20, 'OT', 'Disse Deus: "Pululem as águas de enxames de seres vivos, e voem aves sobre a terra, sob o firmamento do céu."'),
(21, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 21, 'OT', 'E criou Deus os grandes monstros marinhos, e toda criatura vivente que se move, das quais as águas fervilharam segundo as suas espécies; e toda ave de asas segundo a sua espécie. E viu Deus que era bom.'),
(22, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 22, 'OT', 'E Deus os abençoou, dizendo: "Sede fecundos e multiplicai-vos, e enchei as águas dos mares; e as aves se multipliquem sobre a terra."'),
(23, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 23, 'OT', 'E houve tarde, e houve manhã, o quinto dia.'),
(24, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 24, 'OT', 'E disse Deus: Produza a terra seres viventes conforme a sua espécie: animais domésticos, répteis e animais selvagens da terra conforme a sua espécie. E assim foi.'),
(25, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 25, 'OT', 'E fez Deus os animais selvagens da terra conforme a sua espécie, e o gado conforme a sua espécie, e todo o réptil da terra conforme a sua espécie; e viu Deus que era bom.'),
(26, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 26, 'OT', 'E disse Deus: Façamos o homem à nossa imagem, conforme a nossa semelhança; e que eles dominem sobre os peixes do mar, sobre as aves dos céus, sobre os animais domésticos, sobre toda a terra e sobre todo réptil que se move sobre a terra.'),
(27, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 27, 'OT', 'E criou Deus o homem à sua imagem; à imagem de Deus o criou; macho e fêmea os criou.'),
(28, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 28, 'OT', 'E Deus os abençoou e lhes disse: "Sede fecundos, multiplicai-vos, enchei a terra e sujeitai-a; dominai sobre os peixes do mar, sobre as aves dos céus e sobre todo ser vivo que se move sobre a terra."'),
(29, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 29, 'OT', 'E disse Deus: Eis que vos tenho dado toda a erva que dá semente, que está sobre a face de toda a terra, e toda a árvore em que há fruto de árvore que dá semente; isso vos será para alimento.'),
(30, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 30, 'OT', 'E a todo animal da terra, e a toda ave dos céus, e a todo réptil que se move sobre a terra, em que há alma vivente, dei toda a erva verde por alimento. E assim foi.'),
(31, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 1, 31, 'OT', 'E viu Deus tudo o que havia feito, e eis que era muito bom. E houve tarde e houve manhã, o sexto dia.'),
(32, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 1, 'OT', 'Assim foram concluídos os céus e a terra e todo o seu exército.'),
(33, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 2, 'OT', 'E, tendo Deus terminado no sétimo dia a sua obra que fizera, descansou no sétimo dia de toda a sua obra que fizera.'),
(34, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 3, 'OT', 'E abençoou Deus o sétimo dia e o santificou, porque nele descansou de toda a sua obra que Deus criara e fizera.'),
(35, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 4, 'OT', 'Estas são as origens dos céus e da terra, quando foram criados: no dia em que o SENHOR Deus fez a terra e os céus.'),
(36, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 5, 'OT', 'Ainda não havia nenhum arbusto do campo sobre a terra, e nenhuma planta do campo tinha brotado, porque o SENHOR Deus não tinha feito chover sobre a terra, e não havia homem para cultivar o solo.'),
(37, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 6, 'OT', 'Um vapor subia da terra e regava toda a face do solo.'),
(38, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 7, 'OT', 'E formou o SENHOR Deus o homem do pó da terra, e soprou em suas narinas o fôlego da vida; e o homem tornou-se alma vivente.'),
(39, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 8, 'OT', 'E plantou o SENHOR Deus um jardim no Éden, no oriente; e ali pôs o homem que havia formado.'),
(40, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 9, 'OT', 'E o SENHOR Deus fez brotar da terra toda árvore agradável à vista e boa para alimento, e a árvore da vida no meio do jardim, e a árvore do conhecimento do bem e do mal.'),
(41, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 10, 'OT', 'E saía um rio do Éden para regar o jardim; e dali se dividia e se tornava em quatro braços.'),
(42, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 11, 'OT', 'O nome do primeiro é Pison; é ele que circunda toda a terra de Havilá, onde há ouro.'),
(43, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 12, 'OT', 'E o ouro daquela terra é bom; ali há o bdélio e a pedra de ônix.'),
(44, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 13, 'OT', 'E o nome do segundo rio é Giom; este é o que rodeia toda a terra de Cuxe.'),
(45, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 14, 'OT', 'E o nome do terceiro rio é Tigre; este é o que corre ao oriente da Assíria. E o quarto rio é o Eufrates.'),
(46, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 15, 'OT', 'O SENHOR Deus tomou o homem e o colocou no jardim do Éden para o cultivar e o guardar.'),
(47, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 16, 'OT', 'E ordenou o SENHOR Deus ao homem, dizendo: De toda árvore do jardim podes comer livremente,'),
(48, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 17, 'OT', 'Mas da árvore do conhecimento do bem e do mal, dela não comerás; porque no dia em que dela comeres, certamente morrerás.'),
(49, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 18, 'OT', 'Não é bom que o homem esteja só; farei para ele uma auxiliadora que lhe corresponda.'),
(50, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 19, 'OT', 'E o SENHOR Deus formou da terra todos os animais do campo e todas as aves do céu, e os trouxe ao homem, para ver como ele os chamaria; e tudo o que o homem chamou a cada ser vivo, esse foi o seu nome.'),
(51, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 20, 'OT', 'E o homem deu nomes a todos os animais domésticos, às aves do céu e a todos os animais do campo; mas para o homem não se encontrou uma auxiliadora que lhe correspondesse.'),
(52, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 21, 'OT', 'Então o SENHOR Deus fez cair um sono profundo sobre o homem, e ele dormiu; e tomou uma das suas costelas, e fechou a carne naquele lugar.'),
(53, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 22, 'OT', 'E o SENHOR Deus edificou a costela que tomara do homem para fazer uma mulher, e a trouxe ao homem.'),
(54, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 23, 'OT', 'E disse o homem: Esta, agora, é osso dos meus ossos e carne da minha carne; ela será chamada mulher, porque do homem foi tomada.'),
(55, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 24, 'OT', 'Portanto deixará o homem a seu pai e a sua mãe, e se unirá à sua mulher, e serão uma só carne.'),
(56, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 2, 25, 'OT', 'E ambos estavam nus, o homem e a sua mulher; e não se envergonhavam.'),
(57, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 1, 'OT', 'A serpente era mais astuta que todos os animais do campo que o SENHOR Deus tinha feito. E ela disse à mulher: "É verdade que Deus disse: ''Não comereis de toda árvore do jardim''?"'),
(58, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 2, 'OT', 'E a mulher disse à serpente: "Do fruto das árvores do jardim podemos comer,'),
(59, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 3, 'OT', 'Mas do fruto da árvore que está no meio do jardim, disse Deus: "Não comereis dele, nem nele tocareis, para que não morrais."'),
(60, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 4, 'OT', 'Então a serpente disse à mulher: "Certamente não morrereis."'),
(61, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 5, 'OT', 'Porque Deus sabe que no dia em que dele comerdes, vossos olhos se abrirão, e sereis como Deus, conhecendo o bem e o mal.'),
(62, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 6, 'OT', 'A mulher viu que a árvore era boa para alimento, e que era agradável aos olhos, e árvore desejável para dar entendimento; tomou do seu fruto e comeu, e deu também ao seu marido, que estava com ela, e ele comeu.'),
(63, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 7, 'OT', 'Então foram abertos os olhos de ambos, e perceberam que estavam nus; e costuraram folhas de figueira, e fizeram para si cintas.'),
(64, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 8, 'OT', 'E ouviram a voz do SENHOR Deus, que passeava no jardim pela brisa do dia; e esconderam-se o homem e sua mulher da presença do SENHOR Deus, entre as árvores do jardim.'),
(65, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 9, 'OT', 'E chamou o SENHOR Deus ao homem e lhe disse: Onde estás?'),
(66, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 10, 'OT', 'Ouvi a tua voz no jardim, e temi, porque estava nu; e escondi-me.'),
(67, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 11, 'OT', 'E disse: Quem te fez saber que estavas nu? Comeste da árvore de que te ordenei que não comesses?'),
(68, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 12, 'OT', 'Então disse o homem: "A mulher que me deste por companheira, ela me deu da árvore, e eu comi."'),
(69, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 13, 'OT', 'E disse o SENHOR Deus à mulher: Que é isto que fizeste? E disse a mulher: A serpente me enganou, e eu comi.'),
(70, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 14, 'OT', 'Então o SENHOR Deus disse à serpente: "Porquanto fizeste isto, maldita és tu entre todos os animais domésticos e entre todos os animais selvagens do campo; sobre o teu ventre andarás, e pó comerás todos os dias da tua vida."'),
(71, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 15, 'OT', 'Porei inimizade entre ti e a mulher, e entre a tua descendência e a descendência dela; esta te ferirá a cabeça, e tu lhe ferirás o calcanhar.'),
(72, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 16, 'OT', 'À mulher, disse: Multiplicarei grandemente o teu sofrimento e a tua conceição; com dor darás à luz filhos; e o teu desejo será para o teu marido, e ele te dominará.'),
(73, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 17, 'OT', 'E a Adão disse: Porque deste ouvidos à voz de tua mulher e comeste da árvore de que te ordenei, dizendo: Não comerás dela, maldita é a terra por tua causa; com sofrimento comerás dela todos os dias da tua vida.'),
(74, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 18, 'OT', 'Espinhos e cardos te produzirá, e comerás a erva do campo.'),
(75, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 19, 'OT', 'No suor do teu rosto comerás o pão, até que voltes à terra, pois dela foste tomado; porque és pó, e ao pó voltarás.'),
(76, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 20, 'OT', 'E chamou Adão o nome de sua mulher, Eva; porque ela era a mãe de todos os viventes.'),
(77, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 21, 'OT', 'O SENHOR Deus fez para Adão e para sua mulher túnicas de pele e os vestiu.'),
(78, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 22, 'OT', 'Então disse o SENHOR Deus: "Eis que o homem se tornou como um de nós, conhecendo o bem e o mal. Agora, para que não estenda a sua mão, e tome também da árvore da vida, e coma, e viva para sempre,"'),
(79, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 23, 'OT', 'O SENHOR Deus o enviou para fora do jardim do Éden, para cultivar o solo de onde ele fora tomado.'),
(80, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 3, 24, 'OT', 'Expulsou o homem e colocou querubins a leste do jardim do Éden, e uma espada flamejante que se movia de um lado para outro, para guardar o caminho da árvore da vida.'),
(81, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 1, 'OT', 'E conheceu Adão a Eva, sua mulher; e ela concebeu e deu à luz a Caim, e disse: Alcancei do SENHOR um varão.'),
(82, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 2, 'OT', 'E ela deu à luz mais uma vez, a seu irmão Abel. E Abel foi pastor de ovelhas, e Caim foi cultivador do solo.'),
(83, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 3, 'OT', 'E aconteceu que, ao fim de dias, Caim trouxe do fruto da terra uma oferta ao SENHOR.'),
(84, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 4, 'OT', 'E Abel também trouxe dos primogênitos do seu rebanho e da sua gordura; e o SENHOR atentou para Abel e para a sua oferta.'),
(85, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 5, 'OT', 'Mas para Caim e para a sua oferta não atentou; e irou-se Caim fortemente, e o seu semblante caiu.'),
(86, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 6, 'OT', 'E disse o SENHOR a Caim: Por que te iraste? E por que caiu o teu semblante?'),
(87, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 7, 'OT', 'Se fizeres o bem, não serás aceito? E se não fizeres o bem, o pecado está à porta, agachado; e para ti será o seu desejo, e tu o dominarás.'),
(88, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 8, 'OT', 'E disse Caim a seu irmão Abel: "Vamos ao campo." E aconteceu que, estando eles no campo, levantou-se Caim contra seu irmão Abel e o matou.'),
(89, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 9, 'OT', 'E disse o SENHOR a Caim: Onde está Abel, teu irmão? E ele disse: Não sei; sou eu guardador do meu irmão?'),
(90, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 10, 'OT', 'E disse: Que fizeste? A voz do sangue do teu irmão clama a mim desde a terra.'),
(91, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 11, 'OT', 'E agora és maldito desde a terra, que abriu a sua boca para receber da tua mão o sangue do teu irmão.'),
(92, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 12, 'OT', 'Quando lavrares o solo, ele não te dará mais a sua força; fugitivo e errante serás na terra.'),
(93, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 13, 'OT', 'Então disse Caim ao SENHOR: "Grande é a minha iniquidade para ser suportada."'),
(94, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 14, 'OT', 'Eis que hoje me expulsas da face da terra, e da tua face me esconderei; e serei fugitivo e errante na terra, e todo aquele que me encontrar me matará.'),
(95, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 15, 'OT', 'O SENHOR lhe disse: "Portanto, qualquer que matar Caim será vingado sete vezes." E o SENHOR pôs um sinal em Caim, para que ninguém que o encontrasse o ferisse.'),
(96, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 16, 'OT', 'E saiu Caim de diante do SENHOR e habitou na terra de Node, ao oriente do Éden.'),
(97, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 17, 'OT', 'Caim conheceu sua mulher, e ela concebeu e deu à luz a Enoque. Ele estava construindo uma cidade, e chamou o nome da cidade pelo nome de seu filho Enoque.'),
(98, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 18, 'OT', 'A Enoque nasceu Irade, e Irade gerou Meujael, e Meujael gerou Metusael, e Metusael gerou Lameque.'),
(99, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 19, 'OT', 'Lameque tomou para si duas mulheres: o nome da primeira era Ada, e o nome da segunda, Zilá.'),
(100, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 20, 'OT', 'Ada deu à luz Jabal; ele foi o pai dos que habitam em tendas e possuem gado.'),
(101, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 21, 'OT', 'E o nome de seu irmão era Jubal; ele foi o pai de todos os que tocam harpa e flauta.'),
(102, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 22, 'OT', 'E Zilá também deu à luz Tubalcaim, que forjava todo instrumento de bronze e de ferro; e a irmã de Tubalcaim foi Naamá.'),
(103, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 23, 'OT', 'E disse Lameque às suas mulheres: Ada e Zilá, ouvi a minha voz; mulheres de Lameque, escutai o meu dito: pois matei um homem por minha ferida, e um jovem por minha pisadura.'),
(104, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 24, 'OT', 'Porque sete vezes Caim será vingado, mas Lameque, setenta e sete vezes.'),
(105, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 25, 'OT', 'E conheceu Adão outra vez a sua mulher, e ela deu à luz um filho, e chamou o seu nome Sete, dizendo: "Deus me deu outra semente em lugar de Abel, porque Caim o matou."'),
(106, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 4, 26, 'OT', 'A Sete também nasceu um filho, e ele lhe chamou Enos. Nesse tempo começou-se a invocar o nome do SENHOR.'),
(107, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 1, 'OT', 'Este é o livro das gerações de Adão. No dia em que Deus criou o homem, à semelhança de Deus o fez.'),
(108, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 2, 'OT', 'E os criou macho e fêmea, e os abençoou, e chamou o seu nome Adão, no dia em que foram criados.'),
(109, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 3, 'OT', 'E Adão viveu cento e trinta anos, e gerou um filho à sua semelhança, conforme a sua imagem, e chamou o seu nome Sete.'),
(110, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 4, 'OT', 'E foram os dias de Adão, depois que gerou a Sete, oitocentos anos; e gerou filhos e filhas.'),
(111, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 5, 'OT', 'Todos os dias que Adão viveu foram novecentos e trinta anos; e ele morreu.'),
(112, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 6, 'OT', 'Viveu Sete cento e cinco anos, e gerou a Enos.'),
(113, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 7, 'OT', 'E viveu Sete, depois que gerou a Enos, setecentos e sete anos, e gerou filhos e filhas.'),
(114, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 8, 'OT', 'Todos os dias de Sete foram novecentos e doze anos; e ele morreu.'),
(115, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 9, 'OT', 'E viveu Enos noventa anos, e gerou a Cainã.'),
(116, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 10, 'OT', 'E viveu Enos, depois que gerou a Cainã, quinhentos e quinze anos, e oitocentos anos; e gerou filhos e filhas.'),
(117, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 11, 'OT', 'Todos os dias de Enos foram novecentos e cinco anos; e ele morreu.'),
(118, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 12, 'OT', 'E viveu Cainã setenta anos; e gerou a Maalalel.'),
(119, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 13, 'OT', 'E viveu Cainã, depois de gerar a Maalalel, quarenta e oitocentos anos; e gerou filhos e filhas.'),
(120, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 14, 'OT', 'Todos os dias de Quenã foram novecentos e dez anos; e ele morreu.'),
(121, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 15, 'OT', 'Mahalalel viveu sessenta e cinco anos e gerou a Jerede.'),
(122, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 16, 'OT', 'E viveu Maalalel, depois que gerou a Jerede, trinta anos e oitocentos anos; e gerou filhos e filhas.'),
(123, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 17, 'OT', 'E foram todos os dias de Maalalel novecentos e noventa e cinco anos; e morreu.'),
(124, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 18, 'OT', 'Jared viveu cento e sessenta e dois anos e gerou Enoque.'),
(125, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 19, 'OT', 'E viveu Jerede, depois que gerou a Enoque, oitocentos anos; e gerou filhos e filhas.'),
(126, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 20, 'OT', 'Todos os dias de Jerede foram novecentos e sessenta e dois anos; e ele morreu.'),
(127, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 21, 'OT', 'E viveu Enoque sessenta e cinco anos; e gerou a Matusalém.'),
(128, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 22, 'OT', 'E andou Enoque com Deus, depois que gerou Matusalém, trezentos anos; e gerou filhos e filhas.'),
(129, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 23, 'OT', 'Todos os dias de Enoque foram trezentos e sessenta e cinco anos.'),
(130, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 24, 'OT', 'E andou Enoque com Deus; e já não era, porque Deus o tomou para si.'),
(131, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 25, 'OT', 'E viveu Matusalém cento e oitenta e sete anos, e gerou a Lameque.'),
(132, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 26, 'OT', 'E viveu Matusalém, depois que gerou a Lameque, setecentos e oitenta e dois anos; e gerou filhos e filhas.'),
(133, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 27, 'OT', 'Todos os dias de Matusalém foram novecentos e sessenta e nove anos; e ele morreu.'),
(134, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 28, 'OT', 'E viveu Lameque cento e oitenta e dois anos, e gerou um filho.'),
(135, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 29, 'OT', 'E chamou o seu nome Noé, dizendo: Este nos consolará da nossa obra e do trabalho das nossas mãos, por causa da terra que o SENHOR amaldiçoou.'),
(136, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 30, 'OT', 'E viveu Lameque, depois que gerou Noé, quinhentos e noventa e cinco anos; e gerou filhos e filhas.'),
(137, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 31, 'OT', 'E foram todos os dias de Lameque setecentos e setenta e sete anos; e morreu.'),
(138, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 5, 32, 'OT', 'E Noé tinha quinhentos anos; e gerou Noé a Sem, Cam e Jafé.'),
(139, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 1, 'OT', 'E aconteceu que, quando os homens começaram a se multiplicar sobre a face da terra, e lhes nasceram filhas,'),
(140, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 2, 'OT', 'Os filhos de Deus viram que as filhas dos homens eram belas, e tomaram para si mulheres de todas as que escolheram.'),
(141, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 3, 'OT', 'Então disse o SENHOR: "O meu Espírito não contenderá para sempre com o homem, porque ele também é carne; os seus dias serão cento e vinte anos."'),
(142, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 4, 'OT', 'Naqueles dias havia os nefilins na terra, e também depois, quando os filhos de Deus se uniram às filhas dos homens, e elas lhes deram filhos; esses foram os heróis que desde a antiguidade eram homens de renome.'),
(143, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 5, 'OT', 'E viu o SENHOR que a maldade do homem se multiplicava sobre a terra, e que toda a imaginação dos pensamentos do seu coração era somente má todo o dia.'),
(144, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 6, 'OT', 'E o SENHOR se arrependeu de ter feito o homem sobre a terra, e isso lhe pesou no coração.'),
(145, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 7, 'OT', 'Disse o SENHOR: "Apagarei da face da terra o homem que criei, desde o homem até os animais, até os répteis e até as aves do céu, porque me arrependo de os ter feito."'),
(146, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 8, 'OT', 'Noé, porém, achou graça aos olhos do SENHOR.'),
(147, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 9, 'OT', 'Estas são as gerações de Noé: Noé era homem justo e íntegro entre os seus contemporâneos; Noé andava com Deus.'),
(148, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 10, 'OT', 'Noé gerou três filhos: Sem, Cam e Jafé.'),
(149, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 11, 'OT', 'A terra, porém, estava corrompida diante de Deus; e a terra encheu-se de violência.'),
(150, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 12, 'OT', 'Deus olhou para a terra e viu que ela estava corrompida, pois toda a carne havia corrompido o seu caminho sobre a terra.'),
(151, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 13, 'OT', 'Disse Deus a Noé: "O fim de toda a carne chegou diante de mim, porque a terra se encheu de violência por causa deles; e eis que eu os destruirei juntamente com a terra."'),
(152, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 14, 'OT', 'Faze para ti uma arca de madeira de gôfer; farás compartimentos na arca e a revestirás com betume por dentro e por fora.'),
(153, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 15, 'OT', 'E desta maneira a farás: de trezentos côvados o comprimento da arca, de cinquenta côvados a sua largura, e de trinta côvados a sua altura.'),
(154, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 16, 'OT', 'Farás uma abertura para a luz na arca, e a terminarás a um côvado do topo; e porás a porta da arca ao seu lado; farás andares inferiores, segundos e terceiros.'),
(155, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 17, 'OT', 'Eis que eu trago o dilúvio de águas sobre a terra, para destruir toda carne em que há espírito de vida debaixo dos céus; tudo o que há na terra expirará.'),
(156, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 18, 'OT', 'Mas estabelecerei a minha aliança contigo; e entrarás na arca, tu e teus filhos, e tua mulher, e as mulheres de teus filhos contigo.'),
(157, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 19, 'OT', 'De todo ser vivo, de toda carne, dois de cada espécie trarás à arca, para os conservar vivos contigo; macho e fêmea serão.'),
(158, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 20, 'OT', 'Das aves segundo a sua espécie, e dos animais segundo a sua espécie, de todo réptil da terra segundo a sua espécie, dois de cada virão a ti, para os conservar em vida.'),
(159, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 21, 'OT', 'E tu, toma para ti de todo alimento que se come, e ajunta-o para ti; e será para ti e para eles como comida.'),
(160, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 6, 22, 'OT', 'E assim Noé fez: conforme tudo o que Deus lhe ordenou, assim ele fez.'),
(161, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 1, 'OT', 'Disse o SENHOR a Noé: Entra tu e toda a tua casa na arca, porque te vi justo diante de mim nesta geração.'),
(162, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 2, 'OT', 'De todo animal limpo tomarás para ti sete pares, macho e fêmea; mas dos animais que não são limpos, dois, macho e fêmea.'),
(163, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 3, 'OT', 'Também das aves dos céus, sete pares, macho e fêmea, para preservar a descendência sobre a face de toda a terra.'),
(164, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 4, 'OT', 'Porque, passados ainda sete dias, farei chover sobre a terra quarenta dias e quarenta noites; e apagarei de sobre a face da terra toda a substância que fiz.'),
(165, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 5, 'OT', 'E fez Noé conforme tudo o que o SENHOR lhe havia ordenado.'),
(166, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 6, 'OT', 'E Noé tinha seiscentos anos de idade, e o dilúvio veio, águas sobre a terra.'),
(167, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 7, 'OT', 'E entrou Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele na arca, por causa das águas do dilúvio.'),
(168, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 8, 'OT', 'Dos animais limpos e dos animais que não são limpos, e das aves, e de tudo o que rasteja sobre a terra,'),
(169, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 9, 'OT', 'Entraram de dois em dois a Noé na arca, macho e fêmea, como Deus havia ordenado a Noé.'),
(170, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 10, 'OT', 'E aconteceu que, passados sete dias, as águas do dilúvio vieram sobre a terra.'),
(171, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 11, 'OT', 'No ano seiscentos da vida de Noé, no segundo mês, aos dezessete dias do mês, naquele mesmo dia romperam-se todas as fontes do grande abismo, e as janelas dos céus se abriram.'),
(172, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 12, 'OT', 'E houve chuva sobre a terra quarenta dias e quarenta noites.'),
(173, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 13, 'OT', 'No exato dia em que Noé entrou na arca, também entraram Sem, Cam e Jafé, filhos de Noé, a esposa de Noé e as três esposas de seus filhos, juntamente com eles.'),
(174, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 14, 'OT', 'Eles, e todo animal selvagem conforme a sua espécie, e todo gado conforme a sua espécie, e todo réptil que se move sobre a terra conforme a sua espécie, e toda ave conforme a sua espécie, toda criatura alada de toda espécie.'),
(175, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 15, 'OT', 'E entraram para Noé na arca, de dois em dois, de toda a carne em que havia espírito de vida.'),
(176, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 16, 'OT', 'E os que entraram, macho e fêmea de toda a carne, entraram, como Deus lhe havia ordenado; e o SENHOR o fechou por fora.'),
(177, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 17, 'OT', 'E o dilúvio durou quarenta dias sobre a terra; e as águas cresceram e levantaram a arca, e ela se elevou acima da terra.'),
(178, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 18, 'OT', 'E prevaleceram as águas e cresceram grandemente sobre a terra; e a arca andava sobre a superfície das águas.'),
(179, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 19, 'OT', 'E as águas prevaleceram sobremaneira sobre a terra, e todos os altos montes que havia debaixo de todo o céu foram cobertos.'),
(180, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 20, 'OT', 'Quinze côvados acima prevaleceram as águas, e os montes foram cobertos.'),
(181, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 21, 'OT', 'E expirou toda a carne que se move sobre a terra: as aves, os animais domésticos, os animais selvagens, todos os seres que rastejam sobre a terra, e todos os homens.'),
(182, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 22, 'OT', 'Tudo o que tinha fôlego de espírito de vida em suas narinas, tudo o que havia na terra seca, morreu.'),
(183, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 23, 'OT', 'Assim foi eliminado todo ser vivo que havia sobre a face da terra, desde o homem até o animal, até o réptil e até a ave dos céus; e foram exterminados da terra. E restou somente Noé e os que estavam com ele na arca.'),
(184, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 7, 24, 'OT', 'E prevaleceram as águas sobre a terra cento e cinquenta dias.'),
(185, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 1, 'OT', 'E lembrou-se Deus de Noé, e de todos os animais selvagens, e de todos os animais domésticos que estavam com ele na arca; e Deus fez passar um vento sobre a terra, e as águas diminuíram.'),
(186, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 2, 'OT', 'Cerraram-se as fontes do abismo e as janelas do céu, e a chuva do céu foi retida.'),
(187, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 3, 'OT', 'E as águas foram se retirando de sobre a terra, indo e voltando, e as águas diminuíram ao fim de cento e cinquenta dias.'),
(188, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 4, 'OT', 'No sétimo mês, no décimo sétimo dia do mês, a arca repousou sobre os montes de Ararate.'),
(189, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 5, 'OT', 'E as águas foram diminuindo continuamente até o décimo mês; no décimo mês, no primeiro dia do mês, apareceram os cumes dos montes.'),
(190, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 6, 'OT', 'Ao cabo de quarenta dias, Noé abriu a janela da arca que tinha feito.'),
(191, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 7, 'OT', 'Soltou o corvo, que saiu, indo e voltando, até que as águas secaram de sobre a terra.'),
(192, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 8, 'OT', 'Soltou também uma pomba, da sua presença, para ver se as águas tinham diminuído sobre a face da terra.'),
(193, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 9, 'OT', 'A pomba não achou lugar de repouso para a planta do seu pé, e voltou a ele, para a arca, porque as águas estavam sobre a face de toda a terra; e ele estendeu a mão, e a tomou, e a trouxe para si, para a arca.'),
(194, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 10, 'OT', 'E esperou ainda outros sete dias, e tornou a enviar a pomba para fora da arca.'),
(195, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 11, 'OT', 'E a pomba voltou a ele ao entardecer, e eis que havia uma folha de oliveira arrancada no seu bico; e Noé soube que as águas tinham diminuído sobre a terra.'),
(196, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 12, 'OT', 'Esperou ainda outros sete dias e enviou a pomba, e ela não voltou mais a ele.'),
(197, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 13, 'OT', 'No ano seiscentos e um, no primeiro mês, no primeiro dia do mês, as águas secaram de sobre a terra; então Noé tirou a cobertura da arca, e olhou, e eis que a superfície da terra estava seca.'),
(198, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 14, 'OT', 'E no segundo mês, aos vinte e sete dias do mês, a terra estava seca.'),
(199, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 15, 'OT', 'E Deus falou a Noé, dizendo:'),
(200, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 16, 'OT', 'Sai da arca, tu, e tua mulher, e teus filhos, e as mulheres de teus filhos contigo.'),
(201, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 17, 'OT', 'Tira para fora contigo todo ser vivente que está contigo, de toda carne, entre aves, gado e todo réptil que se move sobre a terra, para que povoem a terra, e frutifiquem e se multipliquem sobre a terra.'),
(202, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 18, 'OT', 'Então saiu Noé, e seus filhos, e sua mulher, e as mulheres de seus filhos com ele.'),
(203, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 19, 'OT', 'Todo animal, todo réptil, toda ave e tudo o que se move sobre a terra, conforme as suas famílias, saíram da arca.'),
(204, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 20, 'OT', 'E edificou Noé um altar ao SENHOR; e tomou de todo animal limpo e de toda ave limpa, e ofereceu holocaustos sobre o altar.'),
(205, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 21, 'OT', 'E o SENHOR sentiu o aroma agradável, e o SENHOR disse em seu coração: "Nunca mais amaldiçoarei a terra por causa do homem, pois a inclinação do coração do homem é má desde a sua juventude; e nunca mais destruirei todos os seres vivos como fiz.'),
(206, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 8, 22, 'OT', 'Enquanto durarem todos os dias da terra, semente e colheita, frio e calor, verão e inverno, dia e noite, não cessarão.'),
(207, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 1, 'OT', 'E abençoou Deus a Noé e a seus filhos, e disse-lhes: Frutificai e multiplicai-vos, e enchei a terra.'),
(208, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 2, 'OT', 'O temor e o pavor de vocês estarão sobre todo animal da terra, sobre toda ave dos céus, sobre tudo o que se move pelo solo e sobre todos os peixes do mar; nas suas mãos eles são entregues.'),
(209, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 3, 'OT', 'Tudo o que se move e vive será alimento para vocês; assim como lhes dei a vegetação verde, dou-lhes todas as coisas.'),
(210, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 4, 'OT', 'Todavia, carne com sua vida, isto é, seu sangue, não comereis.'),
(211, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 5, 'OT', 'E certamente requererei o vosso sangue, o sangue das vossas vidas; da mão de todo animal o requererei, e da mão do homem; da mão de cada um, seu irmão, requererei a vida do homem.'),
(212, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 6, 'OT', 'Quem derramar o sangue do homem, pelo homem o seu sangue será derramado; porque à imagem de Deus fez ele o homem.'),
(213, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 7, 'OT', 'Mas vós, frutificai e multiplicai-vos; povoai abundantemente a terra e multiplicai-vos nela.'),
(214, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 8, 'OT', 'E Deus falou a Noé e a seus filhos com ele, dizendo:'),
(215, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 9, 'OT', 'E eu, eis que estabeleço a minha aliança convosco e com a vossa descendência depois de vós.'),
(216, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 10, 'OT', 'e com todo ser vivo que está com vocês: as aves, os animais domésticos e todos os animais selvagens da terra, todos os que saíram da arca, todos os animais da terra.'),
(217, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 11, 'OT', 'Estabelecerei a minha aliança convosco: nenhuma carne será mais exterminada pelas águas do dilúvio, e não haverá mais dilúvio para destruir a terra.'),
(218, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 12, 'OT', 'E disse Deus: Este é o sinal da aliança que estabeleço entre mim e vós, e entre toda alma vivente que está convosco, por gerações eternas.'),
(219, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 13, 'OT', 'O meu arco tenho posto na nuvem, e ele será por sinal da aliança entre mim e a terra.'),
(220, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 14, 'OT', 'E acontecerá que, quando eu fizer vir nuvens sobre a terra, o arco aparecerá nas nuvens.'),
(221, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 15, 'OT', 'E me lembrarei da minha aliança, que está entre mim e vós, e entre toda alma vivente de toda carne; e as águas não se tornarão mais em dilúvio para destruir toda carne.'),
(222, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 16, 'OT', 'E o arco estará nas nuvens, e eu o verei, para me lembrar da aliança eterna entre Deus e toda alma vivente, de toda carne que está sobre a terra.'),
(223, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 17, 'OT', 'E disse Deus a Noé: Este é o sinal da aliança que estabeleci entre mim e toda a carne que está sobre a terra.'),
(224, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 18, 'OT', 'Os filhos de Noé que saíram da arca foram Sem, Cam e Jafé; e Cam é o pai de Canaã.'),
(225, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 19, 'OT', 'Estes três foram os filhos de Noé, e a partir deles se espalhou toda a terra.'),
(226, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 20, 'OT', 'E começou Noé, homem da terra, e plantou uma vinha.'),
(227, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 21, 'OT', 'E bebeu do vinho, e embriagou-se; e descobriu-se no meio de sua tenda.'),
(228, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 22, 'OT', 'E viu Cam, pai de Canaã, a nudez de seu pai, e o contou a seus dois irmãos, fora.'),
(229, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 23, 'OT', 'Então Sem e Jafé tomaram uma capa, colocaram-na sobre os próprios ombros, e, andando de costas, cobriram a nudez de seu pai; seus rostos estavam voltados para trás, e não viram a nudez de seu pai.'),
(230, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 24, 'OT', 'E despertou Noé do seu vinho, e soube o que seu filho mais novo lhe fizera.'),
(231, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 25, 'OT', 'Maldito seja Canaã; servo dos servos será para seus irmãos.'),
(232, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 26, 'OT', 'Bendito seja o SENHOR, Deus de Sem; e seja Canaã seu servo.'),
(233, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 27, 'OT', 'Alargue Deus a Jafé, e habite ele nas tendas de Sem; e seja Canaã servo deles.'),
(234, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 28, 'OT', 'E viveu Noé, depois do dilúvio, trezentos e cinquenta anos.'),
(235, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 9, 29, 'OT', 'E foram todos os dias de Noé novecentos e cinquenta anos, e ele morreu.'),
(236, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 1, 'OT', 'Estas são as gerações dos filhos de Noé: Sem, Cam e Jafé; e nasceram-lhes filhos depois do dilúvio.'),
(237, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 2, 'OT', 'Os filhos de Jafé: Gômer, Magogue, Madai, Javã, Tubal, Meseque e Tirás.'),
(238, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 3, 'OT', 'Os filhos de Gômer: Asquenaz, Rifate e Togarma.'),
(239, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 4, 'OT', 'Os filhos de Javã: Elisá e Társis, Quitim e Dodanim.'),
(240, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 5, 'OT', 'Por estes foram separadas as ilhas das nações em suas terras, cada um conforme a sua língua, segundo as suas famílias, entre as suas nações.'),
(241, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 6, 'OT', 'Os filhos de Cam: Cuxe, Mizraim, Pute e Canaã.'),
(242, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 7, 'OT', 'E os filhos de Cuxe: Seba, Havilá, Sabtá, Raamá e Sabtecá; e os filhos de Raamá: Sabá e Dedã.'),
(243, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 8, 'OT', 'E Cuxe gerou a Nimrode; ele começou a ser poderoso na terra.'),
(244, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 9, 'OT', 'Ele foi poderoso caçador diante do SENHOR; por isso se diz: "Como Ninrode, poderoso caçador diante do SENHOR."'),
(245, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 10, 'OT', 'O princípio do seu reino foi Babel, Ereque, Acade e Calné, na terra de Sinar.'),
(246, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 11, 'OT', 'Desta terra saiu Assur e edificou Nínive, e Rehoboth-Ir, e Calá.'),
(247, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 12, 'OT', 'E Resen, entre Nínive e Calá (esta é a grande cidade).'),
(248, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 13, 'OT', 'E Mizraim gerou a Ludim, os Anamim, os Leabim e os Naftuhim.'),
(249, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 14, 'OT', 'E os patrusins, e os casluins, de onde saíram os filisteus, e os caftorins.'),
(250, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 15, 'OT', 'E Canaã gerou a Sidom, seu primogênito, e a Hete.'),
(251, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 16, 'OT', 'e o jebuseu, o amorreu e o girgaseu,'),
(252, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 17, 'OT', 'e o heveu, o arqueu e o sineu'),
(253, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 18, 'OT', 'E ao arvadeu, e ao zemareu, e ao hamateu; e depois se espalharam as famílias dos cananeus.'),
(254, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 19, 'OT', 'E o território dos cananeus estendia-se desde Sidom, em direção a Gerar, até Gaza; e em direção a Sodoma, Gomorra, Admá e Zeboim, até Lasa.'),
(255, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 20, 'OT', 'Estes são os filhos de Cam, segundo os seus clãs, segundo as suas línguas, em suas terras, em suas nações.'),
(256, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 21, 'OT', 'E a Sem também nasceu um filho, ele é o pai de todos os filhos de Héber, irmão de Jafé, o mais velho.'),
(257, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 22, 'OT', 'Os filhos de Sem: Elão, Assur, Arfaxade, Lude e Arã.'),
(258, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 23, 'OT', 'Os filhos de Arã: Uz, Hul, Geter e Más.'),
(259, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 24, 'OT', 'E Arpaxade gerou a Selá; e Selá gerou a Héber.'),
(260, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 25, 'OT', 'E a Éber nasceram dois filhos: o nome de um foi Pelegue, porque em seus dias se dividiu a terra; e o nome do seu irmão foi Joctã.'),
(261, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 26, 'OT', 'E Joctã gerou a Almodá, e a Salefe, e a Hazarmavete, e a Jerá.'),
(262, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 27, 'OT', 'E a Hadorão, e a Uzal, e a Dicla.'),
(263, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 28, 'OT', 'E a Obal, e a Abimael, e a Sebá.'),
(264, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 29, 'OT', 'E a Ofir, e a Havilá, e a Jobabe; todos estes foram filhos de Joctã.'),
(265, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 30, 'OT', 'E foi a sua habitação desde Messa, indo até Sefar, a montanha do Oriente.'),
(266, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 31, 'OT', 'Estes são os filhos de Sem, segundo as suas famílias, segundo as suas línguas, nas suas terras, segundo as suas nações.'),
(267, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 10, 32, 'OT', 'Estas são as famílias dos filhos de Noé, segundo as suas gerações, nas suas nações; e destes foram separadas as nações na terra depois do dilúvio.'),
(268, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 1, 'OT', 'Toda a terra tinha uma só língua e as mesmas palavras.'),
(269, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 2, 'OT', 'E aconteceu que, partindo eles do Oriente, acharam uma planície na terra de Sinar; e habitaram ali.'),
(270, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 3, 'OT', 'E disseram uns aos outros: Vinde, façamos tijolos e queimemo-los bem. E o tijolo serviu-lhes de pedra, e o betume serviu-lhes de argamassa.'),
(271, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 4, 'OT', 'E disseram: Vinde, edifiquemos para nós uma cidade e uma torre cujo topo alcance os céus, e façamos para nós um nome, para que não sejamos espalhados sobre a face de toda a terra.'),
(272, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 5, 'OT', 'E o SENHOR desceu para ver a cidade e a torre que os filhos dos homens construíam.'),
(273, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 6, 'OT', 'E disse o SENHOR: Eis que o povo é um, e todos têm uma só língua; e isto é o que começam a fazer; e agora, nada lhes será impedido de tudo o que intentarem fazer.'),
(274, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 7, 'OT', 'Eia, desçamos e confundamos ali a sua língua, para que não entendam um a língua do outro.'),
(275, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 8, 'OT', 'Assim o SENHOR os espalhou dali sobre a face de toda a terra, e cessaram de edificar a cidade.'),
(276, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 9, 'OT', 'Por isso lhe chamaram Babel, porque ali o SENHOR confundiu a língua de toda a terra, e dali o SENHOR os espalhou por toda a face da terra.'),
(277, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 10, 'OT', 'Estas são as gerações de Sem: Sem tinha cem anos de idade e gerou a Arpaxade, dois anos depois do dilúvio.'),
(278, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 11, 'OT', 'E viveu Sem, depois que gerou a Arpaxade, quinhentos anos; e gerou filhos e filhas.'),
(279, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 12, 'OT', 'E viveu Arpacsade trinta e cinco anos, e gerou a Selá.'),
(280, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 13, 'OT', 'E viveu Arpachshade depois que gerou a Selá trezentos e três anos, e gerou filhos e filhas.'),
(281, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 14, 'OT', 'Selá viveu trinta anos e gerou Éber.'),
(282, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 15, 'OT', 'E viveu Selá, depois que gerou Éber, trezentos e três anos, e gerou filhos e filhas.'),
(283, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 16, 'OT', 'Eber viveu trinta e quatro anos e gerou a Pelegue.'),
(284, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 17, 'OT', 'E viveu Éber, depois que gerou a Pelegue, quatrocentos e trinta anos, e gerou filhos e filhas.'),
(285, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 18, 'OT', 'Pélegue viveu trinta anos e gerou a Reú.'),
(286, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 19, 'OT', 'E viveu Pelegue, depois que gerou a Reú, duzentos e nove anos, e gerou filhos e filhas.'),
(287, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 20, 'OT', 'E viveu Reú trinta e dois anos, e gerou a Serugue.'),
(288, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 21, 'OT', 'E viveu Reú, depois que gerou a Serugue, duzentos e sete anos, e gerou filhos e filhas.'),
(289, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 22, 'OT', 'Serug viveu trinta anos e gerou a Naor.'),
(290, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 23, 'OT', 'E viveu Serug, depois que gerou a Naor, duzentos anos, e gerou filhos e filhas.'),
(291, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 24, 'OT', 'E viveu Naor vinte e nove anos, e gerou a Terá.'),
(292, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 25, 'OT', 'E viveu Naor, depois que gerou a Terá, cento e dezenove anos, e gerou filhos e filhas.'),
(293, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 26, 'OT', 'E viveu Terá setenta anos, e gerou a Abrão, a Naor e a Harã.'),
(294, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 27, 'OT', 'Estas são as gerações de Terá: Terá gerou Abrão, Naor e Harã; e Harã gerou Ló.'),
(295, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 28, 'OT', 'E morreu Harã na presença de Terá, seu pai, na terra do seu nascimento, em Ur dos caldeus.'),
(296, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 29, 'OT', 'E tomaram Abrão e Naor mulheres para si: o nome da mulher de Abrão era Sarai, e o nome da mulher de Naor era Milca, filha de Harã, pai de Milca e pai de Iscá.'),
(297, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 30, 'OT', 'E Sarai era estéril; não tinha filhos.'),
(298, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 31, 'OT', 'Tera tomou seu filho Abrão, e Ló, filho de Harã, seu neto, e Sarai, sua nora, mulher de seu filho Abrão, e saíram com eles de Ur dos caldeus, para irem à terra de Canaã; e chegaram até Harã, e habitaram ali.'),
(299, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 11, 32, 'OT', 'E foram os dias de Terá duzentos e cinco anos; e morreu Terá em Harã.'),
(300, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 1, 'OT', 'O SENHOR disse a Abrão: Sae-te da tua terra, da tua parentela e da casa de teu pai, para a terra que eu te mostrarei.'),
(301, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 2, 'OT', 'Farei de ti uma grande nação, e te abençoarei, e engrandecerei o teu nome; e sê tu uma bênção.'),
(302, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 3, 'OT', 'Abençoarei os que te abençoarem, e amaldiçoarei aquele que te amaldiçoar; e em ti serão abençoadas todas as famílias da terra.'),
(303, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 4, 'OT', 'Partiu Abrão, como o SENHOR lhe havia dito, e Ló foi com ele. Abrão tinha setenta e cinco anos quando saiu de Harã.'),
(304, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 5, 'OT', 'E tomou Abrão a Sarai, sua mulher, e a Ló, filho de seu irmão, e todos os seus bens que haviam adquirido, e as pessoas que haviam conseguido em Harã; e saíram para irem à terra de Canaã, e chegaram à terra de Canaã.'),
(305, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 6, 'OT', 'Abrão atravessou a terra até o lugar de Siquém, até o carvalho de Moré; e naquele tempo os cananeus estavam na terra.'),
(306, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 7, 'OT', 'O SENHOR apareceu a Abrão e disse: "À tua descendência darei esta terra." E ele edificou ali um altar ao SENHOR, que lhe havia aparecido.'),
(307, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 8, 'OT', 'E partiu dali para a montanha, ao oriente de Betel, e armou a sua tenda, tendo Betel ao ocidente e Ai ao oriente; e edificou ali um altar ao SENHOR e invocou o nome do SENHOR.'),
(308, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 9, 'OT', 'Partiu Abrão, seguindo sempre para o Neguebe.'),
(309, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 10, 'OT', 'Houve fome na terra; e desceu Abrão ao Egito, para peregrinar ali, porque a fome era grande na terra.'),
(310, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 11, 'OT', 'E aconteceu que, ao aproximar-se para entrar no Egito, disse a Sarai, sua mulher: "Eis que agora sei que és mulher formosa à vista.'),
(311, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 12, 'OT', 'Quando os egípcios te virem, dirão: ''Esta é a mulher dele''. Então me matarão, mas a ti te deixarão viva.'),
(312, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 13, 'OT', 'Dize, por favor, que és minha irmã, para que me vá bem por tua causa, e que a minha alma viva por tua causa.'),
(313, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 14, 'OT', 'E aconteceu que, ao entrar Abrão no Egito, os egípcios viram a mulher, porque ela era muito bonita.'),
(314, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 15, 'OT', 'Os oficiais de Faraó a viram e a elogiaram diante de Faraó; e a mulher foi levada para a casa de Faraó.'),
(315, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 16, 'OT', 'E ele tratou bem a Abrão por causa dela; e ele teve ovelhas, bois, jumentos, servos e servas, jumentas e camelos.'),
(316, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 17, 'OT', 'E feriu o SENHOR a Faraó com grandes pragas, e a sua casa, por causa de Sarai, mulher de Abrão.'),
(317, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 18, 'OT', 'Então Faraó chamou Abrão e disse: Que é isto que me fizeste? Por que não me contaste que ela era tua mulher?'),
(318, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 19, 'OT', 'Por que disseste: "Ela é minha irmã"? Por isso a tomei para mim como mulher. Agora, pois, eis aqui tua mulher; toma-a e vai-te.'),
(319, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 12, 20, 'OT', 'E o faraó deu ordens a seus homens a respeito dele, e eles o acompanharam, a ele, à sua mulher e a tudo o que lhe pertencia.'),
(320, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 1, 'OT', 'Subiu Abrão do Egito para o Neguebe, ele e sua mulher, e tudo o que tinha, e Ló com ele.'),
(321, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 2, 'OT', 'E Abrão era muito rico em gado, em prata e em ouro.'),
(322, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 3, 'OT', 'E seguiu em suas jornadas do Neguebe até Beth-el, até o lugar onde a princípio estivera a sua tenda, entre Beth-el e Ai;'),
(323, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 4, 'OT', 'Ao lugar do altar que havia feito ali anteriormente; e Abrão invocou ali o nome do SENHOR.'),
(324, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 5, 'OT', 'E também Ló, que ia com Abrão, tinha ovelhas, gado e tendas.'),
(325, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 6, 'OT', 'E a terra não os podia sustentar para habitarem juntos, porque os seus bens eram muitos; e não podiam habitar juntos.'),
(326, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 7, 'OT', 'E houve contenda entre os pastores do rebanho de Abrão e os pastores do rebanho de Ló; e os cananeus e os ferezeus habitavam então na terra.'),
(327, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 8, 'OT', 'Disse Abrão a Ló: Peço-te que não haja contenda entre mim e ti, nem entre os meus pastores e os teus pastores, pois somos irmãos.'),
(328, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 9, 'OT', 'Não está toda a terra diante de ti? Separa-te, pois, de mim; se fores para a esquerda, eu irei para a direita; e se fores para a direita, eu irei para a esquerda.'),
(329, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 10, 'OT', 'Lot ergueu os olhos e viu toda a planície do Jordão, que era toda bem regada, antes de o SENHOR destruir Sodoma e Gomorra, como o jardim do SENHOR, como a terra do Egito, na direção de Zoar.'),
(330, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 11, 'OT', 'Então Ló escolheu para si toda a planície do Jordão, e Ló partiu para o leste; e separaram-se um do outro.'),
(331, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 12, 'OT', 'Abrão habitou na terra de Canaã, e Ló habitou nas cidades da planície, e armou suas tendas até Sodoma.'),
(332, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 13, 'OT', 'Os homens de Sodoma eram maus e grandes pecadores contra o SENHOR.'),
(333, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 14, 'OT', 'E o SENHOR disse a Abrão, depois que Ló se separou dele: Levanta agora os teus olhos e olha desde o lugar onde estás, para o norte, e para o sul, e para o oriente, e para o ocidente;'),
(334, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 15, 'OT', 'Porque toda esta terra que vês, eu a darei a ti e à tua descendência para sempre.'),
(335, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 16, 'OT', 'E farei a tua descendência como o pó da terra; se alguém puder contar o pó da terra, então também a tua descendência será contada.'),
(336, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 17, 'OT', 'Levanta-te, percorre a terra, no seu comprimento e na sua largura; porque a ti a darei.'),
(337, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 13, 18, 'OT', 'Abrão armou suas tendas, foi e habitou nos carvalhais de Manre, que estão junto a Hebrom; e edificou ali um altar ao SENHOR.'),
(338, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 1, 'OT', 'Aconteceu nos dias de Amraphel, rei de Sinar, Arioque, rei de Elasar, Quedorlaomer, rei de Elão, e Tidal, rei de Goim.'),
(339, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 2, 'OT', 'Fizeram guerra contra Bera, rei de Sodoma, e contra Birsha, rei de Gomorra, contra Sinabe, rei de Admá, e contra Semeber, rei de Zeboim, e contra o rei de Bela, que é Zoar.'),
(340, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 3, 'OT', 'Todos estes se ajuntaram no vale de Sidim, que é o mar de Sal.'),
(341, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 4, 'OT', 'Doze anos serviram a Quedorlaomer, mas no décimo terceiro ano se rebelaram.'),
(342, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 5, 'OT', 'No décimo quarto ano, veio Quedorlaomer e os reis que estavam com ele, e feriram os refains em Ashteroth-karnaim, e os zuzins em Hã, e os emins em Shave-kiriathaim.'),
(343, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 6, 'OT', 'E aos horeus no seu monte Seir, até El-Parã, que está junto ao deserto.'),
(344, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 7, 'OT', 'E voltaram e vieram a En-Mispate, que é Cades, e feriram toda a terra dos amalequitas, e também os amorreus, que habitavam em Hazazon-tamar.'),
(345, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 8, 'OT', 'Então saiu o rei de Sodoma, e o rei de Gomorra, e o rei de Admá, e o rei de Zeboim, e o rei de Bela (esta é Zoar), e ordenaram batalha contra eles no vale de Sidim.'),
(346, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 9, 'OT', 'contra Quedorlaomer, rei de Elão, e Tidal, rei de Goim, e Anrafel, rei de Sinar, e Arioque, rei de Elasar: quatro reis contra cinco.'),
(347, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 10, 'OT', 'O vale de Siddim estava cheio de poços de betume; e os reis de Sodoma e Gomorra fugiram e caíram ali; e os restantes fugiram para a montanha.'),
(348, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 11, 'OT', 'E tomaram todos os bens de Sodoma e Gomorra, e todo o seu alimento, e partiram.'),
(349, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 12, 'OT', 'Tomaram a Ló, e os seus bens, filho do irmão de Abrão, e partiram; e ele habitava em Sodoma.'),
(350, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 13, 'OT', 'Então um fugitivo veio e contou a Abrão, o hebreu, que habitava junto aos carvalhos de Manre, o amorreu, irmão de Escol e irmão de Aner; e eles eram aliados de Abrão.'),
(351, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 14, 'OT', 'Ouvindo Abrão que seu irmão fora levado cativo, armou os seus treinados, nascidos em sua casa, trezentos e dezoito, e os perseguiu até Dã.'),
(352, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 15, 'OT', 'E, dividindo-se contra eles de noite, ele e os seus servos, feriu-os e perseguiu-os até Hobá, que fica à esquerda de Damasco.'),
(353, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 16, 'OT', 'E trouxe de volta todos os bens, e também a Ló, seu irmão, e os seus bens, ele restituiu, e também as mulheres e o povo.'),
(354, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 17, 'OT', 'E o rei de Sodoma saiu ao seu encontro, depois que ele voltou de ferir Quedorlaomer e os reis que estavam com ele, até o vale de Savé, que é o vale do rei.'),
(355, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 18, 'OT', 'E Melquisedeque, rei de Salém, trouxe pão e vinho; e ele era sacerdote do Deus Altíssimo.'),
(356, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 19, 'OT', 'E abençoou-o e disse: Bendito seja Abrão pelo Deus Altíssimo, que criou os céus e a terra.'),
(357, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 20, 'OT', 'Bendito seja o Deus Altíssimo, que entregou os teus inimigos nas tuas mãos. E Abrão deu-lhe o dízimo de tudo.'),
(358, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 21, 'OT', 'Dá-me as pessoas, e fica com os bens.'),
(359, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 22, 'OT', 'Abrão, porém, disse ao rei de Sodoma: "Levantei minha mão ao SENHOR, o Deus Altíssimo, Criador dos céus e da terra,'),
(360, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 23, 'OT', 'Se nem um fio, nem uma correia de sandália, nem qualquer coisa que te pertence tomarei, para que não digas: "Eu enriqueci a Abrão".'),
(361, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 14, 24, 'OT', 'Salvo apenas o que os jovens comeram, e a parte que cabe aos homens que foram comigo: Aner, Escol e Manre; estes que tomem a sua parte.'),
(362, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 1, 'OT', 'Depois destas coisas, veio a palavra do SENHOR a Abrão numa visão, dizendo: Não temas, Abrão; eu sou o teu escudo, o teu galardão será grandíssimo.'),
(363, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 2, 'OT', 'Então disse Abrão: SENHOR Deus, que me darás, pois ando sem filhos, e o herdeiro da minha casa é o damasceno Eliézer?'),
(364, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 3, 'OT', 'Disse Abrão: Eis que não me tens dado descendência, e eis que um servo nascido na minha casa será o meu herdeiro.'),
(365, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 4, 'OT', 'E eis que a palavra do SENHOR veio a ele, dizendo: Este não será o teu herdeiro; mas aquele que sair das tuas entranhas, esse será o teu herdeiro.'),
(366, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 5, 'OT', 'Então o levou para fora e disse: Olha agora para os céus e conta as estrelas, se as podes contar. E disse-lhe: Assim será a tua descendência.'),
(367, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 6, 'OT', 'E creu ele no SENHOR, e isso lhe foi imputado por justiça.'),
(368, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 7, 'OT', 'Disse-lhe: Eu sou o SENHOR, que te tirei de Ur dos caldeus, para te dar esta terra, para a possuíres.'),
(369, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 8, 'OT', 'Ó SENHOR Deus, como saberei que hei de possuí-la?'),
(370, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 9, 'OT', 'Toma-me uma novilha de três anos, uma cabra de três anos, um carneiro de três anos, uma rola e um pombinho.'),
(371, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 10, 'OT', 'Ele trouxe-lhe todos esses, e os partiu ao meio, e pôs cada metade em frente da outra; mas as aves não partiu.'),
(372, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 11, 'OT', 'As aves de rapina desciam sobre os cadáveres, e Abrão as enxotava.'),
(373, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 12, 'OT', 'Ao pôr do sol, um sono profundo caiu sobre Abrão, e eis que grande terror e densas trevas caíram sobre ele.'),
(374, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 13, 'OT', 'E disse a Abrão: Sabe com certeza que a tua descendência será peregrina em terra que não é sua, e os servirão, e os afligirão por quatrocentos anos.'),
(375, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 14, 'OT', 'Também julgarei a nação à qual servirão, e depois sairão com grandes riquezas.'),
(376, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 15, 'OT', 'E tu irás para os teus pais em paz; serás sepultado em boa velhice.'),
(377, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 16, 'OT', 'E a quarta geração voltará para cá, porque a iniquidade dos amorreus não está completa até agora.'),
(378, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 17, 'OT', 'E aconteceu que, posto o sol, houve densas trevas; e eis um forno fumegante e uma tocha de fogo que passou entre aquelas metades.'),
(379, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 18, 'OT', 'Naquele dia o SENHOR fez uma aliança com Abrão, dizendo: À tua descendência dei esta terra, desde o rio do Egito até o grande rio, o rio Eufrates.'),
(380, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 19, 'OT', 'e o queneu, e o quenezeu, e o cadmoneu,'),
(381, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 20, 'OT', 'E os hititas, e os perizeus, e os refains'),
(382, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 15, 21, 'OT', 'e os amorreus, e os cananeus, e os girgaseus, e os jebuseus.'),
(383, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 1, 'OT', 'Ora, Sarai, mulher de Abrão, não lhe havia dado filhos; e ela tinha uma serva egípcia, cujo nome era Hagar.'),
(384, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 2, 'OT', 'Disse Sarai a Abrão: Eis que o SENHOR me impediu de dar à luz; entra, pois, à minha serva, talvez eu venha a ter filhos por meio dela. E Abrão deu ouvidos à voz de Sarai.'),
(385, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 3, 'OT', 'Então Sarai, mulher de Abrão, tomou Hagar, a egípcia, sua serva, e a deu por mulher a Abrão, seu marido, ao fim de dez anos que Abrão habitava na terra de Canaã.'),
(386, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 4, 'OT', 'Ele entrou a Agar, e ela concebeu; e, vendo ela que havia concebido, a sua senhora foi desprezada aos seus olhos.'),
(387, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 5, 'OT', 'Então disse Sarai a Abrão: "Que a minha afronta caia sobre ti! Eu mesma entreguei minha serva aos teus braços, e ela, vendo que concebeu, passou a me desprezar. Que o SENHOR julgue entre mim e ti."'),
(388, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 6, 'OT', 'E disse Abrão a Sarai: Eis que a tua serva está em tua mão; faze-lhe o que for bom aos teus olhos. E Sarai a afligiu, e ela fugiu da sua presença.'),
(389, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 7, 'OT', 'O anjo do SENHOR a encontrou junto a uma fonte de água no deserto, junto à fonte no caminho de Sur.'),
(390, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 8, 'OT', 'E disse: Hagar, serva de Sarai, de onde vens e para onde vais? E ela respondeu: Fujo da presença de Sarai, minha senhora.'),
(391, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 9, 'OT', 'Torna-te à tua senhora e humilha-te sob as suas mãos.'),
(392, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 10, 'OT', 'Disse-lhe o anjo do SENHOR: Multiplicarei sobremaneira a tua descendência, que não será contada, por numerosa que será.'),
(393, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 11, 'OT', 'Disse-lhe o anjo do SENHOR: Eis que concebeste e darás à luz um filho, e chamarás o seu nome Ismael, porque o SENHOR ouviu a tua aflição.'),
(394, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 12, 'OT', 'Ele será um jumento selvagem entre os homens; a sua mão será contra todos, e a mão de todos contra ele; e habitará diante de todos os seus irmãos.'),
(395, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 13, 'OT', 'E ela chamou o nome do SENHOR, que lhe falava: "Tu és Deus que me vê", pois disse: "Acaso não vi aqui aquele que me vê?"'),
(396, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 14, 'OT', 'Por isso se chamou aquele poço de Beer-Lachai-roi; eis que está entre Cades e Berede.'),
(397, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 15, 'OT', 'Hagar deu à luz um filho a Abrão; e Abrão chamou o nome do seu filho, que Hagar dera à luz, Ismael.'),
(398, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 16, 16, 'OT', 'Abrão tinha oitenta e seis anos quando Hagar deu à luz Ismael para Abrão.'),
(399, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 1, 'OT', 'Quando Abrão tinha noventa e nove anos, o SENHOR apareceu a Abrão e lhe disse: Eu sou o Deus Todo-poderoso; anda em minha presença e sê perfeito.'),
(400, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 2, 'OT', 'E estabelecerei a minha aliança entre mim e ti, e te multiplicarei sobremaneira.'),
(401, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 3, 'OT', 'Então caiu Abrão sobre o seu rosto, e Deus falou com ele, dizendo:'),
(402, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 4, 'OT', 'Quanto a mim, eis a minha aliança contigo: tu te tornarás pai de uma multidão de nações.'),
(403, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 5, 'OT', 'E não se chamará mais o teu nome Abrão; mas o teu nome será Abraão, porque por pai de multidão de nações te constituí.'),
(404, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 6, 'OT', 'E te farei frutificar sobremaneira, e de ti farei nações, e reis sairão de ti.'),
(405, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 7, 'OT', 'Estabelecerei a minha aliança entre mim e ti e a tua descendência depois de ti, nas suas gerações, como aliança eterna, para ser o teu Deus e o Deus da tua descendência depois de ti.'),
(406, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 8, 'OT', 'E te darei a ti e à tua descendência depois de ti a terra das tuas peregrinações, toda a terra de Canaã, como possessão perpétua; e serei o seu Deus.'),
(407, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 9, 'OT', 'Disse Deus a Abraão: "Tu, porém, guardarás a minha aliança, tu e a tua descendência depois de ti, nas suas gerações."'),
(408, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 10, 'OT', 'Esta é a minha aliança, que guardareis entre mim e vós e entre a tua descendência depois de ti: todo macho entre vós será circuncidado.'),
(409, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 11, 'OT', 'E circuncidareis a carne do vosso prepúcio; e isto será por sinal da aliança entre mim e vós.'),
(410, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 12, 'OT', 'Todo homem entre vós, de oito dias de idade, será circuncidado, em todas as vossas gerações; tanto o nascido em casa como o comprado com dinheiro de qualquer estrangeiro, que não for da tua descendência.'),
(411, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 13, 'OT', 'Certamente será circuncidado o nascido em tua casa e o comprado com teu dinheiro; e a minha aliança estará na vossa carne como aliança eterna.'),
(412, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 14, 'OT', 'E o incircunciso, o macho que não circuncidar a carne do seu prepúcio, essa pessoa será eliminada do seu povo; ele quebrou a minha aliança.'),
(413, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 15, 'OT', 'Disse Deus a Abraão: "A Sarai, tua mulher, não chamarás pelo nome Sarai; pois Sara será o seu nome."'),
(414, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 16, 'OT', 'E abençoarei a ela, e também dela te darei um filho; e a abençoarei, e ela se tornará nações; reis de povos dela procederão.'),
(415, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 17, 'OT', 'Então Abraão caiu sobre o seu rosto e riu-se, e disse no seu coração: "A um homem de cem anos há de nascer um filho? E Sara, com noventa anos, há de dar à luz?"'),
(416, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 18, 'OT', 'Então Abraão disse a Deus: "Oxalá que Ismael viva diante de ti!"'),
(417, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 19, 'OT', 'Deus disse: "Na verdade, Sara, tua mulher, te dará à luz um filho, e chamarás o seu nome Isaque; e estabelecerei a minha aliança com ele, por aliança eterna, para a sua descendência depois dele."'),
(418, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 20, 'OT', 'E quanto a Ismael, eu te ouvi; eis que o abençoei, e o farei frutificar, e o multiplicarei sobremaneira; doze príncipes ele gerará, e dele farei uma grande nação.'),
(419, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 21, 'OT', 'Mas estabelecerei a minha aliança com Isaque, a quem Sara te dará à luz neste tempo determinado, no ano seguinte.'),
(420, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 22, 'OT', 'E acabou de falar com ele, e Deus subiu de sobre Abraão.'),
(421, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 23, 'OT', 'Então Abraão tomou seu filho Ismael, todos os nascidos em sua casa e todos os comprados com seu dinheiro, todo homem entre os homens da casa de Abraão, e circuncidou a carne do seu prepúcio naquele mesmo dia, conforme Deus lhe havia falado.'),
(422, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 24, 'OT', 'E Abraão tinha noventa e nove anos quando lhe foi circuncidada a carne do seu prepúcio.'),
(423, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 25, 'OT', 'E Ismael, seu filho, tinha treze anos quando foi circuncidado na carne do seu prepúcio.'),
(424, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 26, 'OT', 'Nesse mesmo dia, Abraão foi circuncidado, e Ismael, seu filho.'),
(425, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 17, 27, 'OT', 'E todos os homens da sua casa, tanto os nascidos em casa como os comprados com dinheiro de estrangeiros, foram circuncidados com ele.'),
(426, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 1, 'OT', 'O SENHOR apareceu a Abraão junto aos carvalhos de Manre, enquanto ele estava sentado à entrada da tenda, no calor do dia.'),
(427, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 2, 'OT', 'E levantou os olhos e olhou, e eis que três homens estavam em pé diante dele. Vendo-os, correu da entrada da tenda ao encontro deles e prostrou-se em terra.'),
(428, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 3, 'OT', 'E disse: Senhor, se agora achei graça aos teus olhos, rogo-te que não passes do teu servo.'),
(429, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 4, 'OT', 'Traga-se um pouco de água, lavai os vossos pés e descansai debaixo da árvore.'),
(430, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 5, 'OT', 'E trarei um pedaço de pão, para que revigoreis o vosso coração; depois seguireis adiante, pois por isso chegastes até o vosso servo. E disseram: Faze assim como falaste.'),
(431, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 6, 'OT', 'E Abraão apressou-se para a tenda, a Sara, e disse: Amassa depressa três medidas de flor de farinha, e faze pães.'),
(432, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 7, 'OT', 'E correu Abraão ao gado, e tomou um bezerro tenro e bom, e o deu ao moço, que se apressou em prepará-lo.'),
(433, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 8, 'OT', 'Tomou manteiga e leite, e o novilho que havia preparado, e os pôs diante deles; e ele permanecia em pé junto a eles debaixo da árvore, e eles comeram.'),
(434, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 9, 'OT', 'E disseram-lhe: Onde está Sara, tua mulher? E ele disse: Eis que ela está na tenda.'),
(435, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 10, 'OT', 'E ele disse: Certamente voltarei a ti no tempo da vida, e eis que Sara, tua mulher, terá um filho. E Sara ouvia à porta da tenda, que estava atrás dele.'),
(436, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 11, 'OT', 'Abraão e Sara já eram velhos, avançados em idade; e a Sara havia cessado o costume das mulheres.'),
(437, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 12, 'OT', 'E riu-se Sara dentro de si, dizendo: "Depois de eu ter envelhecido, terei prazer, sendo também o meu senhor velho?"'),
(438, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 13, 'OT', 'E disse o SENHOR a Abraão: Por que se riu Sara, dizendo: Na verdade darei à luz, sendo eu já velha?'),
(439, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 14, 'OT', 'Haveria algo difícil demais para o SENHOR? No tempo determinado voltarei a ti, por este tempo da vida, e Sara terá um filho.'),
(440, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 15, 'OT', 'Então Sara negou, dizendo: "Não me ri", porque teve medo. Mas ele disse: "Não, tu riste."'),
(441, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 16, 'OT', 'Levantaram-se os homens dali e olharam para a face de Sodoma; e Abraão ia com eles para os despedir.'),
(442, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 17, 'OT', 'E disse o SENHOR: Ocultarei eu a Abraão o que faço?'),
(443, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 18, 'OT', 'Visto que Abraão certamente se tornará uma grande e poderosa nação, e por meio dele serão abençoadas todas as nações da terra.'),
(444, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 19, 'OT', 'Porque eu o conheço, para que ele ordene a seus filhos e à sua casa depois dele, e eles guardem o caminho do SENHOR, para praticar justiça e juízo, a fim de que o SENHOR faça vir sobre Abraão o que a respeito dele tem falado.'),
(445, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 20, 'OT', 'Disse o SENHOR: O clamor de Sodoma e Gomorra tem se multiplicado, e o seu pecado tem se agravado muito.'),
(446, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 21, 'OT', 'Descerei agora e verei se praticaram completamente conforme o clamor que chegou a mim; e, se não, sabê-lo-ei.'),
(447, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 22, 'OT', 'Então os homens partiram dali e foram para Sodoma; mas Abraão permaneceu em pé diante do SENHOR.'),
(448, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 23, 'OT', 'E Abraão se aproximou e disse: "Destruirás também o justo com o ímpio?"'),
(449, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 24, 'OT', 'Se houver cinquenta justos no meio da cidade, destruirás também e não pouparás o lugar por causa dos cinquenta justos que estão dentro dela?'),
(450, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 25, 'OT', 'Longe de ti fazer tal coisa: matar o justo com o ímpio, tratando o justo como o ímpio. Longe de ti! O Juiz de toda a terra não faria justiça?'),
(451, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 26, 'OT', 'Então disse o SENHOR: Se eu achar em Sodoma cinquenta justos dentro da cidade, pouparei todo o lugar por causa deles.'),
(452, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 27, 'OT', 'E Abraão respondeu e disse: Eis que agora me atrevi a falar ao SENHOR, ainda que sou pó e cinza.'),
(453, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 28, 'OT', 'Porventura, faltando cinco aos cinquenta justos, destruirás por cinco toda a cidade? E ele disse: Não a destruirei, se eu achar ali quarenta e cinco.'),
(454, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 29, 'OT', 'E continuou ainda a falar-lhe e disse: E se porventura se acharem ali quarenta? E ele disse: Não o farei por causa dos quarenta.'),
(455, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 30, 'OT', 'Ora, não se ire o SENHOR, e eu falarei: talvez se achem ali trinta. E ele disse: Não o farei, se achar ali trinta.'),
(456, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 31, 'OT', 'E disse: Eis que agora me atrevi a falar ao Senhor: talvez se achem ali vinte. E ele disse: Não a destruirei por causa dos vinte.'),
(457, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 32, 'OT', 'Não se ire o SENHOR, que eu fale só mais esta vez: talvez se achem ali dez. E ele disse: Não a destruirei por causa dos dez.'),
(458, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 18, 33, 'OT', 'E o SENHOR foi-se, quando acabou de falar a Abraão; e Abraão voltou ao seu lugar.'),
(459, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 1, 'OT', 'E vieram os dois anjos a Sodoma à tarde, e Ló estava sentado à porta de Sodoma; e, vendo-os Ló, levantou-se para ir ao encontro deles, e inclinou-se com o rosto em terra.'),
(460, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 2, 'OT', 'E ele disse: Eis agora, meus senhores, por favor, vinde à casa de vosso servo, e passai a noite, e lavai os vossos pés; e, levantando-vos cedo, seguireis o vosso caminho. E eles disseram: Não, antes na praça passaremos a noite.'),
(461, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 3, 'OT', 'E porfiou com eles muito, e eles se desviaram para ele, e entraram em sua casa; e lhes fez um banquete, e cozeu pães sem fermento, e comeram.'),
(462, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 4, 'OT', 'Antes que se deitassem, os homens da cidade, os homens de Sodoma, cercaram a casa, desde o jovem até o velho, todo o povo, de todos os lados.'),
(463, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 5, 'OT', 'Chamaram a Lot e lhe disseram: "Onde estão os homens que vieram a você esta noite? Traga-os para fora a nós, para que os conheçamos."'),
(464, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 6, 'OT', 'Saiu, pois, Ló a eles à entrada, e fechou a porta atrás de si.'),
(465, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 7, 'OT', 'Meus irmãos, por favor, não façais mal.'),
(466, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 8, 'OT', 'Eis que tenho duas filhas que ainda não conheceram homem; eu as trarei para fora a vós, e fazei-lhes como for bom aos vossos olhos; somente a estes homens não façais nada, pois por isso vieram à sombra do meu teto.'),
(467, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 9, 'OT', 'E disseram: "Afasta-te!" E disseram: "Este indivíduo veio habitar como estrangeiro, e quer exercer juízo? Agora te faremos pior do que a eles." E pressionaram muito contra o homem, contra Ló, e se aproximaram para arrombar a porta.'),
(468, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 10, 'OT', 'Então os homens estenderam a mão, fizeram Lot entrar para dentro da casa com eles e fecharam a porta.'),
(469, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 11, 'OT', 'E feriram de cegueira os homens que estavam à porta da casa, desde o menor até o maior; e se cansaram de procurar a porta.'),
(470, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 12, 'OT', 'Então os homens disseram a Ló: "Quem mais você tem aqui? Seu genro, seus filhos, suas filhas e tudo o que é seu na cidade, tire-os deste lugar."'),
(471, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 13, 'OT', 'Porque nós vamos destruir este lugar, porque o seu clamor se tornou grande diante do SENHOR, e o SENHOR nos enviou para destruí-lo.'),
(472, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 14, 'OT', 'Levantai-vos, saí deste lugar, porque o SENHOR vai destruir a cidade. Mas aos olhos de seus genros, ele parecia estar zombando.'),
(473, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 15, 'OT', 'E quando a aurora subiu, os anjos apressaram Ló, dizendo: Levanta-te, toma tua mulher e tuas duas filhas que se acham aqui, para que não sejas consumido na iniquidade da cidade.'),
(474, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 16, 'OT', 'Ele, porém, hesitava; então os homens o seguraram pela mão, e pela mão de sua mulher, e pela mão de suas duas filhas, porque o SENHOR teve misericórdia dele; e o tiraram e o puseram fora da cidade.'),
(475, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 17, 'OT', 'E aconteceu que, ao levá-los para fora, disse: Escapa-te por tua vida; não olhes para trás de ti, e não te detenhas em toda a campina; foge para o monte, para que não sejas consumido.'),
(476, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 18, 'OT', 'Ó Senhor, por favor, não!'),
(477, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 19, 'OT', 'Eis que agora o teu servo achou graça aos teus olhos, e engrandeceste a tua bondade que me fizeste, para preservar a minha vida; mas eu não posso fugir para o monte, para que o mal não me alcance, e eu morra.'),
(478, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 20, 'OT', 'Eis que esta cidade está perto para fugir para lá, e é pequena; deixa-me escapar para lá — não é pequena? — para que minha vida seja preservada.'),
(479, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 21, 'OT', 'E ele lhe disse: Eis que também atendi ao teu pedido, para não destruir a cidade de que falaste.'),
(480, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 22, 'OT', 'Apressa-te, escapa para lá, porque nada poderei fazer até que chegues lá. Por isso se chamou o nome da cidade Zoar.'),
(481, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 23, 'OT', 'O sol havia saído sobre a terra, quando Ló entrou em Zoar.'),
(482, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 24, 'OT', 'Então o SENHOR fez chover enxofre e fogo sobre Sodoma e Gomorra, da parte do SENHOR, desde os céus.'),
(483, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 25, 'OT', 'E derrubou aquelas cidades, e toda a planície, e todos os moradores daquelas cidades, e o que brotava da terra.'),
(484, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 26, 'OT', 'E a mulher dele olhou para trás, e tornou-se uma coluna de sal.'),
(485, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 27, 'OT', 'Levantou-se Abraão de manhã cedo, ao lugar onde estivera diante do SENHOR.'),
(486, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 28, 'OT', 'E olhou para Sodoma e Gomorra, e para toda a superfície da terra da planície; e viu, e eis que subia o fumo da terra, como o fumo de uma fornalha.'),
(487, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 29, 'OT', 'E aconteceu que, ao destruir Deus as cidades da planície, Deus se lembrou de Abraão e enviou Ló para fora do meio da destruição, quando derrubou as cidades em que Ló habitava.'),
(488, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 30, 'OT', 'Subiu Ló de Zoar e habitou no monte, e as suas duas filhas com ele; porque temia habitar em Zoar; e habitou numa caverna, ele e as suas duas filhas.'),
(489, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 31, 'OT', 'Então a primogênita disse à mais nova: "Nosso pai é velho, e não há homem na terra que venha até nós, conforme o costume de toda a terra."'),
(490, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 32, 'OT', 'Vem, demos de beber vinho a nosso pai, e deitemo-nos com ele, para que preservemos descendência de nosso pai.'),
(491, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 33, 'OT', 'E deram de beber vinho a seu pai naquela noite; e a primogênita entrou e se deitou com seu pai, e ele não percebeu quando ela se deitou, nem quando se levantou.'),
(492, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 34, 'OT', 'No dia seguinte, a mais velha disse à mais nova: "Ontem à noite eu me deitei com meu pai. Vamos dar-lhe vinho também esta noite, e entra tu, deita-te com ele, para que preservemos descendência de nosso pai."'),
(493, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 35, 'OT', 'E também naquela noite deram de beber vinho a seu pai; e levantou-se a mais nova, e deitou-se com ele; e ele não percebeu quando ela se deitou, nem quando se levantou.'),
(494, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 36, 'OT', 'E conceberam as duas filhas de Ló de seu pai.'),
(495, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 37, 'OT', 'A primogênita deu à luz um filho e chamou o seu nome Moabe; ele é o pai dos moabitas até o dia de hoje.'),
(496, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 19, 38, 'OT', 'E a mais nova também deu à luz um filho, e chamou o seu nome Ben-Ami; ele é o pai dos filhos de Amom até o dia de hoje.'),
(497, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 1, 'OT', 'Partiu Abraão dali para a terra do Neguebe, e habitou entre Cades e Sur; e peregrinou em Gerar.'),
(498, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 2, 'OT', 'E Abraão disse de Sara, sua mulher: "Ela é minha irmã." Então Abimeleque, rei de Gerar, enviou e tomou Sara.'),
(499, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 3, 'OT', 'Deus, porém, veio a Abimeleque em sonho durante a noite e lhe disse: "Eis que você morrerá por causa da mulher que tomou, pois ela é casada com marido."'),
(500, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 4, 'OT', 'Abimeleque não se tinha aproximado dela; por isso disse: Senhor, matarás também uma nação justa?'),
(501, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 5, 'OT', 'Não me disse ele mesmo: "Ela é minha irmã"? E ela também disse: "Ele é meu irmão". Com integridade de coração e com limpeza das minhas mãos tenho feito isto.'),
(502, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 6, 'OT', 'E disse-lhe Deus em sonho: Também eu sei que na sinceridade do teu coração fizeste isto; e também eu te impedi de pecar contra mim; por isso não te permiti tocá-la.'),
(503, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 7, 'OT', 'Agora, pois, devolve a mulher ao homem, porque ele é profeta, e ele orará por ti, e viverás; mas, se não a devolveres, sabe que certamente morrerás, tu e tudo o que é teu.'),
(504, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 8, 'OT', 'Levantou-se Abimeleque de manhã cedo, chamou todos os seus servos e lhes contou todas essas palavras em seus ouvidos; e os homens ficaram muito atemorizados.'),
(505, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 9, 'OT', 'Então Abimeleque chamou Abraão e lhe disse: Que nos fizeste? E em que pequei contra ti, para que trouxesses sobre mim e sobre o meu reino tão grande pecado? Obras que não se fazem, fizeste comigo.'),
(506, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 10, 'OT', 'Que viste, para que fizesses esta coisa?'),
(507, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 11, 'OT', 'E disse Abraão: Porque eu dizia: Certamente não há temor de Deus neste lugar, e eles me matarão por causa da minha mulher.'),
(508, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 12, 'OT', 'E, na verdade, ela é minha irmã, filha de meu pai, mas não filha de minha mãe; e ela se tornou minha esposa.'),
(509, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 13, 'OT', 'E aconteceu que, quando Deus me fez vaguear para longe da casa de meu pai, eu lhe disse: Esta é a bondade que me farás: em todo lugar aonde formos, dize de mim: Ele é meu irmão.'),
(510, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 14, 'OT', 'Então Abimeleque tomou ovelhas e bois, servos e servas, e os deu a Abraão; e devolveu-lhe Sara, sua mulher.'),
(511, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 15, 'OT', 'E disse Abimeleque: Eis que a minha terra está diante de ti; habita onde for bom aos teus olhos.'),
(512, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 16, 'OT', 'E a Sara disse: Eis que dei a teu irmão mil peças de prata; eis que isso te será cobertura de olhos para todos os que estão contigo, e para com todos; e estás corrigida.'),
(513, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 17, 'OT', 'Orou Abraão a Deus, e Deus sarou Abimeleque, e sua mulher, e suas servas, e elas tiveram filhos.'),
(514, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 20, 18, 'OT', 'Porque o SENHOR havia fechado completamente toda madre da casa de Abimeleque, por causa de Sara, mulher de Abraão.'),
(515, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 1, 'OT', 'O SENHOR visitou Sara como havia dito, e o SENHOR fez a Sara conforme havia falado.'),
(516, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 2, 'OT', 'E concebeu Sara e deu à luz a Abraão um filho na sua velhice, no tempo determinado que Deus lhe havia falado.'),
(517, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 3, 'OT', 'Abraão chamou o nome de seu filho que lhe nasceu, o qual Sara lhe deu à luz, Isaque.'),
(518, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 4, 'OT', 'Abraão circuncidou seu filho Isaque, quando este tinha oito dias, conforme Deus lhe havia ordenado.'),
(519, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 5, 'OT', 'Abraão tinha cem anos quando lhe nasceu Isaque, seu filho.'),
(520, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 6, 'OT', 'Disse Sara: "Deus me trouxe riso; todo aquele que ouvir isso se rirá comigo."'),
(521, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 7, 'OT', 'Quem diria a Abraão que Sara amamentaria filhos? Pois lhe dei um filho na sua velhice.'),
(522, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 8, 'OT', 'O menino cresceu e foi desmamado. E Abraão fez um grande banquete no dia em que Isaque foi desmamado.'),
(523, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 9, 'OT', 'Viu Sara o filho de Hagar, a egípcia, que ela dera a Abraão, rindo.'),
(524, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 10, 'OT', 'E ela disse a Abraão: Expulsa esta serva e o seu filho, porque o filho desta serva não herdará com o meu filho, com Isaque.'),
(525, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 11, 'OT', 'E este assunto foi muito desagradável aos olhos de Abraão, por causa de seu filho.'),
(526, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 12, 'OT', 'Deus disse a Abraão: "Não te pareça mal aos teus olhos por causa do menino e por causa da tua serva; ouve tudo o que Sara te disser, porque em Isaque será chamada a tua descendência."'),
(527, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 13, 'OT', 'Também farei do filho da serva uma nação, porque ele é da tua descendência.'),
(528, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 14, 'OT', 'Levantou-se Abraão de madrugada, tomou pão e um odre de água, e os deu a Hagar, pondo-os sobre o seu ombro, e também o menino, e despediu-a. Ela partiu e andou errante pelo deserto de Berseba.'),
(529, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 15, 'OT', 'E acabou a água do odre, e ela lançou o menino debaixo de um dos arbustos.'),
(530, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 16, 'OT', 'E foi, e assentou-se em frente, afastando-se à distância de um tiro de arco; porque dizia: Não verei a morte do menino. E assentou-se em frente, e levantou a sua voz, e chorou.'),
(531, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 17, 'OT', 'E Deus ouviu a voz do menino, e o anjo de Deus chamou Hagar desde o céu e lhe disse: Que há contigo, Hagar? Não temas, porque Deus ouviu a voz do menino no lugar onde ele está.'),
(532, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 18, 'OT', 'Ergue-te, levanta o menino e segura-o pela mão, porque dele farei uma grande nação.'),
(533, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 19, 'OT', 'Deus lhe abriu os olhos, e ela viu um poço de água. Então foi, encheu o odre de água e deu de beber ao menino.'),
(534, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 20, 'OT', 'Deus estava com o jovem, e ele cresceu; habitou no deserto e tornou-se arqueiro.'),
(535, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 21, 'OT', 'E habitou no deserto de Parã; e sua mãe tomou-lhe uma mulher da terra do Egito.'),
(536, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 22, 'OT', 'Aconteceu naquele tempo que Abimeleque, com Ficol, comandante do seu exército, falou a Abraão, dizendo: Deus está contigo em tudo o que fazes.'),
(537, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 23, 'OT', 'Agora, pois, jura-me aqui por Deus que não me enganarás, nem a meu filho, nem a meu neto; segundo a bondade que te fiz, farás comigo e com a terra onde peregrinaste.'),
(538, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 24, 'OT', 'Eu jurarei, disse Abraão.'),
(539, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 25, 'OT', 'Abraão repreendeu Abimeleque por causa do poço de água que os servos de Abimeleque haviam tomado à força.'),
(540, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 26, 'OT', 'Então Abimeleque disse: "Não sei quem fez isso; e também tu não me contaste, nem eu ouvi falar disso senão hoje."'),
(541, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 27, 'OT', 'Tomou Abraão ovelhas e bois, e deu-os a Abimeleque; e fizeram ambos uma aliança.'),
(542, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 28, 'OT', 'E Abraão separou sete cordeiras do rebanho à parte.'),
(543, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 29, 'OT', 'E Abimeleque disse a Abraão: Que são estas sete cordeiras que puseste à parte?'),
(544, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 30, 'OT', 'E ele respondeu: "Toma estas sete cordeiras da minha mão, para que me sirvam de testemunho de que eu cavei este poço."'),
(545, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 31, 'OT', 'Por isso chamou aquele lugar de Berseba, porque ali ambos juraram.'),
(546, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 32, 'OT', 'Fizeram, pois, aliança em Berseba. Então Abimeleque e Ficol, comandante do seu exército, levantaram-se e voltaram para a terra dos filisteus.'),
(547, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 33, 'OT', 'E plantou uma tamargueira em Berseba, e ali invocou o nome do SENHOR, o Deus Eterno.'),
(548, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 21, 34, 'OT', 'E peregrinou Abraão na terra dos filisteus muitos dias.'),
(549, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 1, 'OT', 'E aconteceu depois destas coisas que Deus provou Abraão, e lhe disse: Abraão! E ele respondeu: Eis-me aqui.'),
(550, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 2, 'OT', 'Toma agora o teu filho, o teu único, Isaque, a quem amas, e vai à terra de Moriá; e oferece-o ali em holocausto sobre um dos montes, que eu te direi.'),
(551, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 3, 'OT', 'Levantou-se Abraão de madrugada, albardou o seu jumento, tomou consigo dois dos seus servos e Isaque, seu filho; e, tendo cortado lenha para o holocausto, levantou-se e foi ao lugar que Deus lhe havia indicado.'),
(552, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 4, 'OT', 'No terceiro dia, Abraão levantou os olhos e viu o lugar de longe.'),
(553, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 5, 'OT', 'Abraão disse aos seus servos: Ficai-vos aqui com o jumento, e eu e o jovem iremos até ali; e, havendo adorado, voltaremos a vós.'),
(554, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 6, 'OT', 'Abraão tomou a lenha do holocausto e a colocou sobre Isaque, seu filho; e tomou na sua mão o fogo e o cutelo; e foram ambos juntos.'),
(555, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 7, 'OT', 'Isaque disse a Abraão, seu pai: "Meu pai!" E ele respondeu: "Eis-me aqui, meu filho." E Isaque disse: "Eis o fogo e a lenha, mas onde está o cordeiro para o holocausto?"'),
(556, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 8, 'OT', 'Disse Abraão: Deus proverá para si o cordeiro para o holocausto, meu filho. E os dois seguiram juntos.'),
(557, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 9, 'OT', 'E chegaram ao lugar que Deus lhe havia dito; e ali edificou Abraão o altar, e dispôs a lenha, e amarrou a Isaque, seu filho, e o pôs sobre o altar, por cima da lenha.'),
(558, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 10, 'OT', 'Estendeu Abraão a sua mão e tomou o cutelo para sacrificar o seu filho.'),
(559, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 11, 'OT', 'Então o anjo do SENHOR chamou do céu: "Abraão, Abraão!" E ele respondeu: "Eis-me aqui."'),
(560, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 12, 'OT', 'Não estendas a tua mão contra o jovem e não lhe faças nada; pois agora sei que temes a Deus, visto que não me negaste o teu filho, o teu único.'),
(561, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 13, 'OT', 'Levantou Abraão os olhos e olhou, e eis um carneiro preso pelos chifres num arbusto; e foi Abraão, tomou o carneiro e o ofereceu em holocausto em lugar de seu filho.'),
(562, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 14, 'OT', 'E chamou Abraão o nome daquele lugar: O SENHOR proverá; por isso se diz até hoje: No monte do SENHOR se proverá.'),
(563, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 15, 'OT', 'E o anjo do SENHOR chamou a Abraão pela segunda vez desde os céus,'),
(564, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 16, 'OT', '"Por mim mesmo jurei", declara o SENHOR, "que, porquanto fizeste isto e não retiveste o teu filho, o teu único,'),
(565, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 17, 'OT', 'Certamente te abençoarei e multiplicarei grandemente a tua descendência como as estrelas dos céus e como a areia que está na praia do mar; e a tua descendência possuirá a porta dos seus inimigos.'),
(566, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 18, 'OT', 'E em tua descendência serão abençoadas todas as nações da terra, porque obedeceste à minha voz.'),
(567, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 19, 'OT', 'Então Abraão voltou aos seus servos, e eles se levantaram e foram juntos para Berseba; e Abraão habitou em Berseba.'),
(568, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 20, 'OT', 'E aconteceu depois destas coisas que foi anunciado a Abraão: Eis que Milca também deu à luz filhos a Naor, teu irmão.'),
(569, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 21, 'OT', 'Uz, seu primogênito, e Buz, seu irmão, e Quemuel, pai de Arã.'),
(570, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 22, 'OT', 'e Quessede, e Hazo, e Pildas, e Jidlafe, e Betuel.'),
(571, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 23, 'OT', 'E Betuel gerou Rebeca; esses oito deu à luz Milca a Naor, irmão de Abraão.'),
(572, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 22, 24, 'OT', 'E a sua concubina, cujo nome era Reumá, também deu à luz a Tebá, Gaã, Taás e Maacá.'),
(573, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 1, 'OT', 'A vida de Sara foi de cento e vinte e sete anos; esses foram os anos da vida de Sara.'),
(574, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 2, 'OT', 'Sara morreu em Kiriath-arba, que é Hebrom, na terra de Canaã; e Abraão veio lamentar por Sara e chorar por ela.'),
(575, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 3, 'OT', 'Levantou-se Abraão de diante do seu morto e falou aos filhos de Hete, dizendo:'),
(576, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 4, 'OT', 'Sou estrangeiro e peregrino entre vós; dai-me uma propriedade de sepultura convosco, para que eu sepulte o meu morto de diante de mim.'),
(577, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 5, 'OT', 'E os filhos de Hete responderam a Abraão, dizendo-lhe:'),
(578, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 6, 'OT', 'Ouve-nos, meu senhor; príncipe de Deus és tu no meio de nós; na mais escolhida de nossas sepulturas enterra o teu morto; nenhum de nós te impedirá a sua sepultura, para enterrares o teu morto.'),
(579, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 7, 'OT', 'Levantou-se Abraão e inclinou-se diante do povo da terra, diante dos filhos de Hete.'),
(580, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 8, 'OT', 'E falou com eles, dizendo: Se é de vosso agrado que eu sepulte o meu morto de diante de mim, ouvi-me e intercedei por mim junto a Efrom, filho de Zoar.'),
(581, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 9, 'OT', 'que ele me dê a caverna de Macpela, que lhe pertence, que está na extremidade do seu campo; que ma dê pelo seu justo valor em dinheiro, para posse de sepultura no meio de vocês.'),
(582, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 10, 'OT', 'E Efrom, o hitita, estava sentado no meio dos filhos de Hete; e respondeu Efrom, o hitita, a Abraão, aos ouvidos dos filhos de Hete, de todos os que entravam pela porta da sua cidade, dizendo:'),
(583, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 11, 'OT', 'Não, meu senhor, ouve-me: o campo eu te dou, e a cova que nele está, a ti a dou; diante dos filhos do meu povo eu a dou a ti; sepulta o teu morto.'),
(584, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 12, 'OT', 'Então Abraão se prostrou diante do povo da terra.'),
(585, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 13, 'OT', 'Falou a Efrom, aos ouvidos do povo da terra, dizendo: "Se tu me ouvires, por favor, eu te dou o preço do campo; toma-o de mim, e ali sepultarei o meu morto."'),
(586, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 14, 'OT', 'Efron respondeu a Abraão, dizendo-lhe:'),
(587, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 15, 'OT', 'Meu senhor, ouve-me: a terra vale quatrocentos siclos de prata; que é isso entre mim e ti? Sepulta o teu morto.'),
(588, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 16, 'OT', 'Abraão ouviu Efrom, e Abraão pesou para Efrom a prata de que tinha falado aos ouvidos dos filhos de Hete: quatrocentos siclos de prata, corrente entre os mercadores.'),
(589, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 17, 'OT', 'Assim o campo de Efrom, que estava em Macpela, em frente de Manre, o campo e a caverna que nele havia, e todas as árvores que estavam no campo, em todo o seu limite ao redor,'),
(590, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 18, 'OT', 'a Abraão, como propriedade, diante dos olhos dos filhos de Hete, entre todos os que entravam pelo portão da sua cidade.'),
(591, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 19, 'OT', 'E depois disso, Abraão sepultou Sara, sua mulher, na caverna do campo de Macpela, diante de Manre, que é Hebrom, na terra de Canaã.'),
(592, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 23, 20, 'OT', 'Assim o campo e a caverna que nele estava foram confirmados a Abraão como possessão para sepultura, da parte dos filhos de Hete.'),
(593, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 1, 'OT', 'E Abraão era velho, avançado em dias, e o SENHOR havia abençoado Abraão em tudo.'),
(594, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 2, 'OT', 'E disse Abraão ao seu servo, o mais velho da sua casa, que governava tudo o que possuía: Põe agora a tua mão debaixo da minha coxa.'),
(595, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 3, 'OT', 'E jurarei por ti pelo SENHOR, Deus dos céus e Deus da terra, que não tomarás esposa para meu filho das filhas dos cananeus, em cujo meio eu habito.'),
(596, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 4, 'OT', 'mas irás à minha terra e à minha parentela, e tomarás uma esposa para meu filho Isaque.'),
(597, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 5, 'OT', 'E o servo lhe disse: Talvez a mulher não queira vir comigo para esta terra; devo eu levar teu filho de volta à terra de onde saíste?'),
(598, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 6, 'OT', 'Guarda-te, não faças voltar o meu filho para lá.'),
(599, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 7, 'OT', 'O SENHOR, Deus dos céus, que me tomou da casa de meu pai e da terra da minha parentela, e que me falou e me jurou, dizendo: "À tua descendência darei esta terra", ele enviará o seu anjo adiante de ti, e tomarás uma mulher para meu filho de lá.'),
(600, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 8, 'OT', 'Se a mulher, porém, não quiser seguir-te, ficarás livre deste meu juramento; somente não faças voltar meu filho para lá.'),
(601, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 9, 'OT', 'Então o servo pôs a mão debaixo da coxa de Abraão, seu senhor, e jurou-lhe acerca deste assunto.'),
(602, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 10, 'OT', 'O servo tomou dez camelos dos camelos do seu senhor e partiu, levando consigo todos os bens do seu senhor. Levantou-se e foi para Arã-Naaraim, à cidade de Naor.'),
(603, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 11, 'OT', 'E fez ajoelhar os camelos fora da cidade, junto ao poço de água, à hora da tarde, à hora em que as moças saem a tirar água.'),
(604, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 12, 'OT', 'Ó SENHOR, Deus do meu senhor Abraão, faze-me encontrar hoje o que busco e concede bondade ao meu senhor Abraão.'),
(605, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 13, 'OT', 'Eis que estou em pé junto à fonte de água, e as filhas dos homens da cidade saem para tirar água.'),
(606, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 14, 'OT', 'Que a jovem a quem eu disser: "Inclina o teu cântaro para que eu beba", e ela responder: "Bebe, e também darei de beber aos teus camelos", seja essa a que designaste para o teu servo Isaque; e por isso saberei que fizeste bondade ao meu senhor.'),
(607, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 15, 'OT', 'Antes de ele terminar de falar, eis que Rebeca saía, a qual havia nascido a Betuel, filho de Milca, mulher de Naor, irmão de Abraão, e o seu cântaro estava sobre o seu ombro.'),
(608, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 16, 'OT', 'A jovem era muito bela de aparência, virgem, a quem nenhum homem havia conhecido. Ela desceu à fonte, encheu o seu cântaro e subiu.'),
(609, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 17, 'OT', 'E o servo correu ao encontro dela e disse: Deixa-me beber um pouco de água do teu cântaro.'),
(610, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 18, 'OT', 'E ela disse: "Bebe, meu senhor." E apressou-se, e baixou o seu cântaro sobre a sua mão, e deu-lhe de beber.'),
(611, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 19, 'OT', 'E, tendo acabado de lhe dar de beber, disse: Também tirarei água para os teus camelos, até que acabem de beber.'),
(612, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 20, 'OT', 'E ela se apressou, e esvaziou o seu cântaro no bebedouro, e correu outra vez ao poço para tirar água, e tirou para todos os seus camelos.'),
(613, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 21, 'OT', 'E o homem a observava em silêncio, para saber se o SENHOR havia prosperado a sua jornada ou não.'),
(614, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 22, 'OT', 'Quando os camelos terminaram de beber, o homem tomou um pendente de ouro de meio siclo de peso, e duas pulseiras para as mãos dela, de dez siclos de ouro de peso.'),
(615, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 23, 'OT', 'De quem és filha? Peço-te, dize-me: há lugar na casa de teu pai para nos hospedarmos?'),
(616, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 24, 'OT', 'E ela lhe disse: "Sou filha de Betuel, filho de Milca, a qual ela deu à luz a Naor."'),
(617, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 25, 'OT', 'Disse-lhe: Também temos palha e muito forragem, e lugar para passar a noite.'),
(618, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 26, 'OT', 'Então o homem inclinou-se e prostrou-se diante do SENHOR.'),
(619, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 27, 'OT', 'Bendito seja o SENHOR, Deus do meu senhor Abraão, que não retirou a sua bondade e a sua verdade do meu senhor; quanto a mim, o SENHOR me guiou no caminho à casa dos irmãos do meu senhor.'),
(620, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 28, 'OT', 'A jovem correu e contou à casa de sua mãe estas coisas.'),
(621, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 29, 'OT', 'E Rebeca tinha um irmão, cujo nome era Labão; e Labão correu ao encontro do homem, para fora, até a fonte.'),
(622, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 30, 'OT', 'E quando ele viu o pendente e as pulseiras nas mãos de sua irmã, e ouviu as palavras de Rebeca, sua irmã, que dizia: Assim me falou aquele homem, ele foi até o homem, e eis que ele estava em pé junto aos camelos, perto da fonte.'),
(623, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 31, 'OT', 'Entra, bendito do SENHOR; por que ficas fora? Pois já preparei a casa e lugar para os camelos.'),
(624, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 32, 'OT', 'Então o homem entrou na casa, e desatou os camelos, e deu palha e forragem aos camelos, e água para lavar os seus pés e os pés dos homens que estavam com ele.'),
(625, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 33, 'OT', 'Puseram comida diante dele para comer; porém ele disse: "Não comerei até que eu tenha dito as minhas palavras." E ele disse: "Fala."'),
(626, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 34, 'OT', 'Sou servo de Abraão.'),
(627, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 35, 'OT', 'O SENHOR abençoou muito o meu senhor, e ele se tornou grande; e deu-lhe ovelhas e bois, e prata e ouro, e servos e servas, e camelos e jumentos.'),
(628, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 36, 'OT', 'E Sara, mulher do meu senhor, deu à luz um filho ao meu senhor depois da sua velhice, e ele lhe deu tudo o que tinha.'),
(629, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 37, 'OT', 'Meu senhor me fez jurar, dizendo: Não tomarás mulher para meu filho das filhas dos cananeus, em cuja terra habito.'),
(630, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 38, 'OT', 'Mas irás à casa de meu pai e à minha parentela, e tomarás uma esposa para meu filho.'),
(631, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 39, 'OT', 'Então disse eu ao meu senhor: Talvez a mulher não queira vir comigo.'),
(632, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 40, 'OT', 'Ele me respondeu: ''O SENHOR, em cuja presença tenho andado, enviará o seu anjo contigo e prosperará o teu caminho, para que tomes mulher para meu filho da minha família e da casa de meu pai.'''),
(633, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 41, 'OT', 'Então estarás livre do meu juramento, quando fores à minha família; e se não te derem, estarás livre do meu juramento.'),
(634, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 42, 'OT', 'E hoje cheguei à fonte e disse: Ó SENHOR, Deus de meu senhor Abraão, se agora prosperas o meu caminho, no qual eu ando,'),
(635, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 43, 'OT', 'Eis que estou em pé junto à fonte de água; e quando a jovem sair para tirar água, e eu lhe disser: Dá-me, por favor, um pouco de água do teu cântaro,'),
(636, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 44, 'OT', 'E ela me disser: Bebe tu também, e também tirarei água para os teus camelos; esta é a mulher que o SENHOR designou para o filho de meu senhor.'),
(637, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 45, 'OT', 'Antes de eu terminar de falar em meu coração, eis que Rebeca saía com o seu cântaro sobre o ombro, e desceu à fonte, e tirou água; e eu lhe disse: Dá-me de beber, por favor.'),
(638, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 46, 'OT', 'E ela se apressou e abaixou o seu cântaro de sobre si, e disse: Bebe, e também darei de beber aos teus camelos; e eu bebi, e ela também deu de beber aos camelos.'),
(639, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 47, 'OT', 'Então lhe perguntei e disse: De quem és filha? E ela respondeu: Sou filha de Betuel, filho de Naor, que Milca lhe deu à luz. Então coloquei o pendente em seu nariz e as pulseiras em suas mãos.'),
(640, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 48, 'OT', 'E curvei-me e prostrei-me diante do SENHOR, e bendisse ao SENHOR, Deus do meu senhor Abraão, que me guiou pelo caminho da verdade, para tomar a filha do irmão do meu senhor para seu filho.'),
(641, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 49, 'OT', 'Agora, se vocês vão tratar o meu senhor com bondade e fidelidade, declarem-me isso; e se não, digam-me também, para que eu me volte para a direita ou para a esquerda.'),
(642, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 50, 'OT', 'Então Labão e Betuel responderam e disseram: "Do SENHOR saiu este assunto; não podemos falar-te mal ou bem."'),
(643, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 51, 'OT', 'Eis que Rebeca está diante de ti; toma-a e vai-te, e seja ela mulher do filho de teu senhor, como falou o SENHOR.'),
(644, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 52, 'OT', 'E, ouvindo o servo de Abraão as suas palavras, prostrou-se em terra diante do SENHOR.'),
(645, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 53, 'OT', 'O servo trouxe joias de prata e joias de ouro, e vestes, e as deu a Rebeca; também deu presentes valiosos ao irmão dela e à sua mãe.'),
(646, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 54, 'OT', 'Comeram e beberam, ele e os homens que estavam com ele, e passaram a noite. Levantaram-se pela manhã, e ele disse: Deixai-me ir ao meu senhor.'),
(647, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 55, 'OT', 'Então disseram seu irmão e sua mãe: Fique a jovem conosco alguns dias, ou pelo menos dez; depois irá.'),
(648, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 56, 'OT', 'Não me detenhais, pois o SENHOR tem prosperado o meu caminho; deixai-me partir, para que eu volte ao meu senhor.'),
(649, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 57, 'OT', 'E disseram: Chamemos a jovem e perguntemos-lhe a sua opinião.'),
(650, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 58, 'OT', 'E chamaram Rebeca e lhe disseram: "Irás com este homem?" Ela respondeu: "Irei."'),
(651, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 59, 'OT', 'Despediram Rebeca, sua irmã, e sua ama, e o servo de Abraão, e os seus homens.'),
(652, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 60, 'OT', 'E abençoaram Rebeca e lhe disseram: "Nossa irmã, que te tornes milhares de miríades, e que a tua descendência possua a porta dos seus inimigos."'),
(653, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 61, 'OT', 'Rebeca se levantou com suas servas, montaram nos camelos e seguiram o homem. O servo tomou Rebeca e partiu.'),
(654, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 62, 'OT', 'Isaque vinha do caminho do poço de Lahai-roi, pois habitava na terra do Neguebe.'),
(655, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 63, 'OT', 'Saiu Isaque ao campo ao entardecer para meditar; ergueu os olhos e viu: eis que camelos se aproximavam.'),
(656, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 64, 'OT', 'Levantou Rebeca os olhos e viu Isaque, e desceu do camelo.'),
(657, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 65, 'OT', 'E ela disse ao servo: "Quem é aquele homem que vem pelo campo ao nosso encontro?" E o servo disse: "Ele é meu senhor." Então ela tomou o véu e cobriu-se.'),
(658, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 66, 'OT', 'O servo contou a Isaque todas as coisas que havia feito.'),
(659, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 24, 67, 'OT', 'E Isaque a levou para a tenda de Sara, sua mãe, e tomou Rebeca, e ela se tornou sua mulher, e ele a amou. E Isaque foi consolado depois da morte de sua mãe.'),
(660, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 1, 'OT', 'E Abraão tomou outra mulher, e o seu nome era Quetura.'),
(661, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 2, 'OT', 'E ela lhe deu à luz Zimran, Jocsã, Medã, Midiã, Isbaque e Suá.'),
(662, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 3, 'OT', 'E Jocsã gerou Seba e Dedã; e os filhos de Dedã foram Assurim, Letusim e Leumim.'),
(663, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 4, 'OT', 'Os filhos de Midiã: Efá, Efer, Enoque, Abida e Elda. Todos estes foram filhos de Quetura.'),
(664, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 5, 'OT', 'Abraão deu tudo o que possuía a Isaque.'),
(665, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 6, 'OT', 'Aos filhos das concubinas que Abraão tinha, Abraão deu presentes; e, ainda em vida, enviou-os para longe de seu filho Isaque, para a terra oriental.'),
(666, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 7, 'OT', 'Estes são os dias dos anos da vida de Abraão, que viveu cento e setenta e cinco anos.'),
(667, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 8, 'OT', 'E Abraão expirou e morreu em boa velhice, velho e satisfeito; e foi reunido ao seu povo.'),
(668, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 9, 'OT', 'E sepultaram-no Isaque e Ismael, seus filhos, na caverna de Macpela, no campo de Efrom, filho de Zoar, o hitita, que está diante de Manre.'),
(669, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 10, 'OT', 'O campo que Abraão comprou dos filhos de Hete; ali foi sepultado Abraão, e Sara, sua mulher.'),
(670, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 11, 'OT', 'E aconteceu depois da morte de Abraão, que Deus abençoou a Isaque, seu filho; e Isaque habitava junto ao poço de Lahai-roi.'),
(671, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 12, 'OT', 'Estas são as gerações de Ismael, filho de Abraão, que Hagar, a egípcia, serva de Sara, deu à luz a Abraão.'),
(672, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 13, 'OT', 'Estes são os nomes dos filhos de Ismael, pelos seus nomes, segundo as suas gerações: o primogênito de Ismael, Nebaiote; depois Quedar, Adbeel e Mibsão.'),
(673, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 14, 'OT', 'E Misma, Dumá e Massá.'),
(674, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 15, 'OT', 'Hadade, Tema, Jetur, Nafis e Quedemá.'),
(675, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 16, 'OT', 'Estes são os filhos de Ismael, e estes são os seus nomes pelas suas vilas e pelos seus acampamentos: doze príncipes conforme as suas tribos.'),
(676, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 17, 'OT', 'Estes são os anos da vida de Ismael: cento e trinta e sete anos. Ele expirou e morreu, e foi reunido ao seu povo.'),
(677, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 18, 'OT', 'E habitaram desde Havilá até Sur, que está diante do Egito, indo para Assíria; e ele se estabeleceu diante de todos os seus irmãos.'),
(678, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 19, 'OT', 'Estas são as gerações de Isaque, filho de Abraão: Abraão gerou a Isaque.'),
(679, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 20, 'OT', 'Isaque tinha quarenta anos quando tomou Rebeca, filha de Betuel, o arameu de Paddan-aram, irmã de Labão, o arameu, por sua mulher.'),
(680, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 21, 'OT', 'Isaque orou ao SENHOR em favor de sua mulher, porque ela era estéril; e o SENHOR o atendeu, e Rebeca, sua mulher, concebeu.'),
(681, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 22, 'OT', 'Os filhos lutavam dentro dela, e ela disse: "Se assim é, por que estou viva?" Então foi consultar o SENHOR.'),
(682, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 23, 'OT', 'E o SENHOR lhe disse: Duas nações estão no teu ventre, e dois povos se separarão das tuas entranhas; um povo será mais forte que o outro, e o mais velho servirá ao mais novo.'),
(683, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 24, 'OT', 'E cumpriram-se os seus dias para dar à luz, e eis que havia gêmeos no seu ventre.'),
(684, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 25, 'OT', 'O primeiro saiu ruivo, todo ele como um manto de pelos; por isso chamaram o seu nome Esaú.'),
(685, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 26, 'OT', 'Depois saiu o seu irmão, com a mão agarrada ao calcanhar de Esaú; por isso lhe chamaram Jacó. Isaque tinha sessenta anos quando eles nasceram.'),
(686, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 27, 'OT', 'E cresceram os meninos; e Esaú foi homem perito na caça, homem do campo; e Jacó, homem íntegro, habitava em tendas.'),
(687, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 28, 'OT', 'Isaque amava Esaú, porque a caça era do seu agrado; mas Rebeca amava Jacó.'),
(688, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 29, 'OT', 'Jacó cozinhou um guisado, e Esaú veio do campo, estando ele exausto.'),
(689, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 30, 'OT', 'Disse Esaú a Jacó: Deixa-me, por favor, comer desse guisado vermelho, porque estou exausto. Por isso chamou-se o seu nome Edom.'),
(690, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 31, 'OT', 'Jacó disse: Vende-me hoje a tua primogenitura.'),
(691, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 32, 'OT', 'E disse Esaú: Eis que estou a ponto de morrer; e para que me servirá a primogenitura?'),
(692, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 33, 'OT', 'Jura-me hoje. E jurou-lhe, e vendeu a sua primogenitura a Jacó.'),
(693, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 25, 34, 'OT', 'E Jacó deu a Esaú pão e guisado de lentilhas; e ele comeu e bebeu, levantou-se e seguiu seu caminho. Assim Esaú desprezou a primogenitura.'),
(694, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 1, 'OT', 'Houve fome na terra, além da primeira fome que ocorreu nos dias de Abraão; e Isaque foi a Abimeleque, rei dos filisteus, em Gerar.'),
(695, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 2, 'OT', 'Apareceu-lhe o SENHOR e disse: Não desças ao Egito; habita na terra que eu te disser.'),
(696, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 3, 'OT', 'Peregrina nesta terra, e serei contigo e te abençoarei; porque a ti e à tua descendência darei todas estas terras, e confirmarei o juramento que jurei a Abraão, teu pai.'),
(697, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 4, 'OT', 'E multiplicarei a tua descendência como as estrelas dos céus, e darei à tua descendência todas estas terras; e em tua descendência serão abençoadas todas as nações da terra.'),
(698, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 5, 'OT', 'Porque Abraão obedeceu à minha voz e guardou o meu mandado, os meus preceitos, os meus estatutos e as minhas leis.'),
(699, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 6, 'OT', 'Isaque habitou em Gerar.'),
(700, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 7, 'OT', 'Os homens daquele lugar perguntaram-lhe acerca de sua mulher, e ele disse: "É minha irmã"; porque temia dizer: "É minha mulher", pensando: "Para que não me matem os homens daquele lugar por causa de Rebeca, pois ela era formosa de aparência."'),
(701, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 8, 'OT', 'E aconteceu que, passado muito tempo ali, Abimeleque, rei dos filisteus, olhou pela janela e viu, e eis que Isaque estava brincando com Rebeca, sua mulher.'),
(702, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 9, 'OT', 'Então Abimeleque chamou Isaque e disse: "Certamente ela é tua mulher! Como pudeste dizer: ''Ela é minha irmã''?" E Isaque lhe respondeu: "Porque pensei: ''Para que eu não morra por causa dela''."'),
(703, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 10, 'OT', 'E disse Abimeleque: Que é isto que nos fizeste? Por pouco um do povo não se deitou com tua mulher, e tu terias trazido sobre nós culpa.'),
(704, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 11, 'OT', 'E Abimeleque ordenou a todo o povo, dizendo: Aquele que tocar neste homem ou em sua mulher certamente será morto.'),
(705, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 12, 'OT', 'Isaque semeou naquela terra e, naquele mesmo ano, colheu cem medidas, porque o SENHOR o abençoou.'),
(706, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 13, 'OT', 'E o homem se engrandeceu, e ia crescendo cada vez mais, até que se tornou muito grande.'),
(707, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 14, 'OT', 'Tinha ele rebanhos de ovelhas e rebanhos de gado, e muita gente de serviço; por isso os filisteus o invejavam.'),
(708, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 15, 'OT', 'Todos os poços que os servos de seu pai haviam cavado nos dias de Abraão, seu pai, os filisteus entupiram e encheram de terra.'),
(709, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 16, 'OT', 'Aparta-te de nós, pois te tornaste muito mais poderoso do que nós.'),
(710, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 17, 'OT', 'Partiu Isaque dali, acampou no vale de Gerar e habitou ali.'),
(711, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 18, 'OT', 'Isaque tornou a cavar os poços de água que haviam sido cavados nos dias de Abraão, seu pai, e que os filisteus tinham entupido depois da morte de Abraão; e deu-lhes os mesmos nomes que seu pai lhes havia dado.'),
(712, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 19, 'OT', 'Os servos de Isaque cavaram no vale e encontraram ali um poço de águas vivas.'),
(713, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 20, 'OT', 'Os pastores de Gerar contenderam com os pastores de Isaque, dizendo: "A água é nossa". Por isso, ele chamou o poço de Eseque, porque contenderam com ele.'),
(714, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 21, 'OT', 'Cavaram outro poço, e também contenderam por causa dele; por isso chamou o seu nome Sitna.'),
(715, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 22, 'OT', 'E partiu dali, e cavou outro poço, e não contenderam por ele; e chamou-lhe Reobote, e disse: Porque agora o SENHOR nos deu espaço, e prosperamos nesta terra.'),
(716, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 23, 'OT', 'Subiu dali a Berseba.'),
(717, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 24, 'OT', 'Naquela noite o SENHOR lhe apareceu e disse: "Eu sou o Deus de Abraão, teu pai. Não temas, porque eu estou contigo; eu te abençoarei e multiplicarei a tua descendência por amor de Abraão, meu servo."'),
(718, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 25, 'OT', 'Então edificou ali um altar e invocou o nome do SENHOR, e armou ali a sua tenda; e os servos de Isaque cavaram ali um poço.'),
(719, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 26, 'OT', 'E Abimeleque foi até ele desde Gerar, com Auzate, seu amigo, e Ficol, comandante do seu exército.'),
(720, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 27, 'OT', 'E disse-lhes Isaque: Por que viestes a mim, se vós me odiais e me expulsastes de vós?'),
(721, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 28, 'OT', 'E disseram: "Vimos claramente que o SENHOR está contigo; por isso dissemos: Haja agora um juramento entre nós, entre nós e ti; e façamos aliança contigo.'),
(722, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 29, 'OT', 'Jura-nos que não nos farás mal, assim como nós não te tocamos e te tratamos somente com bondade, e te deixamos ir em paz. Agora tu és o bendito do SENHOR.'),
(723, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 30, 'OT', 'Então lhes preparou um banquete, e comeram e beberam.'),
(724, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 31, 'OT', 'Levantaram-se de madrugada e juraram um ao outro; então Isaque os despediu, e eles partiram dele em paz.'),
(725, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 32, 'OT', 'Naquele mesmo dia, os servos de Isaque vieram e lhe anunciaram a respeito do poço que tinham cavado, e disseram-lhe: "Achamos água."'),
(726, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 33, 'OT', 'E chamou-a Seba; por isso o nome da cidade é Berseba até o dia de hoje.'),
(727, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 34, 'OT', 'Esaú tinha quarenta anos quando tomou por mulher Judite, filha de Beeri, o hitita, e também Basemate, filha de Elom, o hitita.'),
(728, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 26, 35, 'OT', 'E foram uma amargura de espírito para Isaque e para Rebeca.'),
(729, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 1, 'OT', 'E aconteceu que, quando Isaque envelheceu, e os seus olhos se escureceram, de modo que não podia ver, chamou a Esaú, seu filho mais velho, e disse-lhe: Meu filho. E ele lhe respondeu: Eis-me.'),
(730, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 2, 'OT', 'Eis que já estou velho e não sei o dia da minha morte.'),
(731, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 3, 'OT', 'Agora, toma as tuas armas, a tua aljava e o teu arco, e sai ao campo, e caça para mim alguma caça.'),
(732, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 4, 'OT', 'Faze-me um prato saboroso, como eu amo, e traze-mo, para que eu coma; para que a minha alma te abençoe, antes que eu morra.'),
(733, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 5, 'OT', 'E Rebeca estava escutando quando Isaque falava a Esaú, seu filho; e Esaú foi ao campo para caçar caça, a fim de trazer.'),
(734, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 6, 'OT', 'E Rebeca disse a Jacó, seu filho: Eis que ouvi teu pai falar a Esaú, teu irmão, dizendo:'),
(735, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 7, 'OT', 'Traze-me caça e faze-me um guisado saboroso, para que eu coma, e te abençoe diante do SENHOR, antes da minha morte.'),
(736, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 8, 'OT', 'Agora, pois, filho meu, ouve a minha voz naquilo que eu te ordeno.'),
(737, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 9, 'OT', 'Vai agora ao rebanho e traze-me de lá dois bons cabritos das cabras, e eu farei deles um guisado saboroso para teu pai, como ele ama.'),
(738, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 10, 'OT', 'E trarás a teu pai, e ele comerá, para que te abençoe antes da sua morte.'),
(739, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 11, 'OT', 'Jacó disse a Rebeca, sua mãe: "Eis que Esaú, meu irmão, é homem peludo, e eu sou homem liso.'),
(740, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 12, 'OT', 'Porventura meu pai me apalpará, e serei aos seus olhos como enganador; e trarei sobre mim maldição, e não bênção.'),
(741, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 13, 'OT', 'Disse-lhe sua mãe: Sobre mim seja a tua maldição, meu filho; somente ouve a minha voz e vai, traze-mos.'),
(742, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 14, 'OT', 'Ele foi, tomou-os e os trouxe à sua mãe; e sua mãe fez um prato saboroso, como seu pai amava.'),
(743, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 15, 'OT', 'Então Rebeca tomou as vestes de Esaú, seu filho mais velho, as melhores que tinha consigo em casa, e vestiu Jacó, seu filho mais novo.'),
(744, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 16, 'OT', 'E as peles dos cabritos das cabras vestiu sobre as suas mãos e sobre a lisura do seu pescoço.'),
(745, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 17, 'OT', 'E deu o guisado saboroso e o pão que tinha preparado na mão de Jacó, seu filho.'),
(746, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 18, 'OT', 'E foi ele a seu pai e disse: Meu pai! E ele respondeu: Eis-me; quem és tu, meu filho?'),
(747, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 19, 'OT', 'Jacó disse a seu pai: "Eu sou Esaú, teu primogênito; fiz como me disseste. Levanta-te, por favor, assenta-te e come da minha caça, para que a tua alma me abençoe."'),
(748, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 20, 'OT', 'Então Isaque perguntou a seu filho: "Como foi que a achaste tão depressa, meu filho?" Ele respondeu: "Porque o SENHOR, teu Deus, a trouxe ao meu encontro."'),
(749, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 21, 'OT', 'Chega-te agora, para que eu te apalpe, meu filho: és tu mesmo meu filho Esaú, ou não?'),
(750, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 22, 'OT', 'Então Jacó se aproximou de seu pai Isaque, que o apalpou e disse: "A voz é a voz de Jacó, mas as mãos são as mãos de Esaú."'),
(751, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 23, 'OT', 'E não o reconheceu, porque as suas mãos estavam peludas, como as mãos de Esaú, seu irmão; e o abençoou.'),
(752, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 24, 'OT', 'Então ele perguntou: "Você é mesmo meu filho Esaú?" E ele respondeu: "Sou eu."'),
(753, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 25, 'OT', 'Então disse: Traze-me para perto, para que eu coma da caça de meu filho, a fim de que a minha alma te abençoe. E ele lha trouxe, e comeu; e trouxe-lhe vinho, e bebeu.'),
(754, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 26, 'OT', 'Então disse Isaque, seu pai: "Aproxima-te agora e beija-me, meu filho."'),
(755, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 27, 'OT', 'E chegou-se, e beijou-o; e, sentindo o cheiro das suas vestes, abençoou-o, e disse: Eis que o cheiro do meu filho é como o cheiro de um campo que o SENHOR abençoou.'),
(756, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 28, 'OT', 'Que Deus te dê do orvalho do céu e da gordura da terra, e abundância de trigo e de vinho novo.'),
(757, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 29, 'OT', 'Sirvam-te povos, e nações se prostrem diante de ti; sê senhor sobre teus irmãos, e os filhos de tua mãe se curvem a ti; maldito seja quem te amaldiçoar, e bendito seja quem te abençoar.'),
(758, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 30, 'OT', 'E aconteceu que, quando Isaque terminou de abençoar Jacó, e apenas Jacó tinha saído da presença de Isaque, seu pai, Esaú, seu irmão, chegou da sua caçada.'),
(759, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 31, 'OT', 'Ele também preparou um prato saboroso e o trouxe a seu pai, e disse-lhe: Levanta-te, meu pai, e come da caça de teu filho, para que a tua alma me abençoe.'),
(760, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 32, 'OT', 'E disse-lhe Isaque, seu pai: Quem és tu? E ele disse: Eu sou teu filho, o teu primogênito, Esaú.'),
(761, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 33, 'OT', 'Então Isaque estremeceu com um tremor muito grande e disse: "Quem foi, então, que apanhou a caça e a trouxe para mim? Comi de tudo antes que você chegasse, e o abençoei; também será abençoado."'),
(762, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 34, 'OT', 'Quando Esaú ouviu as palavras de seu pai, gritou com um grito grande e muito amargo, e disse a seu pai: "Abençoa-me também a mim, meu pai!"'),
(763, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 35, 'OT', 'E ele disse: "Veio o teu irmão com astúcia e tomou a tua bênção."'),
(764, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 36, 'OT', 'Então disse: "Não é por isso que ele se chama Jacó? Pois já duas vezes me enganou: tomou a minha primogenitura, e eis que agora tomou a minha bênção." E acrescentou: "Não reservaste para mim uma bênção?"'),
(765, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 37, 'OT', 'Então Isaque respondeu e disse a Esaú: Eis que o constituí senhor sobre ti, e todos os seus irmãos lhe dei por servos, e com trigo e vinho novo o sustentei; e para ti, pois, o que farei, meu filho?'),
(766, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 38, 'OT', 'E disse Esaú a seu pai: Tens uma só bênção, meu pai? Abençoa-me também a mim, meu pai. E levantou Esaú a sua voz, e chorou.'),
(767, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 39, 'OT', 'Então Isaque, seu pai, respondeu e lhe disse: Eis que a gordura da terra será a tua habitação, e do orvalho do céu, do alto.'),
(768, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 40, 'OT', 'Viverás pela tua espada, e servirás a teu irmão; mas quando te libertares, sacudirás o seu jugo do teu pescoço.'),
(769, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 41, 'OT', 'Esaú guardou rancor de Jacó por causa da bênção com que seu pai o havia abençoado; e Esaú disse em seu coração: "Chegar-se-hão os dias de luto de meu pai, e matarei a Jacó, meu irmão."'),
(770, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 42, 'OT', 'Foram relatadas a Rebeca as palavras de Esaú, seu filho mais velho; e ela enviou e chamou Jacó, seu filho mais novo, e disse-lhe: Eis que Esaú, teu irmão, se consola a teu respeito, planejando matar-te.'),
(771, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 43, 'OT', 'Agora, meu filho, ouve a minha voz; levanta-te, foge para junto de Labão, meu irmão, em Harã.'),
(772, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 44, 'OT', 'E habitarás com ele alguns dias, até que se desvie a ira de teu irmão.'),
(773, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 45, 'OT', 'Até que a ira de teu irmão se afaste de ti, e ele se esqueça do que lhe fizeste; então enviarei e te trarei de lá. Por que ficaria eu privada de vós ambos num mesmo dia?'),
(774, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 27, 46, 'OT', 'Disse Rebeca a Isaque: "Estou enfastiada da minha vida por causa das filhas de Hete. Se Jacó tomar mulher dentre as filhas de Hete, como estas, dentre as filhas desta terra, para que me serve a vida?"'),
(775, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 1, 'OT', 'Isaque chamou Jacó, abençoou-o e ordenou-lhe, dizendo: "Não tomes mulher dentre as filhas de Canaã."'),
(776, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 2, 'OT', 'Levanta-te, vai a Paddan-aram, à casa de Betuel, pai de tua mãe, e toma de lá uma mulher das filhas de Labão, irmão de tua mãe.'),
(777, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 3, 'OT', 'E Deus Todo-poderoso te abençoe, e te faça frutificar, e te multiplique, para que sejas uma multidão de povos.'),
(778, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 4, 'OT', 'E que ele te dê a bênção de Abraão, a ti e à tua descendência contigo, para que possuas a terra das tuas peregrinações, que Deus deu a Abraão.'),
(779, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 5, 'OT', 'Isaque enviou Jacó, e ele foi a Paddan-aram, a Labão, filho de Betuel, o arameu, irmão de Rebeca, mãe de Jacó e de Esaú.'),
(780, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 6, 'OT', 'Vendo Esaú que Isaque abençoara Jacó e o enviara a Paddan-aram, para tomar de lá uma mulher para si, e que, ao abençoá-lo, lhe ordenara, dizendo: "Não tomarás mulher das filhas de Canaã",'),
(781, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 7, 'OT', 'E Jacó obedeceu a seu pai e a sua mãe, e foi a Paddan-aram.'),
(782, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 8, 'OT', 'Vendo Esaú que as filhas de Canaã eram más aos olhos de Isaque, seu pai,'),
(783, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 9, 'OT', 'Foi-se Esaú a Ismael e tomou por mulher, além das suas mulheres, a Maalate, filha de Ismael, filho de Abraão, irmã de Nebaiote.'),
(784, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 10, 'OT', 'Jacó partiu de Berseba e foi para Harã.'),
(785, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 11, 'OT', 'Chegou a um lugar e ali passou a noite, porque o sol já se havia posto; tomou uma das pedras do lugar, pô-la como travesseiro para a sua cabeça e deitou-se naquele lugar.'),
(786, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 12, 'OT', 'E sonhou, e eis que uma escada estava posta na terra, cujo topo alcançava o céu; e eis que os anjos de Deus subiam e desciam por ela.'),
(787, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 13, 'OT', 'E eis que o SENHOR estava em pé acima dela e disse: Eu sou o SENHOR, o Deus de Abraão, teu pai, e o Deus de Isaque; a terra sobre a qual estás deitado, a ti a darei e à tua descendência.'),
(788, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 14, 'OT', 'E a tua descendência será como o pó da terra, e te espalharás para o oeste, para o leste, para o norte e para o sul; e em ti e na tua descendência serão abençoadas todas as famílias da terra.'),
(789, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 15, 'OT', 'E eis que estou contigo, e te guardarei por onde quer que fores, e te farei voltar a esta terra, porque não te deixarei até que eu tenha feito o que te falei.'),
(790, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 16, 'OT', 'Jacó despertou do seu sono e disse: "Na verdade, o SENHOR está neste lugar, e eu não o sabia."'),
(791, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 17, 'OT', 'E temeu e disse: Quão temível é este lugar! Este não é outro senão a casa de Deus, e esta é a porta dos céus.'),
(792, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 18, 'OT', 'Levantou-se Jacó pela manhã, tomou a pedra que havia posto como travesseiro, e a ergueu como coluna, e derramou óleo sobre o seu topo.'),
(793, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 19, 'OT', 'E chamou o nome daquele lugar Betel; porém o nome da cidade antes era Luz.'),
(794, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 20, 'OT', 'E Jacó fez um voto, dizendo: Se Deus estiver comigo e me guardar neste caminho em que vou, e me der pão para comer e roupa para vestir,'),
(795, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 21, 'OT', 'e eu voltar em paz à casa de meu pai, então o SENHOR será o meu Deus.'),
(796, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 28, 22, 'OT', 'E esta pedra que ergui como coluna será casa de Deus; e de tudo o que me deres, certamente te darei o dízimo.'),
(797, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 1, 'OT', 'Jacó levantou os pés e foi para a terra dos filhos do oriente.'),
(798, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 2, 'OT', 'E olhou, e eis um poço no campo, e eis três rebanhos de ovelhas deitados junto a ele; porque daquele poço davam de beber aos rebanhos; e havia uma grande pedra sobre a boca do poço.'),
(799, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 3, 'OT', 'Ali se reuniam todos os rebanhos, e os pastores rolavam a pedra da boca do poço, davam de beber às ovelhas e tornavam a colocar a pedra sobre a boca do poço, no seu lugar.'),
(800, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 4, 'OT', 'E perguntou-lhes Jacó: "Meus irmãos, de onde sois?" E responderam: "Somos de Harã."'),
(801, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 5, 'OT', 'E ele lhes disse: Conheceis Labão, filho de Naor? E disseram: Conhecemos.'),
(802, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 6, 'OT', 'E ele lhes disse: Está bem com ele? E disseram: Está bem; e eis que Raquel, sua filha, vem com as ovelhas.'),
(803, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 7, 'OT', 'Ele disse: "Ainda é plena luz do dia, não é hora de reunir o rebanho; dai de beber às ovelhas e ide apascentá-las."'),
(804, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 8, 'OT', 'E disseram: Não podemos, até que todos os rebanhos se reúnam, e rolem a pedra da boca do poço, e então daremos de beber às ovelhas.'),
(805, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 9, 'OT', 'Ainda ele falava com eles, quando Raquel chegou com as ovelhas de seu pai, pois ela era pastora.'),
(806, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 10, 'OT', 'E aconteceu que, vendo Jacó a Raquel, filha de Labão, irmão de sua mãe, e as ovelhas de Labão, irmão de sua mãe, chegou Jacó, removeu a pedra da boca do poço e deu de beber às ovelhas de Labão, irmão de sua mãe.'),
(807, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 11, 'OT', 'Jacó beijou Raquel, levantou a sua voz e chorou.'),
(808, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 12, 'OT', 'E Jacó contou a Raquel que ele era irmão de seu pai e que era filho de Rebeca; então ela correu e contou a seu pai.'),
(809, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 13, 'OT', 'Quando Labão ouviu as notícias sobre Jacó, filho de sua irmã, correu ao seu encontro, abraçou-o, beijou-o e o levou para sua casa. E Jacó contou a Labão todas essas coisas.'),
(810, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 14, 'OT', 'Então Labão lhe disse: "Verdadeiramente, tu és meu osso e minha carne." E ele ficou com ele um mês inteiro de dias.'),
(811, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 15, 'OT', 'Então Labão disse a Jacó: "Porque tu és meu irmão, hás de servir-me de graça? Dize-me qual será o teu salário."'),
(812, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 16, 'OT', 'Labão tinha duas filhas: o nome da mais velha era Lia, e o nome da mais nova era Raquel.'),
(813, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 17, 'OT', 'Leia tinha olhos delicados, mas Raquel era formosa de porte e bela de aparência.'),
(814, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 18, 'OT', 'Jacó amava Raquel e disse: "Servirei sete anos por Raquel, tua filha mais nova."'),
(815, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 19, 'OT', 'Melhor é que eu a dê a ti do que a dê a outro homem; fica comigo.'),
(816, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 20, 'OT', 'Jacó serviu sete anos por Raquel, e eles lhe pareceram como poucos dias, por causa do seu amor por ela.'),
(817, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 21, 'OT', 'Dá-me a minha mulher, pois os meus dias se cumpriram, e eu entrarei a ela.'),
(818, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 22, 'OT', 'Então Labão reuniu todos os homens daquele lugar e fez um banquete.'),
(819, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 23, 'OT', 'À tarde, tomou sua filha Lia e a trouxe a ele; e ele se deitou com ela.'),
(820, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 24, 'OT', 'E Labão deu a ela sua serva Zilpa, para servir a sua filha Lia como serva.'),
(821, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 25, 'OT', 'E aconteceu pela manhã, e eis que era Lia; então disse a Labão: Que é isto que me fizeste? Não te servi por Raquel? Por que, pois, me enganaste?'),
(822, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 26, 'OT', 'Não se faz assim em nosso lugar, dar a mais nova antes da mais velha.'),
(823, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 27, 'OT', 'Cumpre a semana desta; e te daremos também a esta, pelo serviço que servirás comigo ainda outros sete anos.'),
(824, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 28, 'OT', 'Jacó fez assim e cumpriu a semana dela; então ele lhe deu sua filha Raquel por mulher.'),
(825, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 29, 'OT', 'E Labão deu a sua serva Bilha a Raquel, sua filha, como serva.'),
(826, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 30, 'OT', 'E entrou também a Raquel, e amou também a Raquel mais do que a Lia; e serviu com ele ainda outros sete anos.'),
(827, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 31, 'OT', 'Vendo o SENHOR que Lia era desprezada, abriu a sua madre; mas Raquel era estéril.'),
(828, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 32, 'OT', 'E concebeu Lia, e deu à luz um filho, e chamou o seu nome Rúben, porque disse: "O SENHOR viu a minha aflição; agora, pois, o meu marido me amará."'),
(829, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 33, 'OT', 'E ela concebeu outra vez, e deu à luz um filho, e disse: "Porque o SENHOR ouviu que eu era desprezada, por isso me deu também este." E chamou o seu nome Simeão.'),
(830, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 34, 'OT', 'E ela concebeu outra vez, e deu à luz um filho, e disse: "Agora, desta vez, meu marido se unirá a mim, porque lhe dei à luz três filhos." Por isso, chamou-lhe o nome Levi.'),
(831, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 29, 35, 'OT', 'Ela concebeu de novo, deu à luz um filho e disse: "Desta vez louvarei o SENHOR." Por isso lhe chamou Judá. E cessou de dar à luz.'),
(832, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 1, 'OT', 'Vendo Raquel que não dava filhos a Jacó, teve inveja de sua irmã e disse a Jacó: Dá-me filhos, ou senão morro.'),
(833, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 2, 'OT', 'A ira de Jacó se acendeu contra Raquel, e ele disse: "Estou eu no lugar de Deus, que te negou o fruto do ventre?"'),
(834, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 3, 'OT', 'E ela disse: Eis aqui minha serva Bila; entra a ela, para que dê à luz sobre os meus joelhos, e eu também seja edificada por meio dela.'),
(835, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 4, 'OT', 'E ela lhe deu Bilha, sua serva, por mulher; e Jacó teve relações com ela.'),
(836, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 5, 'OT', 'Bilha concebeu e deu a Jacó um filho.'),
(837, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 6, 'OT', 'Deus me julgou, e também ouviu a minha voz, e me deu um filho; por isso ela o chamou de Dã.'),
(838, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 7, 'OT', 'Bilha, serva de Raquel, concebeu outra vez e deu a Jacó um segundo filho.'),
(839, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 8, 'OT', 'Disse Raquel: "Lutei com Deus as lutas de minha irmã e também venci." E chamou o seu nome Naftali.'),
(840, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 9, 'OT', 'Vendo Lia que havia cessado de dar à luz, tomou a Zilpa, sua serva, e a deu a Jacó por mulher.'),
(841, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 10, 'OT', 'Zilpa, serva de Lia, deu à luz um filho a Jacó.'),
(842, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 11, 'OT', 'Disse Lia: "Vem uma tropa!" E chamou o seu nome Gade.'),
(843, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 12, 'OT', 'Zilpa, serva de Lia, deu à luz um segundo filho a Jacó.'),
(844, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 13, 'OT', 'Então disse Lia: Para minha felicidade, porque as filhas me chamarão bem-aventurada; e chamou o seu nome Aser.'),
(845, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 14, 'OT', 'Foi nos dias da colheita do trigo que Rúben saiu ao campo, encontrou mandrágoras e as trouxe para Lia, sua mãe. Então Raquel disse a Lia: "Dá-me, por favor, das mandrágoras do teu filho."'),
(846, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 15, 'OT', 'E ela lhe disse: "É pouco que tenhas tomado o meu marido, e tomarás também as mandrágoras do meu filho?" Então Raquel disse: "Por isso ele se deitará contigo esta noite, em troca das mandrágoras do teu filho."'),
(847, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 16, 'OT', 'Jacó veio do campo à tarde, e Lia saiu ao seu encontro e disse: "Entrarás a mim, porque certamente te aluguei com as mandrágoras do meu filho." E ele se deitou com ela naquela noite.'),
(848, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 17, 'OT', 'E Deus ouviu a Lia, e ela concebeu e deu à luz a Jacó um quinto filho.'),
(849, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 18, 'OT', 'Então disse Lia: Deus me deu meu salário, porque dei minha serva ao meu marido; e chamou o seu nome Issacar.'),
(850, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 19, 'OT', 'E Lia concebeu outra vez e deu à luz um sexto filho a Jacó.'),
(851, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 20, 'OT', 'Disse Lia: "Deus me presenteou com um bom presente; desta vez meu marido habitará comigo, porque lhe dei à luz seis filhos." E chamou o seu nome Zebulom.'),
(852, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 21, 'OT', 'E depois deu à luz uma filha, e chamou o seu nome Diná.'),
(853, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 22, 'OT', 'E lembrou-se Deus de Raquel, e Deus a ouviu, e abriu a sua madre.'),
(854, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 23, 'OT', 'Ela concebeu, deu à luz um filho e disse: "Deus tirou de mim a minha vergonha."'),
(855, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 24, 'OT', 'E chamou o seu nome José, dizendo: O SENHOR me acrescente outro filho.'),
(856, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 25, 'OT', 'E aconteceu que, quando Raquel deu à luz José, Jacó disse a Labão: Deixa-me ir, e voltarei ao meu lugar e à minha terra.'),
(857, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 26, 'OT', 'Dá-me as minhas mulheres e os meus filhos, pelos quais te servi, e irei; pois tu sabes o meu serviço, que te prestei.'),
(858, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 27, 'OT', 'Então Labão lhe disse: "Se agora achei graça aos teus olhos, fica comigo; tenho observado que o SENHOR me abençoou por tua causa."'),
(859, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 28, 'OT', 'Determina-me o teu salário, e eu o darei.'),
(860, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 29, 'OT', 'Tu sabes como te servi e como o teu gado esteve comigo.'),
(861, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 30, 'OT', 'Porque o pouco que tinhas antes de mim cresceu em grande abundância, e o SENHOR te abençoou por onde eu andei; agora, quando farei eu também provisão para a minha própria casa?'),
(862, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 31, 'OT', 'E ele disse: "Que te darei?" E Jacó disse: "Não me darás nada; se me fizeres isto, voltarei a apascentar e a guardar o teu rebanho."'),
(863, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 32, 'OT', 'Passarei hoje por todo o teu rebanho, separando dele toda ovelha salpicada e malhada, e toda ovelha escura entre os cordeiros, e as malhadas e salpicadas entre as cabras; e isto será o meu salário.'),
(864, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 33, 'OT', 'Assim responderá por mim a minha justiça no dia de amanhã, quando vieres ver o meu salário diante de ti: tudo o que não for salpicado e malhado entre as cabras, e moreno entre os cordeiros, isso será roubo da minha parte.'),
(865, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 34, 'OT', 'Então disse Labão: "Que assim seja, conforme a tua palavra."'),
(866, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 35, 'OT', 'Naquele mesmo dia, separou os bodes listrados e malhados e todas as cabras salpicadas e malhadas, tudo o que tinha brancura entre elas, e todo o escuro entre os cordeiros; e os entregou nas mãos de seus filhos.'),
(867, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 36, 'OT', 'E pôs três dias de caminho entre si e Jacó; e Jacó apascentava o restante dos rebanhos de Labão.'),
(868, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 37, 'OT', 'Então Jacó tomou varas verdes de estoraque, de amendoeira e de plátano, e nelas descascou riscas brancas, descobrindo a brancura que havia nas varas.'),
(869, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 38, 'OT', 'E colocou as varas que havia descascado nos canais de água, nos bebedouros, onde o rebanho vinha beber, em frente ao rebanho; e eles conceberam quando vinham beber.'),
(870, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 39, 'OT', 'E concebia o rebanho diante das varas, e as ovelhas davam à luz crias listradas, salpicadas e malhadas.'),
(871, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 40, 'OT', 'Jacó separou os cordeiros e pôs as faces do rebanho voltadas para os listrados e para todo o escuro no rebanho de Labão; e estabeleceu para si rebanhos à parte, e não os misturou com o rebanho de Labão.'),
(872, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 41, 'OT', 'E acontecia que, sempre que as ovelhas fortes concebiam, Jacó punha as varas diante dos olhos do rebanho nos canais de água, para que concebessem diante das varas.'),
(873, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 42, 'OT', 'Mas, quando o rebanho enfraquecia, ele não as colocava; assim, os fracos eram de Labão, e os fortes, de Jacó.'),
(874, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 30, 43, 'OT', 'E o homem prosperou sobremaneira, e teve muitos rebanhos, e servas, e servos, e camelos, e jumentos.'),
(875, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 1, 'OT', 'E Jacó ouviu as palavras dos filhos de Labão, que diziam: "Jacó tomou tudo o que era de nosso pai, e do que era de nosso pai fez toda esta riqueza."'),
(876, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 2, 'OT', 'Jacó viu o rosto de Labão, e eis que ele não estava para com ele como antes, como nos dias passados.'),
(877, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 3, 'OT', 'E disse o SENHOR a Jacó: Torna-te à terra de teus pais e à tua parentela, e eu serei contigo.'),
(878, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 4, 'OT', 'Jacó mandou chamar Raquel e Lia ao campo, onde estava o seu rebanho.'),
(879, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 5, 'OT', 'Vejo que o rosto de vosso pai não é para comigo como era antes; porém o Deus de meu pai tem estado comigo.'),
(880, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 6, 'OT', 'E vós sabeis que com todo o meu poder tenho servido a vosso pai.'),
(881, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 7, 'OT', 'Mas vosso pai me enganou e mudou o meu salário dez vezes; porém Deus não lhe permitiu que me fizesse mal.'),
(882, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 8, 'OT', 'Se ele dissesse: "Os salpicados serão o teu salário", então todas as ovelhas davam à luz salpicados; e se ele dissesse: "Os listrados serão o teu salário", então todas as ovelhas davam à luz listrados.'),
(883, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 9, 'OT', 'Assim Deus tirou o gado de vosso pai e o deu a mim.'),
(884, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 10, 'OT', 'E aconteceu que, no tempo em que o rebanho concebia, levantei os meus olhos e vi em sonho: eis que os bodes que subiam sobre as ovelhas eram listrados, salpicados e malhados.'),
(885, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 11, 'OT', 'E o anjo de Deus me disse em sonho: Jacó! E eu respondi: Eis-me.'),
(886, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 12, 'OT', 'Levanta agora os teus olhos e vê todos os bodes que sobem sobre o rebanho: listrados, salpicados e malhados; porque tenho visto tudo o que Labão te faz.'),
(887, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 13, 'OT', 'Eu sou o Deus de Beth-el, onde ungiste uma coluna, onde me fizeste um voto. Agora, levanta-te, sai desta terra e volta à terra da tua parentela.'),
(888, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 14, 'OT', 'Então Raquel e Lia responderam e lhe disseram: "Há ainda para nós parte ou herança na casa de nosso pai?"'),
(889, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 15, 'OT', 'Não nos considera ele como estrangeiras? Pois nos vendeu e consumiu completamente o nosso dinheiro.'),
(890, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 16, 'OT', 'Porque toda a riqueza que Deus tirou de nosso pai é nossa e de nossos filhos; agora, pois, faze tudo o que Deus te tem dito.'),
(891, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 17, 'OT', 'Levantou-se Jacó, pôs os seus filhos e as suas mulheres sobre os camelos.'),
(892, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 18, 'OT', 'Levou todo o seu rebanho e todos os seus bens que havia adquirido, o gado que possuía, que tinha obtido em Paddan-aram, para ir a Isaque, seu pai, à terra de Canaã.'),
(893, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 19, 'OT', 'Labão foi tosquiar as suas ovelhas, e Raquel furtou os ídolos do seu pai.'),
(894, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 20, 'OT', 'Jacó enganou Labão, o arameu, não lhe contando que estava fugindo.'),
(895, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 21, 'OT', 'Então ele fugiu com tudo o que tinha, levantou-se, atravessou o rio e dirigiu o seu rosto para a região montanhosa de Gileade.'),
(896, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 22, 'OT', 'No terceiro dia, foi anunciado a Labão que Jacó havia fugido.'),
(897, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 23, 'OT', 'Então tomou consigo os seus irmãos e perseguiu-o por sete dias de caminho, e alcançou-o no monte de Gileade.'),
(898, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 24, 'OT', 'Veio Deus a Labão, o arameu, em sonho de noite, e disse-lhe: Guarda-te, que não fales com Jacó nem bem nem mal.'),
(899, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 25, 'OT', 'Labão alcançou Jacó, e Jacó tinha armado a sua tenda na montanha; e Labão armou a sua com os seus irmãos na montanha de Gileade.'),
(900, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 26, 'OT', 'Então Labão disse a Jacó: "Que fizeste, roubando-me o coração e levando minhas filhas como cativas pela espada?"'),
(901, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 27, 'OT', 'Por que te escondeste para fugir, e me enganaste, e não me avisaste, para que eu te despedisse com alegria e com cânticos, com tamborim e com harpa?'),
(902, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 28, 'OT', 'E nem me deixaste beijar meus filhos e minhas filhas. Agora procedeste loucamente, fazendo assim.'),
(903, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 29, 'OT', 'Há poder em minha mão para vos fazer mal, mas o Deus de vosso pai ontem à noite me falou, dizendo: Guarda-te de falar com Jacó, nem bem nem mal.'),
(904, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 30, 'OT', 'Agora, certamente partiste, porque ansiabas pela casa de teu pai; por que roubaste os meus deuses?'),
(905, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 31, 'OT', 'Então respondeu Jacó e disse a Labão: Porque temia, pois pensava: para que não me arrebates as tuas filhas de mim.'),
(906, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 32, 'OT', 'Com quem achares os teus deuses, esse não viva; reconhece diante de nossos irmãos o que é teu do que está comigo, e toma-o para ti. Pois Jacó não sabia que Raquel os tinha furtado.'),
(907, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 33, 'OT', 'Então Labão entrou na tenda de Jacó, e na tenda de Lia, e na tenda das duas servas, e não os achou; e saiu da tenda de Lia, e entrou na tenda de Raquel.'),
(908, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 34, 'OT', 'Raquel, porém, tomou os ídolos domésticos e os colocou na sela do camelo, e sentou-se sobre eles. Labão vasculhou toda a tenda, mas não os encontrou.'),
(909, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 35, 'OT', 'E ela disse a seu pai: Não se acenda a ira aos olhos de meu senhor, porque não posso me levantar diante de ti, pois tenho o caminho das mulheres. E ele buscou, mas não achou os ídolos domésticos.'),
(910, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 36, 'OT', 'Então Jacó se irou e contendou com Labão; e Jacó respondeu e disse a Labão: Qual é a minha transgressão? Qual é o meu pecado, que me perseguiste com tanto ardor?'),
(911, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 37, 'OT', 'Visto que apalpaste todos os meus bens, que achaste de todos os bens da tua casa? Põe-nos aqui diante de meus irmãos e teus irmãos, e que julguem entre nós dois.'),
(912, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 38, 'OT', 'Estes vinte anos estive eu contigo; as tuas ovelhas e as tuas cabras não abortaram, e não comi os carneiros do teu rebanho.'),
(913, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 39, 'OT', 'O que foi despedaçado, eu não te trazia; eu mesmo o pagava; da minha mão o requerias; o furtado de dia e o furtado de noite.'),
(914, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 40, 'OT', 'De dia me consumia o calor, e de noite a geada; e o meu sono fugia dos meus olhos.'),
(915, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 41, 'OT', 'Estes vinte anos estive em tua casa: catorze anos te servi por tuas duas filhas e seis anos por teu rebanho; e mudaste o meu salário dez vezes.'),
(916, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 42, 'OT', 'Se não estivesse comigo o Deus de meu pai, o Deus de Abraão, e o Temor de Isaque, certamente agora me terias enviado vazio. Deus viu a minha aflição e o trabalho das minhas mãos, e repreendeu-te ontem à noite.'),
(917, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 43, 'OT', 'Então Labão respondeu e disse a Jacó: As filhas são minhas filhas, e os filhos são meus filhos, e o rebanho é o meu rebanho, e tudo o que vês é meu. E o que posso fazer hoje a estas minhas filhas, ou aos filhos que elas geraram?'),
(918, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 44, 'OT', 'Agora, vem, façamos aliança eu e tu, e que ela sirva de testemunho entre mim e ti.'),
(919, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 45, 'OT', 'Jacó tomou uma pedra e a ergueu como coluna.'),
(920, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 46, 'OT', 'E disse Jacó a seus irmãos: Ajuntai pedras. E tomaram pedras, e fizeram um montão, e comeram ali sobre o montão.'),
(921, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 47, 'OT', 'E chamou-o Labão Jegar-sahadutha; e Jacó chamou-o Galeede.'),
(922, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 48, 'OT', 'Então disse Labão: "Este montão é hoje testemunha entre mim e ti." Por isso chamou-lhe o nome Galeede.'),
(923, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 49, 'OT', 'E Mizpá, pois disse: Atente o SENHOR entre mim e ti, quando estivermos escondidos um do outro.'),
(924, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 50, 'OT', 'Se afligires as minhas filhas, e se tomares outras mulheres além das minhas filhas, ninguém está conosco; vê, Deus é testemunha entre mim e ti.'),
(925, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 51, 'OT', 'Eis este monte de pedras, e eis a coluna que levantei entre mim e ti.'),
(926, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 52, 'OT', 'Este montão é testemunha, e esta coluna é testemunha, de que eu não passarei este montão até ti, e de que tu não passarás este montão e esta coluna até mim, para o mal.'),
(927, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 53, 'OT', 'O Deus de Abraão e o Deus de Naor, o Deus de seu pai, julgue entre nós. E jurou Jacó pelo Temor de seu pai Isaque.'),
(928, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 54, 'OT', 'Jacó ofereceu um sacrifício no monte e convidou seus irmãos para comerem pão; eles comeram pão e passaram a noite no monte.'),
(929, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 31, 55, 'OT', 'Levantou-se Labão de madrugada, beijou seus filhos e suas filhas, e os abençoou. Então partiu e voltou Labão para o seu lugar.'),
(930, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 1, 'OT', 'Jacó seguiu o seu caminho, e os anjos de Deus o encontraram.'),
(931, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 2, 'OT', 'E disse Jacó, quando os viu: Este é o acampamento de Deus. E chamou o nome daquele lugar Maanaim.'),
(932, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 3, 'OT', 'Jacó enviou mensageiros diante de si a Esaú, seu irmão, à terra de Seir, campo de Edom.'),
(933, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 4, 'OT', 'E ordenou-lhes, dizendo: Assim direis a meu senhor Esaú: Assim diz teu servo Jacó: Com Labão morei como estrangeiro e me demorei até agora.'),
(934, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 5, 'OT', 'Tenho bois e jumentos, ovelhas, e servos e servas; e enviei para anunciar a meu senhor, a fim de achar graça aos teus olhos.'),
(935, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 6, 'OT', 'Os mensageiros voltaram a Jacó, dizendo: "Chegamos a teu irmão Esaú, e ele vem ao teu encontro, com quatrocentos homens."'),
(936, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 7, 'OT', 'Jacó ficou muito atemorizado e angustiado; então dividiu o povo que estava com ele, e as ovelhas, e os bois, e os camelos, em dois grupos.'),
(937, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 8, 'OT', 'Se Esaú vier contra um dos acampamentos e o ferir, o acampamento que restar escapará.'),
(938, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 9, 'OT', 'Disse Jacó: Deus de meu pai Abraão, e Deus de meu pai Isaque, ó SENHOR, que me disseste: Torna-te à tua terra e à tua parentela, e eu te farei bem.'),
(939, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 10, 'OT', 'Menor sou eu que todas as benignidades e que toda a fidelidade que tens feito ao teu servo; porque com meu cajado passei este Jordão, e agora me tornei em dois acampamentos.'),
(940, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 11, 'OT', 'Livra-me, peço-te, da mão de meu irmão, da mão de Esaú, porque eu o temo, para que não venha e me fira, a mãe com os filhos.'),
(941, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 12, 'OT', 'E tu disseste: Certamente te farei bem e farei a tua descendência como a areia do mar, que não se pode contar por ser tão numerosa.'),
(942, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 13, 'OT', 'E passou a noite ali; e tomou do que tinha em mãos um presente para seu irmão Esaú:'),
(943, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 14, 'OT', 'Duzentas cabras e vinte bodes; duzentas ovelhas e vinte carneiros.'),
(944, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 15, 'OT', 'Trinta camelas de leite com suas crias, quarenta vacas e dez novilhos; vinte jumentas e dez jumentinhos.'),
(945, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 16, 'OT', 'E ele os entregou nas mãos de seus servos, cada rebanho separadamente, e disse a seus servos: Passai adiante de mim, e ponde espaço entre rebanho e rebanho.'),
(946, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 17, 'OT', 'E ordenou ao primeiro, dizendo: Quando Esaú, meu irmão, te encontrar e te perguntar, dizendo: De quem és tu, e para onde vais, e de quem são estes diante de ti,'),
(947, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 18, 'OT', 'Dirás a teu servo Jacó: É um presente enviado a meu senhor Esaú; e eis que ele também vem atrás de nós.'),
(948, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 19, 'OT', 'E ordenou também ao segundo, e ao terceiro, e a todos os que seguiam os rebanhos, dizendo: Conforme esta mesma palavra falareis a Esaú, quando o encontrardes.'),
(949, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 20, 'OT', 'E direis também: Eis que o teu servo Jacó vem atrás de nós. Pois pensava: Eu o aplacarei com o presente que vai adiante de mim, e depois verei a sua face; talvez ele me receba com favor.'),
(950, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 21, 'OT', 'E passou o presente diante da sua face; porém ele passou aquela noite no acampamento.'),
(951, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 22, 'OT', 'Levantou-se naquela noite, tomou as suas duas mulheres, as suas duas servas e os seus onze filhos, e atravessou o vau de Jaboque.'),
(952, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 23, 'OT', 'Tomou-os e fê-los passar o ribeiro, e fez passar tudo o que tinha.'),
(953, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 24, 'OT', 'Jacó ficou só; e um homem lutou com ele até o romper da alva.'),
(954, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 25, 'OT', 'Vendo que não podia vencê-lo, tocou na articulação da coxa de Jacó, e a articulação da coxa de Jacó se deslocou enquanto lutava com ele.'),
(955, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 26, 'OT', 'Deixa-me ir, pois já rompeu a alva. Mas ele respondeu: Não te deixarei ir, a menos que me abençoes.'),
(956, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 27, 'OT', 'E disse-lhe: Qual é o teu nome? E ele disse: Jacó.'),
(957, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 28, 'OT', 'Então disse: Não se chamará mais o teu nome Jacó, mas Israel; porque lutaste com Deus e com os homens, e prevaleceste.'),
(958, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 29, 'OT', 'E Jacó perguntou e disse: Dá-me, peço-te, o teu nome. E ele disse: Por que perguntas pelo meu nome? E abençoou-o ali.'),
(959, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 30, 'OT', 'E chamou Jacó o nome daquele lugar Peniel, porque disse: Vi a Deus face a face, e a minha vida foi preservada.'),
(960, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 31, 'OT', 'E saiu-lhe o sol, quando ele passou por Penuel; e ele mancava da sua coxa.'),
(961, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 32, 32, 'OT', 'Por isso os filhos de Israel não comem o nervo da coxa, que está sobre a juntura do quadril, até o dia de hoje; porque ele tocou a juntura do quadril de Jacó no nervo da coxa.'),
(962, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 1, 'OT', 'Jacó levantou os olhos e viu: Esaú vinha, e com ele quatrocentos homens. Então repartiu os filhos entre Lia, Raquel e as duas servas.'),
(963, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 2, 'OT', 'Pôs as servas e seus filhos à frente, e Lia e seus filhos atrás, e Raquel e José por último.'),
(964, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 3, 'OT', 'Ele mesmo passou à frente deles e inclinou-se até o chão sete vezes, até chegar perto de seu irmão.'),
(965, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 4, 'OT', 'Então Esaú correu ao seu encontro, abraçou-o, lançou-se sobre o seu pescoço e beijou-o; e choraram.'),
(966, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 5, 'OT', 'Levantou os olhos, viu as mulheres e as crianças, e perguntou: "Quem são estes contigo?" E ele respondeu: "Os filhos que Deus graciosamente concedeu a teu servo."'),
(967, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 6, 'OT', 'Então as servas se aproximaram, elas e seus filhos, e se prostraram.'),
(968, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 7, 'OT', 'Chegou também Lia com seus filhos, e inclinaram-se; depois chegou José com Raquel, e inclinaram-se.'),
(969, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 8, 'OT', 'E perguntou Esaú: "Para que te serve todo este grupo que encontrei?" E ele respondeu: "Para achar graça aos olhos de meu senhor."'),
(970, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 9, 'OT', 'Tenho muito, meu irmão; fique com o que é teu.'),
(971, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 10, 'OT', 'Jacó disse: "Não, por favor! Se agora achei favor aos teus olhos, aceita o meu presente da minha mão, pois vi o teu rosto como quem vê o rosto de Deus, e tu me recebeste com bondade."'),
(972, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 11, 'OT', 'Toma, por favor, a minha bênção que te foi trazida, porque Deus tem sido gracioso comigo e porque tenho de tudo. E insistiu com ele, até que a tomou.'),
(973, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 12, 'OT', 'Disse: Partamos e sigamos, e eu irei adiante de ti.'),
(974, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 13, 'OT', 'Ele, porém, lhe disse: Meu senhor sabe que as crianças são frágeis, e que tenho comigo ovelhas e vacas que estão amamentando; se forem forçadas demais num só dia, todo o rebanho morrerá.'),
(975, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 14, 'OT', 'Passe o meu senhor adiante do seu servo; e eu seguirei calmamente, conforme o passo do rebanho que está diante de mim e conforme o passo das crianças, até que eu chegue ao meu senhor em Seir.'),
(976, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 15, 'OT', 'E disse Esaú: Deixarei contigo alguns do povo que está comigo. E ele disse: Para que isso? Ache eu graça aos olhos de meu senhor.'),
(977, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 16, 'OT', 'E voltou Esaú naquele dia pelo seu caminho a Seir.'),
(978, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 17, 'OT', 'E Jacó partiu para Sucote, e edificou para si uma casa, e fez cabanas para o seu gado; por isso chamou o nome daquele lugar Sucote.'),
(979, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 18, 'OT', 'Jacó chegou em paz à cidade de Siquém, na terra de Canaã, ao voltar de Paddan-aram, e acampou diante da cidade.'),
(980, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 19, 'OT', 'E comprou a parte do campo onde armara sua tenda, das mãos dos filhos de Hamor, pai de Siquém, por cem peças de prata.'),
(981, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 33, 20, 'OT', 'E armou ali um altar e o chamou de El, o Deus de Israel.'),
(982, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 1, 'OT', 'Saiu Diná, filha de Leia, que esta dera à luz a Jacó, para ver as filhas da terra.'),
(983, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 2, 'OT', 'E Siquém, filho de Hamor, o heveu, príncipe daquela terra, viu-a, tomou-a, deitou-se com ela e a humilhou.'),
(984, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 3, 'OT', 'Sua alma se apegou a Diná, filha de Jacó; ele amou a jovem e falou-lhe ao coração.'),
(985, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 4, 'OT', 'Toma-me esta jovem por mulher.'),
(986, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 5, 'OT', 'E Jacó ouviu que ele havia contaminado a Diná, sua filha; e seus filhos estavam no campo com o gado; e Jacó calou-se até que eles viessem.'),
(987, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 6, 'OT', 'E saiu Hamor, pai de Siquém, a Jacó, para falar com ele.'),
(988, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 7, 'OT', 'E os filhos de Jacó voltaram do campo quando ouviram isso; e os homens se entristeceram, e muito se indignaram, porque ele cometera uma loucura em Israel, deitando-se com a filha de Jacó; coisa que não se devia fazer.'),
(989, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 8, 'OT', 'E Hamor falou com eles, dizendo: "Siquém, meu filho, tem a sua alma apegada à vossa filha; dai-lha, por favor, por mulher."'),
(990, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 9, 'OT', 'E fazei aliança de casamento conosco; dareis vossas filhas a nós, e tomareis nossas filhas para vós.'),
(991, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 10, 'OT', 'E habitai conosco; e a terra estará diante de vós; habitai e negociai nela, e tomai posse dela.'),
(992, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 11, 'OT', 'E disse Siquém ao pai dela e aos irmãos dela: "Ache eu graça aos vossos olhos, e darei o que me disserdes."'),
(993, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 12, 'OT', 'Aumentai muito sobre mim o dote e o presente, e darei o que me disserdes; e dai-me a moça por mulher.'),
(994, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 13, 'OT', 'Então os filhos de Jacó responderam a Siquém e a Hamor, seu pai, enganosamente, e falaram, porque ele havia contaminado a Diná, sua irmã.'),
(995, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 14, 'OT', 'E disseram-lhes: Não podemos fazer esta coisa, dar a nossa irmã a um homem que tem prepúcio, porque isso é uma vergonha para nós.'),
(996, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 15, 'OT', 'Somente com isto consentiremos a vós: se vos tornardes como nós, circuncidando todo varão entre vós.'),
(997, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 16, 'OT', 'Então daremos as nossas filhas a vós, e tomaremos as vossas filhas para nós, e habitaremos convosco, e seremos um só povo.'),
(998, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 17, 'OT', 'Mas, se não nos ouvirdes para vos circuncidardes, tomaremos a nossa filha e iremos embora.'),
(999, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 18, 'OT', 'E as suas palavras foram boas aos olhos de Hamor e aos olhos de Siquém, filho de Hamor.'),
(1000, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 19, 'OT', 'E não tardou o jovem em fazer aquilo, porque se agradava da filha de Jacó; e ele era o mais honrado de toda a casa de seu pai.'),
(1001, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 20, 'OT', 'Então Hamor e seu filho Siquém foram à porta da sua cidade e falaram aos homens da cidade, dizendo:'),
(1002, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 21, 'OT', 'Estes homens são pacíficos conosco; portanto habitarão na terra e negociarão nela; eis que a terra é espaçosa diante deles; tomaremos as suas filhas para nós como mulheres, e daremos as nossas filhas a eles.'),
(1003, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 22, 'OT', 'Somente com esta condição consentirão aqueles homens em habitar conosco, para nos tornarmos um só povo: que todo homem entre nós seja circuncidado, assim como eles são circuncidados.'),
(1004, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 23, 'OT', 'O seu gado, as suas possessões e todos os seus animais, não são nossos? Apenas concordemos com eles, e habitarão conosco.'),
(1005, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 24, 'OT', 'E deram ouvidos a Hamor e a Siquém, seu filho, todos os que saíam pela porta da sua cidade; e foram circuncidados todos os machos, todos os que saíam pela porta da sua cidade.'),
(1006, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 25, 'OT', 'Ao terceiro dia, quando estavam com dores, os dois filhos de Jacó, Simeão e Levi, irmãos de Diná, tomaram cada um a sua espada, entraram na cidade com segurança e mataram todo o homem.'),
(1007, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 26, 'OT', 'E mataram Hamor e seu filho Siquém ao fio da espada; e tomaram Diná da casa de Siquém, e saíram.'),
(1008, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 27, 'OT', 'Os filhos de Jacó vieram sobre os feridos e saquearam a cidade, porque haviam contaminado a sua irmã.'),
(1009, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 28, 'OT', 'Tomaram as suas ovelhas, os seus bois, os seus jumentos, e tudo o que havia na cidade e no campo.'),
(1010, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 29, 'OT', 'E todo o seu gado, e todos os seus pequeninos, e as suas mulheres levaram cativos, e saquearam tudo o que havia nas casas.'),
(1011, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 30, 'OT', 'Então Jacó disse a Simeão e a Levi: Tendes-me perturbado, fazendo-me odioso para os moradores da terra, os cananeus e os ferezeus; e eu sou poucos homens em número; eles se reunirão contra mim e me ferirão, e serei destruído, eu e a minha casa.'),
(1012, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 34, 31, 'OT', 'E disseram: Trataria ele a nossa irmã como a uma prostituta?'),
(1013, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 1, 'OT', 'Levanta-te, sobe a Betel e habita ali; e faze ali um altar ao Deus que te apareceu quando fugias da face de Esaú, teu irmão.'),
(1014, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 2, 'OT', 'Então disse Jacó à sua casa e a todos os que estavam com ele: Tirai os deuses estranhos que há no meio de vós, purificai-vos e trocai as vossas vestes.'),
(1015, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 3, 'OT', 'Levantemo-nos e subamos a Betel; ali farei um altar ao Deus que me respondeu no dia da minha angústia, e que esteve comigo no caminho por onde andei.'),
(1016, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 4, 'OT', 'Entregaram, pois, a Jacó todos os deuses estrangeiros que havia em suas mãos e os brincos que estavam em suas orelhas; e Jacó os escondeu debaixo do carvalho que está junto a Siquém.'),
(1017, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 5, 'OT', 'E partiram; e o terror de Deus caiu sobre as cidades ao redor deles, e não perseguiram os filhos de Jacó.'),
(1018, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 6, 'OT', 'Jacó chegou a Luz, que está na terra de Canaã (esta é Betel), ele e todo o povo que estava com ele.'),
(1019, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 7, 'OT', 'E edificou ali um altar e chamou o lugar de El-beth-el, porque ali Deus se lhe havia revelado quando fugia da presença de seu irmão.'),
(1020, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 8, 'OT', 'Morreu Débora, a ama de Rebeca, e foi sepultada abaixo de Betel, debaixo do carvalho; e Jacó chamou-lhe Alom-Bacute.'),
(1021, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 9, 'OT', 'Deus apareceu novamente a Jacó, quando ele voltava de Paddan-aram, e o abençoou.'),
(1022, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 10, 'OT', 'E disse-lhe Deus: O teu nome é Jacó; não se chamará mais o teu nome Jacó, mas Israel será o teu nome. E chamou o seu nome Israel.'),
(1023, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 11, 'OT', 'Disse-lhe Deus: Eu sou o Deus Todo-poderoso; sê fecundo e multiplica-te; uma nação e uma multidão de nações virão de ti, e reis sairão dos teus lombos.'),
(1024, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 12, 'OT', 'E a terra que dei a Abraão e a Isaque, a ti a darei; e à tua descendência depois de ti darei a terra.'),
(1025, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 13, 'OT', 'E Deus subiu de sobre ele, no lugar onde lhe havia falado.'),
(1026, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 14, 'OT', 'Jacó ergueu uma coluna de pedra no lugar onde Deus falara com ele; derramou sobre ela uma libação e deitou sobre ela azeite.'),
(1027, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 15, 'OT', 'E chamou Jacó o nome daquele lugar, onde Deus falara com ele, Betel.'),
(1028, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 16, 'OT', 'Partiram de Betel, e ainda havia um pequeno trecho de terra para chegar a Efrata, quando Raquel entrou em trabalho de parto, e teve dificuldade no parto.'),
(1029, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 17, 'OT', 'E aconteceu que, tendo ela dificuldade em seu parto, a parteira lhe disse: Não temas, porque também este filho terás.'),
(1030, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 18, 'OT', 'E aconteceu que, ao sair-lhe a alma, porque morreu, ela chamou o seu nome Benoni; mas seu pai o chamou Benjamim.'),
(1031, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 19, 'OT', 'Morreu Raquel e foi sepultada no caminho de Efrata, que é Beth-lehem.'),
(1032, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 20, 'OT', 'Jacó ergueu uma coluna sobre a sua sepultura; esta é a coluna da sepultura de Raquel até o dia de hoje.'),
(1033, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 21, 'OT', 'Partiu Israel e armou a sua tenda para além de Migdal Eder.'),
(1034, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 22, 'OT', 'E aconteceu que, enquanto Israel habitava naquela terra, Ruben foi e deitou-se com Bila, concubina de seu pai; e Israel soube disso. E os filhos de Jacó eram doze.'),
(1035, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 23, 'OT', 'Os filhos de Lia: Rúben, o primogênito de Jacó, depois Simeão e Levi, e Judá, e Issacar e Zebulom.'),
(1036, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 24, 'OT', 'Os filhos de Raquel: José e Benjamim.'),
(1037, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 25, 'OT', 'E os filhos de Bila, serva de Raquel: Dã e Naftali.'),
(1038, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 26, 'OT', 'Os filhos de Zilpa, serva de Lia: Gade e Aser. Estes são os filhos de Jacó, que lhe nasceram em Paddan-aram.'),
(1039, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 27, 'OT', 'Jacó chegou a Isaque, seu pai, em Mamre, em Kiriath-arba (que é Hebrom), onde Abraão e Isaque haviam peregrinado.'),
(1040, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 28, 'OT', 'E foram os dias de Isaque cento e oitenta anos.'),
(1041, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 35, 29, 'OT', 'Isaque expirou e morreu, e foi reunido ao seu povo, velho e farto de dias; e Esaú e Jacó, seus filhos, o sepultaram.'),
(1042, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 1, 'OT', 'Estas são as gerações de Esaú, que é Edom.'),
(1043, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 2, 'OT', 'Esaú tomou suas mulheres dentre as filhas de Canaã: Ada, filha de Elom, o heteu, e Aolibama, filha de Aná, filha de Zibeão, o heveu.'),
(1044, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 3, 'OT', 'E a Basemate, filha de Ismael, irmã de Nebaiote.'),
(1045, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 4, 'OT', 'Ada deu à luz a Esaú o filho Elifaz, e Basemate deu à luz Reuel.'),
(1046, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 5, 'OT', 'E Aolibama deu à luz a Jeús, a Jalam e a Corá. Estes são os filhos de Esaú, que lhe nasceram na terra de Canaã.'),
(1047, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 6, 'OT', 'Esaú tomou suas mulheres, seus filhos, suas filhas, todas as pessoas de sua casa, seu gado, todos os seus animais e todos os seus bens que havia adquirido na terra de Canaã, e foi para outra terra, para longe de seu irmão Jacó.'),
(1048, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 7, 'OT', 'Porque os seus bens eram muitos para habitarem juntos, e a terra das suas peregrinações não os podia sustentar por causa do seu gado.'),
(1049, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 8, 'OT', 'Esaú habitou no monte Seir; Esaú é Edom.'),
(1050, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 9, 'OT', 'Estas são as gerações de Esaú, pai de Edom, na região montanhosa de Seir.'),
(1051, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 10, 'OT', 'Estes são os nomes dos filhos de Esaú: Elifaz, filho de Ada, mulher de Esaú; Reuel, filho de Basemate, mulher de Esaú.'),
(1052, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 11, 'OT', 'Os filhos de Elifaz foram: Temã, Omar, Zefô, Gaetã e Quenaz.'),
(1053, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 12, 'OT', 'E Timna era concubina de Elifaz, filho de Esaú, e ela deu à luz a Elifaz o filho Amaleque. Estes são os filhos de Ada, mulher de Esaú.'),
(1054, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 13, 'OT', 'Estes foram os filhos de Reuel: Naate, Zera, Sama e Miza; estes foram os filhos de Basemate, mulher de Esaú.'),
(1055, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 14, 'OT', 'Estes foram os filhos de Aolibama, filha de Aná, filha de Zibeão, mulher de Esaú: ela deu a Esaú Jeús, Jalão e Corá.'),
(1056, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 15, 'OT', 'Estes são os chefes dos filhos de Esaú: os filhos de Elifaz, o primogênito de Esaú, foram: o chefe Temã, o chefe Omar, o chefe Zefô, o chefe Quenaz.'),
(1057, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 16, 'OT', 'Chefe Corá, chefe Gatã, chefe Amaleque; estes são os chefes de Elifaz na terra de Edom; estes são os filhos de Ada.'),
(1058, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 17, 'OT', 'Estes são os filhos de Reuel, filho de Esaú: o chefe Naate, o chefe Zera, o chefe Sama, o chefe Miza; estes são os chefes de Reuel na terra de Edom; estes são os filhos de Basemate, mulher de Esaú.'),
(1059, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 18, 'OT', 'E estes são os filhos de Aolibama, mulher de Esaú: o chefe Jeús, o chefe Jalam, o chefe Corá; estes são os chefes de Aolibama, filha de Aná, mulher de Esaú.'),
(1060, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 19, 'OT', 'Estes são os filhos de Esaú, e estes são os seus chefes; ele é Edom.'),
(1061, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 20, 'OT', 'Estes são os filhos de Seir, o horeu, que habitavam a terra: Lotã, Sobal, Zibeão e Aná.'),
(1062, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 21, 'OT', 'E Disom, e Ezer, e Disã; estes são os chefes dos horeus, filhos de Seir, na terra de Edom.'),
(1063, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 22, 'OT', 'Os filhos de Lotã: Hori e Hemã; e a irmã de Lotã: Timna.'),
(1064, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 23, 'OT', 'Estes são os filhos de Sobal: Alvã, Manaate, Ebal, Sefô e Onã.'),
(1065, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 24, 'OT', 'Estes são os filhos de Zibeão: Aiá e Aná. Este é o Aná que achou as fontes de água quente no deserto, quando apascentava os jumentos de seu pai Zibeão.'),
(1066, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 25, 'OT', 'Estes são os filhos de Aná: Disom e Oolibama, filha de Aná.'),
(1067, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 26, 'OT', 'Estes são os filhos de Disã: Hemdã, Esbã, Itrã e Querã.'),
(1068, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 27, 'OT', 'Estes são os filhos de Eser: Bilã, Zaavã e Acã.'),
(1069, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 28, 'OT', 'Estes são os filhos de Disã: Uz e Arã.'),
(1070, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 29, 'OT', 'Estes são os chefes dos horeus: o chefe Lotã, o chefe Sobal, o chefe Zibeão, o chefe Aná.'),
(1071, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 30, 'OT', 'O chefe Disom, o chefe Ezer, o chefe Disã; estes são os chefes dos horeus, segundo os seus chefes, na terra de Seir.'),
(1072, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 31, 'OT', 'Estes são os reis que reinaram na terra de Edom, antes que reinasse um rei sobre os filhos de Israel.'),
(1073, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 32, 'OT', 'Bela, filho de Beor, reinou em Edom, e o nome da sua cidade era Dinabá.'),
(1074, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 33, 'OT', 'Morreu Bela; e Jobabe, filho de Zerá, de Bozra, reinou em seu lugar.'),
(1075, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 34, 'OT', 'Morreu Jobabe; e Husão, da terra dos temanitas, reinou em seu lugar.'),
(1076, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 35, 'OT', 'Morreu Husam, e em seu lugar reinou Hadade, filho de Bedade, que feriu Midiã no campo de Moabe; e o nome da sua cidade era Avite.'),
(1077, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 36, 'OT', 'Morreu Hadade; e Samlá, de Masreca, reinou em seu lugar.'),
(1078, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 37, 'OT', 'Morreu Samlá, e Saul, de Reobote junto ao Rio, reinou em seu lugar.'),
(1079, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 38, 'OT', 'Morreu Saul, e Baal-hanan, filho de Acbor, reinou em seu lugar.'),
(1080, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 39, 'OT', 'E morreu Baal-hanan, filho de Acbor; e Hadar reinou em seu lugar, e o nome da sua cidade era Pau; e o nome da sua mulher era Meetabel, filha de Matred, filha de Me-Zaabe.'),
(1081, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 40, 'OT', 'Estes são os nomes dos chefes de Esaú, segundo as suas famílias, segundo os seus lugares, com os seus nomes: o chefe Timna, o chefe Alva, o chefe Jetete.'),
(1082, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 41, 'OT', 'O chefe Aolibama, o chefe Elá, o chefe Pinom,'),
(1083, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 42, 'OT', 'O chefe Quenaz, o chefe Temã, o chefe Mibzar.'),
(1084, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 36, 43, 'OT', 'Chefe Magdiel, chefe Iram; estes são os chefes de Edom, segundo as suas habitações, na terra da sua possessão. Este é Esaú, pai de Edom.'),
(1085, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 1, 'OT', 'Jacó habitou na terra das peregrinações de seu pai, na terra de Canaã.'),
(1086, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 2, 'OT', 'Estas são as gerações de Jacó: José, aos dezessete anos, apascentava o rebanho com seus irmãos; e o jovem estava com os filhos de Bila e com os filhos de Zilpa, mulheres de seu pai. E José trazia aos seus irmãos uma má fama a seu pai.'),
(1087, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 3, 'OT', 'Israel amava José mais do que a todos os seus filhos, porque ele era filho da sua velhice; e fez-lhe uma túnica de várias cores.'),
(1088, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 4, 'OT', 'Vendo seus irmãos que seu pai o amava mais do que a todos os seus irmãos, odiaram-no e não podiam falar com ele pacificamente.'),
(1089, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 5, 'OT', 'José teve um sonho e o contou a seus irmãos; e eles passaram a odiá-lo ainda mais.'),
(1090, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 6, 'OT', 'Ouvi, por favor, este sonho que tive:'),
(1091, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 7, 'OT', 'Eis que estávamos atando feixes no meio do campo, e eis que o meu feixe se levantava e também ficava em pé, e eis que os vossos feixes o rodeavam e se inclinavam ao meu feixe.'),
(1092, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 8, 'OT', 'Então seus irmãos lhe disseram: "Tu reinarás sobre nós? Tu dominarás sobre nós?" E o odiaram ainda mais por causa de seus sonhos e de suas palavras.'),
(1093, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 9, 'OT', 'E sonhou ainda outro sonho, e o contou a seus irmãos, dizendo: Eis que sonhei mais um sonho, e eis que o sol, a lua e onze estrelas se curvavam diante de mim.'),
(1094, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 10, 'OT', 'Ele o contou a seu pai e a seus irmãos; e seu pai o repreendeu e lhe disse: "Que sonho é este que você teve? Será que eu, sua mãe e seus irmãos viremos a nos curvar diante de você, com o rosto em terra?"'),
(1095, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 11, 'OT', 'Seus irmãos tinham inveja dele, mas seu pai guardou o assunto no coração.'),
(1096, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 12, 'OT', 'E os seus irmãos foram apascentar o rebanho de seu pai em Siquém.'),
(1097, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 13, 'OT', 'Disse Israel a José: "Não estão teus irmãos pastoreando em Siquém? Vem, e eu te enviarei a eles." E ele lhe respondeu: "Eis-me."'),
(1098, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 14, 'OT', 'E ele lhe disse: Vai agora, vê a paz de teus irmãos e a paz do rebanho, e traze-me resposta. Assim o enviou do vale de Hebrom, e ele veio a Siquém.'),
(1099, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 15, 'OT', 'Um homem o encontrou, e eis que ele andava errante pelo campo; e o homem lhe perguntou, dizendo: Que procuras?'),
(1100, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 16, 'OT', 'Procuro meus irmãos; dize-me, por favor, onde eles apascentam o rebanho.'),
(1101, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 17, 'OT', 'O homem disse: "Foram-se daqui, pois ouvi-os dizer: ''Vamos a Dotã''." Então José foi atrás de seus irmãos e os encontrou em Dotã.'),
(1102, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 18, 'OT', 'Eles o viram de longe e, antes que se aproximasse deles, conspiraram contra ele para matá-lo.'),
(1103, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 19, 'OT', 'E disseram uns aos outros: Eis que vem aquele sonhador!'),
(1104, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 20, 'OT', 'Vinde, pois, e matemo-lo, e lancemo-lo numa destas cisternas; e diremos: Uma fera o devorou; e veremos que será dos seus sonhos.'),
(1105, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 21, 'OT', 'E Ruben ouviu isso e o livrou das mãos deles, dizendo: Não lhe tiremos a vida.'),
(1106, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 22, 'OT', 'E disse-lhes Reuven: Não derrameis sangue; lançai-o nesta cova que está no deserto, e não estendais a mão contra ele; para livrá-lo das vossas mãos, a fim de o restituir a seu pai.'),
(1107, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 23, 'OT', 'Quando José chegou aos seus irmãos, eles tiraram dele a sua túnica, a túnica de várias cores que ele vestia.'),
(1108, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 24, 'OT', 'Tomaram-no e o lançaram na cisterna; a cisterna estava vazia, não havia água nela.'),
(1109, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 25, 'OT', 'E assentaram-se a comer pão; e levantaram os olhos e viram, e eis que uma caravana de ismaelitas vinha de Gileade; e seus camelos traziam especiarias, bálsamo e mirra, indo levá-los ao Egito.'),
(1110, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 26, 'OT', 'Então Judá disse aos seus irmãos: "Que proveito haverá em matarmos o nosso irmão e escondermos o seu sangue?"'),
(1111, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 27, 'OT', 'Vinde, e vendamo-lo aos ismaelitas, e não seja a nossa mão sobre ele, porque ele é nosso irmão, nossa carne. E seus irmãos o ouviram.'),
(1112, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 28, 'OT', 'Passando os mercadores midianitas, eles o puxaram e tiraram José da cisterna, e venderam José aos ismaelitas por vinte peças de prata; e levaram José ao Egito.'),
(1113, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 29, 'OT', 'Voltou Reuben ao poço, e eis que José não estava no poço; então rasgou as suas vestes.'),
(1114, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 30, 'OT', 'E voltou aos seus irmãos e disse: O menino não está; e eu, para onde irei?'),
(1115, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 31, 'OT', 'Tomaram a túnica de José, mataram um cabrito e mergulharam a túnica no sangue.'),
(1116, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 32, 'OT', 'E enviaram a túnica de várias cores e a levaram a seu pai, e disseram: "Isto achamos; reconhece agora se é ou não a túnica de teu filho."'),
(1117, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 33, 'OT', 'Ele a reconheceu e disse: "É a túnica de meu filho; uma fera selvagem o devorou; José foi despedaçado!"'),
(1118, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 34, 'OT', 'Então Jacó rasgou as suas vestes, pôs pano de saco sobre os lombos e lamentou por seu filho muitos dias.'),
(1119, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 35, 'OT', 'Levantaram-se, pois, todos os seus filhos e todas as suas filhas para o consolarem, mas ele recusou ser consolado e disse: "Certamente descerei ao meu filho, pranteando, até o Sheol." E seu pai chorou por ele.'),
(1120, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 37, 36, 'OT', 'E os midianitas o venderam no Egito a Potifar, oficial de Faraó, capitão da guarda.'),
(1121, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 1, 'OT', 'Naquele tempo, Judá desceu de entre seus irmãos e foi até um homem de Adulão, cujo nome era Hira.'),
(1122, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 2, 'OT', 'E viu Judá ali a filha de um homem cananeu, cujo nome era Suá; e tomou-a e entrou a ela.'),
(1123, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 3, 'OT', 'Ela concebeu e deu à luz um filho, e chamou o seu nome Er.'),
(1124, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 4, 'OT', 'Ela concebeu novamente e deu à luz um filho, e chamou o seu nome Onã.'),
(1125, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 5, 'OT', 'E ela concebeu novamente e deu à luz um filho, e chamou o seu nome Selá; e ele estava em Quezibe quando ela o deu à luz.'),
(1126, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 6, 'OT', 'Judá tomou uma mulher para Er, o seu primogênito, e o nome dela era Tamar.'),
(1127, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 7, 'OT', 'Er, o primogênito de Judá, era mau aos olhos do SENHOR, e o SENHOR o matou.'),
(1128, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 8, 'OT', 'Então Judá disse a Onã: "Vá até a mulher do seu irmão e cumpra o dever de cunhado com ela, e suscite descendência para o seu irmão."'),
(1129, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 9, 'OT', 'Onan sabia que a descendência não seria sua; por isso, quando se unia à mulher de seu irmão, derramava o sêmen na terra, para não dar descendência a seu irmão.'),
(1130, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 10, 'OT', 'O que ele fazia era mau aos olhos do SENHOR, por isso ele também o matou.'),
(1131, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 11, 'OT', 'Então Judá disse a Tamar, sua nora: Fica-te viúva na casa de teu pai, até que Selá, meu filho, cresça; pois pensava: Para que ele não morra também, como seus irmãos. E Tamar foi e habitou na casa de seu pai.'),
(1132, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 12, 'OT', 'Passando-se muitos dias, morreu a filha de Sua, mulher de Judá; e, consolado Judá, subiu aos tosquiadores das suas ovelhas, ele e Hira, seu amigo, o adulamita, a Timna.'),
(1133, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 13, 'OT', 'Foi anunciado a Tamar: "Eis que o teu sogro sobe a Timna, para tosquiar as suas ovelhas."'),
(1134, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 14, 'OT', 'Então ela tirou de sobre si as vestes da sua viuvez, cobriu-se com um véu e se envolveu, e assentou-se à entrada de Enaim, que está no caminho de Timna, porque viu que Selá já era grande, e ela não lhe fora dada por mulher.'),
(1135, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 15, 'OT', 'Viu-a Judá e a teve por prostituta, porque ela havia coberto o rosto.'),
(1136, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 16, 'OT', 'E desviou-se para ela no caminho e disse: "Deixa-me, por favor, entrar a ti", pois não sabia que ela era sua nora. E ela disse: "Que me darás, para que entres a mim?"'),
(1137, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 17, 'OT', 'Eu enviarei um cabrito do rebanho. Ela disse: Dás-me um penhor até que o envies?'),
(1138, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 18, 'OT', 'Então ele disse: Que penhor te darei? Ela respondeu: O teu selo, o teu cordão e o cajado que está em tua mão. Ele os deu a ela, e entrou a ela, e ela concebeu dele.'),
(1139, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 19, 'OT', 'Levantou-se, foi-se, tirou o véu de sobre si e vestiu as roupas da sua viuvez.'),
(1140, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 20, 'OT', 'Judá enviou o cabrito por meio do seu amigo, o adulamita, para receber o penhor das mãos da mulher, mas ele não a encontrou.'),
(1141, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 21, 'OT', 'E perguntou aos homens daquele lugar, dizendo: Onde está a prostituta que estava no caminho, junto às duas fontes? E disseram: Aqui não houve prostituta alguma.'),
(1142, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 22, 'OT', 'E voltou a Judá e disse: Não a encontrei; e também os homens daquele lugar disseram: Não houve prostituta sagrada aqui.'),
(1143, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 23, 'OT', 'Então disse Judá: "Tome-o para si, para que não sejamos motivo de zombaria. Eis que enviei este cabrito, mas tu não a encontraste."'),
(1144, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 24, 'OT', 'E cerca de três meses depois, foi anunciado a Judá: "Tamar, tua nora, se prostituiu, e eis que está grávida da prostituição." Então disse Judá: "Tirae-a para fora, e seja queimada."'),
(1145, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 25, 'OT', 'Ela foi trazida para fora, e ela mandou dizer ao seu sogro: "Do homem a quem pertencem estas coisas, eu estou grávida." E ela disse: "Reconhece, por favor, de quem é este selo, estes cordões e este cajado."'),
(1146, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 26, 'OT', 'E reconheceu Judá e disse: "Ela é mais justa do que eu, porque não a dei a Selá, meu filho." E não tornou mais a conhecê-la.'),
(1147, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 27, 'OT', 'E aconteceu que, ao tempo de dar à luz, eis que havia gêmeos em seu ventre.'),
(1148, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 28, 'OT', 'E aconteceu que, ao dar à luz, ele pôs a mão para fora; e a parteira a tomou e atou em sua mão um fio vermelho, dizendo: Este saiu primeiro.'),
(1149, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 29, 'OT', 'E aconteceu que, ao recolher a sua mão, eis que saiu o seu irmão; e ela disse: "Como tu rompeste! Sobre ti seja a brecha!" E chamaram o seu nome Perez.'),
(1150, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 38, 30, 'OT', 'Depois saiu o seu irmão, em cuja mão estava o fio escarlate; e chamaram-lhe Zera.'),
(1151, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 1, 'OT', 'E José foi levado para o Egito, e Potifar, oficial de Faraó, capitão da guarda, homem egípcio, comprou-o das mãos dos ismaelitas que o tinham levado para lá.'),
(1152, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 2, 'OT', 'O SENHOR estava com José, e ele se tornou um homem próspero; e estava na casa do seu senhor egípcio.'),
(1153, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 3, 'OT', 'Vendo o seu senhor que o SENHOR estava com ele, e que tudo o que ele fazia o SENHOR prosperava em sua mão,'),
(1154, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 4, 'OT', 'José achou graça aos olhos dele, e o servia; e ele o encarregou da sua casa, e tudo o que tinha entregou em sua mão.'),
(1155, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 5, 'OT', 'E desde que o pôs sobre a sua casa e sobre tudo o que tinha, o SENHOR abençoou a casa do egípcio por causa de José; e a bênção do SENHOR estava sobre tudo o que ele tinha, na casa e no campo.'),
(1156, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 6, 'OT', 'E deixou tudo o que tinha na mão de José, e não sabia de nada do que estava com ele, exceto o pão que comia. E José era formoso de porte e formoso de aparência.'),
(1157, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 7, 'OT', 'E aconteceu depois destas coisas que a mulher de seu senhor lançou os olhos sobre José e disse: Deita-te comigo.'),
(1158, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 8, 'OT', 'Ele, porém, recusou e disse à mulher do seu senhor: Eis que o meu senhor não sabe o que há em casa comigo, e tudo o que tem ele entregou em minha mão.'),
(1159, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 9, 'OT', 'Não há neste homem maior do que eu nesta casa, e ele não me reteve coisa alguma, senão a ti, porque tu és sua mulher; como, pois, faria eu esta grande maldade e pecaria contra Deus?'),
(1160, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 10, 'OT', 'E acontecia que, falando ela a José dia após dia, ele não a ouvia, para deitar-se com ela e estar com ela.'),
(1161, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 11, 'OT', 'Aconteceu naquele dia que ele entrou em casa para fazer o seu trabalho, e não havia nenhum dos homens da casa ali dentro.'),
(1162, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 12, 'OT', 'E ela o segurou pela sua veste, dizendo: Deita-te comigo. E ele deixou a sua veste na mão dela, e fugiu, e saiu para fora.'),
(1163, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 13, 'OT', 'E aconteceu que, vendo ela que ele deixara a sua veste na mão dela e fugira para fora,'),
(1164, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 14, 'OT', 'Ela chamou os homens de sua casa e lhes disse: "Vejam, ele nos trouxe um homem hebreu para zombar de nós! Ele veio a mim para se deitar comigo, e eu gritei em alta voz.'),
(1165, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 15, 'OT', 'E aconteceu que, ouvindo ele que eu levantava a minha voz e gritava, deixou a sua roupa comigo, e fugiu, e saiu para fora.'),
(1166, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 16, 'OT', 'E ela deixou a roupa dele junto a si, até que o seu senhor voltou para casa.'),
(1167, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 17, 'OT', 'E ela lhe falou conforme estas mesmas palavras, dizendo: "O servo hebreu que nos trouxeste veio a mim para zombar de mim."'),
(1168, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 18, 'OT', 'E aconteceu que, levantando eu a minha voz e gritando, ele deixou a sua roupa comigo e fugiu para fora.'),
(1169, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 19, 'OT', 'E aconteceu que, ouvindo o seu senhor as palavras de sua mulher, que lhe falava, dizendo: Conforme a estas mesmas palavras me fez teu servo; e a sua ira se acendeu.'),
(1170, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 20, 'OT', 'O senhor de José o tomou e o colocou na prisão, no lugar onde os presos do rei estavam encarcerados; e ele permaneceu ali na prisão.'),
(1171, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 21, 'OT', 'O SENHOR estava com José, estendeu sobre ele a sua bondade e lhe concedeu favor aos olhos do carcereiro-chefe.'),
(1172, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 22, 'OT', 'O chefe da prisão entregou nas mãos de José todos os presos que estavam na casa da prisão, e tudo o que ali se fazia, ele o fazia.'),
(1173, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 39, 23, 'OT', 'O carcereiro-chefe não se preocupava com nada do que estava sob sua responsabilidade, porque o SENHOR estava com ele; e tudo o que ele fazia, o SENHOR prosperava.'),
(1174, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 1, 'OT', 'Aconteceu depois destas coisas que o copeiro do rei do Egito e o padeiro pecaram contra o seu senhor, o rei do Egito.'),
(1175, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 2, 'OT', 'E indignou-se o faraó contra os seus dois oficiais, contra o chefe dos copeiros e contra o chefe dos padeiros.'),
(1176, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 3, 'OT', 'E entregou-os na prisão, na casa do capitão da guarda, na casa do cárcere, no lugar onde José estava preso.'),
(1177, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 4, 'OT', 'E o capitão da guarda encarregou José de cuidar deles, e ele os servia; e passaram-se dias na prisão.'),
(1178, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 5, 'OT', 'E ambos sonharam um sonho, cada um o seu sonho na mesma noite, cada um conforme a interpretação do seu sonho, o copeiro e o padeiro do rei do Egito, que estavam presos na casa do cárcere.'),
(1179, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 6, 'OT', 'José veio a eles pela manhã, e os viu, e eis que estavam abatidos.'),
(1180, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 7, 'OT', 'Então perguntou aos oficiais de Faraó, que estavam com ele na prisão da casa de seu senhor, dizendo: Por que estão tristes os vossos semblantes hoje?'),
(1181, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 8, 'OT', 'Eles lhe disseram: "Tivemos um sonho, e não há quem o interprete." E José lhes disse: "Não pertencem a Deus as interpretações? Contai-mo, por favor."'),
(1182, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 9, 'OT', 'Então o chefe dos copeiros contou o seu sonho a José e lhe disse: Em meu sonho, eis que havia uma videira diante de mim.'),
(1183, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 10, 'OT', 'E na videira havia três ramos; e ela, como que brotando, floresceu; os seus cachos amadureceram em uvas.'),
(1184, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 11, 'OT', 'E o copo de Faraó estava na minha mão; e eu tomava as uvas, e as espremia no copo de Faraó, e dava o copo na mão de Faraó.'),
(1185, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 12, 'OT', 'E disse-lhe José: Esta é a sua interpretação: os três ramos são três dias.'),
(1186, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 13, 'OT', 'Dentro de três dias, o Faraó levantará a tua cabeça e te restaurará ao teu cargo; e porás a taça do Faraó na sua mão, conforme o costume anterior, quando eras seu copeiro.'),
(1187, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 14, 'OT', 'Somente lembra-te de mim quando te for bem, e faze-me, peço-te, o favor de mencionar-me a Faraó, e tira-me desta casa.'),
(1188, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 15, 'OT', 'Porque certamente fui roubado da terra dos hebreus; e também aqui nada fiz para que me colocassem na cisterna.'),
(1189, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 16, 'OT', 'Vendo o chefe dos padeiros que a interpretação era boa, disse a José: Eu também sonhava, e eis que três cestos de pão branco estavam sobre a minha cabeça.'),
(1190, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 17, 'OT', 'E no cesto mais alto havia de todos os manjares de Faraó, obra de padeiro; e as aves os comiam do cesto de sobre a minha cabeça.'),
(1191, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 18, 'OT', 'Então respondeu José e disse: Esta é a sua interpretação: os três cestos são três dias.'),
(1192, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 19, 'OT', 'Dentro de três dias, Faraó levantará a tua cabeça de sobre ti, e te pendurará num madeiro, e as aves comerão a tua carne de sobre ti.'),
(1193, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 20, 'OT', 'E aconteceu ao terceiro dia, o dia do nascimento de Faraó, que ele fez um banquete para todos os seus servos; e levantou a cabeça do chefe dos copeiros e a cabeça do chefe dos padeiros no meio dos seus servos.'),
(1194, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 21, 'OT', 'E restituiu o chefe dos copeiros ao seu cargo, e ele pôs a taça na mão de Faraó.'),
(1195, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 22, 'OT', 'Mas ao chefe dos padeiros enforcou, conforme José lhes havia interpretado.'),
(1196, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 40, 23, 'OT', 'O copeiro-mor, porém, não se lembrou de José, e o esqueceu.'),
(1197, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 1, 'OT', 'E aconteceu que, ao fim de dois anos inteiros, Faraó sonhou, e eis que ele estava em pé junto ao rio.'),
(1198, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 2, 'OT', 'E eis que subiam do rio sete vacas, formosas à vista e gordas de carne, e pastavam no capim.'),
(1199, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 3, 'OT', 'E eis que subiam do rio, depois delas, outras sete vacas, feias de aparência e magras de carne; e paravam junto às outras vacas na margem do rio.'),
(1200, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 4, 'OT', 'E as vacas feias à vista e magras de carne devoraram as sete vacas formosas à vista e gordas. Então Faraó acordou.'),
(1201, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 5, 'OT', 'E dormiu, e sonhou outra vez: eis que sete espigas subiam de um só colmo, cheias e boas.'),
(1202, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 6, 'OT', 'E eis que sete espigas finas e ressequidas pelo vento oriental brotavam depois delas.'),
(1203, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 7, 'OT', 'E as espigas finas devoraram as sete espigas cheias e boas. Então Faraó acordou, e eis que era um sonho.'),
(1204, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 8, 'OT', 'E aconteceu que pela manhã o seu espírito se perturbou; e ele enviou e chamou todos os magos do Egito e todos os seus sábios; e Faraó lhes contou os seus sonhos, mas não havia quem os interpretasse para Faraó.'),
(1205, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 9, 'OT', 'Então o chefe dos copeiros falou a Faraó, dizendo: Lembro-me hoje dos meus pecados.'),
(1206, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 10, 'OT', 'Faraó indignou-se contra os seus servos, e pôs-me sob custódia na casa do capitão da guarda, a mim e ao chefe dos padeiros.'),
(1207, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 11, 'OT', 'E sonhamos um sonho na mesma noite, eu e ele; cada um sonhamos conforme a interpretação do seu próprio sonho.'),
(1208, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 12, 'OT', 'E estava ali conosco um jovem hebreu, servo do capitão da guarda; contamos-lhe os sonhos, e ele os interpretou para nós, a cada um conforme o seu sonho.'),
(1209, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 13, 'OT', 'E aconteceu que, assim como ele nos interpretou, assim foi: a mim me restituiu ao meu cargo, e a ele o enforcou.'),
(1210, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 14, 'OT', 'Então o faraó enviou e chamou José, e o fizeram sair depressa da prisão; ele rapou a barba, trocou de roupas e foi até o faraó.'),
(1211, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 15, 'OT', 'E disse Faraó a José: Sonhei um sonho, e não há quem o interprete; mas de ti ouvi dizer que, quando ouves um sonho, o interpretas.'),
(1212, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 16, 'OT', 'José respondeu ao faraó: "Não sou eu; Deus dará ao faraó uma resposta de paz."'),
(1213, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 17, 'OT', 'Então Faraó disse a José: Em meu sonho, eu estava em pé na margem do rio.'),
(1214, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 18, 'OT', 'E eis que subiam do rio sete vacas gordas de carne e formosas à vista, e pastavam no prado.'),
(1215, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 19, 'OT', 'E eis que outras sete vacas subiam atrás delas, muito feias de aparência e magras de carne; não vi outras assim em toda a terra do Egito, quanto à fealdade.'),
(1216, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 20, 'OT', 'E as vacas magras e feias comeram as sete primeiras vacas gordas.'),
(1217, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 21, 'OT', 'E elas entraram em seu interior, mas não se percebia que haviam entrado, pois a sua aparência era má como no princípio. Então despertei.'),
(1218, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 22, 'OT', 'Vi também em meu sonho, e eis que sete espigas subiam de um mesmo colmo, cheias e boas.'),
(1219, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 23, 'OT', 'E eis que sete espigas secas, finas e queimadas pelo vento oriental, brotavam depois delas.'),
(1220, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 24, 'OT', 'E as sete espigas finas devoraram as sete espigas boas. Eu o contei aos magos, mas ninguém me explicou o significado.'),
(1221, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 25, 'OT', 'Então José disse ao faraó: O sonho do faraó é um só; o que Deus vai fazer, ele o anunciou ao faraó.'),
(1222, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 26, 'OT', 'As sete vacas formosas são sete anos; e as sete espigas formosas também são sete anos; o sonho é um só.'),
(1223, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 27, 'OT', 'E as sete vacas magras e feias que subiam depois delas são sete anos, e as sete espigas secas e queimadas pelo vento oriental serão sete anos de fome.'),
(1224, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 28, 'OT', 'Isto é o que eu disse a Faraó: Deus mostrou a Faraó o que ele está prestes a fazer.'),
(1225, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 29, 'OT', 'Eis que vêm sete anos de grande fartura em toda a terra do Egito.'),
(1226, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 30, 'OT', 'E depois delas levantar-se-ão sete anos de fome, e toda a fartura será esquecida na terra do Egito, e a fome consumirá a terra.'),
(1227, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 31, 'OT', 'E a fartura não será conhecida na terra, por causa daquela fome que virá depois; pois será gravíssima.'),
(1228, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 32, 'OT', 'E o sonho foi repetido a Faraó duas vezes, porque a coisa está determinada por Deus, e Deus se apressa em realizá-la.'),
(1229, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 33, 'OT', 'Portanto, que Faraó escolha um homem discernente e sábio, e o coloque sobre a terra do Egito.'),
(1230, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 34, 'OT', 'Faça o faraó isso, e nomeie supervisores sobre a terra, e tome a quinta parte da terra do Egito nos sete anos de fartura.'),
(1231, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 35, 'OT', 'E ajuntem todo o alimento destes bons anos que vêm, e amontoem o trigo sob a mão de Faraó, alimento nas cidades, e o guardem.'),
(1232, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 36, 'OT', 'E o alimento será para provisão da terra, para os sete anos de fome que haverá na terra do Egito, para que a terra não seja destruída pela fome.'),
(1233, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 37, 'OT', 'E esta palavra foi boa aos olhos de Faraó e aos olhos de todos os seus servos.'),
(1234, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 38, 'OT', 'E disse Faraó aos seus servos: "Acharemos um homem como este, em quem haja o Espírito de Deus?"'),
(1235, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 39, 'OT', 'Disse Faraó a José: "Já que Deus te fez saber tudo isto, não há ninguém tão entendido e sábio como tu."'),
(1236, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 40, 'OT', 'Tu estarás sobre a minha casa, e pela tua palavra se governará todo o meu povo; somente no trono eu serei maior do que tu.'),
(1237, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 41, 'OT', 'Disse Faraó a José: Vê, eu te coloquei sobre toda a terra do Egito.'),
(1238, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 42, 'OT', 'E o faraó tirou o seu anel da mão e o colocou na mão de José, e o vestiu com vestes de linho fino, e pôs um colar de ouro no seu pescoço.'),
(1239, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 43, 'OT', 'E fê-lo subir no seu segundo carro, e clamavam diante dele: "Ajoelhai!" Assim o pôs sobre toda a terra do Egito.'),
(1240, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 44, 'OT', 'E disse Faraó a José: Eu sou Faraó; e sem ti ninguém levantará a sua mão ou o seu pé em toda a terra do Egito.'),
(1241, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 45, 'OT', 'E o faraó deu a José o nome de Zaphnath-paneah e lhe deu por esposa Asenate, filha de Potífera, sacerdote de On. E José saiu por toda a terra do Egito.'),
(1242, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 46, 'OT', 'José tinha trinta anos quando se apresentou diante do faraó, rei do Egito. E José saiu da presença do faraó e percorreu toda a terra do Egito.'),
(1243, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 47, 'OT', 'E a terra produziu em abundância durante os sete anos de fartura.'),
(1244, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 48, 'OT', 'E ajuntou todo o alimento dos sete anos que houve na terra do Egito, e guardou o alimento nas cidades; o alimento do campo ao redor de cada cidade, ele o depositou dentro dela.'),
(1245, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 49, 'OT', 'José ajuntou trigo em grande abundância, como a areia do mar, até que cessou de contar, porque não havia número.'),
(1246, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 50, 'OT', 'E a José nasceram dois filhos, antes que viesse o ano da fome, os quais lhe deu à luz Asenate, filha de Potífera, sacerdote de Om.'),
(1247, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 51, 'OT', 'E chamou José o nome do primogênito Manassés, porque disse: Deus me fez esquecer de todo o meu trabalho e de toda a casa de meu pai.'),
(1248, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 52, 'OT', 'E ao segundo chamou Efraim, porque Deus me fez frutificar na terra da minha aflição.'),
(1249, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 53, 'OT', 'E acabaram-se os sete anos de fartura que havia na terra do Egito.'),
(1250, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 54, 'OT', 'E começaram a vir os sete anos de fome, como José havia dito; e havia fome em todas as terras, mas em toda a terra do Egito havia pão.'),
(1251, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 55, 'OT', 'E toda a terra do Egito teve fome, e o povo clamou a Faraó por pão; e Faraó disse a todos os egípcios: Ide a José; o que ele vos disser, fazei.'),
(1252, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 56, 'OT', 'E havia fome sobre toda a face da terra; e José abriu todos os celeiros que havia neles, e vendeu aos egípcios; e a fome prevaleceu na terra do Egito.'),
(1253, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 41, 57, 'OT', 'E toda a terra vinha ao Egito para comprar de José, porque a fome era severa em toda a terra.'),
(1254, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 1, 'OT', 'Jacó viu que havia trigo no Egito, e disse Jacó a seus filhos: Por que estais olhando uns para os outros?'),
(1255, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 2, 'OT', 'Disse mais: Eis que ouvi que há trigo no Egito; descei para lá e comprai-nos de lá, para que vivamos e não morramos.'),
(1256, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 3, 'OT', 'Desceram, pois, os dez irmãos de José para comprar trigo do Egito.'),
(1257, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 4, 'OT', 'Mas Jacó não enviou Benjamim, irmão de José, com os seus irmãos, pois disse: Para que não lhe aconteça algum desastre.'),
(1258, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 5, 'OT', 'Os filhos de Israel vieram comprar grãos entre os que vinham, porque havia fome na terra de Canaã.'),
(1259, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 6, 'OT', 'José era o governador da terra; era ele quem vendia a todo o povo da terra. E os irmãos de José vieram e se prostraram diante dele com o rosto em terra.'),
(1260, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 7, 'OT', 'José viu seus irmãos e os reconheceu, mas fingiu não conhecê-los e lhes falou asperamente. Perguntou-lhes: "De onde vocês vêm?" Eles responderam: "Da terra de Canaã, para comprar mantimento."'),
(1261, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 8, 'OT', 'José reconheceu os seus irmãos, mas eles não o reconheceram.'),
(1262, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 9, 'OT', 'Então José lembrou-se dos sonhos que havia sonhado a respeito deles, e disse-lhes: Vós sois espias; para ver a nudez da terra viestes.'),
(1263, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 10, 'OT', 'Não, senhor meu; mas teus servos vieram para comprar mantimento.'),
(1264, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 11, 'OT', 'Todos nós somos filhos de um mesmo homem; somos homens honestos; os teus servos não são espiões.'),
(1265, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 12, 'OT', 'Não, mas vocês vieram para ver a nudez da terra.'),
(1266, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 13, 'OT', 'Eles responderam: "Nós, teus servos, somos doze irmãos, filhos de um mesmo homem na terra de Canaã; e eis que o mais novo está hoje com nosso pai, mas um já não existe."'),
(1267, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 14, 'OT', 'Isto é o que vos tenho dito: sois espiões.'),
(1268, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 15, 'OT', 'Nisto sereis provados: pela vida de Faraó, não saireis daqui, a menos que vosso irmão mais novo venha aqui.'),
(1269, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 16, 'OT', 'Enviai um dentre vós, e ele traga vosso irmão; mas vós ficareis presos, e vossas palavras serão provadas, se há verdade convosco; e se não, pela vida de Faraó, certamente sois espiões.'),
(1270, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 17, 'OT', 'E reuniu-os na prisão por três dias.'),
(1271, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 18, 'OT', 'No terceiro dia, José lhes disse: Fazei isto e vivereis, pois eu temo a Deus.'),
(1272, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 19, 'OT', 'Se sois homens honestos, que um de vossos irmãos fique preso na casa de vossa guarda; e vós, ide, levai trigo para a fome de vossas casas.'),
(1273, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 20, 'OT', 'E trazei-me o vosso irmão mais novo, e assim vossas palavras serão confirmadas, e não morrereis. E eles assim fizeram.'),
(1274, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 21, 'OT', 'Então disseram uns aos outros: "Na verdade, somos culpados quanto ao nosso irmão, pois vimos a angústia da sua alma quando nos suplicava, e não o ouvimos; por isso veio sobre nós esta angústia."'),
(1275, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 22, 'OT', 'Então Rúben lhes respondeu: "Não lhes disse eu: ''Não pequem contra o menino''? Mas vocês não me ouviram; e agora o seu sangue está sendo requerido."'),
(1276, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 23, 'OT', 'E eles não sabiam que José os entendia, porque havia um intérprete entre eles.'),
(1277, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 24, 'OT', 'E retirou-se deles e chorou. Depois voltou a eles e lhes falou, e tomou Simeão dentre eles, e o amarrou diante dos seus olhos.'),
(1278, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 25, 'OT', 'E José ordenou que enchessem os seus sacos de trigo, e que devolvessem o dinheiro de cada um no seu saco, e que lhes dessem provisões para o caminho; e assim lhes foi feito.'),
(1279, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 26, 'OT', 'E carregaram o seu trigo sobre os seus jumentos e partiram dali.'),
(1280, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 27, 'OT', 'E abriu um deles o seu saco para dar ração ao seu jumento na hospedaria, e viu o seu dinheiro; e eis que ele estava na boca do seu saco.'),
(1281, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 28, 'OT', 'E disse a seus irmãos: Tornou-se o meu dinheiro, e eis que está também na minha sacola. Então lhes desfaleceu o coração, e tremiam, dizendo um ao outro: Que é isto que Deus nos fez?'),
(1282, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 29, 'OT', 'E vieram a Jacó, seu pai, na terra de Canaã, e contaram-lhe tudo o que lhes havia acontecido, dizendo:'),
(1283, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 30, 'OT', 'O homem, o senhor da terra, falou conosco asperamente e nos tratou como espiões da terra.'),
(1284, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 31, 'OT', 'Somos homens honestos; não fomos espiões.'),
(1285, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 32, 'OT', 'Somos doze irmãos, filhos de nosso pai; um já não existe, e o mais novo está hoje com nosso pai na terra de Canaã.'),
(1286, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 33, 'OT', 'E o homem, o senhor da terra, nos disse: Nisto saberei que sois honestos: deixai comigo um de vossos irmãos, e tomai o trigo para a fome de vossas casas, e ide.'),
(1287, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 34, 'OT', 'Trazei-me vosso irmão mais novo; assim saberei que não sois espias, mas homens honestos. Então vos devolverei vosso irmão, e podereis negociar na terra.'),
(1288, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 35, 'OT', 'E aconteceu que, despejando eles os seus sacos, eis que cada um tinha o seu pacote de prata no seu saco; e viram os pacotes de prata, eles e seu pai, e tiveram medo.'),
(1289, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 36, 'OT', 'Então Jacó, seu pai, disse-lhes: Tendes-me desfilhado; José não está mais, e Simeão não está mais; e agora levareis Benjamim. Todas estas coisas vieram sobre mim.'),
(1290, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 37, 'OT', 'Então Rúben disse a seu pai: "Podes matar os meus dois filhos se eu não o trouxer de volta a ti. Entrega-o em minhas mãos, e eu o trarei de volta a ti."'),
(1291, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 42, 38, 'OT', 'Não descerá meu filho convosco, pois seu irmão está morto, e ele ficou sozinho. Se lhe sobrevier algum desastre no caminho em que fordes, fareis descer minhas cãs com tristeza à sepultura.'),
(1292, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 1, 'OT', 'E a fome era grande na terra.'),
(1293, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 2, 'OT', 'E aconteceu que, quando acabaram de comer o trigo que trouxeram do Egito, seu pai lhes disse: "Voltai, comprai-nos um pouco de alimento."'),
(1294, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 3, 'OT', 'Então Judá lhe disse: "O homem nos advertiu solenemente: ''Não vereis a minha face, a menos que vosso irmão esteja convosco.''"'),
(1295, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 4, 'OT', 'Se tu enviares o nosso irmão conosco, desceremos e compraremos alimento para ti.'),
(1296, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 5, 'OT', 'Mas se não o enviares, não desceremos; porque o homem nos disse: Não vereis a minha face, a menos que o vosso irmão esteja convosco.'),
(1297, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 6, 'OT', 'Por que me fizestes este mal, dizendo ao homem que ainda tínheis um irmão?'),
(1298, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 7, 'OT', 'E eles responderam: "Aquele homem nos perguntou detalhadamente sobre nós e sobre nossa família, dizendo: ''Vosso pai ainda vive? Tendes outro irmão?'' E respondemos-lhe conforme essas palavras. Poderíamos nós saber que ele diria: ''Trazei vosso irmão''?"'),
(1299, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 8, 'OT', 'Judá disse a Israel, seu pai: Envia o jovem comigo, e nos levantaremos e iremos, para que vivamos e não morramos, nem nós, nem tu, nem os nossos pequenos.'),
(1300, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 9, 'OT', 'Eu serei fiador por ele; da minha mão o requererás. Se eu não o trouxer a ti e o apresentar diante de ti, serei culpado para contigo para sempre.'),
(1301, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 10, 'OT', 'Se não nos tivéssemos demorado, certamente já teríamos voltado duas vezes.'),
(1302, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 11, 'OT', 'Então Israel, seu pai, lhes disse: Se assim é, fazei isto: tomai dos melhores frutos da terra em vossos vasos, e levai ao homem um presente: um pouco de bálsamo, um pouco de mel, especiarias e mirra, pistácios e amêndoas.'),
(1303, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 12, 'OT', 'Levem o dobro da prata em suas mãos, e a prata que foi devolvida na boca de seus sacos, levem-na de volta em suas mãos; talvez tenha sido um engano.'),
(1304, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 13, 'OT', 'Levem também o seu irmão, levantem-se e voltem ao homem.'),
(1305, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 14, 'OT', 'E o Todo-poderoso vos dê misericórdia diante do homem, para que ele vos devolva o vosso outro irmão e Benjamim; e eu, se ficar privado de filhos, ficarei privado de filhos.'),
(1306, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 15, 'OT', 'Os homens tomaram aquele presente, e levaram dinheiro em dobro em suas mãos, e também Benjamim; levantaram-se, desceram ao Egito e apresentaram-se diante de José.'),
(1307, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 16, 'OT', 'Vendo José Benjamim com eles, disse ao administrador de sua casa: Leva estes homens para dentro de casa, mata um animal e prepara-o, pois estes homens comerão comigo ao meio-dia.'),
(1308, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 17, 'OT', 'O homem fez como José havia ordenado, e o homem levou os homens para a casa de José.'),
(1309, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 18, 'OT', 'Então os homens ficaram com medo, pois foram levados à casa de José, e disseram: Por causa do dinheiro que foi devolvido em nossos sacos da primeira vez, fomos trazidos aqui, para que ele se volte contra nós e caia sobre nós, e nos tome como escravos, juntamente com nossos jumentos.'),
(1310, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 19, 'OT', 'Aproximaram-se do homem que estava sobre a casa de José e falaram com ele à porta da casa.'),
(1311, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 20, 'OT', 'Por favor, senhor, certamente descemos no princípio para comprar alimento.'),
(1312, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 21, 'OT', 'E aconteceu que, ao chegarmos à hospedaria, abrimos os nossos sacos, e eis que o dinheiro de cada homem estava na boca do seu saco, o nosso dinheiro por seu peso; e o trouxemos de volta em nossas mãos.'),
(1313, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 22, 'OT', 'Também trouxemos outro dinheiro em nossas mãos para comprar alimento; não sabemos quem pôs o nosso dinheiro em nossos sacos.'),
(1314, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 23, 'OT', 'Ele respondeu: "A paz esteja com vocês, não temam. O Deus de vocês e o Deus de seu pai lhes deu um tesouro nos seus sacos; o dinheiro de vocês chegou até mim." E trouxe-lhes Simeão.'),
(1315, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 24, 'OT', 'O homem levou os homens à casa de José, deu-lhes água, e eles lavaram os pés; também deu forragem aos seus jumentos.'),
(1316, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 25, 'OT', 'E prepararam o presente até José chegar ao meio-dia, pois tinham ouvido que ali comeriam pão.'),
(1317, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 26, 'OT', 'José entrou em casa, e eles lhe trouxeram para dentro o presente que estava em suas mãos, e prostraram-se diante dele com o rosto em terra.'),
(1318, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 27, 'OT', 'E perguntou-lhes como estavam, e disse: Está bem o vosso pai, o ancião de quem falastes? Ainda vive ele?'),
(1319, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 28, 'OT', 'E eles disseram: "Paz ao teu servo, nosso pai; ele ainda vive." E inclinaram-se e prostraram-se.'),
(1320, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 29, 'OT', 'E levantou os olhos e viu Benjamim, seu irmão, filho de sua mãe, e disse: "É este o vosso irmão mais novo, de quem me falastes?" E disse: "Deus te conceda graça, meu filho."'),
(1321, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 30, 'OT', 'José apressou-se, porque as suas entranhas se comoveram por seu irmão, e procurou um lugar para chorar; entrou no quarto e chorou ali.'),
(1322, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 31, 'OT', 'Lavou o rosto, saiu e, contendo-se, disse: "Ponde pão."'),
(1323, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 32, 'OT', 'E serviram-lhe à parte, e a eles à parte, e aos egípcios que comiam com ele à parte; porque os egípcios não podiam comer pão com os hebreus, pois isso é abominação para os egípcios.'),
(1324, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 33, 'OT', 'E assentaram-se diante dele, o primogênito segundo a sua primogenitura, e o mais novo segundo a sua menoridade; e os homens se maravilharam uns com os outros.'),
(1325, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 43, 34, 'OT', 'E ele lhes enviou porções da sua própria mesa, e a porção de Benjamim era cinco vezes maior do que a de todos eles. E beberam, e se alegraram com ele.'),
(1326, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 1, 'OT', 'Ordenou ao que estava sobre a sua casa, dizendo: Enche os sacos destes homens de mantimento, quanto puderem levar, e põe o dinheiro de cada um na boca do seu saco.'),
(1327, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 2, 'OT', 'E o meu copo, o copo de prata, porás na boca do saco do mais novo, com o dinheiro do seu trigo. E ele fez conforme a palavra de José, que tinha dito.'),
(1328, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 3, 'OT', 'Ao raiar da manhã, os homens foram enviados, eles e os seus jumentos.'),
(1329, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 4, 'OT', 'Tendo eles saído da cidade, e ainda não estando longe, José disse ao que estava sobre a sua casa: Levanta-te, persegue os homens; e, alcançando-os, lhes dirás: Por que pagastes mal por bem?'),
(1330, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 5, 'OT', 'Não é este o copo em que bebe o meu senhor, e em que ele costuma adivinhar? Fizestes mal no que fizestes.'),
(1331, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 6, 'OT', 'E alcançou-os e falou-lhes estas palavras.'),
(1332, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 7, 'OT', 'Eles lhe responderam: "Por que o meu senhor fala tais palavras? Longe estejam os teus servos de fazerem tal coisa!"'),
(1333, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 8, 'OT', 'Eis que o dinheiro que achamos na boca dos nossos sacos, nós o trouxemos de volta a ti desde a terra de Canaã; como, pois, furtaríamos da casa do teu senhor prata ou ouro?'),
(1334, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 9, 'OT', 'Aquele dos teus servos com quem for encontrado, morra; e também nós seremos escravos do meu senhor.'),
(1335, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 10, 'OT', 'Ele respondeu: "Seja também assim conforme as vossas palavras; aquele com quem se achar será meu escravo, e vós sereis inocentes."'),
(1336, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 11, 'OT', 'Apressaram-se, e cada um baixou o seu saco à terra, e cada um abriu o seu saco.'),
(1337, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 12, 'OT', 'E buscou, começando do mais velho e terminando no mais novo; e o copo foi achado no saco de Benjamim.'),
(1338, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 13, 'OT', 'Então rasgaram as suas vestes, e cada um carregou o seu jumento, e voltaram para a cidade.'),
(1339, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 14, 'OT', 'Então Judá e seus irmãos chegaram à casa de José, e ele ainda estava ali; e prostraram-se diante dele em terra.'),
(1340, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 15, 'OT', 'E disse-lhes José: Que é isto que fizestes? Não sabeis vós que um homem como eu certamente adivinha?'),
(1341, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 16, 'OT', 'Então Judá disse: Que diremos ao meu senhor? Que falaremos? E como nos justificaremos? Deus achou a iniquidade de teus servos; eis que somos servos do meu senhor, tanto nós como aquele em cuja mão foi achado o copo.'),
(1342, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 17, 'OT', 'Longe de mim fazer tal coisa! O homem em cuja mão o copo foi encontrado, ele será meu servo; mas vocês subam em paz para seu pai.'),
(1343, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 18, 'OT', 'Então Judá se aproximou dele e disse: "Por favor, meu senhor, permite que teu servo fale uma palavra aos ouvidos de meu senhor, e não se acenda a tua ira contra o teu servo, pois tu és como o Faraó.'),
(1344, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 19, 'OT', 'Meu senhor perguntou a seus servos, dizendo: Tendes vós pai ou irmão?'),
(1345, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 20, 'OT', 'E dissemos a meu senhor: Temos um pai idoso, e um filho da sua velhice, o mais novo, cujo irmão morreu; e ele ficou sozinho de sua mãe, e seu pai o ama.'),
(1346, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 21, 'OT', 'Trazei-mo a mim, e porei os meus olhos sobre ele.'),
(1347, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 22, 'OT', 'Dissemos a meu senhor: "O jovem não pode deixar seu pai; se deixar seu pai, morrerá."'),
(1348, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 23, 'OT', 'Então disseste a teus servos: Se vosso irmão mais novo não descer convosco, não tornareis a ver a minha face.'),
(1349, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 24, 'OT', 'E aconteceu que, subindo nós a teu servo, meu pai, e contando-lhe as palavras de meu senhor,'),
(1350, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 25, 'OT', 'E disse nosso pai: Voltai, comprai-nos um pouco de comida.'),
(1351, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 26, 'OT', 'Não podemos descer; se o nosso irmão mais novo estiver conosco, desceremos, pois não podemos ver a face do homem se o nosso irmão mais novo não estiver conosco.'),
(1352, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 27, 'OT', 'Então teu servo, meu pai, nos disse: Vós sabeis que minha mulher me deu dois filhos.'),
(1353, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 28, 'OT', 'Um saiu de mim, e eu disse: Certamente foi despedaçado, e não o tenho visto até agora.'),
(1354, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 29, 'OT', 'Se agora também tirardes este da minha presença, e lhe acontecer algum desastre, fareis descer as minhas cãs com tristeza à sepultura.'),
(1355, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 30, 'OT', 'Agora, pois, ao voltar eu a teu servo, meu pai, e o jovem não estando conosco — visto que a sua alma está ligada à alma dele —'),
(1356, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 31, 'OT', 'acontecerá que, quando ele vir que o jovem não está, morrerá; e teus servos farão descer as cãs de teu servo, nosso pai, com tristeza à sepultura.'),
(1357, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 32, 'OT', 'Porque teu servo se tornou fiador do jovem diante de meu pai, dizendo: Se eu não o trouxer de volta a ti, serei culpado diante de meu pai para sempre.'),
(1358, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 33, 'OT', 'Agora, pois, fique teu servo no lugar do jovem como escravo de meu senhor, e que o jovem suba com seus irmãos.'),
(1359, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 44, 34, 'OT', 'Porque como subirei a meu pai, se o jovem não estiver comigo? Para que eu não veja o mal que sobrevirá a meu pai.'),
(1360, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 1, 'OT', 'José não pôde mais se conter diante de todos os que estavam ao seu redor, e clamou: "Fazei sair todos os homens da minha presença!" E não ficou ninguém com ele quando José se deu a conhecer a seus irmãos.'),
(1361, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 2, 'OT', 'E levantou a sua voz em choro, e os egípcios o ouviram, e a casa de Faraó o ouviu.'),
(1362, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 3, 'OT', 'E José disse a seus irmãos: "Eu sou José! Meu pai ainda vive?" E seus irmãos não puderam responder-lhe, porque estavam aterrorizados diante dele.'),
(1363, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 4, 'OT', 'Peço-vos, chegai-vos a mim. E eles se aproximaram. Então ele disse: Eu sou José, vosso irmão, a quem vendestes para o Egito.'),
(1364, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 5, 'OT', 'Agora, pois, não vos entristeçais, nem vos irrite contra vós mesmos, porque me vendestes para cá; pois para preservação da vida Deus me enviou diante de vós.'),
(1365, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 6, 'OT', 'Porque já houve dois anos de fome no meio da terra, e ainda restam cinco anos em que não haverá lavoura nem colheita.'),
(1366, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 7, 'OT', 'Deus me enviou adiante de vocês para deixar um remanescente de vocês na terra e para preservar-lhes a vida por meio de um grande livramento.'),
(1367, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 8, 'OT', 'Agora, não fostes vós que me enviastes para cá, mas Deus; e ele me pôs por pai de Faraó, e por senhor de toda a sua casa, e governador em toda a terra do Egito.'),
(1368, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 9, 'OT', 'Apressai-vos, subi a meu pai e dizei-lhe: Assim diz o teu filho José: Deus me pôs por senhor de todo o Egito; desce a mim, não te demores.'),
(1369, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 10, 'OT', 'Habitarás na terra de Gósen e estarás perto de mim, tu, os teus filhos, os filhos dos teus filhos, as tuas ovelhas, o teu gado e tudo o que tens.'),
(1370, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 11, 'OT', 'Ali te sustentarei, porque ainda haverá cinco anos de fome, para que não sejas reduzido à pobreza, tu, a tua casa e tudo o que tens.'),
(1371, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 12, 'OT', 'E eis que vossos olhos veem, e os olhos de meu irmão Benjamim, que é a minha boca que vos fala.'),
(1372, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 13, 'OT', 'Anunciai a meu pai toda a minha glória no Egito e tudo o que vistes; apressai-vos e fazei descer meu pai para cá.'),
(1373, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 14, 'OT', 'E lançou-se ao pescoço de Benjamim, seu irmão, e chorou; e Benjamim chorou sobre o seu pescoço.'),
(1374, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 15, 'OT', 'E beijou todos os seus irmãos e chorou sobre eles; e depois disso, seus irmãos falaram com ele.'),
(1375, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 16, 'OT', 'E a notícia chegou à casa do faraó, dizendo: "Os irmãos de José vieram." E isso agradou ao faraó e aos seus oficiais.'),
(1376, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 17, 'OT', 'Disse o faraó a José: "Dize a teus irmãos: Fazei isto: carregai vossos animais e parti, ide à terra de Canaã.'),
(1377, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 18, 'OT', 'Tomai vosso pai e vossas famílias e vinde a mim; e eu vos darei o melhor da terra do Egito, e comereis a gordura da terra.'),
(1378, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 19, 'OT', 'Tu és ordenado: fazei isto: tomai para vós carros da terra do Egito para vossos filhos e para vossas mulheres, e levai vosso pai, e vinde.'),
(1379, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 20, 'OT', 'Não vos preocupeis com vossos bens, pois o melhor de toda a terra do Egito será vosso.'),
(1380, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 21, 'OT', 'E os filhos de Israel fizeram assim; e José lhes deu carros, conforme a ordem de Faraó, e lhes deu provisões para o caminho.'),
(1381, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 22, 'OT', 'A todos eles deu, a cada um, mudas de roupas; mas a Benjamim deu trezentas peças de prata e cinco mudas de roupas.'),
(1382, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 23, 'OT', 'E a seu pai enviou assim: dez jumentos carregados do melhor do Egito, e dez jumentas carregadas de trigo, pão e mantimento para seu pai, para o caminho.'),
(1383, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 24, 'OT', 'Despediu os seus irmãos, e eles partiram; e disse-lhes: Não vos irriteis pelo caminho.'),
(1384, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 25, 'OT', 'Subiram do Egito e vieram à terra de Canaã, a Jacó, seu pai.'),
(1385, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 26, 'OT', 'E anunciaram-lhe, dizendo: José ainda vive, e ele é governante em toda a terra do Egito. E seu coração ficou paralisado, porque não lhes acreditava.'),
(1386, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 27, 'OT', 'E contaram-lhe todas as palavras de José, que ele lhes havia falado; e vendo ele os carros que José enviara para levá-lo, reviveu o espírito de Jacó, seu pai.'),
(1387, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 45, 28, 'OT', 'Basta! Ainda vive meu filho José; eu irei e o verei antes que eu morra.'),
(1388, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 1, 'OT', 'Partiu Israel com tudo o que tinha, e veio a Berseba, e ofereceu sacrifícios ao Deus de seu pai Isaque.'),
(1389, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 2, 'OT', 'E Deus falou a Israel em visões da noite, e disse: Jacó, Jacó! E ele respondeu: Eis-me.'),
(1390, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 3, 'OT', 'E disse: Eu sou o Deus, o Deus de teu pai; não temas descer ao Egito, porque ali farei de ti uma grande nação.'),
(1391, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 4, 'OT', 'Eu descerei contigo ao Egito, e certamente te farei subir novamente; e José porá a mão sobre os teus olhos.'),
(1392, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 5, 'OT', 'Jacó levantou-se de Berseba, e os filhos de Israel levaram Jacó, seu pai, e seus pequeninos, e suas mulheres, nos carros que Faraó enviara para levá-lo.'),
(1393, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 6, 'OT', 'Tomaram o seu gado e os seus bens que haviam adquirido na terra de Canaã, e vieram ao Egito, Jacó e toda a sua descendência com ele.'),
(1394, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 7, 'OT', 'Os seus filhos e os filhos dos seus filhos com ele, as suas filhas e as filhas dos seus filhos, e toda a sua descendência, levou consigo ao Egito.'),
(1395, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 8, 'OT', 'E estes são os nomes dos filhos de Israel que vieram ao Egito: Jacó e seus filhos. O primogênito de Jacó: Rúben.'),
(1396, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 9, 'OT', 'Os filhos de Rúben: Hanoc, Palu, Hezrom e Carmi.'),
(1397, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 10, 'OT', 'E os filhos de Simeão: Jemuel, Jamim, Oade, Jaquim, Zoar e Saul, filho da cananeia.'),
(1398, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 11, 'OT', 'E os filhos de Levi: Gérson, Coate e Merari.'),
(1399, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 12, 'OT', 'Os filhos de Judá: Er, Onã, Selá, Perez e Zerá; Er e Onã morreram na terra de Canaã; e os filhos de Perez foram Hezrom e Hamul.'),
(1400, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 13, 'OT', 'E os filhos de Issacar: Tola, Puvá, Jó e Sinrom.'),
(1401, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 14, 'OT', 'Os filhos de Zebulom: Sered, Elom e Jaleel.'),
(1402, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 15, 'OT', 'Estes são os filhos de Lia, que ela deu à luz a Jacó em Paddan-aram, juntamente com sua filha Diná; todas as pessoas de seus filhos e de suas filhas eram trinta e três.'),
(1403, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 16, 'OT', 'E os filhos de Gade: Zifiom, Hagui, Suni, Ezbon, Eri, Arodi e Areli.'),
(1404, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 17, 'OT', 'E os filhos de Aser: Imna, e Isva, e Isvi, e Beria, e Sera, sua irmã; e os filhos de Beria: Héber e Malquiel.'),
(1405, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 18, 'OT', 'Estes são os filhos de Zilpa, que Labão deu a sua filha Lia; e ela deu à luz estes a Jacó: dezesseis pessoas.'),
(1406, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 19, 'OT', 'Os filhos de Raquel, esposa de Jacó: José e Benjamim.'),
(1407, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 20, 'OT', 'E nasceram a José, na terra do Egito, os filhos que lhe deu Asenate, filha de Potífera, sacerdote de Om: Manassés e Efraim.'),
(1408, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 21, 'OT', 'Os filhos de Benjamim: Bela, Bequer, Asbel, Gera, Naamã, Eí, Rôs, Mupim, Hupim e Arde.'),
(1409, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 22, 'OT', 'Estes são os filhos de Raquel, que nasceram a Jacó; ao todo, catorze pessoas.'),
(1410, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 23, 'OT', 'E os filhos de Dã: Husim.'),
(1411, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 24, 'OT', 'Os filhos de Naftali: Jaziel, Guni, Jezer e Silém.'),
(1412, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 25, 'OT', 'Estes são os filhos de Bilha, que Labão deu a sua filha Raquel; e ela deu à luz estes a Jacó; todas as almas foram sete.'),
(1413, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 26, 'OT', 'Todas as pessoas que vieram com Jacó para o Egito, descendentes dele, sem contar as mulheres dos filhos de Jacó, totalizaram sessenta e seis pessoas.'),
(1414, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 27, 'OT', 'E os filhos de José, que lhe nasceram no Egito, eram duas pessoas. Todas as pessoas da casa de Jacó que vieram ao Egito foram setenta.'),
(1415, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 28, 'OT', 'Enviou Judá adiante de si a José, para que este o guiasse até Gósen; e chegaram à terra de Gósen.'),
(1416, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 29, 'OT', 'José aprontou o seu carro e subiu ao encontro de Israel, seu pai, em Gósen. Ao vê-lo, lançou-se ao seu pescoço e chorou sobre o seu pescoço longamente.'),
(1417, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 30, 'OT', 'Disse Israel a José: Morro agora, depois de ver o teu rosto, porque ainda vives.'),
(1418, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 31, 'OT', 'Então José disse a seus irmãos e à casa de seu pai: "Subirei e anunciarei a Faraó, e lhe direi: Meus irmãos e a casa de meu pai, que estavam na terra de Canaã, vieram a mim."'),
(1419, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 32, 'OT', 'Os homens são pastores de ovelhas, pois eram homens de gado, e trouxeram consigo as suas ovelhas, o seu gado e tudo o que possuem.'),
(1420, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 33, 'OT', 'Quando Faraó vos chamar e perguntar: "Qual é a vossa ocupação?",'),
(1421, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 46, 34, 'OT', 'Então direis: Teus servos foram homens de gado desde a nossa mocidade até agora, tanto nós como os nossos pais; para que habiteis na terra de Gósen, porque todo pastor de ovelhas é abominação para os egípcios.'),
(1422, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 1, 'OT', 'José veio e anunciou ao faraó, dizendo: "Meu pai e meus irmãos, com suas ovelhas e seus bois, e tudo o que têm, vieram da terra de Canaã, e eis que estão na terra de Gósen."'),
(1423, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 2, 'OT', 'E tomou cinco dentre seus irmãos e os apresentou diante de Faraó.'),
(1424, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 3, 'OT', 'Então Faraó perguntou aos irmãos de José: "Qual é a vossa ocupação?" E eles responderam a Faraó: "Teus servos são pastores de ovelhas, tanto nós como os nossos pais."'),
(1425, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 4, 'OT', 'Disseram ao faraó: "Viemos para habitar nesta terra, porque não há pasto para os rebanhos dos teus servos, pois a fome é severa na terra de Canaã. Agora, pois, que teus servos habitem na terra de Gósen."'),
(1426, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 5, 'OT', 'Então o faraó disse a José: "Teu pai e teus irmãos vieram a ti."'),
(1427, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 6, 'OT', 'A terra do Egito está diante de ti; no melhor da terra, faze habitar teu pai e teus irmãos; habitem na terra de Gósen. E se sabes que entre eles há homens capazes, coloca-os como chefes do gado sobre o que é meu.'),
(1428, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 7, 'OT', 'José trouxe Jacó, seu pai, e o apresentou diante de Faraó; e Jacó abençoou Faraó.'),
(1429, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 8, 'OT', 'Então Faraó perguntou a Jacó: "Quantos são os dias dos anos da tua vida?"'),
(1430, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 9, 'OT', 'Jacó disse a Faraó: Os dias dos anos das minhas peregrinações são cento e trinta anos; poucos e maus foram os dias dos anos da minha vida, e não alcançaram os dias dos anos da vida de meus pais nos dias das suas peregrinações.'),
(1431, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 10, 'OT', 'Jacó abençoou o faraó e saiu da presença do faraó.'),
(1432, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 11, 'OT', 'E José estabeleceu seu pai e seus irmãos e lhes deu propriedade na terra do Egito, no melhor da terra, na terra de Ramessés, como Faraó havia ordenado.'),
(1433, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 12, 'OT', 'José sustentou com pão o seu pai, os seus irmãos e toda a casa de seu pai, conforme o número dos filhos.'),
(1434, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 13, 'OT', 'E não havia pão em toda a terra, porque a fome era muito severa; e a terra do Egito e a terra de Canaã desfaleciam por causa da fome.'),
(1435, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 14, 'OT', 'José recolheu todo o dinheiro que havia na terra do Egito e na terra de Canaã, pelo trigo que compravam; e José trouxe o dinheiro para a casa do Faraó.'),
(1436, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 15, 'OT', 'Acabando-se o dinheiro na terra do Egito e na terra de Canaã, todos os egípcios vieram a José, dizendo: Dá-nos pão; por que morreríamos diante de ti? Pois o dinheiro se acabou.'),
(1437, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 16, 'OT', 'E José disse: Trazei o vosso gado, e eu vos darei em troca do vosso gado, se o dinheiro faltar.'),
(1438, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 17, 'OT', 'E trouxeram o seu gado a José; e José deu-lhes pão em troca dos cavalos, e do rebanho das ovelhas, e do rebanho do gado, e dos jumentos; e os sustentou com pão naquele ano, por todo o seu gado.'),
(1439, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 18, 'OT', 'E terminado aquele ano, vieram a ele no segundo ano e disseram-lhe: Não esconderemos do meu senhor que o dinheiro acabou, e os rebanhos e o gado pertencem ao meu senhor; nada restou diante do meu senhor, senão o nosso corpo e a nossa terra.'),
(1440, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 19, 'OT', 'Por que morreríamos diante dos teus olhos, tanto nós como a nossa terra? Compra-nos a nós e a nossa terra por pão, e nós e a nossa terra seremos servos de Faraó; e dá semente, para que vivamos e não morramos, e a terra não fique desolada.'),
(1441, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 20, 'OT', 'José comprou toda a terra do Egito para o faraó, porque os egípcios venderam cada um o seu campo, pois a fome havia se agravado sobre eles; e a terra passou a pertencer ao faraó.'),
(1442, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 21, 'OT', 'E ao povo, fê-lo passar às cidades, desde uma extremidade do Egito até a outra.'),
(1443, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 22, 'OT', 'Somente a terra dos sacerdotes não a comprou, porque os sacerdotes tinham uma porção estabelecida do faraó, e comiam da sua porção que o faraó lhes havia dado; por isso não venderam a sua terra.'),
(1444, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 23, 'OT', 'Então José disse ao povo: Eis que hoje comprei a vós e a vossa terra para o Faraó; eis aqui tendes semente para vós, e semeareis a terra.'),
(1445, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 24, 'OT', 'E será que, das colheitas, dareis a quinta parte a Faraó; e as quatro partes serão vossas, para semente do campo, e para o vosso alimento, e para os que estão nas vossas casas, e para comerem vossos filhos.'),
(1446, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 25, 'OT', 'E disseram: Tu nos preservaste a vida; achemos graça aos olhos de meu senhor, e seremos servos de Faraó.'),
(1447, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 26, 'OT', 'José estabeleceu isto como estatuto até o dia de hoje sobre a terra do Egito: para Faraó, o quinto. Somente a terra dos sacerdotes não ficou pertencendo a Faraó.'),
(1448, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 27, 'OT', 'Israel habitou na terra do Egito, na terra de Gósen; nela tomaram posse, e frutificaram, e multiplicaram-se muito.'),
(1449, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 28, 'OT', 'Jacó viveu na terra do Egito dezessete anos; e os dias de Jacó, os anos da sua vida, foram cento e quarenta e sete anos.'),
(1450, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 29, 'OT', 'Chegando-se os dias de Israel para morrer, chamou a seu filho José e disse-lhe: Se agora achei graça aos teus olhos, põe a tua mão debaixo da minha coxa e faze comigo bondade e verdade; não me enterres no Egito.'),
(1451, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 30, 'OT', 'Quando eu dormir com meus pais, levar-me-ás do Egito e sepultar-me-ás na sepultura deles. E ele disse: Eu farei conforme a tua palavra.'),
(1452, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 47, 31, 'OT', 'Jura-me, disse ele. E ele lhe jurou. Então Israel se inclinou sobre a cabeceira da cama.'),
(1453, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 1, 'OT', 'E aconteceu depois destas coisas que disseram a José: Eis que teu pai está doente. Então ele tomou consigo os seus dois filhos, Manassés e Efraim.'),
(1454, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 2, 'OT', 'E anunciaram a Jacó: "Eis que teu filho José vem a ti." Então Israel se fortaleceu e se assentou sobre o leito.'),
(1455, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 3, 'OT', 'E Jacó disse a José: O Todo-poderoso me apareceu em Luz, na terra de Canaã, e me abençoou.'),
(1456, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 4, 'OT', 'E disse-me: Eis que te farei frutificar e multiplicar, e te porei por congregação de povos, e darei esta terra à tua descendência depois de ti, em possessão perpétua.'),
(1457, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 5, 'OT', 'Agora, pois, os teus dois filhos, que te nasceram na terra do Egito, antes que eu viesse a ti no Egito, são meus; Efraim e Manassés serão meus, como Rúben e Simeão.'),
(1458, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 6, 'OT', 'Mas a tua descendência, que gerarás depois deles, será tua; pelo nome de seus irmãos serão chamados na sua herança.'),
(1459, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 7, 'OT', 'E eu, quando vinha de Padã, morreu-me Raquel na terra de Canaã, no caminho, quando ainda faltava um pequeno trecho de terra para chegar a Efrata; e eu a sepultei ali, no caminho de Efrata, que é Beth-lehem.'),
(1460, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 8, 'OT', 'E Israel viu os filhos de José e disse: Quem são estes?'),
(1461, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 9, 'OT', 'José disse a seu pai: "Estes são meus filhos, que Deus me deu aqui." E ele disse: "Peço-te, traze-os a mim, para que eu os abençoe."'),
(1462, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 10, 'OT', 'Os olhos de Israel estavam pesados pela velhice, já não podia ver; e ele os fez chegar a si, e os beijou, e os abraçou.'),
(1463, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 11, 'OT', 'Disse Israel a José: Não esperava ver o teu rosto, e eis que Deus me mostrou também a tua descendência.'),
(1464, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 12, 'OT', 'José os tirou de seus joelhos e inclinou-se com o rosto em terra diante dele.'),
(1465, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 13, 'OT', 'Tomou José a ambos: Efraim à sua direita, à esquerda de Israel, e Manassés à sua esquerda, à direita de Israel, e os fez aproximar dele.'),
(1466, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 14, 'OT', 'Então Israel estendeu a sua mão direita e a pôs sobre a cabeça de Efraim, embora este fosse o mais novo, e a sua mão esquerda sobre a cabeça de Manassés, cruzando as mãos, pois Manassés era o primogênito.'),
(1467, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 15, 'OT', 'E abençoou a José e disse: O Deus em cuja presença andaram meus pais Abraão e Isaque, o Deus que me pastoreia desde o meu nascimento até este dia.'),
(1468, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 16, 'OT', 'O anjo que me redimiu de todo o mal abençoe estes jovens; e neles seja invocado o meu nome e o nome de meus pais Abraão e Isaque; e que cresçam em multidão no meio da terra.'),
(1469, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 17, 'OT', 'Vendo José que seu pai punha a mão direita sobre a cabeça de Efraim, isso lhe pareceu mal; e segurou a mão de seu pai para a tirar de sobre a cabeça de Efraim, e a pôr sobre a cabeça de Manassés.'),
(1470, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 18, 'OT', 'José disse a seu pai: "Não assim, meu pai, porque este é o primogênito; põe a tua mão direita sobre a cabeça dele."'),
(1471, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 19, 'OT', 'Seu pai recusou e disse: "Eu sei, meu filho, eu sei; ele também se tornará um povo, e ele também será grande; contudo, seu irmão menor será maior do que ele, e sua descendência se tornará uma multidão de nações."'),
(1472, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 20, 'OT', 'Assim os abençoou naquele dia, dizendo: "Em ti Israel abençoará, dizendo: ''Deus te faça como Efraim e como Manassés''." E pôs Efraim diante de Manassés.'),
(1473, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 21, 'OT', 'E Israel disse a José: Eis que eu morro, mas Deus será convosco e vos fará voltar à terra de vossos pais.'),
(1474, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 48, 22, 'OT', 'E eu te dou um vale a mais do que a teus irmãos, que tomei da mão dos amorreus com a minha espada e com o meu arco.'),
(1475, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 1, 'OT', 'Jacó chamou seus filhos e disse: Ajuntae-vos, e eu vos anunciarei o que vos acontecerá nos últimos dias.'),
(1476, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 2, 'OT', 'Ajuntai-vos e ouvi, filhos de Jacó; e ouvi a Israel, vosso pai.'),
(1477, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 3, 'OT', 'Rúben, tu és meu primogênito, minha força e o princípio do meu vigor; o mais excelente em dignidade e o mais excelente em poder.'),
(1478, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 4, 'OT', 'Impetuoso como as águas, não serás o mais excelente, porque subiste ao leito de teu pai; então o profanaste; subiste à minha cama.'),
(1479, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 5, 'OT', 'Simeão e Levi são irmãos; as suas espadas são instrumentos de violência.'),
(1480, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 6, 'OT', 'Não entre a minha alma no seu conselho secreto; com a sua congregação não se una a minha glória; porque no seu furor mataram homens, e na sua vontade aleijaram bois.'),
(1481, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 7, 'OT', 'Maldito seja o seu furor, porque era forte, e a sua ira, porque era dura; eu os dividirei em Jacó e os espalharei em Israel.'),
(1482, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 8, 'OT', 'Judá, a ti te louvarão teus irmãos; a tua mão estará sobre o pescoço de teus inimigos; os filhos de teu pai se curvarão diante de ti.'),
(1483, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 9, 'OT', 'Judá é um filhote de leão; da presa subiste, filho meu. Ele se encurva e se deita como leão, e como leoa: quem o despertará?'),
(1484, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 10, 'OT', 'O cetro não se apartará de Judá, nem o bastão de autoridade dentre seus pés, até que venha Siló; e a ele se congregarão os povos.'),
(1485, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 11, 'OT', 'Ele amarra o seu jumentinho à videira, e o filho da sua jumenta à cepa mais excelente; lava as suas vestes no vinho, e a sua capa no sangue das uvas.'),
(1486, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 12, 'OT', 'Seus olhos são escuros de vinho, e seus dentes, brancos de leite.'),
(1487, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 13, 'OT', 'Zebulom habitará na costa dos mares; ele será porto de navios, e a sua extremidade alcançará Sidom.'),
(1488, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 14, 'OT', 'Issacar é um jumento de ossos fortes, deitado entre dois fardos.'),
(1489, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 15, 'OT', 'Ele viu que o descanso era bom, e a terra, agradável; inclinou os ombros para levar carga e tornou-se servo sob tributo.'),
(1490, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 16, 'OT', 'Dã julgará o seu povo, como uma das tribos de Israel.'),
(1491, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 17, 'OT', 'Dã será serpente junto ao caminho, uma víbora junto à vereda, que morde os calcanhares do cavalo, e o seu cavaleiro cai para trás.'),
(1492, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 18, 'OT', 'A tua salvação esperei, ó SENHOR.'),
(1493, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 19, 'OT', 'Gade, uma tropa o atacará, mas ele atacará a retaguarda.'),
(1494, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 20, 'OT', 'De Aser, o seu pão será farto, e ele dará iguarias reais.'),
(1495, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 21, 'OT', 'Naftali é uma corça solta; ele profere palavras formosas.'),
(1496, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 22, 'OT', 'José é um ramo frutífero, ramo frutífero junto à fonte; seus ramos se estendem sobre o muro.'),
(1497, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 23, 'OT', 'Os flecheiros o atormentaram, e atiraram contra ele, e o perseguiram com ódio.'),
(1498, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 24, 'OT', 'O seu arco permaneceu firme, e os braços das suas mãos foram fortalecidos pelas mãos do Poderoso de Jacó, donde vem o Pastor, a Pedra de Israel.'),
(1499, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 25, 'OT', 'Pelo Deus de teu pai, que te ajudará, e pelo Todo-poderoso, que te abençoará com bênçãos dos céus de cima, com bênçãos do abismo que está debaixo, com bênçãos dos seios e do ventre.'),
(1500, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 26, 'OT', 'As bênçãos de teu pai excedem as bênçãos de meus pais, até o cume dos montes eternos; estejam elas sobre a cabeça de José e sobre o alto da cabeça do escolhido entre seus irmãos.'),
(1501, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 27, 'OT', 'Benjamim é lobo que despedaça; pela manhã devora a presa, e à tarde reparte o despojo.'),
(1502, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 28, 'OT', 'Todas estas são as doze tribos de Israel; e isto é o que lhes falou seu pai, e os abençoou; a cada um conforme a sua bênção os abençoou.'),
(1503, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 29, 'OT', 'E ordenou-lhes, e disse-lhes: Eu estou para ser reunido ao meu povo; sepultai-me junto a meus pais, na caverna que está no campo de Efrom, o heteu.'),
(1504, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 30, 'OT', 'Na cova que está no campo de Macpela, que está diante de Manre, na terra de Canaã, a qual Abraão comprou com o campo de Efrom, o heteu, por posse de sepultura.'),
(1505, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 31, 'OT', 'Ali sepultaram Abraão e Sara, sua mulher; ali sepultaram Isaque e Rebeca, sua mulher; e ali sepultei Lia.'),
(1506, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 32, 'OT', 'A compra do campo e da caverna que nele está foi feita aos filhos de Hete.'),
(1507, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 49, 33, 'OT', 'E tendo Jacó acabado de dar ordens a seus filhos, recolheu os seus pés na cama, e expirou, e foi reunido ao seu povo.'),
(1508, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 1, 'OT', 'José lançou-se sobre o rosto de seu pai, chorou sobre ele e o beijou.'),
(1509, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 2, 'OT', 'E José ordenou aos seus servos, os médicos, que embalsamassem a seu pai; e os médicos embalsamaram a Israel.'),
(1510, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 3, 'OT', 'E cumpriram-se-lhe quarenta dias, porque assim se cumprem os dias dos que são embalsamados; e os egípcios o choraram setenta dias.'),
(1511, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 4, 'OT', 'Passados os dias de seu pranto, José falou à casa de Faraó, dizendo: Se agora achei graça aos vossos olhos, falai, por favor, aos ouvidos de Faraó, dizendo:'),
(1512, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 5, 'OT', 'Meu pai me fez jurar, dizendo: "Eis que estou morrendo; no túmulo que cavei para mim na terra de Canaã, ali me sepultarás." Agora, pois, deixa-me subir e sepultar meu pai; então voltarei.'),
(1513, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 6, 'OT', 'E disse Faraó: Sobe e sepulta teu pai, como ele te fez jurar.'),
(1514, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 7, 'OT', 'E José subiu para sepultar seu pai; e subiram com ele todos os servos de Faraó, os anciãos da sua casa, e todos os anciãos da terra do Egito.'),
(1515, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 8, 'OT', 'E toda a casa de José, e seus irmãos, e a casa de seu pai; somente deixaram na terra de Gósen os seus pequeninos, e as suas ovelhas, e o seu gado.'),
(1516, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 9, 'OT', 'E subiram com ele também carros e cavaleiros; e o acampamento era muito numeroso.'),
(1517, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 10, 'OT', 'Chegaram à eira de Atade, que está além do Jordão, e ali prantearam com grande e mui profunda lamentação; e José fez por seu pai um luto de sete dias.'),
(1518, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 11, 'OT', 'E os moradores da terra, os cananeus, viram o luto na eira de Atade, e disseram: "Grande é este pranto para os egípcios." Por isso chamaram aquele lugar Abel-Mizraim, que está além do Jordão.'),
(1519, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 12, 'OT', 'E fizeram-lhe os seus filhos assim como ele lhes havia ordenado.'),
(1520, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 13, 'OT', 'Os seus filhos o levaram para a terra de Canaã e o sepultaram na caverna do campo de Macpela, campo que Abraão havia comprado de Efrom, o hitita, como propriedade para sepultura, diante de Manre.'),
(1521, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 14, 'OT', 'E José voltou para o Egito, ele e seus irmãos, e todos os que subiram com ele para sepultar seu pai, depois de haver sepultado seu pai.'),
(1522, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 15, 'OT', 'Vendo os irmãos de José que seu pai já estava morto, disseram: "Talvez José nos guarde rancor e certamente nos retribua todo o mal que lhe fizemos."'),
(1523, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 16, 'OT', 'Mandaram dizer a José: "Teu pai ordenou antes de sua morte, dizendo:'),
(1524, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 17, 'OT', 'Assim dirão a José: "Perdoa, por favor, a transgressão de teus irmãos e o seu pecado, porque te fizeram mal." Agora, pois, perdoa, por favor, a transgressão dos servos do Deus de teu pai. E José chorou quando eles lhe falavam.'),
(1525, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 18, 'OT', 'Então seus irmãos também vieram, prostraram-se diante dele e disseram: Eis-nos por teus servos.'),
(1526, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 19, 'OT', 'Não temais; porventura estou eu no lugar de Deus?'),
(1527, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 20, 'OT', 'Vós planejastes o mal contra mim, mas Deus o planejou para o bem, para fazer como hoje, para preservar a vida de um povo numeroso.'),
(1528, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 21, 'OT', 'Agora, não temais; eu vos sustentarei a vós e a vossos filhos. E os consolou, e falou ao coração deles.'),
(1529, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 22, 'OT', 'José habitou no Egito, ele e a casa de seu pai; e viveu José cento e dez anos.'),
(1530, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 23, 'OT', 'E viu José os filhos de Efraim, da terceira geração; também os filhos de Maquir, filho de Manassés, nasceram sobre os joelhos de José.'),
(1531, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 24, 'OT', 'E disse José a seus irmãos: Eu morro; mas Deus certamente vos visitará e vos fará subir desta terra para a terra que jurou a Abraão, a Isaque e a Jacó.'),
(1532, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 25, 'OT', 'E José fez jurar os filhos de Israel, dizendo: Certamente Deus vos visitará, e fareis subir os meus ossos daqui.'),
(1533, 1, 'GOI_Pt', 'GOI_Pt', 'pt', 'GEN', 50, 26, 'OT', 'Morreu José com cento e dez anos de idade; e o embalsamaram e o puseram num caixão no Egito.'),
(1534, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 1, 'OT', 'Estes são os nomes dos filhos de Israel que entraram no Egito com Jacó, cada um com a sua casa.'),
(1535, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 2, 'OT', 'Rúben, Simeão, Levi e Judá.'),
(1536, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 3, 'OT', 'Issacar, Zebulom e Benjamim.'),
(1537, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 4, 'OT', 'Dã e Naftali, Gade e Aser.'),
(1538, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 5, 'OT', 'Todas as pessoas que descendiam de Jacó eram setenta; José, porém, já estava no Egito.'),
(1539, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 6, 'OT', 'Morreu José, e todos os seus irmãos, e toda aquela geração.'),
(1540, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 7, 'OT', 'Os filhos de Israel frutificaram, e multiplicaram-se, e cresceram, e tornaram-se extremamente numerosos; e a terra se encheu deles.'),
(1541, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 8, 'OT', 'Levantou-se um novo rei sobre o Egito, que não conhecera José.'),
(1542, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 9, 'OT', 'E ele disse ao seu povo: Eis que o povo dos filhos de Israel é numeroso e mais forte do que nós.'),
(1543, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 10, 'OT', 'Eia, sejamos sábios para com ele, para que não se multiplique, e aconteça que, vindo guerra, ele também se una aos nossos inimigos, e peleje contra nós, e suba da terra.'),
(1544, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 11, 'OT', 'E impuseram sobre eles chefes de tributos, para os afligir com suas cargas; e edificaram para Faraó cidades de tesouros, Pitom e Ramessés.'),
(1545, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 12, 'OT', 'Quanto mais o oprimiam, tanto mais se multiplicava e tanto mais se espalhava; e eles se inquietavam por causa dos filhos de Israel.'),
(1546, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 13, 'OT', 'Os egípcios fizeram os filhos de Israel servir com dureza.'),
(1547, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 14, 'OT', 'E amarguraram-lhes a vida com dura servidão, em barro e em tijolos, e com todo o trabalho no campo; com toda a servidão com que os serviam com rigor.'),
(1548, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 15, 'OT', 'O rei do Egito falou às parteiras das hebreias, das quais o nome de uma era Sifrá, e o nome da outra, Puá.'),
(1549, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 16, 'OT', 'E ele disse: Quando ajudardes as hebreias a dar à luz, e as virdes sobre os assentos de parto, se for filho, matai-o; mas se for filha, então viverá.'),
(1550, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 17, 'OT', 'As parteiras, porém, temeram a Deus e não fizeram como o rei do Egito lhes havia ordenado; antes, preservaram os meninos com vida.'),
(1551, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 18, 'OT', 'Então o rei do Egito chamou as parteiras e lhes disse: Por que fizestes isto, que preservastes os meninos com vida?'),
(1552, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 19, 'OT', 'E as parteiras disseram a Faraó: "Porque as mulheres hebreias não são como as egípcias; pois são vigorosas, e dão à luz antes que a parteira chegue a elas."'),
(1553, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 20, 'OT', 'Deus fez bem às parteiras, e o povo se multiplicou e se tornou muito numeroso.'),
(1554, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 21, 'OT', 'E porque as parteiras temeram a Deus, ele lhes estabeleceu casas.'),
(1555, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 1, 22, 'OT', 'Então Faraó ordenou a todo o seu povo, dizendo: "Todo filho que nascer, lançai-o no rio; mas toda filha, preservai com vida."'),
(1556, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 1, 'OT', 'Um homem da casa de Levi foi e tomou por esposa uma filha de Levi.'),
(1557, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 2, 'OT', 'A mulher concebeu, deu à luz um filho e, vendo que ele era bom, escondeu-o por três meses.'),
(1558, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 3, 'OT', 'Não podendo mais escondê-lo, tomou uma cesta de juncos, e a revestiu com betume e piche; e, pondo nela o menino, a colocou entre os juncos à beira do rio.'),
(1559, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 4, 'OT', 'E sua irmã ficou de longe, para saber o que lhe aconteceria.'),
(1560, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 5, 'OT', 'A filha do Faraó desceu para se banhar no rio, e as suas servas caminhavam pela margem do rio. Ela viu a cesta no meio dos juncos e enviou a sua serva para pegá-la.'),
(1561, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 6, 'OT', 'E abriu-a e viu o menino, e eis que o menino chorava; e teve compaixão dele, e disse: Este é um dos meninos dos hebreus.'),
(1562, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 7, 'OT', 'Então a irmã dele disse à filha de Faraó: "Irei eu e chamarei para ti uma mulher que amamenta dentre as hebreias, para que ela amamente o menino para ti?"'),
(1563, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 8, 'OT', 'E a filha do faraó lhe disse: "Vai." E a moça foi e chamou a mãe do menino.'),
(1564, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 9, 'OT', 'Então a filha de Faraó lhe disse: Leva este menino e amamenta-o para mim, e eu te darei o teu salário. E a mulher tomou o menino e o amamentou.'),
(1565, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 10, 'OT', 'O menino cresceu, e ela o trouxe à filha do faraó, e ele se tornou filho dela. Ela lhe deu o nome de Moisés, dizendo: "Porque das águas o tirei."'),
(1566, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 11, 'OT', 'Naqueles dias, Moisés, já adulto, saiu para ver seus irmãos e observou o seu trabalho pesado. Viu um egípcio espancando um hebreu, um de seus irmãos.'),
(1567, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 12, 'OT', 'Olhou para um lado e para o outro e, vendo que não havia ninguém, feriu o egípcio e o escondeu na areia.'),
(1568, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 13, 'OT', 'No dia seguinte, saiu e viu dois hebreus brigando. Então perguntou ao culpado: "Por que você bate no seu próximo?"'),
(1569, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 14, 'OT', 'E ele respondeu: Quem te constituiu príncipe e juiz sobre nós? Pensas matar-me, como mataste o egípcio? Então Moisés temeu e disse: Certamente o caso foi descoberto.'),
(1570, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 15, 'OT', 'E o faraó ouviu esta notícia e procurou matar Moisés; mas Moisés fugiu da presença do faraó e habitou na terra de Midiã, e assentou-se junto ao poço.'),
(1571, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 16, 'OT', 'O sacerdote de Midiã tinha sete filhas, que vieram tirar água e encheram os tanques para dar de beber ao rebanho de seu pai.'),
(1572, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 17, 'OT', 'Os pastores vieram e as expulsaram; então Moisés se levantou, as socorreu e deu de beber ao rebanho delas.'),
(1573, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 18, 'OT', 'E elas chegaram a Reuel, seu pai, e ele disse: Por que voltastes tão depressa hoje?'),
(1574, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 19, 'OT', 'Elas responderam: "Um egípcio nos livrou das mãos dos pastores; e também tirou água para nós em abundância e deu de beber ao rebanho."'),
(1575, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 20, 'OT', 'E ele disse às suas filhas: "E onde está ele? Por que deixastes o homem? Chamai-o para que coma pão."'),
(1576, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 21, 'OT', 'Moisés consentiu em morar com aquele homem, e ele deu a sua filha Zípora a Moisés.'),
(1577, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 22, 'OT', 'Ela deu à luz um filho, e ele lhe chamou Gérson, porque disse: Peregrino fui em terra estrangeira.'),
(1578, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 23, 'OT', 'E aconteceu que, depois de muitos dias, morreu o rei do Egito, e os filhos de Israel suspiraram por causa da servidão, e clamaram; e o seu clamor subiu a Deus, por causa da servidão.'),
(1579, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 24, 'OT', 'Deus ouviu o seu gemido, e Deus lembrou-se da sua aliança com Abraão, com Isaque e com Jacó.'),
(1580, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 2, 25, 'OT', 'Deus viu os filhos de Israel, e Deus os conheceu.'),
(1581, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 1, 'OT', 'Moisés apascentava o rebanho de Jetro, seu sogro, sacerdote de Midiã; e levou o rebanho para além do deserto, e chegou ao monte de Deus, a Horebe.'),
(1582, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 2, 'OT', 'E apareceu-lhe o anjo do SENHOR numa chama de fogo do meio de uma sarça; e ele olhou, e eis que a sarça ardia no fogo, e a sarça não se consumia.'),
(1583, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 3, 'OT', 'Então Moisés disse: "Irei para lá e verei esta grande visão: por que a sarça não se queima?"'),
(1584, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 4, 'OT', 'Vendo o SENHOR que ele se voltava para ver, Deus o chamou do meio da sarça e disse: "Moisés, Moisés!" E ele respondeu: "Eis-me."'),
(1585, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 5, 'OT', 'Não te aproximes daqui; tira as sandálias dos teus pés, porque o lugar em que estás é terra santa.'),
(1586, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 6, 'OT', 'E disse: Eu sou o Deus de teu pai, o Deus de Abraão, o Deus de Isaque e o Deus de Jacó. E Moisés escondeu o rosto, porque temeu olhar para Deus.'),
(1587, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 7, 'OT', 'E disse o SENHOR: Certamente vi a aflição do meu povo que está no Egito, e ouvi o seu clamor por causa dos seus opressores, porque conheci as suas dores.'),
(1588, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 8, 'OT', 'Desci para livrá-lo da mão dos egípcios e para fazê-lo subir daquela terra para uma terra boa e espaçosa, para uma terra que mana leite e mel, para o lugar dos cananeus, dos hititas, dos amorreus, dos ferezeus, dos heveus e dos jebuseus.'),
(1589, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 9, 'OT', 'E agora, eis que o clamor dos filhos de Israel chegou a mim, e também vi a opressão com que os egípcios os oprimem.'),
(1590, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 10, 'OT', 'Vem agora, pois, e eu te enviarei a Faraó, para que tires o meu povo, os filhos de Israel, do Egito.'),
(1591, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 11, 'OT', 'Então Moisés disse a Deus: Quem sou eu, para ir ao faraó e tirar os filhos de Israel do Egito?'),
(1592, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 12, 'OT', 'E Deus disse: Certamente eu serei contigo; e isto te será por sinal de que eu te enviei: quando tiveres tirado o povo do Egito, servireis a Deus neste monte.'),
(1593, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 13, 'OT', 'Então Moisés disse a Deus: "Eis que eu vou aos filhos de Israel e lhes direi: ''O Deus de vossos pais me enviou a vós''; e eles me perguntarão: ''Qual é o seu nome?'' O que lhes direi?"'),
(1594, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 14, 'OT', 'E Deus disse a Moisés: "EU SOU O QUE SOU." E disse: "Assim dirás aos filhos de Israel: ''EU SOU me enviou a vós.''"'),
(1595, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 15, 'OT', 'E Deus disse ainda a Moisés: Assim dirás aos filhos de Israel: O SENHOR, Deus de vossos pais, o Deus de Abraão, o Deus de Isaque e o Deus de Jacó, me enviou a vós; este é o meu nome para sempre, e este é o meu memorial de geração em geração.'),
(1596, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 16, 'OT', 'Vai, e reúne os anciãos de Israel, e dize-lhes: O SENHOR, o Deus de vossos pais, o Deus de Abraão, de Isaque e de Jacó, me apareceu, dizendo: Certamente vos tenho visitado, e visto o que vos é feito no Egito.'),
(1597, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 17, 'OT', 'Portanto, eu disse: Far-vos-hei subir da aflição do Egito para a terra do cananeu, do heteu, do amorreu, do ferezeu, do heveu e do jebuseu, para uma terra que mana leite e mel.'),
(1598, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 18, 'OT', 'E eles ouvirão a tua voz; e irás, tu e os anciãos de Israel, ao rei do Egito, e lhe dirás: O SENHOR, o Deus dos hebreus, nos encontrou; agora, pois, deixe-nos ir caminho de três dias ao deserto, para que sacrifiquemos ao SENHOR nosso Deus.'),
(1599, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 19, 'OT', 'Eu sei, porém, que o rei do Egito não vos deixará ir, nem ainda por mão forte.'),
(1600, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 20, 'OT', 'Estenderei a minha mão e ferirei o Egito com todas as minhas maravilhas que farei no meio dele; e depois disso ele vos deixará ir.'),
(1601, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 21, 'OT', 'E darei graça a este povo aos olhos dos egípcios; e acontecerá que, quando sairdes, não saireis vazios.'),
(1602, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 3, 22, 'OT', 'Cada mulher pedirá à sua vizinha e à sua hospeda objetos de prata, objetos de ouro e vestes; e os poreis sobre vossos filhos e sobre vossas filhas; e despojareis o Egito.'),
(1603, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 1, 'OT', 'Então respondeu Moisés e disse: Mas eis que não crerão em mim, nem ouvirão a minha voz, porque dirão: O SENHOR não te apareceu.'),
(1604, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 2, 'OT', 'O SENHOR lhe perguntou: "O que é isso na tua mão?" Ele respondeu: "Uma vara."'),
(1605, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 3, 'OT', 'Lança-a à terra. Ele a lançou à terra, e ela se tornou em serpente; e Moisés fugiu dela.'),
(1606, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 4, 'OT', 'Disse o SENHOR a Moisés: Estende a tua mão e pega-o pela cauda. Ele estendeu a mão, pegou-o, e tornou-se em vara na sua mão.'),
(1607, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 5, 'OT', 'para que creiam que te apareceu o SENHOR, o Deus de seus pais, o Deus de Abraão, o Deus de Isaque e o Deus de Jacó.'),
(1608, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 6, 'OT', 'Disse-lhe ainda o SENHOR: "Põe agora a tua mão no peito." Ele pôs a mão no peito e, ao retirá-la, eis que a sua mão estava leprosa, branca como a neve.'),
(1609, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 7, 'OT', 'E disse: "Torna a pôr a tua mão no teu peito." E ele pôs a mão no peito; e, tirando-a do peito, eis que ela se tornara como a sua própria carne.'),
(1610, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 8, 'OT', 'E acontecerá que, se não crerem em ti, nem ouvirem a voz do primeiro sinal, crerão na voz do último sinal.'),
(1611, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 9, 'OT', 'E se eles não crerem nestes dois sinais, nem ouvirem a tua voz, tomarás das águas do rio e as derramarás na terra seca; e as águas que tomares do rio se tornarão em sangue sobre a terra seca.'),
(1612, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 10, 'OT', 'Então Moisés disse ao SENHOR: "Ah, Senhor! Eu não sou homem de palavras, nem desde ontem, nem desde anteontem, nem desde que falaste ao teu servo; porque sou pesado de boca e pesado de língua."'),
(1613, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 11, 'OT', 'E disse o SENHOR a ele: Quem fez a boca do homem? Ou quem faz o mudo, ou o surdo, ou o que vê, ou o cego? Não sou eu, o SENHOR?'),
(1614, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 12, 'OT', 'Vai, pois, agora, e eu serei com a tua boca e te ensinarei o que hás de falar.'),
(1615, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 13, 'OT', 'Ah, Senhor! Envia, peço-te, pela mão daquele a quem hás de enviar.'),
(1616, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 14, 'OT', 'Então se acendeu a ira do SENHOR contra Moisés, e disse: Não é Arão, o levita, teu irmão? Eu sei que ele falará muito bem; e eis que ele também sai ao teu encontro; e, vendo-te, se alegrará em seu coração.'),
(1617, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 15, 'OT', 'Tu falarás com ele e porás as palavras na sua boca; e eu estarei com a tua boca e com a sua boca, e vos ensinarei o que haveis de fazer.'),
(1618, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 16, 'OT', 'Ele falará por ti ao povo; e ele será para ti como boca, e tu serás para ele como Deus.'),
(1619, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 17, 'OT', 'Toma esta vara na tua mão, com a qual farás os sinais.'),
(1620, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 18, 'OT', 'Então Moisés foi e voltou a Jetro, seu sogro, e lhe disse: "Deixa-me ir e voltar aos meus irmãos que estão no Egito, para ver se ainda vivem." E Jetro disse a Moisés: "Vai em paz."'),
(1621, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 19, 'OT', 'Disse o SENHOR a Moisés em Midiã: Vai, volta para o Egito, porque todos os homens que procuravam tirar-te a vida morreram.'),
(1622, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 20, 'OT', 'Tomou Moisés sua mulher e seus filhos, e os pôs sobre um jumento, e voltou à terra do Egito; e Moisés tomou a vara de Deus na sua mão.'),
(1623, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 21, 'OT', 'E disse o SENHOR a Moisés: Ao voltares ao Egito, vê que faças diante de Faraó todas as maravilhas que pus em tua mão; mas eu endurecerei o seu coração, e ele não deixará ir o povo.'),
(1624, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 22, 'OT', 'Assim diz o SENHOR: Israel é meu filho, meu primogênito.'),
(1625, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 23, 'OT', 'E eu te disse: Deixa ir o meu filho, para que me sirva; mas tu recusaste deixá-lo ir. Eis que eu matarei o teu filho, o teu primogênito.'),
(1626, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 24, 'OT', 'E aconteceu no caminho, na hospedaria, que o SENHOR o encontrou e procurou matá-lo.'),
(1627, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 25, 'OT', 'Então Zípora tomou uma pedra afiada, cortou o prepúcio de seu filho e o lançou aos pés dele, dizendo: "Certamente tu és para mim um esposo de sangue."'),
(1628, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 26, 'OT', 'E ele se afastou dele. Então ela disse: "Esposo de sangue, por causa da circuncisão."'),
(1629, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 27, 'OT', 'Disse o SENHOR a Arão: Vai ao encontro de Moisés no deserto. E ele foi, encontrou-o no monte de Deus, e o beijou.'),
(1630, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 28, 'OT', 'E relatou Moisés a Arão todas as palavras do SENHOR, que o enviara, e todos os sinais que lhe ordenara.'),
(1631, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 29, 'OT', 'Moisés e Arão foram e reuniram todos os anciãos dos filhos de Israel.'),
(1632, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 30, 'OT', 'E Arão falou todas as palavras que o SENHOR tinha dito a Moisés, e fez os sinais diante dos olhos do povo.'),
(1633, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 4, 31, 'OT', 'O povo creu, e ouviram que o SENHOR havia visitado os filhos de Israel e que tinha visto a sua aflição; então se inclinaram e adoraram.'),
(1634, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 1, 'OT', 'Depois, Moisés e Arão foram e disseram a Faraó: Assim diz o SENHOR, Deus de Israel: Deixa ir o meu povo, para que me celebre uma festa no deserto.'),
(1635, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 2, 'OT', 'Faraó respondeu: "Quem é o SENHOR, para que eu ouça a sua voz e deixe Israel ir? Não conheço o SENHOR, e também não deixarei Israel ir."'),
(1636, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 3, 'OT', 'Eles disseram: O Deus dos hebreus nos chamou; deixe-nos ir três dias de caminho ao deserto para oferecer sacrifícios ao SENHOR, nosso Deus, para que ele não nos atinja com peste ou com espada.'),
(1637, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 4, 'OT', 'Então o rei do Egito lhes disse: Por que, Moisés e Arão, fazeis o povo cessar das suas obras? Ide às vossas cargas.'),
(1638, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 5, 'OT', 'Disse o faraó: Eis que o povo da terra já é numeroso, e vós os fazeis cessar das suas cargas.'),
(1639, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 6, 'OT', 'Naquele mesmo dia, Faraó ordenou aos feitores do povo e aos seus oficiais, dizendo:'),
(1640, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 7, 'OT', 'Não continueis a dar palha ao povo para fazer tijolos, como antes; eles mesmos irão e colherão palha para si.'),
(1641, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 8, 'OT', 'E a quantidade de tijolos que eles faziam ontem e anteontem, imporeis sobre eles; não diminuireis dela, porque estão ociosos; por isso clamam, dizendo: Vamos, sacrifiquemos ao nosso Deus.'),
(1642, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 9, 'OT', 'Aggrave-se o trabalho sobre os homens, e que eles se ocupem nele, e não deem atenção a palavras de mentira.'),
(1643, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 10, 'OT', 'Então saíram os feitores do povo e seus oficiais, e disseram ao povo: Assim diz Faraó: Eu não vos darei palha.'),
(1644, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 11, 'OT', 'Ide vós, tomai para vós palha onde a encontrardes, porque nada se diminuirá do vosso trabalho.'),
(1645, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 12, 'OT', 'Então o povo se espalhou por toda a terra do Egito, para colher palha em vez de restolho.'),
(1646, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 13, 'OT', 'E os feitores os pressionavam, dizendo: Completai o vosso trabalho, a tarefa de cada dia, como quando havia palha.'),
(1647, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 14, 'OT', 'E foram açoitados os oficiais dos filhos de Israel, que os supervisores de Faraó haviam posto sobre eles, dizendo: Por que não cumpristes a vossa tarefa de fazer tijolos, como antes, ontem e hoje?'),
(1648, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 15, 'OT', 'Então os oficiais dos filhos de Israel foram e clamaram ao Faraó, dizendo: Por que fazes assim a teus servos?'),
(1649, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 16, 'OT', 'Não se dá palha aos teus servos, e nos dizem: Fazei tijolos; e eis que os teus servos são açoitados, e a culpa é do teu povo.'),
(1650, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 17, 'OT', 'Vós sois ociosos, vós sois ociosos; por isso dizeis: Vamos, sacrifiquemos ao SENHOR.'),
(1651, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 18, 'OT', 'Ide, pois, trabalhai; palha não vos será dada, e a conta dos tijolos dareis.'),
(1652, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 19, 'OT', 'Os oficiais dos filhos de Israel viram-se em aflição, pois se dizia: "Não diminuireis nada dos vossos tijolos, da tarefa de cada dia no seu dia."'),
(1653, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 20, 'OT', 'Encontraram Moisés e Arão, que estavam à sua espera, quando saíam da presença do Faraó.'),
(1654, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 21, 'OT', 'E disseram-lhes: Que o SENHOR olhe para vós e julgue, pois fizestes o nosso cheiro abominável diante de Faraó e diante de seus servos, dando-lhes a espada na mão para nos matar.'),
(1655, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 22, 'OT', 'Então Moisés voltou ao SENHOR e disse: Senhor, por que fizeste mal a este povo? Por que me enviaste?'),
(1656, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 5, 23, 'OT', 'Desde que fui a Faraó para falar em teu nome, ele tem maltratado este povo; e de modo algum tens livrado o teu povo.'),
(1657, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 1, 'OT', 'Então o SENHOR disse a Moisés: Agora verás o que farei a Faraó; porque por mão forte os deixará ir, e por mão forte os expulsará da sua terra.'),
(1658, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 2, 'OT', 'E Deus falou a Moisés e disse-lhe: Eu sou o SENHOR.'),
(1659, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 3, 'OT', 'Apareci a Abraão, a Isaque e a Jacó como Deus Todo-poderoso, mas pelo meu nome SENHOR não me dei a conhecer a eles.'),
(1660, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 4, 'OT', 'E também estabeleci a minha aliança com eles, para lhes dar a terra de Canaã, a terra de suas peregrinações, na qual habitaram como estrangeiros.'),
(1661, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 5, 'OT', 'E também ouvi o gemido dos filhos de Israel, a quem os egípcios escravizam, e me lembrei da minha aliança.'),
(1662, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 6, 'OT', 'Portanto, dize aos filhos de Israel: Eu sou o SENHOR, e vos tirarei de debaixo das cargas dos egípcios, e vos livrarei da servidão deles, e vos resgatarei com braço estendido e com grandes juízos.'),
(1663, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 7, 'OT', 'E eu vos tomarei por meu povo, e serei vosso Deus; e sabereis que eu sou o SENHOR vosso Deus, que vos tiro de debaixo das cargas dos egípcios.'),
(1664, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 8, 'OT', 'E vos trarei à terra a respeito da qual levantei a minha mão, para dá-la a Abraão, a Isaque e a Jacó; e vo-la darei por herança. Eu sou o SENHOR.'),
(1665, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 9, 'OT', 'Falou Moisés assim aos filhos de Israel, mas não ouviram a Moisés, por causa da angústia de espírito e da dura servidão.'),
(1666, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 10, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(1667, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 11, 'OT', 'Vai, fala a Faraó, rei do Egito, que deixe sair os filhos de Israel da sua terra.'),
(1668, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 12, 'OT', 'Moisés, porém, falou diante do SENHOR, dizendo: Eis que os filhos de Israel não me ouviram; como, então, Faraó me ouvirá? E eu sou incircunciso de lábios.'),
(1669, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 13, 'OT', 'O SENHOR falou a Moisés e a Arão e lhes deu ordens para os filhos de Israel e para o faraó, rei do Egito, para tirar os filhos de Israel da terra do Egito.'),
(1670, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 14, 'OT', 'Estas são as cabeças das casas de seus pais: os filhos de Rúben, o primogênito de Israel: Enoque, Palu, Hezrom e Carmi; estas são as famílias de Rúben.'),
(1671, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 15, 'OT', 'Os filhos de Simeão: Jemuel, Jamim, Oade, Jaquim, Zoar e Saul, filho da cananeia; estas são as famílias de Simeão.'),
(1672, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 16, 'OT', 'Estes são os nomes dos filhos de Levi, segundo as suas gerações: Gérson, Coate e Merari. E os anos da vida de Levi foram cento e trinta e sete anos.'),
(1673, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 17, 'OT', 'Os filhos de Gérson: Libni e Simei, segundo as suas famílias.'),
(1674, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 18, 'OT', 'Os filhos de Coate: Anrão, Isar, Hebrom e Uziel; e os anos da vida de Coate foram cento e trinta e três anos.'),
(1675, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 19, 'OT', 'E os filhos de Merari: Mali e Musi; estas são as famílias de Levi, segundo as suas gerações.'),
(1676, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 20, 'OT', 'Amram tomou por mulher Joquebede, sua tia, e ela lhe deu à luz Arão e Moisés; e os anos da vida de Amram foram cento e trinta e sete anos.'),
(1677, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 21, 'OT', 'E os filhos de Isar: Corá, Nefegue e Zicri.'),
(1678, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 22, 'OT', 'Os filhos de Uziel: Misael, Elzafã e Sitri.'),
(1679, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 23, 'OT', 'E Arão tomou por mulher a Eliseba, filha de Aminadabe, irmã de Naassom; e ela lhe deu à luz Nadabe, Abiú, Eleazar e Itamar.'),
(1680, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 24, 'OT', 'Os filhos de Corá: Assir, Elcana e Abiasafe. Essas são as famílias dos coraítas.'),
(1681, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 25, 'OT', 'E Eleazar, filho de Arão, tomou para si uma das filhas de Putiel por mulher, e ela lhe deu à luz Fineias. Estes são os chefes das casas patriarcais dos levitas, segundo as suas famílias.'),
(1682, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 26, 'OT', 'Este é Arão e Moisés, aos quais o SENHOR disse: "Tirai os filhos de Israel da terra do Egito, segundo os seus exércitos."'),
(1683, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 27, 'OT', 'Estes são os que falaram a Faraó, rei do Egito, para tirar os filhos de Israel do Egito: este é Moisés e Arão.'),
(1684, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 28, 'OT', 'E aconteceu que, no dia em que o SENHOR falou a Moisés na terra do Egito,'),
(1685, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 29, 'OT', 'Falou o SENHOR a Moisés, dizendo: Eu sou o SENHOR; fala a Faraó, rei do Egito, tudo o que eu te digo.'),
(1686, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 6, 30, 'OT', 'Então Moisés disse diante do SENHOR: Eis que eu sou incircunciso de lábios; e como Faraó me ouvirá?'),
(1687, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 1, 'OT', 'Então o SENHOR disse a Moisés: "Eis que te constituí como Deus para Faraó, e Arão, teu irmão, será o teu profeta."'),
(1688, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 2, 'OT', 'Tu falarás tudo o que eu te ordenar; e Arão, teu irmão, falará a Faraó, para que deixe sair os filhos de Israel da sua terra.'),
(1689, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 3, 'OT', 'Eu, porém, endurecerei o coração do faraó e multiplicarei os meus sinais e as minhas maravilhas na terra do Egito.'),
(1690, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 4, 'OT', 'Faraó não vos ouvirá; e eu porei a minha mão sobre o Egito, e tirarei os meus exércitos, o meu povo, os filhos de Israel, da terra do Egito, com grandes juízos.'),
(1691, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 5, 'OT', 'E os egípcios saberão que eu sou o SENHOR, quando eu estender a minha mão sobre o Egito e tirar os filhos de Israel do meio deles.'),
(1692, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 6, 'OT', 'Fez Moisés e Arão; como o SENHOR lhes ordenara, assim fizeram.'),
(1693, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 7, 'OT', 'Moisés tinha oitenta anos, e Arão, oitenta e três, quando falaram ao faraó.'),
(1694, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 8, 'OT', 'E o SENHOR disse a Moisés e a Arão:'),
(1695, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 9, 'OT', 'Quando Faraó vos falar, dizendo: "Fazei um milagre para vós", dirás a Arão: "Toma a tua vara e lança-a diante de Faraó; e ela se tornará em serpente."'),
(1696, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 10, 'OT', 'Então Moisés e Arão foram a Faraó e fizeram assim como o SENHOR havia ordenado; e Arão lançou a sua vara diante de Faraó e diante dos seus servos, e ela se tornou em serpente.'),
(1697, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 11, 'OT', 'E Faraó também chamou os sábios e os feiticeiros, e os magos do Egito fizeram também o mesmo com os seus encantamentos.'),
(1698, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 12, 'OT', 'Cada um lançou a sua vara, e elas se tornaram em serpentes; mas a vara de Arão engoliu as varas deles.'),
(1699, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 13, 'OT', 'O coração de Faraó se endureceu, e ele não os ouviu, como o SENHOR tinha dito.'),
(1700, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 14, 'OT', 'Então disse o SENHOR a Moisés: O coração de Faraó está endurecido; ele recusa deixar ir o povo.'),
(1701, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 15, 'OT', 'Vai pela manhã a Faraó; eis que ele sairá às águas; e põe-te diante dele na margem do rio, e tomarás em tua mão a vara que se tornou em serpente.'),
(1702, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 16, 'OT', 'E dirás a ele: O SENHOR, o Deus dos hebreus, enviou-me a ti, dizendo: Deixa ir o meu povo, para que me sirva no deserto; e eis que até agora não tens ouvido.'),
(1703, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 17, 'OT', 'Assim diz o SENHOR: Nisto saberás que eu sou o SENHOR: Eis que eu ferirei com a vara que tenho em minha mão as águas que estão no rio, e elas se tornarão em sangue.'),
(1704, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 18, 'OT', 'E os peixes que estão no rio morrerão, e o rio se tornará fétido; e os egípcios se cansarão de beber água do rio.'),
(1705, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 19, 'OT', 'Disse o SENHOR a Moisés: Dize a Arão: Toma o teu cajado e estende a tua mão sobre as águas do Egito, sobre os seus rios, sobre os seus canais, sobre os seus lagos e sobre todo o reservatório das suas águas, e elas se tornarão em sangue; e haverá sangue em toda a terra do Egito, tanto nos vasos de madeira como nos de pedra.'),
(1706, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 20, 'OT', 'E Moisés e Arão fizeram assim como o SENHOR havia ordenado: ele ergueu a vara e feriu as águas que estavam no rio, diante dos olhos de Faraó e diante dos olhos de seus servos; e todas as águas que estavam no rio se tornaram em sangue.'),
(1707, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 21, 'OT', 'E os peixes que estavam no rio morreram, e o rio cheirou mal, e os egípcios não puderam beber água do rio; e houve sangue por toda a terra do Egito.'),
(1708, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 22, 'OT', 'E os magos do Egito fizeram o mesmo com os seus encantamentos; e o coração de Faraó se endureceu, e não os ouviu, como o SENHOR tinha dito.'),
(1709, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 23, 'OT', 'E virou-se Faraó e foi para sua casa, e não aplicou o coração nem a isto.'),
(1710, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 24, 'OT', 'Todos os egípcios cavaram ao redor do Nilo para buscar água para beber, pois não podiam beber das águas do Nilo.'),
(1711, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 7, 25, 'OT', 'E sete dias se passaram, depois que o SENHOR feriu o rio.'),
(1712, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 1, 'OT', 'Disse o SENHOR a Moisés: Entra a Faraó e dize-lhe: Assim diz o SENHOR: Deixa ir o meu povo, para que me sirva.'),
(1713, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 2, 'OT', 'Se recusares deixá-lo ir, eis que ferirei com rãs todo o teu território.'),
(1714, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 3, 'OT', 'O Nilo se encherá de rãs, que subirão e entrarão na tua casa, no teu quarto de dormir e sobre a tua cama, nas casas dos teus servos, sobre o teu povo, nos teus fornos e nas tuas amassadeiras.'),
(1715, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 4, 'OT', 'E as rãs subirão sobre ti, sobre o teu povo e sobre todos os teus servos.'),
(1716, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 5, 'OT', 'Disse o SENHOR a Moisés: Dize a Arão: Estende a tua mão com a tua vara sobre os rios, sobre os canais e sobre os lagos, e faze subir as rãs sobre a terra do Egito.'),
(1717, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 6, 'OT', 'Estendeu Arão a sua mão sobre as águas do Egito, e subiram as rãs, e cobriram a terra do Egito.'),
(1718, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 7, 'OT', 'E os magos fizeram o mesmo com os seus encantamentos, e fizeram subir rãs sobre a terra do Egito.'),
(1719, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 8, 'OT', 'Então o faraó chamou Moisés e Arão e disse: "Rogai ao SENHOR que afaste as rãs de mim e do meu povo; então deixarei ir o povo, para que ofereçam sacrifícios ao SENHOR."'),
(1720, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 9, 'OT', 'Disse Moisés a Faraó: Digna-te a marcar-me quando hei de interceder por ti, por teus servos e por teu povo, para que as rãs sejam removidas de ti e de tuas casas, restando somente no rio.'),
(1721, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 10, 'OT', 'Disse ele: "Amanhã". E Moisés respondeu: "Seja conforme a tua palavra, para que saibas que não há ninguém como o SENHOR, nosso Deus."'),
(1722, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 11, 'OT', 'E as rãs se retirarão de ti, das tuas casas, dos teus servos e do teu povo; somente no rio permanecerão.'),
(1723, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 12, 'OT', 'Então Moisés e Arão saíram da presença do faraó; e Moisés clamou ao SENHOR por causa das rãs que ele tinha trazido sobre o faraó.'),
(1724, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 13, 'OT', 'E o SENHOR fez conforme a palavra de Moisés; e as rãs morreram das casas, dos pátios e dos campos.'),
(1725, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 14, 'OT', 'E ajuntaram-nos em montões, montão sobre montão, e a terra cheirava mal.'),
(1726, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 15, 'OT', 'Vendo Faraó que havia alívio, endureceu o seu coração e não os ouviu, como o SENHOR havia dito.'),
(1727, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 16, 'OT', 'Disse o SENHOR a Moisés: Dize a Arão: Estende a tua vara e fere o pó da terra, e ele se tornará em piolhos por toda a terra do Egito.'),
(1728, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 17, 'OT', 'E fizeram assim: Arão estendeu a mão com a sua vara e feriu o pó da terra, e houve piolhos nos homens e nos animais; todo o pó da terra se tornou piolhos em toda a terra do Egito.'),
(1729, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 18, 'OT', 'Os magos fizeram o mesmo com seus encantamentos para produzir piolhos, mas não conseguiram; e havia piolhos nos homens e nos animais.'),
(1730, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 19, 'OT', 'Então os magos disseram a Faraó: "Isto é o dedo de Deus." Mas o coração de Faraó se endureceu, e ele não os ouviu, assim como o SENHOR havia dito.'),
(1731, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 20, 'OT', 'Levanta-te pela manhã e apresenta-te diante de Faraó; eis que ele sairá às águas, e dize-lhe: Assim diz o SENHOR: Deixa ir o meu povo, para que me sirva.'),
(1732, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 21, 'OT', 'Porque, se não deixares ir o meu povo, eis que enviarei enxames de moscas sobre ti, sobre os teus servos, sobre o teu povo e nas tuas casas; e as casas dos egípcios se encherão desses enxames, e também a terra em que eles estiverem.'),
(1733, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 22, 'OT', 'Naquele dia separarei a terra de Gósen, onde habita o meu povo, para que ali não haja enxame de moscas, a fim de que saibas que eu sou o SENHOR no meio desta terra.'),
(1734, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 23, 'OT', 'E porei resgate entre o meu povo e o teu povo; amanhã será este sinal.'),
(1735, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 24, 'OT', 'E o SENHOR fez assim; e vieram enxames pesados de moscas à casa do Faraó e à casa dos seus servos, e em toda a terra do Egito a terra foi devastada por causa dos enxames de moscas.'),
(1736, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 25, 'OT', 'Então Faraó chamou Moisés e Arão e disse: "Ide e sacrificai ao vosso Deus nesta terra."'),
(1737, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 26, 'OT', 'Não é correto fazermos assim, pois sacrificaríamos ao SENHOR, nosso Deus, a abominação dos egípcios. Eis que, se sacrificarmos a abominação dos egípcios diante dos seus olhos, não nos apedrejarão?'),
(1738, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 27, 'OT', 'Caminho de três dias iremos ao deserto, e sacrificaremos ao SENHOR nosso Deus, como ele nos disser.'),
(1739, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 28, 'OT', 'Então Faraó disse: Deixar-vos-ei ir, para que sacrifiqueis ao SENHOR vosso Deus no deserto; somente que, indo, não vos afasteis muito; orai também por mim.'),
(1740, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 29, 'OT', 'Disse Moisés: Eis que saio de ti e suplicarei ao SENHOR, e os enxames de moscas se retirarão de Faraó, dos seus servos e do seu povo amanhã; somente que Faraó não continue a enganar, não deixando ir o povo para sacrificar ao SENHOR.'),
(1741, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 30, 'OT', 'Então Moisés saiu da presença do faraó e orou ao SENHOR.'),
(1742, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 31, 'OT', 'E o SENHOR fez conforme a palavra de Moisés, e removeu os enxames de moscas de Faraó, dos seus servos e do seu povo; não restou um só.'),
(1743, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 8, 32, 'OT', 'Faraó, porém, endureceu o seu coração também desta vez, e não deixou o povo ir.'),
(1744, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 1, 'OT', 'Disse o SENHOR a Moisés: Vai a Faraó e dize-lhe: Assim diz o SENHOR, o Deus dos hebreus: Deixa ir o meu povo, para que me sirva.'),
(1745, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 2, 'OT', 'Porque, se recusares deixá-los ir e ainda os detiveres,'),
(1746, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 3, 'OT', 'Eis que a mão do SENHOR virá sobre o teu gado que está no campo: sobre os cavalos, sobre os jumentos, sobre os camelos, sobre os bois e sobre as ovelhas, com uma peste muito grave.'),
(1747, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 4, 'OT', 'E o SENHOR fará distinção entre o gado de Israel e o gado do Egito, e nada morrerá de tudo o que pertence aos filhos de Israel.'),
(1748, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 5, 'OT', 'E o SENHOR estabeleceu um tempo determinado, dizendo: Amanhã o SENHOR fará esta coisa na terra.'),
(1749, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 6, 'OT', 'E o SENHOR fez esta coisa no dia seguinte, e todo o gado dos egípcios morreu; mas do gado dos filhos de Israel não morreu nenhum.'),
(1750, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 7, 'OT', 'Faraó enviou para verificar, e eis que nenhum animal do gado de Israel havia morrido; mas o coração de Faraó se endureceu, e ele não deixou o povo ir.'),
(1751, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 8, 'OT', 'Então disse o SENHOR a Moisés e a Arão: Tomai para vós mãos cheias de cinza de forno, e Moisés a espalhe para o céu diante dos olhos de Faraó.'),
(1752, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 9, 'OT', 'E será como pó fino sobre toda a terra do Egito, e se tornará em úlceras que rebentam em feridas nos homens e nos animais, por toda a terra do Egito.'),
(1753, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 10, 'OT', 'Tomaram a cinza do forno e se puseram diante de Faraó; Moisés a espalhou para o céu, e ela se tornou em úlceras que rebentavam em feridas nos homens e nos animais.'),
(1754, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 11, 'OT', 'Os magos não podiam permanecer diante de Moisés, por causa das úlceras, pois as úlceras estavam sobre os magos e sobre todos os egípcios.'),
(1755, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 12, 'OT', 'O SENHOR endureceu o coração de Faraó, e ele não os ouviu, como o SENHOR havia dito a Moisés.'),
(1756, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 13, 'OT', 'Levanta-te pela manhã cedo, e põe-te diante de Faraó, e dize-lhe: Assim diz o SENHOR, o Deus dos hebreus: Deixa ir o meu povo, para que me sirva.'),
(1757, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 14, 'OT', 'Porque desta vez enviarei todas as minhas pragas sobre o teu coração, e sobre os teus servos, e sobre o teu povo, para que saibas que não há outro como eu em toda a terra.'),
(1758, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 15, 'OT', 'Porque agora tenho estendido a minha mão, para ferir a ti e ao teu povo com pestilência, e tu serias exterminado da terra.'),
(1759, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 16, 'OT', 'Por isso te mantive de pé: para mostrar o meu poder em ti, e para que o meu nome seja proclamado em toda a terra.'),
(1760, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 17, 'OT', 'Ainda te exaltas contra o meu povo, para não os deixar ir?'),
(1761, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 18, 'OT', 'Eis que amanhã, a esta mesma hora, farei cair uma chuva de pedras muito pesada, como nunca houve no Egito, desde o dia em que foi fundado até agora.'),
(1762, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 19, 'OT', 'Agora, pois, envia e recolhe o teu gado e tudo o que tens no campo; todo homem e animal que for encontrado no campo e não for recolhido à casa, a saraiva cairá sobre eles, e morrerão.'),
(1763, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 20, 'OT', 'Aquele que temia a palavra do SENHOR entre os servos de Faraó fez refugiar os seus servos e o seu gado nas casas.'),
(1764, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 21, 'OT', 'Mas aquele que não levou a sério a palavra do SENHOR deixou os seus servos e o seu gado no campo.'),
(1765, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 22, 'OT', 'Disse o SENHOR a Moisés: Estende a tua mão para o céu, e haverá granizo em toda a terra do Egito, sobre os homens e sobre os animais, e sobre toda a planta do campo na terra do Egito.'),
(1766, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 23, 'OT', 'Moisés estendeu a sua vara para o céu, e o SENHOR enviou trovões e saraiva, e fogo corria pela terra; e o SENHOR fez cair saraiva sobre a terra do Egito.'),
(1767, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 24, 'OT', 'Houve saraiva, e fogo que se misturava no meio da saraiva, muito grave, como nunca houve em toda a terra do Egito, desde que veio a ser uma nação.'),
(1768, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 25, 'OT', 'A saraiva feriu em toda a terra do Egito tudo o que havia no campo, desde os homens até os animais; também a saraiva feriu toda a erva do campo e quebrou todas as árvores do campo.'),
(1769, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 26, 'OT', 'Somente na terra de Gósen, onde estavam os filhos de Israel, não houve granizo.'),
(1770, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 27, 'OT', 'Então Faraó mandou chamar Moisés e Arão e lhes disse: "Pequei desta vez; o SENHOR é justo, e eu e o meu povo somos ímpios."'),
(1771, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 28, 'OT', 'Rogai ao SENHOR, pois já bastam os trovões de Deus e a saraiva; e eu vos deixarei ir, e não permanecereis mais aqui.'),
(1772, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 29, 'OT', 'Então Moisés lhe disse: Ao sair da cidade, estenderei minhas mãos ao SENHOR; os trovões cessarão, e não haverá mais saraiva, para que saibas que a terra é do SENHOR.'),
(1773, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 30, 'OT', 'Quanto a ti e aos teus servos, eu sei que ainda não temeis diante do SENHOR Deus.'),
(1774, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 31, 'OT', 'O linho e a cevada foram destruídos, porque a cevada já estava em espiga, e o linho em flor.'),
(1775, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 32, 'OT', 'Mas o trigo e o centeio não foram feridos, porque estavam cobertos.'),
(1776, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 33, 'OT', 'Saiu Moisés da presença do faraó, da cidade, e estendeu as mãos ao SENHOR; e cessaram os trovões e a saraiva, e a chuva não caiu mais sobre a terra.'),
(1777, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 34, 'OT', 'Vendo Faraó que a chuva, a saraiva e os trovões haviam cessado, continuou a pecar e endureceu o seu coração, ele e os seus servos.'),
(1778, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 9, 35, 'OT', 'O coração de Faraó se endureceu, e ele não deixou ir os filhos de Israel, como o SENHOR tinha dito por meio de Moisés.'),
(1779, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 1, 'OT', 'Disse o SENHOR a Moisés: Vai a Faraó, porque eu endureci o coração dele e o coração dos seus servos, para que eu faça estes meus sinais no meio deles.'),
(1780, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 2, 'OT', 'E para que contes aos ouvidos de teu filho e do filho de teu filho as coisas que fiz no Egito e os meus sinais que estabeleci entre eles, para que saibais que eu sou o SENHOR.'),
(1781, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 3, 'OT', 'Então Moisés e Arão foram a Faraó e lhe disseram: Assim diz o SENHOR, o Deus dos hebreus: Até quando recusarás humilhar-te diante de mim? Deixa ir o meu povo, para que me sirva.'),
(1782, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 4, 'OT', 'Porque se tu recusares deixar ir o meu povo, eis que trarei amanhã gafanhotos sobre o teu território.'),
(1783, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 5, 'OT', 'E cobrirá a face da terra, de modo que não se poderá ver a terra; e comerá o restante do que escapou, o que vos ficou da saraiva; e comerá toda a árvore que cresce para vós no campo.'),
(1784, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 6, 'OT', 'E encherão as tuas casas, e as casas de todos os teus servos, e as casas de todos os egípcios, o que nunca viram teus pais nem os pais de teus pais, desde o dia em que existiram sobre a terra até o dia de hoje. E virou-se, e saiu da presença de Faraó.'),
(1785, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 7, 'OT', 'Os servos do faraó lhe disseram: "Até quando este será um laço para nós? Deixa ir os homens, para que sirvam ao SENHOR, seu Deus. Ainda não sabes que o Egito está destruído?"'),
(1786, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 8, 'OT', 'Então Moisés e Arão foram levados de volta a Faraó, e ele lhes disse: Ide, servi ao SENHOR vosso Deus; quem são os que hão de ir?'),
(1787, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 9, 'OT', 'Disse Moisés: Com nossos jovens e com nossos anciãos iremos; com nossos filhos e com nossas filhas, com nossas ovelhas e com nossos bois iremos, porque festa do SENHOR temos para nós.'),
(1788, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 10, 'OT', 'Ele lhes disse: "Que o SENHOR esteja convosco, assim como eu vos deixarei ir, a vós e aos vossos filhos; vede que o mal está diante da vossa face."'),
(1789, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 11, 'OT', 'Não será assim; ide agora vós, os homens, e servi ao SENHOR, pois isso é o que pedistes. E foram expulsos da presença de Faraó.'),
(1790, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 12, 'OT', 'Disse o SENHOR a Moisés: Estende a tua mão sobre a terra do Egito para os gafanhotos, para que subam sobre a terra do Egito e comam toda a erva da terra, tudo o que o granizo deixou.'),
(1791, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 13, 'OT', 'Estendeu Moisés a sua vara sobre a terra do Egito, e o SENHOR trouxe um vento oriental sobre a terra todo aquele dia e toda a noite; ao amanhecer, o vento oriental trouxe os gafanhotos.'),
(1792, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 14, 'OT', 'Subiu o gafanhoto sobre toda a terra do Egito e pousou em todo o território do Egito; era muito pesado. Antes dele não houve gafanhoto semelhante a ele, e depois dele não haverá assim.'),
(1793, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 15, 'OT', 'Cobriram toda a face da terra, e a terra se escureceu; e comeram toda a erva da terra e todo o fruto das árvores que a saraiva deixara; e não restou nenhuma verdura nas árvores nem na erva do campo em toda a terra do Egito.'),
(1794, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 16, 'OT', 'Então Faraó se apressou a chamar Moisés e Arão, e disse: Pequei contra o SENHOR, vosso Deus, e contra vós.'),
(1795, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 17, 'OT', 'Agora, pois, perdoa o meu pecado somente desta vez, e orai ao SENHOR vosso Deus, para que afaste de mim somente esta morte.'),
(1796, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 18, 'OT', 'Saiu da presença do faraó e orou ao SENHOR.'),
(1797, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 19, 'OT', 'Então o SENHOR trouxe um vento fortíssimo do oeste, que levantou os gafanhotos e os lançou no Mar Vermelho; não restou um único gafanhoto em todo o território do Egito.'),
(1798, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 20, 'OT', 'O SENHOR endureceu o coração de Faraó, e ele não deixou partir os filhos de Israel.'),
(1799, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 21, 'OT', 'Então disse o SENHOR a Moisés: Estende a tua mão para o céu, e haverá trevas sobre a terra do Egito, trevas que se possam apalpar.'),
(1800, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 22, 'OT', 'Moisés estendeu a mão para o céu, e houve trevas espessas em toda a terra do Egito por três dias.'),
(1801, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 23, 'OT', 'Não viu ninguém a seu irmão, nem se levantou alguém do seu lugar por três dias; mas para todos os filhos de Israel havia luz em suas habitações.'),
(1802, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 24, 'OT', 'Então Faraó chamou Moisés e disse: "Ide, servi ao SENHOR; somente fiquem as vossas ovelhas e o vosso gado; também as vossas crianças irão convosco."'),
(1803, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 25, 'OT', 'Moisés disse: Tu também darás em nossas mãos sacrifícios e holocaustos, e os ofereceremos ao SENHOR, nosso Deus.'),
(1804, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 26, 'OT', 'Também o nosso gado irá conosco; nem uma unha ficará, porque dele havemos de tomar para servir ao SENHOR nosso Deus; e nós não sabemos com que havemos de servir ao SENHOR, até que cheguemos lá.'),
(1805, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 27, 'OT', 'O SENHOR, porém, endureceu o coração de Faraó, e ele não quis deixá-los ir.'),
(1806, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 28, 'OT', 'Disse-lhe Faraó: Vai-te de mim; guarda-te de tornares a ver o meu rosto, porque no dia em que vires o meu rosto, morrerás.'),
(1807, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 10, 29, 'OT', 'Disse Moisés: Assim falaste; não tornarei a ver o teu rosto.'),
(1808, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 1, 'OT', 'Disse o SENHOR a Moisés: Ainda uma praga trarei sobre Faraó e sobre o Egito; depois ele vos deixará ir daqui. Quando vos deixar ir, ele vos expulsará totalmente daqui.'),
(1809, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 2, 'OT', 'Fala agora aos ouvidos do povo, que cada homem peça ao seu próximo, e cada mulher à sua próxima, objetos de prata e objetos de ouro.'),
(1810, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 3, 'OT', 'E o SENHOR deu graça ao povo aos olhos dos egípcios; também o homem Moisés era muito grande na terra do Egito, aos olhos dos servos do faraó e aos olhos do povo.'),
(1811, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 4, 'OT', 'Disse Moisés: Assim diz o SENHOR: À meia-noite eu sairei pelo meio do Egito.'),
(1812, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 5, 'OT', 'E morrerá todo primogênito na terra do Egito, desde o primogênito de Faraó, que se assenta sobre o seu trono, até o primogênito da serva que está atrás da mó, e todo primogênito dos animais.'),
(1813, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 6, 'OT', 'E haverá grande clamor em toda a terra do Egito, qual nunca houve, nem jamais haverá.'),
(1814, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 7, 'OT', 'Mas contra todos os filhos de Israel, nem um cão moverá a sua língua, desde os homens até os animais, para que saibais que o SENHOR faz distinção entre os egípcios e Israel.'),
(1815, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 8, 'OT', 'Então todos estes teus servos descerão a mim e se prostrarão diante de mim, dizendo: "Sai tu, e todo o povo que te segue"; e depois disso eu sairei. E Moisés saiu da presença do Faraó em ardente ira.'),
(1816, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 9, 'OT', 'Disse o SENHOR a Moisés: Faraó não vos ouvirá, para que as minhas maravilhas se multipliquem na terra do Egito.'),
(1817, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 11, 10, 'OT', 'Moisés e Arão fizeram todos estes prodígios diante do faraó; mas o SENHOR endureceu o coração do faraó, e ele não deixou sair os filhos de Israel da sua terra.'),
(1818, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 1, 'OT', 'E o SENHOR falou a Moisés e a Arão na terra do Egito, dizendo:'),
(1819, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 2, 'OT', 'Este mês será para vós o princípio dos meses; será o primeiro dos meses do ano para vós.'),
(1820, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 3, 'OT', 'Falai a toda a congregação de Israel, dizendo: No décimo dia deste mês, cada um tomará para si um cordeiro, segundo a casa de seus pais, um cordeiro para cada casa.'),
(1821, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 4, 'OT', 'E se a família for pequena demais para um cordeiro, então ele tomará um com seu vizinho mais próximo de sua casa, conforme o número de pessoas; cada um conforme o que puder comer, fareis a conta para o cordeiro.'),
(1822, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 5, 'OT', 'O cordeiro será sem defeito, macho de um ano; tomá-lo-eis das ovelhas ou das cabras.'),
(1823, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 6, 'OT', 'E o guardareis até o décimo quarto dia deste mês, e toda a assembleia da congregação de Israel o sacrificará entre as duas tardes.'),
(1824, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 7, 'OT', 'E tomarão do sangue e o colocarão nos dois umbrais e na verga da porta, nas casas em que o comerem.'),
(1825, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 8, 'OT', 'E comerão a carne naquela noite, assada ao fogo, com pães sem fermento e ervas amargas a comerão.'),
(1826, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 9, 'OT', 'Não comereis dele cru, nem cozido em água, mas assado ao fogo: a sua cabeça com os seus pés e com as suas entranhas.'),
(1827, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 10, 'OT', 'E não deixareis nada dele até a manhã; mas o que restar dele até a manhã, queimareis no fogo.'),
(1828, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 11, 'OT', 'Assim o comereis: os vossos lombos cingidos, as vossas sandálias nos pés e o vosso cajado na mão; e o comereis apressadamente; esta é a Páscoa do SENHOR.'),
(1829, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 12, 'OT', 'E passarei pela terra do Egito naquela noite, e ferirei todo primogênito na terra do Egito, desde os homens até os animais; e sobre todos os deuses do Egito executarei juízos; eu sou o SENHOR.'),
(1830, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 13, 'OT', 'O sangue será para vós um sinal nas casas em que estiverdes; e, vendo eu o sangue, passarei por cima de vós, e não haverá entre vós praga destruidora, quando eu ferir a terra do Egito.'),
(1831, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 14, 'OT', 'Este dia será para vocês um memorial, e vocês o celebrarão como festa ao SENHOR; nas suas gerações o celebrarão como estatuto perpétuo.'),
(1832, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 15, 'OT', 'Sete dias comereis pães sem fermento; ao primeiro dia tirareis o fermento das vossas casas; porque todo aquele que comer pão levedado, essa pessoa será cortada de Israel, desde o primeiro dia até o sétimo dia.'),
(1833, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 16, 'OT', 'No primeiro dia haverá santa convocação, e no sétimo dia tereis santa convocação; nenhum trabalho se fará neles, exceto o que cada pessoa precisar comer; somente isso vos será permitido preparar.'),
(1834, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 17, 'OT', 'Guardareis a festa dos pães sem fermento, porque nesse mesmo dia tirei os vossos exércitos da terra do Egito; portanto, guardareis este dia nas vossas gerações como estatuto perpétuo.'),
(1835, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 18, 'OT', 'No primeiro mês, no dia catorze do mês, à tarde, comereis pães sem fermento até o dia vinte e um do mês, à tarde.'),
(1836, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 19, 'OT', 'Por sete dias não se achará fermento nas vossas casas; porque qualquer que comer pão levedado, aquela alma será cortada da congregação de Israel, tanto o estrangeiro como o natural da terra.'),
(1837, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 20, 'OT', 'Nenhuma coisa levedada comereis; em todas as vossas habitações comereis pães sem fermento.'),
(1838, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 21, 'OT', 'Chamou Moisés a todos os anciãos de Israel e disse-lhes: Escolhei e tomai para vós ovelhas para as vossas famílias, e sacrificai a Páscoa.'),
(1839, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 22, 'OT', 'Tomareis um molho de hissopo, molhá-lo-eis no sangue que estiver na bacia, e aplicareis no lintel e nos dois umbrais da porta o sangue que estiver na bacia; e nenhum de vós sairá da porta da sua casa até pela manhã.'),
(1840, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 23, 'OT', 'O SENHOR passará para ferir os egípcios; e, ao ver o sangue na verga da porta e nos dois umbrais, o SENHOR passará adiante da porta e não permitirá que o destruidor entre em vossas casas para ferir.'),
(1841, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 24, 'OT', 'Guardem isto como estatuto para vocês e para os seus filhos para sempre.'),
(1842, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 25, 'OT', 'Quando vocês entrarem na terra que o SENHOR vos dará, como ele prometeu, guardareis este culto.'),
(1843, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 26, 'OT', 'E acontecerá que, quando vossos filhos vos perguntarem: "Que serviço é este que vocês fazem?"'),
(1844, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 27, 'OT', 'Direis: Este é o sacrifício da Páscoa ao SENHOR, que passou sobre as casas dos filhos de Israel no Egito, quando feriu os egípcios e livrou as nossas casas. Então o povo se inclinou e adorou.'),
(1845, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 28, 'OT', 'Os filhos de Israel foram e fizeram assim; como o SENHOR havia ordenado a Moisés e a Arão, assim fizeram.'),
(1846, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 29, 'OT', 'Aconteceu que, à meia-noite, o SENHOR feriu todos os primogênitos na terra do Egito, desde o primogênito de Faraó, que se assentava no seu trono, até o primogênito do prisioneiro que estava na cisterna, e todo primogênito dos animais.'),
(1847, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 30, 'OT', 'Levantou-se Faraó de noite, ele e todos os seus servos, e todo o Egito; e houve grande clamor no Egito, porque não havia casa em que não houvesse um morto.'),
(1848, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 31, 'OT', 'Levantai-vos, saí do meio do meu povo, tanto vós como os filhos de Israel; e ide, servi ao SENHOR, como tendes dito.'),
(1849, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 32, 'OT', 'Levai também convosco vossas ovelhas e vossas vacas, como tendes dito; e ide, e abençoai-me também a mim.'),
(1850, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 33, 'OT', 'E os egípcios pressionavam o povo, apressando-se para enviá-los para fora da terra, pois diziam: "Todos nós morreremos."'),
(1851, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 34, 'OT', 'E o povo levou a sua massa antes que levedasse, as suas amassadeiras atadas em seus mantos, sobre os seus ombros.'),
(1852, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 35, 'OT', 'Os filhos de Israel fizeram conforme a palavra de Moisés, e pediram aos egípcios objetos de prata, objetos de ouro e roupas.'),
(1853, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 36, 'OT', 'E o SENHOR deu graça ao povo diante dos egípcios, e eles lhes emprestaram; e despojaram os egípcios.'),
(1854, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 37, 'OT', 'Os filhos de Israel partiram de Ramessés para Sucote, cerca de seiscentos mil homens a pé, além das crianças.'),
(1855, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 38, 'OT', 'E também subiu com eles uma grande mistura de gente, e ovelhas e gado, uma multidão muito numerosa de animais.'),
(1856, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 39, 'OT', 'E cozeram bolos asmos da massa que trouxeram do Egito, porque não havia levedado, pois foram expulsos do Egito e não puderam demorar-se, e também não prepararam provisões para si.'),
(1857, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 40, 'OT', 'O tempo que os filhos de Israel habitaram no Egito foi de quatrocentos e trinta anos.'),
(1858, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 41, 'OT', 'E aconteceu que, ao fim de quatrocentos e trinta anos, naquele mesmo dia, todos os exércitos do SENHOR saíram da terra do Egito.'),
(1859, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 42, 'OT', 'Noite de vigília é esta para o SENHOR, para os tirar da terra do Egito; esta é a noite do SENHOR, vigília para todos os filhos de Israel nas suas gerações.'),
(1860, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 43, 'OT', 'Disse o SENHOR a Moisés e a Arão: Esta é a ordenança da Páscoa: nenhum estrangeiro comerá dela.'),
(1861, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 44, 'OT', 'Todo servo comprado com dinheiro, depois de o circuncidares, então comerá dela.'),
(1862, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 45, 'OT', 'O residente temporário e o assalariado não comerão dela.'),
(1863, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 46, 'OT', 'Numa só casa se comerá; não levarás da carne para fora da casa, nem quebrarás osso dela.'),
(1864, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 47, 'OT', 'Toda a congregação de Israel o fará.'),
(1865, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 48, 'OT', 'E se um estrangeiro habitar contigo e quiser celebrar a Páscoa ao SENHOR, que todo macho dele seja circuncidado, e então se aproximará para celebrá-la; e será como o natural da terra; mas nenhum incircunciso comerá dela.'),
(1866, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 49, 'OT', 'Uma mesma lei haverá para o natural e para o estrangeiro que peregrina no meio de vós.'),
(1867, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 50, 'OT', 'Todos os filhos de Israel fizeram conforme o SENHOR havia ordenado a Moisés e a Arão; assim fizeram.'),
(1868, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 12, 51, 'OT', 'E aconteceu naquele mesmo dia que o SENHOR tirou os filhos de Israel da terra do Egito, segundo os seus exércitos.'),
(1869, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(1870, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 2, 'OT', 'Sanctifica-me todo primogênito, o que abrir toda madre entre os filhos de Israel, de homens e de animais: porque meu é.'),
(1871, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 3, 'OT', 'Lembrae-vos deste dia, em que saístes do Egito, da casa da servidão; porque com mão forte o SENHOR vos tirou daqui; portanto, não se comerá pão levedado.'),
(1872, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 4, 'OT', 'Hoje vocês saem, no mês de Abibe.'),
(1873, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 5, 'OT', 'Quando o SENHOR te houver introduzido na terra dos cananeus, dos hititas, dos amorreus, dos heveus e dos jebuseus, a qual jurou a teus pais que te daria, terra que mana leite e mel, celebrarás este culto neste mês.'),
(1874, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 6, 'OT', 'Sete dias comerás pães sem fermento, e no sétimo dia haverá festa ao SENHOR.'),
(1875, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 7, 'OT', 'Sete dias se comerão pães sem fermento, e não se verá contigo massa levedada, nem se verá contigo fermento em todos os teus limites.'),
(1876, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 8, 'OT', 'Naquele dia contarás a teu filho, dizendo: É por causa disto que o SENHOR fez por mim quando saí do Egito.'),
(1877, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 9, 'OT', 'E será para você um sinal sobre a sua mão e uma lembrança entre os seus olhos, para que a lei do SENHOR esteja na sua boca; pois com mão forte o SENHOR o tirou do Egito.'),
(1878, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 10, 'OT', 'Guardarás, pois, este estatuto no seu tempo determinado, de ano em ano.'),
(1879, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 11, 'OT', 'Quando o SENHOR o tiver levado à terra dos cananeus, como jurou a você e aos seus pais, e a tiver dado a você,'),
(1880, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 12, 'OT', 'E consagrarás ao SENHOR todo primogênito que abrir o ventre, e todo primogênito macho das crias dos teus animais pertencerá ao SENHOR.'),
(1881, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 13, 'OT', 'Todo primogênito de jumenta resgatarás com cordeiro; e, se não o resgatares, quebrar-lhe-ás o pescoço; e todo primogênito do homem entre teus filhos resgatarás.'),
(1882, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 14, 'OT', 'E quando teu filho te perguntar no futuro, dizendo: Que é isto? Então lhe dirás: Com mão forte o SENHOR nos tirou do Egito, da casa da servidão.'),
(1883, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 15, 'OT', 'E aconteceu que, quando Faraó endureceu o coração para não nos deixar ir, o SENHOR matou todos os primogênitos na terra do Egito, desde o primogênito do homem até o primogênito dos animais; por isso eu sacrifico ao SENHOR todo macho que abre o ventre, mas todo primogênito de meus filhos eu resgato.'),
(1884, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 16, 'OT', 'E será por sinal sobre a tua mão e por frontais entre os teus olhos; porque com mão forte o SENHOR nos tirou do Egito.'),
(1885, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 17, 'OT', 'E aconteceu que, quando Faraó deixou ir o povo, Deus não os conduziu pelo caminho da terra dos filisteus, embora fosse mais perto; porque Deus disse: Para que o povo não se arrependa ao ver a guerra e volte para o Egito.'),
(1886, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 18, 'OT', 'Deus fez o povo dar a volta pelo caminho do deserto até o mar de Sufe; e os filhos de Israel subiram da terra do Egito armados.'),
(1887, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 19, 'OT', 'Moisés levou consigo os ossos de José, porque José havia feito os filhos de Israel jurarem, dizendo: "Certamente Deus vos visitará; e fareis subir os meus ossos daqui convosco."'),
(1888, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 20, 'OT', 'Partiram de Sucote e acamparam em Etã, na extremidade do deserto.'),
(1889, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 21, 'OT', 'O SENHOR ia adiante deles, de dia numa coluna de nuvem, para os guiar pelo caminho, e de noite numa coluna de fogo, para lhes dar luz, a fim de que caminhassem de dia e de noite.'),
(1890, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 13, 22, 'OT', 'Não se apartava de diante do povo a coluna de nuvem, de dia, nem a coluna de fogo, de noite.'),
(1891, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 1, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(1892, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 2, 'OT', 'Fala aos filhos de Israel que voltem e acampem diante de Pi-hahiroth, entre Migdol e o mar, diante de Baal-zephon; em frente a ele acampareis junto ao mar.'),
(1893, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 3, 'OT', 'Então o Faraó dirá dos filhos de Israel: Estão confusos na terra; o deserto os encerrou.'),
(1894, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 4, 'OT', 'E endurecerei o coração de Faraó, para que ele os persiga, e serei glorificado em Faraó e em todo o seu exército, e os egípcios saberão que eu sou o SENHOR. E eles fizeram assim.'),
(1895, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 5, 'OT', 'Foi anunciado ao rei do Egito que o povo havia fugido; e o coração de Faraó e de seus servos se voltou contra o povo, e disseram: "Que é isto que fizemos, deixando Israel ir, para que não nos sirva?"'),
(1896, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 6, 'OT', 'E atrelou o seu carro de guerra e levou consigo o seu povo.'),
(1897, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 7, 'OT', 'Tomou seiscentos carros escolhidos e todos os carros do Egito, com oficiais sobre todos eles.'),
(1898, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 8, 'OT', 'O SENHOR endureceu o coração de Faraó, rei do Egito, e ele perseguiu os filhos de Israel; mas os filhos de Israel saíram com mão erguida.'),
(1899, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 9, 'OT', 'Os egípcios os perseguiram, e todos os cavalos e carros de Faraó, os seus cavaleiros e o seu exército os alcançaram acampados junto ao mar, perto de Pi-hahiroth, diante de Baal-zephon.'),
(1900, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 10, 'OT', 'E Faraó se aproximou; e os filhos de Israel levantaram os olhos, e eis que os egípcios marchavam atrás deles, e temeram muito; então os filhos de Israel clamaram ao SENHOR.'),
(1901, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 11, 'OT', 'E disseram a Moisés: Não havia sepulturas no Egito, que nos trouxeste para morrermos no deserto? Que é isto que nos fizeste, tirando-nos do Egito?'),
(1902, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 12, 'OT', 'Não é esta a palavra que te falamos no Egito, dizendo: Deixa-nos, que sirvamos aos egípcios? Pois melhor nos era servir aos egípcios do que morrer no deserto.'),
(1903, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 13, 'OT', 'Não temais; permanecei firmes e vede o livramento do SENHOR, que hoje vos fará; porque aos egípcios, que hoje vistes, nunca mais os vereis para sempre.'),
(1904, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 14, 'OT', 'O SENHOR lutará por vós; e vós vos calareis.'),
(1905, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 15, 'OT', 'Então o SENHOR disse a Moisés: "Por que clamas a mim? Dize aos filhos de Israel que marchem."'),
(1906, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 16, 'OT', 'Tu, porém, levanta a tua vara e estende a tua mão sobre o mar, e divide-o; e os filhos de Israel passarão pelo meio do mar em terra seca.'),
(1907, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 17, 'OT', 'E eu, eis que endurecerei o coração dos egípcios, para que entrem atrás deles; e serei glorificado em Faraó e em todo o seu exército, nos seus carros e nos seus cavaleiros.'),
(1908, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 18, 'OT', 'E os egípcios saberão que eu sou o SENHOR, quando eu for glorificado em Faraó, nos seus carros e nos seus cavaleiros.'),
(1909, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 19, 'OT', 'O anjo de Deus, que ia diante do acampamento de Israel, retirou-se e foi para trás deles; e a coluna de nuvem retirou-se de diante deles e se pôs atrás deles.'),
(1910, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 20, 'OT', 'E veio entre o acampamento do Egito e o acampamento de Israel; e a nuvem era trevas para aqueles, e para estes iluminava a noite; e não se aproximou um do outro toda a noite.'),
(1911, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 21, 'OT', 'Então Moisés estendeu a sua mão sobre o mar, e o SENHOR fez o mar recuar por um forte vento oriental toda a noite, e tornou o mar em terra seca, e as águas foram divididas.'),
(1912, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 22, 'OT', 'Os filhos de Israel entraram pelo meio do mar em terra seca, e as águas lhes foram um muro à sua direita e à sua esquerda.'),
(1913, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 23, 'OT', 'Os egípcios os perseguiram e entraram atrás deles, todos os cavalos de Faraó, os seus carros e os seus cavaleiros, até o meio do mar.'),
(1914, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 24, 'OT', 'Na vigília da manhã, o SENHOR olhou para o acampamento dos egípcios por meio da coluna de fogo e de nuvem, e lançou o acampamento dos egípcios em confusão.'),
(1915, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 25, 'OT', 'E fez travar as rodas dos seus carros, e os conduziu com dificuldade. Então os egípcios disseram: Fujamos da presença de Israel, porque o SENHOR luta por eles contra os egípcios.'),
(1916, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 26, 'OT', 'Disse o SENHOR a Moisés: Estende a tua mão sobre o mar, e as águas voltarão sobre os egípcios, sobre os seus carros e sobre os seus cavaleiros.'),
(1917, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 27, 'OT', 'Então Moisés estendeu a sua mão sobre o mar, e o mar voltou à sua força ao amanhecer, e os egípcios fugiram ao seu encontro; e o SENHOR derrubou os egípcios no meio do mar.'),
(1918, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 28, 'OT', 'As águas voltaram e cobriram os carros e os cavaleiros de todo o exército de Faraó, que os haviam seguido no mar; não restou nem um só deles.'),
(1919, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 29, 'OT', 'Os filhos de Israel caminharam pelo meio do mar em terra seca, e as águas lhes foram um muro à sua direita e à sua esquerda.'),
(1920, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 30, 'OT', 'Assim o SENHOR salvou Israel naquele dia da mão dos egípcios; e Israel viu os egípcios mortos na praia do mar.'),
(1921, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 14, 31, 'OT', 'E viu Israel a grande mão que o SENHOR fez contra os egípcios; e o povo temeu ao SENHOR, e creram no SENHOR e em Moisés, seu servo.'),
(1922, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 1, 'OT', 'Então Moisés e os filhos de Israel cantaram este cântico ao SENHOR, e disseram: Cantarei ao SENHOR, porque ele se exaltou gloriosamente; lançou no mar o cavalo e o seu cavaleiro.'),
(1923, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 2, 'OT', 'O SENHOR é a minha força e o meu cântico; ele se tornou a minha salvação. Este é o meu Deus, e eu o louvarei; o Deus de meu pai, e eu o exaltarei.'),
(1924, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 3, 'OT', 'O SENHOR é guerreiro; o SENHOR é o seu nome.'),
(1925, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 4, 'OT', 'Os carros de Faraó e o seu exército, ele lançou no mar; e os seus melhores guerreiros afundaram no mar de Sufe.'),
(1926, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 5, 'OT', 'Os abismos os cobriram; desceram às profundezas como pedra.'),
(1927, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 6, 'OT', 'A tua mão direita, ó SENHOR, é majestosa em poder; a tua mão direita, ó SENHOR, despedaça o inimigo.'),
(1928, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 7, 'OT', 'Na grandeza da tua majestade, derrubas os que se levantam contra ti; envias o teu furor, que os consome como palha.'),
(1929, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 8, 'OT', 'E com o sopro das tuas narinas amontoaram-se as águas, pararam as correntes como um montão; os abismos coalharam-se no coração do mar.'),
(1930, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 9, 'OT', 'O inimigo disse: Perseguirei, alcançarei, repartirei o despojo; a minha alma se fartará deles; sacarei a minha espada, a minha mão os destruirá.'),
(1931, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 10, 'OT', 'Sopraste com o teu vento, o mar os cobriu; afundaram-se como chumbo em águas impetuosas.'),
(1932, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 11, 'OT', 'Quem é como tu, SENHOR, entre os deuses? Quem é como tu, glorioso em santidade, temível em louvores, autor de maravilhas?'),
(1933, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 12, 'OT', 'Estendeste a tua mão direita; a terra os tragou.'),
(1934, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 13, 'OT', 'Guiaste com a tua bondade o povo que remiste; com a tua força o conduziste à tua santa habitação.'),
(1935, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 14, 'OT', 'Os povos ouviram e estremeceram; tremor apoderou-se dos habitantes da Filístia.'),
(1936, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 15, 'OT', 'Então os líderes de Edom ficarão aterrorizados; tremor apoderar-se-á dos poderosos de Moabe; todos os habitantes de Canaã se derreterão.'),
(1937, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 16, 'OT', 'Cairá sobre eles terror e pavor; pela grandeza do teu braço, ficarão imóveis como pedra, até que passe o teu povo, ó SENHOR, até que passe este povo que adquiriste.'),
(1938, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 17, 'OT', 'Tu os trarás e os plantarás no monte da tua herança, lugar para a tua habitação, que fizeste, ó SENHOR; o santuário, ó Senhor, que as tuas mãos estabeleceram.'),
(1939, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 18, 'OT', 'O SENHOR reinará para todo o sempre.'),
(1940, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 19, 'OT', 'Porque o cavalo de Faraó entrou no mar com os seus carros e os seus cavaleiros, e o SENHOR fez voltar sobre eles as águas do mar; mas os filhos de Israel caminharam em terra seca no meio do mar.'),
(1941, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 20, 'OT', 'Então Miriã, a profetisa, irmã de Arão, tomou o tamborim na sua mão, e todas as mulheres saíram atrás dela com tamborins e com danças.'),
(1942, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 21, 'OT', 'E Miriã lhes respondia: Cantai ao SENHOR, porque gloriosamente triunfou; lançou no mar o cavalo e o seu cavaleiro.'),
(1943, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 22, 'OT', 'Moisés fez Israel partir do mar de Sufe, e saíram ao deserto de Sur; e caminharam três dias no deserto, e não acharam água.'),
(1944, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 23, 'OT', 'Então chegaram a Mara, mas não puderam beber as águas de Mara, porque eram amargas; por isso o lugar foi chamado Mara.'),
(1945, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 24, 'OT', 'E o povo murmurou contra Moisés, dizendo: Que havemos de beber?'),
(1946, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 25, 'OT', 'E ele clamou ao SENHOR, e o SENHOR lhe mostrou uma árvore; e ele a lançou nas águas, e as águas se tornaram doces. Ali lhes estabeleceu estatuto e ordenança, e ali os provou.'),
(1947, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 26, 'OT', 'E disse: Se ouvires atentamente a voz do SENHOR, teu Deus, e fizeres o que é reto aos seus olhos, e inclinares os ouvidos aos seus mandamentos, e guardares todos os seus estatutos, nenhuma das enfermidades que pus sobre o Egito porei sobre ti, porque eu sou o SENHOR que te sara.'),
(1948, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 15, 27, 'OT', 'Então chegaram a Elim, onde havia doze fontes de água e setenta palmeiras; e ali acamparam junto às águas.'),
(1949, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 1, 'OT', 'Partiram de Elim, e toda a congregação dos filhos de Israel veio ao deserto de Sim, que está entre Elim e Sinai, no décimo quinto dia do segundo mês, depois que saíram da terra do Egito.'),
(1950, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 2, 'OT', 'E toda a congregação dos filhos de Israel murmurou contra Moisés e contra Arão no deserto.'),
(1951, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 3, 'OT', 'Os filhos de Israel lhes disseram: "Quem dera tivéssemos morrido pela mão do SENHOR na terra do Egito, quando nos assentávamos junto às panelas de carne e comíamos pão até nos fartarmos! Pois vocês nos trouxeram a este deserto para matar de fome toda esta multidão."'),
(1952, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 4, 'OT', 'Então disse o SENHOR a Moisés: Eis que farei chover pão do céu para vós; e o povo sairá e colherá a porção de cada dia no seu dia, para que eu o prove se anda na minha lei ou não.'),
(1953, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 5, 'OT', 'E acontecerá que, no sexto dia, prepararão o que trouxerem; e será o dobro do que colhem cada dia.'),
(1954, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 6, 'OT', 'Ao entardecer sabereis que o SENHOR vos tirou da terra do Egito.'),
(1955, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 7, 'OT', 'E pela manhã vereis a glória do SENHOR, porque ele ouviu as vossas murmurações contra o SENHOR; e quem somos nós, para que murmureis contra nós?'),
(1956, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 8, 'OT', 'Disse Moisés: "Isso acontecerá quando o SENHOR vos der carne à tarde para comer, e pão pela manhã até vos fartardes, porque o SENHOR ouviu as vossas murmurações, com que murmurais contra ele. E quem somos nós? As vossas murmurações não são contra nós, mas sim contra o SENHOR."'),
(1957, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 9, 'OT', 'Disse Moisés a Arão: Dize a toda a congregação dos filhos de Israel: Chegae-vos para diante do SENHOR, porque ele ouviu as vossas murmurações.'),
(1958, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 10, 'OT', 'E aconteceu que, quando Arão falou a toda a congregação dos filhos de Israel, eles se voltaram para o deserto, e eis que a glória do SENHOR apareceu na nuvem.'),
(1959, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 11, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(1960, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 12, 'OT', 'Ouvi as murmurações dos filhos de Israel; fala-lhes, dizendo: Entre as duas tardes comereis carne, e pela manhã vos fartareis de pão; e sabereis que eu sou o SENHOR, vosso Deus.'),
(1961, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 13, 'OT', 'Ao cair da tarde, subiram codornizes e cobriram o acampamento; e pela manhã havia uma camada de orvalho ao redor do acampamento.'),
(1962, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 14, 'OT', 'E, alçando-se a camada de orvalho, eis que sobre a superfície do deserto havia algo fino e escamoso, fino como a geada sobre a terra.'),
(1963, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 15, 'OT', 'E viram os filhos de Israel e disseram uns aos outros: Que é isto? Pois não sabiam o que era. Disse-lhes Moisés: Este é o pão que o SENHOR vos deu para comer.'),
(1964, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 16, 'OT', 'Esta é a palavra que o SENHOR ordenou: Colhei dele cada um conforme o que pode comer, um ômer por cabeça, segundo o número das vossas pessoas; cada um tomará para os que estão na sua tenda.'),
(1965, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 17, 'OT', 'E os filhos de Israel fizeram assim; e colheram, uns mais e outros menos.'),
(1966, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 18, 'OT', 'Mediram-no com o ômer, e o que colheu muito não teve sobra, e o que colheu pouco não teve falta; cada um colheu conforme o que podia comer.'),
(1967, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 19, 'OT', 'Ninguém deixe dele até a manhã.'),
(1968, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 20, 'OT', 'Eles, porém, não deram ouvidos a Moisés; alguns deixaram dele até a manhã, e criou bichos e cheirou mal; e Moisés indignou-se contra eles.'),
(1969, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 21, 'OT', 'Colhiam-no, pois, cada manhã, cada um conforme a sua necessidade; e, quando o sol aquecia, derretia-se.'),
(1970, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 22, 'OT', 'E aconteceu que, no sexto dia, colheram pão em dobro, dois ômeres para cada um; e todos os líderes da congregação vieram e o relataram a Moisés.'),
(1971, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 23, 'OT', 'E ele lhes disse: Isto é o que o SENHOR disse: Amanhã é descanso, sábado santo ao SENHOR; o que quiserdes assar, assai, e o que quiserdes cozinhar, cozinhai; e todo o excedente, guardai-o para vós, para ser conservado até a manhã.'),
(1972, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 24, 'OT', 'E guardaram-no até a manhã, como Moisés havia ordenado; e não cheirou mal, nem havia nele bicho algum.'),
(1973, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 25, 'OT', 'Então disse Moisés: Comei-o hoje, porque hoje é o sábado dedicado ao SENHOR; hoje não o achareis no campo.'),
(1974, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 26, 'OT', 'Seis dias o colhereis, mas no sétimo dia é sábado; nele não haverá.'),
(1975, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 27, 'OT', 'No sétimo dia, alguns do povo saíram para colher, mas não encontraram nada.'),
(1976, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 28, 'OT', 'Então disse o SENHOR a Moisés: Até quando recusareis guardar os meus mandamentos e as minhas leis?'),
(1977, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 29, 'OT', 'Vejam que o SENHOR vos deu o sábado; por isso, no sexto dia, ele vos dá pão para dois dias. Fique cada um no seu lugar; ninguém saia do seu lugar no sétimo dia.'),
(1978, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 30, 'OT', 'E o povo descansou no sétimo dia.'),
(1979, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 31, 'OT', 'A casa de Israel chamou-lhe maná; e era como semente de coentro branco, e o seu sabor como bolos de mel.'),
(1980, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 32, 'OT', 'Disse Moisés: "Esta é a palavra que o SENHOR ordenou: ''Enche um ômer dele para guardar para as vossas gerações, para que vejam o pão que vos dei a comer no deserto, quando vos tirei da terra do Egito.''"'),
(1981, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 33, 'OT', 'Disse Moisés a Arão: Toma um vaso, e põe nele um ômer cheio de maná, e coloca-o diante do SENHOR, em guarda para as vossas gerações.'),
(1982, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 34, 'OT', 'Como o SENHOR ordenou a Moisés, assim Arão o colocou diante do testemunho, para ser guardado.'),
(1983, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 35, 'OT', 'E os filhos de Israel comeram o maná quarenta anos, até chegarem a uma terra habitada; comeram o maná até chegarem aos limites da terra de Canaã.'),
(1984, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 16, 36, 'OT', 'Um gômer é a décima parte de uma efa.'),
(1985, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 1, 'OT', 'Toda a congregação dos filhos de Israel partiu do deserto de Sim, conforme as suas jornadas, segundo a ordem do SENHOR, e acamparam em Refidim; e não havia água para o povo beber.'),
(1986, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 2, 'OT', 'O povo contendia com Moisés e dizia: Dae-nos água para beber. Moisés lhes respondeu: Por que contendes comigo? Por que tentais o SENHOR?'),
(1987, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 3, 'OT', 'Ali o povo teve sede de água, e o povo murmurou contra Moisés, dizendo: Por que nos fizeste subir do Egito, para nos matar de sede, a mim, a meus filhos e ao meu gado?'),
(1988, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 4, 'OT', 'Então Moisés clamou ao SENHOR, dizendo: "Que farei a este povo? Por pouco não me apedrejam!"'),
(1989, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 5, 'OT', 'Disse o SENHOR a Moisés: Passa adiante do povo e toma contigo alguns dos anciãos de Israel; e toma na tua mão a tua vara com que feriste o rio, e vai.'),
(1990, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 6, 'OT', 'Eis que estarei diante de ti ali sobre a rocha, em Horebe; ferirás a rocha, e dela sairão águas, e o povo beberá. E Moisés assim o fez, diante dos olhos dos anciãos de Israel.'),
(1991, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 7, 'OT', 'E chamou o nome daquele lugar Massá e Meribá, por causa da contenda dos filhos de Israel, e porque tentaram o SENHOR, dizendo: Está o SENHOR no meio de nós, ou não?'),
(1992, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 8, 'OT', 'Então veio Amaleque e lutou contra Israel em Refidim.'),
(1993, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 9, 'OT', 'Disse Moisés a Josué: Escolhe-nos homens, e sai, luta contra Amaleque; amanhã eu estarei no topo do monte, e a vara de Deus estará na minha mão.'),
(1994, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 10, 'OT', 'E fez Josué como Moisés lhe dissera, para lutar contra Amaleque; e Moisés, Arão e Hur subiram ao topo da colina.'),
(1995, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 11, 'OT', 'E acontecia que, quando Moisés levantava a sua mão, Israel prevalecia; mas, quando ele a abaixava, Amaleque prevalecia.'),
(1996, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 12, 'OT', 'As mãos de Moisés ficaram pesadas; então eles pegaram uma pedra e a colocaram debaixo dele, e ele se assentou sobre ela. Arão e Hur sustentaram as suas mãos, um de um lado e o outro do outro; assim as suas mãos permaneceram firmes até o pôr do sol.'),
(1997, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 13, 'OT', 'E assim Josué derrotou Amaleque e seu povo ao fio da espada.'),
(1998, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 14, 'OT', 'Então disse o SENHOR a Moisés: Escreve isto como memorial no livro e põe nos ouvidos de Josué: certamente apagarei a memória de Amaleque de debaixo dos céus.'),
(1999, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 15, 'OT', 'Moisés edificou um altar e chamou o seu nome: SENHOR é minha bandeira.'),
(2000, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 17, 16, 'OT', 'E disse: Porque a mão está sobre o trono do SENHOR; haverá guerra do SENHOR contra Amaleque de geração em geração.'),
(2001, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 1, 'OT', 'E Jetro, sacerdote de Midiã, sogro de Moisés, ouviu tudo o que Deus tinha feito a Moisés e a Israel, seu povo: que o SENHOR tinha tirado Israel do Egito.'),
(2002, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 2, 'OT', 'E Jetro, sogro de Moisés, tomou Zípora, mulher de Moisés, depois que ele a enviara de volta.'),
(2003, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 3, 'OT', 'e seus dois filhos, dos quais um se chamava Gérson, porque ele disse: "Fui estrangeiro em terra estranha".'),
(2004, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 4, 'OT', 'E o nome do outro era Eliezer, pois disse: "O Deus de meu pai foi minha ajuda e me livrou da espada de Faraó."'),
(2005, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 5, 'OT', 'E Jetro, sogro de Moisés, veio com seus filhos e sua esposa a Moisés, no deserto, onde ele estava acampado junto ao monte de Deus.'),
(2006, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 6, 'OT', 'E disse a Moisés: Eu, teu sogro Jetro, venho a ti, e tua mulher, e seus dois filhos com ela.'),
(2007, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 7, 'OT', 'Então Moisés saiu ao encontro do seu sogro, inclinou-se e beijou-o; e perguntaram um ao outro como estavam, e entraram na tenda.'),
(2008, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 8, 'OT', 'Moisés contou ao seu sogro tudo o que o SENHOR tinha feito a Faraó e aos egípcios por causa de Israel, e toda a dificuldade que os havia sobrevindo no caminho, e como o SENHOR os livrou.'),
(2009, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 9, 'OT', 'E alegrou-se Jetro por todo o bem que o SENHOR fizera a Israel, livrando-o da mão dos egípcios.'),
(2010, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 10, 'OT', 'E Jetro disse: Bendito seja o SENHOR, que vos livrou da mão dos egípcios e da mão de Faraó; que livrou este povo de debaixo da mão dos egípcios.'),
(2011, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 11, 'OT', 'Agora sei que o SENHOR é maior do que todos os deuses, porque naquilo em que se ensoberbeceram, ele os superou.'),
(2012, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 12, 'OT', 'Então Jetro, sogro de Moisés, tomou holocausto e sacrifícios para Deus; e Arão e todos os anciãos de Israel vieram para comer pão com o sogro de Moisés diante de Deus.'),
(2013, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 13, 'OT', 'No dia seguinte, Moisés assentou-se para julgar o povo; e o povo permaneceu diante de Moisés desde a manhã até a tarde.'),
(2014, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 14, 'OT', 'Vendo o sogro de Moisés tudo o que ele fazia ao povo, disse: Que é isto que tu fazes ao povo? Por que te assentas sozinho, e todo o povo está em pé diante de ti, desde a manhã até a tarde?'),
(2015, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 15, 'OT', 'Moisés respondeu ao seu sogro: "Porque o povo vem a mim para consultar a Deus."'),
(2016, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 16, 'OT', 'Quando surge alguma questão entre eles, vem a mim, e eu julgo entre um homem e o seu próximo, e lhes ensino os estatutos de Deus e as suas leis.'),
(2017, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 17, 'OT', 'O sogro de Moisés lhe disse: Não é bom o que você está fazendo.'),
(2018, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 18, 'OT', 'Certamente desfalecerás, tanto tu como este povo que está contigo; porque a tarefa é pesada demais para ti; não a podes fazer sozinho.'),
(2019, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 19, 'OT', 'Ouve agora a minha voz; eu te aconselharei, e Deus será contigo. Sê tu pelo povo diante de Deus, e leva tu as questões a Deus.'),
(2020, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 20, 'OT', 'E advertirás a eles os estatutos e as leis, e lhes farás saber o caminho em que devem andar, e a obra que devem fazer.'),
(2021, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 21, 'OT', 'E tu escolherás dentre todo o povo homens capazes, tementes a Deus, homens de verdade, que aborrecem a ganância; e os colocarás sobre eles como chefes de mil, chefes de cem, chefes de cinquenta e chefes de dez.'),
(2022, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 22, 'OT', 'E julgarão o povo em todo o tempo; e todo o caso grande trarão a ti, e todo o caso pequeno julgarão eles mesmos; assim aliviarás a carga de sobre ti, e eles a levarão contigo.'),
(2023, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 23, 'OT', 'Se fizeres esta palavra, e Deus te ordenar, poderás permanecer de pé; e também todo este povo virá em paz ao seu lugar.'),
(2024, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 24, 'OT', 'Moisés ouviu a voz do seu sogro e fez tudo o que ele tinha dito.'),
(2025, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 25, 'OT', 'Moisés escolheu homens capazes de todo o Israel e os colocou como chefes sobre o povo: chefes de mil, chefes de cem, chefes de cinquenta e chefes de dez.'),
(2026, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 26, 'OT', 'E eles julgavam o povo em todo o tempo; a causa difícil traziam a Moisés, e toda causa pequena julgavam eles.'),
(2027, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 18, 27, 'OT', 'Despediu Moisés o seu sogro, e ele foi para a sua terra.'),
(2028, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 1, 'OT', 'No terceiro mês da saída dos filhos de Israel da terra do Egito, nesse mesmo dia chegaram ao deserto de Sinai.'),
(2029, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 2, 'OT', 'Partiram de Refidim, vieram ao deserto de Sinai e acamparam no deserto; e Israel acampou ali diante do monte.'),
(2030, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 3, 'OT', 'E Moisés subiu a Deus, e o SENHOR o chamou do monte, dizendo: Assim dirás à casa de Jacó e anunciarás aos filhos de Israel:'),
(2031, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 4, 'OT', 'Vós vistes o que fiz aos egípcios, como vos levei sobre asas de águias e vos trouxe a mim.'),
(2032, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 5, 'OT', 'Agora, pois, se ouvirdes atentamente a minha voz e guardardes a minha aliança, sereis o meu tesouro peculiar dentre todos os povos, porque toda a terra é minha.'),
(2033, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 6, 'OT', 'E vós sereis para mim um reino de sacerdotes e uma nação santa. Estas são as palavras que falarás aos filhos de Israel.'),
(2034, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 7, 'OT', 'E veio Moisés, e chamou os anciãos do povo, e pôs diante deles todas estas palavras que o SENHOR lhe havia ordenado.'),
(2035, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 8, 'OT', 'Então todo o povo respondeu a uma só voz e disse: Tudo o que o SENHOR falou, faremos. E Moisés levou as palavras do povo de volta ao SENHOR.'),
(2036, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 9, 'OT', 'E disse o SENHOR a Moisés: Eis que eu virei a ti numa nuvem espessa, para que o povo ouça quando eu falar contigo, e também para que creiam em ti para sempre. E Moisés relatou as palavras do povo ao SENHOR.'),
(2037, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 10, 'OT', 'Disse o SENHOR a Moisés: Vai ao povo e santifica-os hoje e amanhã; e lavem eles as suas vestes.'),
(2038, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 11, 'OT', 'E estejam prontos para o terceiro dia, porque no terceiro dia o SENHOR descerá diante dos olhos de todo o povo sobre o monte Sinai.'),
(2039, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 12, 'OT', 'E demarcarás limites ao povo ao redor, dizendo: Guardai-vos de subir ao monte e de tocar a sua borda; todo aquele que tocar o monte certamente morrerá.'),
(2040, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 13, 'OT', 'Nenhuma mão tocará nele; certamente será apedrejado ou flechado, seja animal, seja homem, não viverá. Quando a trombeta soar, eles subirão ao monte.'),
(2041, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 14, 'OT', 'Então Moisés desceu do monte ao povo, e santificou o povo; e eles lavaram as suas vestes.'),
(2042, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 15, 'OT', 'Estejam prontos para o terceiro dia; não se aproximem de mulher alguma.'),
(2043, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 16, 'OT', 'E aconteceu que, ao terceiro dia, ao amanhecer, houve trovões e relâmpagos, e uma nuvem espessa sobre o monte, e um som de trombeta muito forte; e todo o povo que estava no acampamento tremeu.'),
(2044, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 17, 'OT', 'Moisés levou o povo para fora do acampamento ao encontro de Deus, e eles se colocaram ao pé do monte.'),
(2045, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 18, 'OT', 'E todo o monte Sinai fumegava, porque o SENHOR descera sobre ele em fogo; e a sua fumaça subia como a fumaça de uma fornalha, e todo o monte tremia grandemente.'),
(2046, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 19, 'OT', 'E o som da trombeta ia crescendo e se tornando muito forte; Moisés falava, e Deus lhe respondia em voz.'),
(2047, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 20, 'OT', 'E desceu o SENHOR sobre o monte Sinai, ao cume do monte; e chamou o SENHOR a Moisés ao cume do monte; e Moisés subiu.'),
(2048, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 21, 'OT', 'Desce, adverte o povo, para que não rompam até o SENHOR para ver, e muitos deles caiam.'),
(2049, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 22, 'OT', 'Também os sacerdotes que se aproximam do SENHOR devem se santificar, para que o SENHOR não irrompa contra eles.'),
(2050, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 23, 'OT', 'Então Moisés disse ao SENHOR: O povo não poderá subir ao monte Sinai, porque tu nos advertiste, dizendo: Põe limites ao monte e santifica-o.'),
(2051, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 24, 'OT', 'Disse-lhe o SENHOR: Vai, desce; depois subirás tu, e Arão contigo; mas os sacerdotes e o povo não rompam a barreira para subir ao SENHOR, para que ele não irrompa contra eles.'),
(2052, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 19, 25, 'OT', 'Então Moisés desceu ao povo e lhes disse isso.'),
(2053, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 1, 'OT', 'E Deus falou todas estas palavras, dizendo:'),
(2054, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 2, 'OT', 'Eu sou o SENHOR, teu Deus, que te tirei da terra do Egito, da casa da servidão.'),
(2055, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 3, 'OT', 'Não terás outros deuses diante de mim.'),
(2056, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 4, 'OT', 'Não farás para ti imagem esculpida, nem qualquer semelhança do que há em cima nos céus, nem do que há embaixo na terra, nem do que há nas águas debaixo da terra.'),
(2057, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 5, 'OT', 'Não te prostrarás diante delas nem as servirás, porque eu, o SENHOR teu Deus, sou Deus zeloso, que castigo a iniquidade dos pais sobre os filhos, até a terceira e quarta geração daqueles que me odeiam.'),
(2058, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 6, 'OT', 'e que faço misericórdia a milhares, aos que me amam e aos que guardam os meus mandamentos.'),
(2059, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 7, 'OT', 'Não tomarás o nome do SENHOR, teu Deus, em vão, porque o SENHOR não deixará impune aquele que tomar o seu nome em vão.'),
(2060, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 8, 'OT', 'Lembra-te do dia do sábado, para o santificar.'),
(2061, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 9, 'OT', 'Seis dias trabalharás e farás toda a tua obra.'),
(2062, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 10, 'OT', 'Mas o sétimo dia é o sábado do SENHOR, teu Deus; não farás nenhum trabalho, nem tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem teu animal, nem o estrangeiro que está dentro das tuas portas.'),
(2063, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 11, 'OT', 'Porque em seis dias fez o SENHOR os céus e a terra, o mar e tudo o que neles há, e ao sétimo dia descansou; por isso, o SENHOR abençoou o dia do sábado e o santificou.'),
(2064, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 12, 'OT', 'Honra teu pai e tua mãe, para que se prolonguem os teus dias na terra que o SENHOR, teu Deus, te dá.'),
(2065, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 13, 'OT', 'Não matarás.'),
(2066, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 14, 'OT', 'Não adulterarás.'),
(2067, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 15, 'OT', 'Não furtarás.'),
(2068, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 16, 'OT', 'Não darás falso testemunho contra o teu próximo.'),
(2069, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 17, 'OT', 'Não cobiçarás a casa do teu próximo; não cobiçarás a mulher do teu próximo, nem o seu servo, nem a sua serva, nem o seu boi, nem o seu jumento, nem coisa alguma que pertença ao teu próximo.'),
(2070, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 18, 'OT', 'E todo o povo via os trovões e os relâmpagos, e o som da trombeta, e o monte fumegando; e o povo, vendo isso, tremeu e ficou de longe.'),
(2071, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 19, 'OT', 'E disseram a Moisés: Fala tu conosco, e ouviremos; e não fale Deus conosco, para que não morramos.'),
(2072, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 20, 'OT', 'E disse Moisés ao povo: Não temais, porque Deus veio para vos provar, e para que o seu temor esteja diante de vós, para que não pequeis.'),
(2073, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 21, 'OT', 'O povo permaneceu de longe, e Moisés se aproximou da nuvem escura onde Deus estava.'),
(2074, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 22, 'OT', 'Então o SENHOR disse a Moisés: Assim dirás aos filhos de Israel: Vós vistes que dos céus falei convosco.'),
(2075, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 23, 'OT', 'Não fareis deuses juntamente comigo; deuses de prata e deuses de ouro não fareis para vós.'),
(2076, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 24, 'OT', 'Um altar de terra me farás, e sobre ele sacrificarás os teus holocaustos e as tuas ofertas pacíficas, as tuas ovelhas e os teus bois; em todo lugar onde eu fizer lembrar o meu nome, virei a ti e te abençoarei.'),
(2077, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 25, 'OT', 'Se me fizeres um altar de pedras, não o construirás de pedras lavradas; pois se levantares a tua ferramenta sobre ele, tu o profanarás.'),
(2078, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 20, 26, 'OT', 'Não subirás por degraus ao meu altar, para que a tua nudez não seja exposta sobre ele.'),
(2079, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 1, 'OT', 'Estes são os estatutos que lhes proporás.'),
(2080, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 2, 'OT', 'Se comprares um servo hebreu, seis anos servirá; mas ao sétimo sairá livre, sem pagar nada.'),
(2081, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 3, 'OT', 'Se entrou sozinho, sozinho sairá; se era homem casado, sua mulher sairá com ele.'),
(2082, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 4, 'OT', 'Se o seu senhor lhe der uma mulher, e ela lhe der filhos ou filhas, a mulher e seus filhos serão do seu senhor, e ele sairá sozinho.'),
(2083, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 5, 'OT', 'Mas se o servo disser claramente: "Eu amo o meu senhor, a minha mulher e os meus filhos; não quero sair livre",'),
(2084, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 6, 'OT', 'Então o seu senhor o levará diante de Deus, e o fará chegar à porta ou ao umbral da porta; e o seu senhor furará a sua orelha com uma sovela, e ele o servirá para sempre.'),
(2085, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 7, 'OT', 'E se um homem vender sua filha como serva, ela não sairá como saem os servos.'),
(2086, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 8, 'OT', 'Se ela desagradar ao seu senhor, que não a designou para si, ele a deixará ser resgatada; não terá poder para vendê-la a um povo estrangeiro, por ter agido traiçoeiramente com ela.'),
(2087, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 9, 'OT', 'E se a desposar com seu filho, fará com ela conforme o direito das filhas.'),
(2088, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 10, 'OT', 'Se ele tomar para si outra mulher, não diminuirá o alimento dela, nem a sua roupa, nem o seu direito conjugal.'),
(2089, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 11, 'OT', 'E se estas três coisas não lhe fizer, ela sairá livre, sem pagamento de dinheiro.'),
(2090, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 12, 'OT', 'Quem ferir um homem e este morrer, certamente será morto.'),
(2091, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 13, 'OT', 'Mas se não lhe armou ciladas, e Deus o fez encontrar em suas mãos, então designarei para você um lugar para onde ele fugirá.'),
(2092, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 14, 'OT', 'Se alguém se levantar contra o seu próximo para matá-lo com astúcia, você o tirará do meu altar para que morra.'),
(2093, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 15, 'OT', 'Quem ferir seu pai ou sua mãe certamente será morto.'),
(2094, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 16, 'OT', 'E quem sequestrar um homem e o vender, e for achado na sua mão, certamente será morto.'),
(2095, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 17, 'OT', 'Quem amaldiçoar seu pai ou sua mãe certamente será morto.'),
(2096, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 18, 'OT', 'E se homens brigarem, e um ferir o outro com pedra ou com o punho, e ele não morrer, mas ficar de cama,'),
(2097, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 19, 'OT', 'Se ele se levantar e andar fora, apoiado no seu bordão, então aquele que o feriu será absolvido; somente pagará o tempo perdido e o fará curar completamente.'),
(2098, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 20, 'OT', 'Se alguém ferir seu servo ou sua serva com um bastão, e ele morrer sob sua mão, certamente será vingado.'),
(2099, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 21, 'OT', 'Porém, se ele sobreviver por um ou dois dias, não será punido, porque é seu dinheiro.'),
(2100, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 22, 'OT', 'Se alguns homens brigarem e ferirem uma mulher grávida, e ela abortar, porém não houver dano grave, certamente será multado, conforme o que o marido da mulher lhe impuser, e pagará diante dos juízes.'),
(2101, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 23, 'OT', 'Mas se houver dano grave, então darás vida por vida.'),
(2102, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 24, 'OT', 'Olho por olho, dente por dente, mão por mão, pé por pé.'),
(2103, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 25, 'OT', 'Queimadura por queimadura, ferida por ferida, golpe por golpe.'),
(2104, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 26, 'OT', 'E se alguém ferir o olho do seu servo ou o olho da sua serva, e o danificar, ele o deixará ir livre em compensação pelo seu olho.'),
(2105, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 27, 'OT', 'E se ele derrubar o dente do seu servo ou o dente da sua serva, o deixará ir livre em troca do seu dente.'),
(2106, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 28, 'OT', 'Se um boi chifrar um homem ou uma mulher, e este morrer, o boi será apedrejado com certeza, e a sua carne não será comida; mas o dono do boi será inocente.'),
(2107, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 29, 'OT', 'Se um boi costumava chifrar já em tempos passados, e seu dono foi avisado, mas não o guardou, e o boi matar um homem ou uma mulher, o boi será apedrejado, e também o seu dono morrerá.'),
(2108, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 30, 'OT', 'Se lhe for imposto resgate, então dará o resgate da sua vida conforme tudo o que lhe for imposto.'),
(2109, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 31, 'OT', 'Se um boi escornear um filho ou escornear uma filha, conforme este estatuto lhe será feito.'),
(2110, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 32, 'OT', 'Se o boi chifrar um servo ou uma serva, dará trinta siclos de prata ao seu senhor, e o boi será apedrejado.'),
(2111, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 33, 'OT', 'E se alguém abrir um poço, ou se alguém cavar um poço e não o cobrir, e cair ali um boi ou um jumento,'),
(2112, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 34, 'OT', 'O dono do poço pagará; restituirá o dinheiro ao seu dono, e o animal morto será seu.'),
(2113, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 35, 'OT', 'Se o boi de um homem ferir o boi do seu próximo, e este morrer, venderão o boi vivo e dividirão o seu valor, e também dividirão o boi morto entre eles.'),
(2114, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 21, 36, 'OT', 'Ou se for notório que aquele boi já era chifrador desde antes, e seu dono não o guardou, certamente pagará boi por boi, e o morto será seu.'),
(2115, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 1, 'OT', 'Se alguém furtar um boi ou uma ovelha, e o degolar ou vender, pagará cinco bois pelo boi e quatro ovelhas pela ovelha.'),
(2116, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 2, 'OT', 'Se o ladrão for encontrado no arrombamento, e for ferido e morrer, não haverá culpa de sangue para ele.'),
(2117, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 3, 'OT', 'Se o sol já tiver nascido sobre ele, haverá culpa de sangue; ele certamente restituirá. Se não tiver com que pagar, será vendido por seu furto.'),
(2118, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 4, 'OT', 'Se o furto for achado vivo em sua mão, desde boi até jumento até ovelha, pagará o dobro.'),
(2119, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 5, 'OT', 'Se alguém fizer pastar um campo ou uma vinha, e soltar o seu animal para que ele paste no campo de outro, restituirá com o melhor do seu próprio campo e o melhor da sua própria vinha.'),
(2120, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 6, 'OT', 'Se um fogo se espalhar e alcançar espinhos, e o grão empilhado, ou a plantação, ou o campo for consumido, aquele que acendeu o fogo certamente pagará o que foi queimado.'),
(2121, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 7, 'OT', 'Se alguém der ao seu próximo prata ou objetos para guardar, e forem roubados da casa daquele homem, se o ladrão for encontrado, pagará o dobro.'),
(2122, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 8, 'OT', 'Se o ladrão não for encontrado, o dono da casa se apresentará diante de Deus, para jurar que não pôs a mão nos bens do seu próximo.'),
(2123, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 9, 'OT', 'Sobre todo caso de transgressão, seja boi, jumento, ovelha, roupa, ou qualquer coisa perdida, sobre a qual alguém disser: "Isto é meu", a causa de ambos virá perante Deus; aquele a quem Deus condenar pagará o dobro ao seu próximo.'),
(2124, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 10, 'OT', 'Se alguém entregar ao seu próximo um jumento, ou boi, ou ovelha, ou qualquer animal para guardar, e ele morrer, ou for ferido, ou for levado, sem que ninguém o veja,'),
(2125, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 11, 'OT', 'O juramento do SENHOR será entre os dois, de que ele não estendeu a mão sobre os bens do seu próximo; e o dono aceitará o juramento, e ele não restituirá.'),
(2126, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 12, 'OT', 'Mas se for roubado de junto dele, ele o restituirá ao seu dono.'),
(2127, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 13, 'OT', 'Se for dilacerado por animais, que o traga como testemunha; não pagará pelo dilacerado.'),
(2128, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 14, 'OT', 'E se alguém tomar emprestado do seu próximo, e for quebrado ou morrer, não estando o seu dono presente, certamente o restituirá.'),
(2129, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 15, 'OT', 'Se o seu dono estiver com ele, não pagará; se for alugado, será pelo seu aluguel.'),
(2130, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 16, 'OT', 'Se um homem seduzir uma virgem que não for desposada e se deitar com ela, certamente a tomará por mulher, pagando o dote.'),
(2131, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 17, 'OT', 'Se o pai dela se recusar terminantemente a entregá-la a ele, ele pagará em prata o equivalente ao dote das virgens.'),
(2132, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 18, 'OT', 'Não deixarás viver a feiticeira.'),
(2133, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 19, 'OT', 'Todo aquele que se deitar com um animal certamente será morto.'),
(2134, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 20, 'OT', 'Quem sacrificar a outros deuses será destruído, exceto ao SENHOR somente.'),
(2135, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 21, 'OT', 'Não maltratarás o estrangeiro, nem o oprimirás, pois fostes estrangeiros na terra do Egito.'),
(2136, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 22, 'OT', 'A nenhuma viúva nem órfão afligireis.'),
(2137, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 23, 'OT', 'Se de alguma maneira os afligires, e eles clamarem a mim, certamente ouvirei o seu clamor.'),
(2138, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 24, 'OT', 'A minha ira se acenderá, e eu vos matarei à espada; e vossas mulheres ficarão viúvas, e vossos filhos órfãos.'),
(2139, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 25, 'OT', 'Se emprestares dinheiro ao meu povo, ao pobre que está contigo, não serás para ele como um credor; não lhe imporás juros.'),
(2140, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 26, 'OT', 'Se tomares em penhor a capa do teu próximo, restituir-lhe-ás antes do pôr do sol.'),
(2141, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 27, 'OT', 'Porque é a sua única cobertura, é o manto para a sua pele; em que se deitaria? E será que, quando clamar a mim, eu o ouvirei, porque sou misericordioso.'),
(2142, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 28, 'OT', 'Não amaldiçoes a Deus, nem amaldiçoes o líder do teu povo.'),
(2143, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 29, 'OT', 'Não retardarás as tuas primícias nem os teus licores; o primogênito dos teus filhos me darás.'),
(2144, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 30, 'OT', 'Assim farás com o teu boi e com a tua ovelha: sete dias ficará com a sua mãe; ao oitavo dia o darás a mim.'),
(2145, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 22, 31, 'OT', 'Ser-me-eis homens santos; portanto, não comereis carne despedaçada no campo; aos cães a lançareis.'),
(2146, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 1, 'OT', 'Não aceitarás notícia falsa; não darás a mão ao ímpio para seres testemunha de violência.'),
(2147, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 2, 'OT', 'Não seguirás a multidão para fazer o mal; nem testemunharás numa contenda, para te desviares após a multidão, a fim de perverteres o direito.'),
(2148, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 3, 'OT', 'Não favorecerás o pobre na sua demanda.'),
(2149, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 4, 'OT', 'Se encontrares o boi do teu inimigo ou o seu jumento desgarrado, sem falta o reconduzirás a ele.'),
(2150, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 5, 'OT', 'Se você vir o jumento daquele que te odeia caído sob a sua carga, e você se abstiver de ajudá-lo, certamente você o ajudará com ele.'),
(2151, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 6, 'OT', 'Não perverterás o direito do teu pobre na sua demanda.'),
(2152, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 7, 'OT', 'Afasta-te de palavras falsas, e não mates o inocente e o justo, porque não justificarei o ímpio.'),
(2153, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 8, 'OT', 'Não aceitarás suborno, pois o suborno cega os que veem e perverte as palavras dos justos.'),
(2154, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 9, 'OT', 'Não oprimirás o estrangeiro, pois vós conheceis o coração do estrangeiro, porque fostes estrangeiros na terra do Egito.'),
(2155, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 10, 'OT', 'Seis anos semearás a tua terra e recolherás a sua colheita.'),
(2156, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 11, 'OT', 'No sétimo ano, porém, tu a deixarás descansar e a abandonarás, para que os pobres do teu povo comam dela, e o que sobrar, os animais do campo comerão. Assim farás com a tua vinha e com o teu olival.'),
(2157, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 12, 'OT', 'Seis dias farás os teus trabalhos, mas no sétimo dia descansarás, para que descanse o teu boi e o teu jumento, e para que tome alento o filho da tua serva e o estrangeiro.'),
(2158, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 13, 'OT', 'Em tudo o que vos tenho dito, guardai-vos; e o nome de outros deuses não mencionareis, nem se ouvirá da vossa boca.'),
(2159, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 14, 'OT', 'Três vezes por ano me celebrarás festa.'),
(2160, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 15, 'OT', 'Guarda a festa dos pães sem fermento: sete dias comerás pães sem fermento, como te ordenei, no tempo determinado do mês de Abibe, porque nele saíste do Egito; e ninguém aparecerá diante de mim de mãos vazias.'),
(2161, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 16, 'OT', 'E a festa da colheita dos primeiros frutos do teu trabalho, que semeares no campo; e a festa da colheita no fim do ano, quando recolheres do campo o teu trabalho.'),
(2162, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 17, 'OT', 'Três vezes por ano, todos os teus homens se apresentarão diante do SENHOR, o Soberano.'),
(2163, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 18, 'OT', 'Não sacrificarás o sangue do meu sacrifício com pão levedado, nem ficará a gordura da minha festa até a manhã.'),
(2164, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 19, 'OT', 'As primícias dos primeiros frutos da tua terra trarás à casa do SENHOR, teu Deus; não cozerás o cabrito no leite de sua mãe.'),
(2165, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 20, 'OT', 'Eis-que eu envio um anjo diante de ti, para te guardar no caminho e te levar ao lugar que preparei.'),
(2166, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 21, 'OT', 'Guarda-te diante dele e ouve a sua voz; não sejas rebelde contra ele, porque não perdoará a vossa transgressão, pois o meu nome está nele.'),
(2167, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 22, 'OT', 'Se diligentemente ouvires a sua voz e fizeres tudo o que eu disser, então serei inimigo dos teus inimigos e adversário dos teus adversários.'),
(2168, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 23, 'OT', 'Porque o meu anjo irá diante de ti e te levará aos amorreus, aos hititas, aos perizeus, aos cananeus, aos heveus e aos jebuseus; e eu os destruirei.'),
(2169, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 24, 'OT', 'Não te prostrarás diante dos seus deuses, nem os servirás, nem farás conforme as suas obras; antes, os destruirás completamente e quebrarás totalmente as suas colunas sagradas.'),
(2170, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 25, 'OT', 'Servireis ao SENHOR, vosso Deus, e ele abençoará o vosso pão e a vossa água; e eu removerei a enfermidade do meio de ti.'),
(2171, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 26, 'OT', 'Não haverá mulher que aborte nem estéril na tua terra; o número dos teus dias completarei.'),
(2172, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 27, 'OT', 'Enviarei o meu terror diante de ti, e destruirei todo o povo aonde vieres, e farei que todos os teus inimigos te voltem as costas.'),
(2173, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 28, 'OT', 'Enviarei vespões diante de ti, e eles expulsarão os heveus, os cananeus e os hititas de diante de ti.'),
(2174, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 29, 'OT', 'Não os expulsarei de diante de ti num só ano, para que a terra não se torne em deserto e as feras do campo se multipliquem contra ti.'),
(2175, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 30, 'OT', 'Pouco a pouco os expulsarei de diante de ti, até que sejas fecundo e possuas a terra por herança.'),
(2176, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 31, 'OT', 'E porei os teus limites desde o mar de Suf até o mar dos filisteus, e desde o deserto até o rio; porque darei em vossas mãos os habitantes da terra, e os expulsarei de diante de ti.'),
(2177, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 32, 'OT', 'Não farás aliança com eles, nem com os seus deuses.'),
(2178, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 23, 33, 'OT', 'Não habitarão na tua terra, para que não te façam pecar contra mim; porque se servires aos seus deuses, isso te será um laço.'),
(2179, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 1, 'OT', 'E a Moisés disse: Sobe ao SENHOR, tu e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel; e inclinai-vos de longe.'),
(2180, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 2, 'OT', 'E Moisés se aproximará sozinho do SENHOR; eles, porém, não se aproximarão, nem o povo subirá com ele.'),
(2181, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 3, 'OT', 'E veio Moisés e relatou ao povo todas as palavras do SENHOR e todos os estatutos; e todo o povo respondeu a uma só voz e disse: Todas as palavras que o SENHOR falou, faremos.'),
(2182, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 4, 'OT', 'Moisés escreveu todas as palavras do SENHOR, e, levantando-se de manhã cedo, edificou um altar ao pé do monte, e doze colunas, segundo as doze tribos de Israel.'),
(2183, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 5, 'OT', 'Enviou os jovens dos filhos de Israel, e eles ofereceram holocaustos e sacrificaram ao SENHOR sacrifícios pacíficos de novilhos.'),
(2184, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 6, 'OT', 'Moisés tomou metade do sangue e o colocou em bacias; e a outra metade do sangue aspergiu sobre o altar.'),
(2185, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 7, 'OT', 'Tomou o livro da aliança e o leu aos ouvidos do povo, e eles disseram: Tudo o que o SENHOR falou faremos e obedeceremos.'),
(2186, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 8, 'OT', 'Eis-aqui o sangue da aliança que o SENHOR fez convosco, sobre todas estas palavras.'),
(2187, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 9, 'OT', 'E subiram Moisés e Arão, Nadabe e Abiú, e setenta dos anciãos de Israel.'),
(2188, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 10, 'OT', 'E viram o Deus de Israel, e debaixo de seus pés havia como uma obra de pedra de safira, e como o aspecto do céu na sua claridade.'),
(2189, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 11, 'OT', 'E aos nobres dos filhos de Israel não estendeu a sua mão; eles viram a Deus, e comeram e beberam.'),
(2190, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 12, 'OT', 'Então o SENHOR disse a Moisés: "Sobe a mim no monte e fica lá; e te darei as tábuas de pedra, a lei e o mandamento que escrevi, para os ensinar."'),
(2191, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 13, 'OT', 'Levantou-se Moisés com Josué, seu servidor; e subiu Moisés ao monte de Deus.'),
(2192, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 14, 'OT', 'E aos anciãos disse: Esperai-nos aqui, até que voltemos a vós; e eis que Arão e Hur ficam convosco; quem tiver alguma questão, se chegará a eles.'),
(2193, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 15, 'OT', 'E subiu Moisés ao monte, e a nuvem cobriu o monte.'),
(2194, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 16, 'OT', 'A glória do SENHOR repousou sobre o monte Sinai, e a nuvem o cobriu por seis dias; e ao sétimo dia ele chamou Moisés do meio da nuvem.'),
(2195, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 17, 'OT', 'E a aparência da glória do SENHOR era como fogo consumidor no topo do monte, aos olhos dos filhos de Israel.'),
(2196, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 24, 18, 'OT', 'E Moisés entrou no meio da nuvem e subiu ao monte; e Moisés esteve no monte quarenta dias e quarenta noites.'),
(2197, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(2198, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 2, 'OT', 'Fala aos filhos de Israel, e que tomem para mim uma oferta; de todo homem cujo coração se mover voluntariamente, tomareis a minha oferta.'),
(2199, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 3, 'OT', 'E esta é a oferta que vocês tomarão deles: ouro, prata e bronze.'),
(2200, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 4, 'OT', 'E azul, e púrpura, e carmesim, e linho fino, e pelos de cabras.'),
(2201, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 5, 'OT', 'Peles de carneiros tingidas de vermelho, peles de animais marinhos e madeira de acácia.'),
(2202, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 6, 'OT', 'Azeite para a luz, especiarias para o óleo da unção e especiarias para o incenso aromático.'),
(2203, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 7, 'OT', 'Pedras de ônix e pedras de engaste para o éfode e para o peitoral.'),
(2204, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 8, 'OT', 'E me farão um santuário, e habitarei no meio deles.'),
(2205, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 9, 'OT', 'Conforme tudo o que eu te mostrar, o modelo do tabernáculo e o modelo de todos os seus utensílios, assim fareis.'),
(2206, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 10, 'OT', 'Farão uma arca de madeira de acácia; o seu comprimento será de dois côvados e meio, a sua largura de um côvado e meio, e a sua altura de um côvado e meio.'),
(2207, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 11, 'OT', 'E a cobrirás de ouro puro; por dentro e por fora a cobrirás, e farás sobre ela uma moldura de ouro ao redor.'),
(2208, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 12, 'OT', 'Fundirás para ela quatro argolas de ouro e as porás nos quatro cantos dela: duas argolas num lado dela e duas argolas no outro lado dela.'),
(2209, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 13, 'OT', 'Farás varas de madeira de acácia e as cobrirás de ouro.'),
(2210, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 14, 'OT', 'E colocarás as varas nas argolas, aos lados da arca, para levar a arca por meio delas.'),
(2211, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 15, 'OT', 'As varas estarão nas argolas da arca; não se tirarão dela.'),
(2212, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 16, 'OT', 'E porás na arca o testemunho, que eu te darei.'),
(2213, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 17, 'OT', 'Farás também uma tampa de ouro puro: o seu comprimento será de dois côvados e meio, e a sua largura de um côvado e meio.'),
(2214, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 18, 'OT', 'Farás dois querubins de ouro; de ouro batido os farás, nas duas extremidades do propiciatório.'),
(2215, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 19, 'OT', 'Farás um querubim numa extremidade e um querubim na outra extremidade; de uma só peça com o propiciatório fareis os querubins nas suas duas extremidades.'),
(2216, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 20, 'OT', 'Os querubins estenderão as asas para cima, cobrindo com elas o propiciatório; e as suas faces estarão uma de frente para a outra; as faces dos querubins estarão voltadas para o propiciatório.'),
(2217, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 21, 'OT', 'E porás o propiciatório sobre a arca, em cima; e na arca porás o testemunho que eu te darei.'),
(2218, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 22, 'OT', 'E ali virei a ti e falarei contigo de cima do propiciatório, do meio dos dois querubins que estão sobre a arca do testemunho, tudo o que eu te ordenar para os filhos de Israel.'),
(2219, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 23, 'OT', 'Farás também uma mesa de madeira de acácia; o seu comprimento será de dois côvados, a sua largura de um côvado, e a sua altura de um côvado e meio.'),
(2220, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 24, 'OT', 'E cobrirás de ouro puro, e lhe farás uma moldura de ouro ao redor.'),
(2221, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 25, 'OT', 'Farás também ao redor uma moldura da largura de um palmo, e farás uma borda de ouro ao redor da moldura.'),
(2222, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 26, 'OT', 'Farás para ele quatro argolas de ouro, e as porás nos quatro cantos que estão nos seus quatro pés.'),
(2223, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 27, 'OT', 'Defronte da moldura estarão as argolas, como lugares para os varais, para se levar a mesa.'),
(2224, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 28, 'OT', 'Farás as varas de madeira de acácia e as cobrirás de ouro, e com elas se levará a mesa.'),
(2225, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 29, 'OT', 'Farás os seus pratos, as suas colheres, as suas jarras e as suas taças com que se fazem as libações; de ouro puro os farás.'),
(2226, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 30, 'OT', 'E sobre a mesa porás o pão da presença diante de mim continuamente.'),
(2227, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 31, 'OT', 'Farás também um candelabro de ouro puro; de ouro batido se fará o candelabro; o seu pedestal, a sua haste, as suas taças, os seus botões e as suas flores serão todos de uma só peça com ele.'),
(2228, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 32, 'OT', 'E dos seus lados sairão seis braços: três braços do candelabro de um lado, e três braços do candelabro do outro lado.'),
(2229, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 33, 'OT', 'Três cálices em forma de flor de amêndoa no primeiro braço, com botão e flor; e três cálices em forma de flor de amêndoa no outro braço, com botão e flor; assim será para os seis braços que saem do candelabro.'),
(2230, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 34, 'OT', 'E no candelabro haverá quatro cálices em forma de flor de amendoeira, com seus botões e suas flores.'),
(2231, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 35, 'OT', 'E um botão debaixo de dois braços que saem dela, e um botão debaixo de dois braços que saem dela, e um botão debaixo de dois braços que saem dela, para os seis braços que saem do candelabro.'),
(2232, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 36, 'OT', 'Os seus botões e os seus ramos serão todos de uma só peça com ela; tudo será uma só obra batida de ouro puro.'),
(2233, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 37, 'OT', 'Farás também sete lâmpadas para ela; e as lâmpadas serão acesas para alumiar diante dela.'),
(2234, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 38, 'OT', 'Os seus espevitadores e os seus apagadores serão de ouro puro.'),
(2235, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 39, 'OT', 'De um talento de ouro puro a farás, com todos estes utensílios.'),
(2236, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 25, 40, 'OT', 'Atenta para fazeres conforme o seu modelo, que te foi mostrado no monte.'),
(2237, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 1, 'OT', 'Farás o tabernáculo com dez cortinas de linho fino torcido, e de azul, púrpura e carmesim; com querubins as farás, obra de artista.'),
(2238, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 2, 'OT', 'O comprimento de cada cortina será de vinte e oito côvados, e a largura de cada cortina será de quatro côvados; todas as cortinas terão a mesma medida.'),
(2239, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 3, 'OT', 'Cinco cortinas serão unidas uma à outra; e as outras cinco cortinas serão unidas uma à outra.'),
(2240, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 4, 'OT', 'Farás laçadas de azul na borda da cortina, na extremidade, na juntura; e assim farás na borda da cortina que está na extremidade, na segunda juntura.'),
(2241, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 5, 'OT', 'Cinquenta laçadas farás na primeira cortina, e cinquenta laçadas farás na extremidade da cortina que está na segunda juntura; as laçadas se corresponderão uma à outra.'),
(2242, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 6, 'OT', 'Farás cinquenta colchetes de ouro e unirás as cortinas, uma à outra, com os colchetes; e o tabernáculo será um só.'),
(2243, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 7, 'OT', 'Farás cortinas de pelos de cabra para a tenda sobre o tabernáculo; de onze cortinas as farás.'),
(2244, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 8, 'OT', 'O comprimento de cada cortina será de trinta côvados, e a largura de cada cortina será de quatro côvados; estas onze cortinas terão a mesma medida.'),
(2245, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 9, 'OT', 'E unirás as cinco cortinas à parte, e as seis cortinas à parte; e dobrarás a sexta cortina diante da entrada da tenda.'),
(2246, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 10, 'OT', 'Farás cinquenta laçadas na borda da cortina que está na extremidade da junção, e cinquenta laçadas na borda da cortina da segunda junção.'),
(2247, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 11, 'OT', 'Farás cinquenta colchetes de bronze, e meterás os colchetes nas laçadas, e ajuntarás a tenda, para que seja uma só.'),
(2248, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 12, 'OT', 'E o excesso que sobra das cortinas da tenda, a metade da cortina que sobra, penderá sobre a parte posterior do tabernáculo.'),
(2249, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 13, 'OT', 'E o côvado de um lado e o côvado do outro lado, no que sobejar no comprimento das cortinas da tenda, ficará pendente sobre os lados do tabernáculo, de um lado e do outro, para o cobrir.'),
(2250, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 14, 'OT', 'Farás também uma coberta para a tenda, de peles de carneiro tingidas de vermelho, e uma coberta de peles de animais marinhos por cima.'),
(2251, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 15, 'OT', 'Farás também as tábuas para o tabernáculo de madeira de acácia, que estarão em pé.'),
(2252, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 16, 'OT', 'Dez côvados será o comprimento de cada armação, e um côvado e meio a largura de cada armação.'),
(2253, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 17, 'OT', 'Duas mãos terá cada armação, unidas uma à outra; assim farás com todas as armações do tabernáculo.'),
(2254, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 18, 'OT', 'Farás também as tábuas para o tabernáculo: vinte tábuas para o lado sul, para o sul.'),
(2255, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 19, 'OT', 'Farás também quarenta bases de prata debaixo das vinte tábuas: duas bases debaixo de uma tábua para as suas duas encaixes, e duas bases debaixo de outra tábua para as suas duas encaixes.'),
(2256, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 20, 'OT', 'E para o lado do tabernáculo, o segundo lado, para a banda do norte, vinte tábuas.'),
(2257, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 21, 'OT', 'E as suas quarenta bases de prata: duas bases debaixo de uma armação, e duas bases debaixo da outra armação.'),
(2258, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 22, 'OT', 'E para o lado posterior do tabernáculo, ao ocidente, farás seis tábuas.'),
(2259, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 23, 'OT', 'Farás também duas tábuas para os cantos do tabernáculo, nos dois lados.'),
(2260, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 24, 'OT', 'Serão duplos desde a parte inferior, e juntos serão perfeitos no topo, até a primeira argola; assim será com os dois; para os dois cantos serão.'),
(2261, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 25, 'OT', 'Serão oito tábuas, com as suas bases de prata: dezesseis bases; duas bases debaixo de uma tábua, e duas bases debaixo de outra tábua.'),
(2262, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 26, 'OT', 'Farás também cinco barras de madeira de acácia para as tábuas de um lado do tabernáculo.'),
(2263, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 27, 'OT', 'E cinco travessões para as armações do segundo lado do tabernáculo, e cinco travessões para as armações do tabernáculo no lado posterior, para o oeste.'),
(2264, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 28, 'OT', 'E a barra do meio passará pelo meio das tábuas, atravessando de uma extremidade à outra.'),
(2265, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 29, 'OT', 'Cobrirás de ouro as tábuas, e farás de ouro as suas argolas, como suportes para os travessões; e cobrirás de ouro os travessões.'),
(2266, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 30, 'OT', 'Levantarás o tabernáculo conforme o seu modelo, que te foi mostrado no monte.'),
(2267, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 31, 'OT', 'Farás também um véu de azul, púrpura, carmesim e linho fino torcido; com querubins, obra de artista, o farás.'),
(2268, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 32, 'OT', 'E o pendurarás sobre quatro colunas de madeira de acácia, revestidas de ouro, com seus ganchos de ouro, sobre quatro bases de prata.'),
(2269, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 33, 'OT', 'Pendurarás o véu debaixo dos colchetes, e trarás para lá, para dentro do véu, a arca do testemunho; e o véu vos fará separação entre o lugar santo e o lugar santíssimo.'),
(2270, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 34, 'OT', 'E porás o propiciatório sobre a arca do testemunho, no Santo dos Santos.'),
(2271, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 35, 'OT', 'E porás a mesa fora do véu, e o candelabro defronte da mesa, ao lado do tabernáculo, para o sul; e a mesa porás ao lado do norte.'),
(2272, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 36, 'OT', 'Farás também para a entrada da tenda um véu de azul, púrpura, carmesim e linho fino torcido, obra de bordador.'),
(2273, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 26, 37, 'OT', 'Farás para o véu cinco colunas de madeira de acácia, e as cobrirás de ouro; seus colchetes serão de ouro, e fundirás para elas cinco bases de bronze.'),
(2274, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 1, 'OT', 'Farás também o altar de madeira de acácia; cinco côvados será o seu comprimento, e cinco côvados a sua largura; quadrado será o altar, e três côvados a sua altura.'),
(2275, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 2, 'OT', 'Farás as suas pontas nos seus quatro cantos; as suas pontas serão da mesma peça, e o cobrirás de bronze.'),
(2276, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 3, 'OT', 'Far-lhe-has as suas caldeiras para recolher a cinza, e as suas pás, e as suas bacias, e os seus garfos, e os seus braseiros; todos os seus utensílios farás de bronze.'),
(2277, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 4, 'OT', 'Far-lhe-has também uma grelha de bronze, em forma de rede, e farás sobre a rede quatro argolas de bronze, nos seus quatro cantos.'),
(2278, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 5, 'OT', 'E a colocarás debaixo da borda do altar, por baixo, de modo que a rede chegue até o meio do altar.'),
(2279, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 6, 'OT', 'Farás varas para o altar, varas de madeira de acácia, e as cobrirás de bronze.'),
(2280, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 7, 'OT', 'E os seus varais serão introduzidos nas argolas, e os varais estarão sobre os dois lados do altar, quando for levado.'),
(2281, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 8, 'OT', 'Oco de tábuas o farás; como te foi mostrado no monte, assim o farão.'),
(2282, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 9, 'OT', 'Farás também o átrio do tabernáculo; ao lado sul, para o sul, haverá cortinas para o átrio de linho fino torcido, de cem côvados de comprimento para um lado.'),
(2283, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 10, 'OT', 'E as suas vinte colunas e as suas vinte bases serão de bronze; os ganchos das colunas e as suas faixas serão de prata.'),
(2284, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 11, 'OT', 'E assim, para o lado norte, ao longo do comprimento, as cortinas terão cem côvados de comprimento; e as suas vinte colunas e as suas vinte bases serão de bronze; os colchetes das colunas e as suas faixas serão de prata.'),
(2285, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 12, 'OT', 'E a largura do pátio, ao lado do ocidente, terá cortinas de cinquenta côvados; as suas colunas serão dez, e as suas bases dez.'),
(2286, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 13, 'OT', 'E a largura do pátio, ao lado oriental, para o nascente, será de cinquenta côvados.'),
(2287, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 14, 'OT', 'E de quinze côvados as cortinas para um lado; as suas colunas, três, e as suas bases, três.'),
(2288, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 15, 'OT', 'E para o segundo lado, quinze cortinas; as suas colunas, três, e as suas bases, três.'),
(2289, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 16, 'OT', 'E à porta do átrio haverá uma cortina de vinte côvados, de azul, púrpura, carmesim e linho fino torcido, obra de bordador; as suas colunas serão quatro, e as suas bases quatro.'),
(2290, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 17, 'OT', 'Todos os postes do pátio ao redor serão revestidos de prata, e os seus ganchos serão de prata, e as suas bases serão de bronze.'),
(2291, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 18, 'OT', 'O comprimento do pátio será de cem côvados, e a largura de cinquenta em cada lado, e a altura de cinco côvados, de linho fino torcido; e as suas bases serão de bronze.'),
(2292, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 19, 'OT', 'Todos os utensílios do tabernáculo, em todo o seu serviço, e todas as suas estacas, e todas as estacas do pátio, serão de bronze.'),
(2293, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 20, 'OT', 'Tu ordenarás aos filhos de Israel que te tragam azeite puro de oliveiras, batido para a luz, para manter acesa a lâmpada continuamente.'),
(2294, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 27, 21, 'OT', 'Na tenda do encontro, fora do véu que está diante do testemunho, Arão e seus filhos o prepararão, desde a tarde até a manhã, perante o SENHOR; é um estatuto perpétuo para as suas gerações, da parte dos filhos de Israel.'),
(2295, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 1, 'OT', 'Faze chegar a ti teu irmão Arão e seus filhos com ele, do meio dos filhos de Israel, para me servirem como sacerdotes: Arão, Nadabe e Abiú, Eleazar e Itamar, filhos de Arão.'),
(2296, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 2, 'OT', 'Farás vestes sagradas para Arão, teu irmão, para glória e esplendor.'),
(2297, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 3, 'OT', 'Fala também a todos os sábios de coração, a quem enchi do espírito de sabedoria, que façam as vestes de Arão para santificá-lo, para que me sirva como sacerdote.'),
(2298, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 4, 'OT', 'Estas são as vestes que farão: o peitoral, o éfode, o manto, a túnica bordada, a mitra e o cinto. Farão vestes sagradas para Arão, teu irmão, e para seus filhos, para que me sirvam como sacerdotes.'),
(2299, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 5, 'OT', 'E eles tomarão o ouro, e o azul, e a púrpura, e o carmesim, e o linho fino.'),
(2300, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 6, 'OT', 'E farão o éfode de ouro, de fio azul, de púrpura, de carmesim e de linho fino torcido, obra de artista.'),
(2301, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 7, 'OT', 'Terá duas ombreiras unidas às suas duas extremidades, e assim ficará unida.'),
(2302, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 8, 'OT', 'E o cinto do éfode, que estará sobre ele, será da mesma obra, feito do mesmo material: ouro, azul, púrpura, carmesim e linho fino torcido.'),
(2303, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 9, 'OT', 'Tomarás duas pedras de ônix e gravarás nelas os nomes dos filhos de Israel.'),
(2304, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 10, 'OT', 'Seis dos seus nomes sobre uma pedra, e os nomes dos seis restantes sobre a segunda pedra, segundo as suas gerações.'),
(2305, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 11, 'OT', 'Obra de ourives de pedra, como gravuras de selo, gravarás as duas pedras com os nomes dos filhos de Israel; engastadas em filigranas de ouro as farás.'),
(2306, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 12, 'OT', 'E porás as duas pedras sobre as omoplatas do éfode, como pedras de memorial para os filhos de Israel; e Arão levará os seus nomes diante do SENHOR sobre os seus dois ombros, para memorial.'),
(2307, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 13, 'OT', 'Farás também engastes de ouro.'),
(2308, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 14, 'OT', 'E duas correntes de ouro puro farás, de obra trançada, e porás as correntes trançadas sobre os engastes.'),
(2309, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 15, 'OT', 'Farás o peitoral do juízo, obra de artífice, como a obra do éfode o farás: de ouro, de azul, de púrpura, de carmesim e de linho fino torcido o farás.'),
(2310, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 16, 'OT', 'Quadrado e dobrado será; de um palmo o seu comprimento, e de um palmo a sua largura.'),
(2311, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 17, 'OT', 'E o encherás com pedras de engaste, em quatro fileiras de pedras: a primeira fileira será de sárdio, topázio e esmeralda.'),
(2312, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 18, 'OT', 'E a segunda fileira será de carbúnculo, safira e jaspe.'),
(2313, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 19, 'OT', 'E a terceira fileira: lesheme, shebo e aclamá.'),
(2314, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 20, 'OT', 'E a quarta fileira será de berilo, ônix e jaspe; serão engastados em ouro nos seus encaixes.'),
(2315, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 21, 'OT', 'E as pedras serão conforme os nomes dos filhos de Israel: doze, conforme os seus nomes; serão como gravuras de selo, cada uma com o seu nome, para as doze tribos.'),
(2316, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 22, 'OT', 'Farás também sobre o peitoral cadeias de trança, obra de cordão, de ouro puro.'),
(2317, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 23, 'OT', 'Farás também sobre o peitoral duas argolas de ouro, e porás as duas argolas nas duas extremidades do peitoral.'),
(2318, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 24, 'OT', 'E porás as duas correntes de ouro nos dois anéis, nas extremidades do peitoral.'),
(2319, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 25, 'OT', 'E as duas pontas das duas correntes porás sobre os dois engastes, e as porás sobre os ombros do éfode, defronte da sua frente.'),
(2320, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 26, 'OT', 'Farás também duas argolas de ouro e as porás nas duas extremidades do peitoral, na sua borda que está voltada para o lado de dentro do éfode.'),
(2321, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 27, 'OT', 'Farás também duas argolas de ouro, e as porás nas duas ombreiras do éfode, por baixo, diante dele, junto à sua junção, acima do cinto do éfode.'),
(2322, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 28, 'OT', 'E amarrarão o peitoral pelos seus anéis aos anéis do éfode com um cordão azul, para que fique sobre o cinto do éfode, e o peitoral não se solte do éfode.'),
(2323, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 29, 'OT', 'Aarão levará os nomes dos filhos de Israel no peitoral do juízo sobre o seu coração, quando entrar no santuário, para memorial diante do SENHOR continuamente.'),
(2324, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 30, 'OT', 'Põe no peitoral do juízo o Urim e o Tumim, para que estejam sobre o coração de Arão quando ele entrar diante do SENHOR; assim Arão levará o juízo dos filhos de Israel sobre o seu coração diante do SENHOR continuamente.'),
(2325, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 31, 'OT', 'Farás também o manto do éfode, todo de azul.'),
(2326, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 32, 'OT', 'E a abertura da cabeça estará no meio dela; terá uma borda tecida ao redor da abertura, como a abertura de uma cota de malha, para que não se rasgue.'),
(2327, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 33, 'OT', 'E farás nas suas bordas romãs de azul, e de púrpura, e de carmesim, ao redor das suas bordas; e campainhas de ouro no meio delas ao redor.'),
(2328, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 34, 'OT', 'Um sino de ouro e uma romã, um sino de ouro e uma romã, na borda do manto, ao redor.'),
(2329, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 35, 'OT', 'E estará sobre Arão quando ministrar, e o seu som se ouvirá quando ele entrar no santuário diante do SENHOR e quando sair, para que não morra.'),
(2330, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 36, 'OT', 'Farás também uma lâmina de ouro puro, e nela gravarás, como se gravam selos: "Santo ao SENHOR".'),
(2331, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 37, 'OT', 'E o porás sobre um cordão azul, e estará sobre a mitra; diante da face da mitra estará.'),
(2332, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 38, 'OT', 'E estará sobre a testa de Arão, e Arão levará a iniquidade das coisas santas que os filhos de Israel santificarem em todas as ofertas de suas coisas santas; e estará sobre a sua testa continuamente, para que sejam aceitos diante do SENHOR.'),
(2333, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 39, 'OT', 'Farás a túnica de linho fino, e farás a mitra de linho fino; e o cinto farás de obra bordada.'),
(2334, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 40, 'OT', 'Farás também túnicas para os filhos de Arão, e lhes farás cintos, e lhes farás tiaras, para glória e ornamento.'),
(2335, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 41, 'OT', 'Vestirás Arão, teu irmão, e seus filhos com ele; e os ungirás, consagrarás e santificarás, para que me sirvam como sacerdotes.'),
(2336, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 42, 'OT', 'Faze-lhes calções de linho para cobrir a carne nua; da cintura até as coxas serão.'),
(2337, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 28, 43, 'OT', 'E estarão sobre Arão e sobre seus filhos, quando entrarem na tenda da congregação, ou quando se aproximarem do altar para ministrar no lugar santo, para que não levem iniquidade e morram. Isto será estatuto perpétuo para ele e para a sua descendência depois dele.'),
(2338, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 1, 'OT', 'Isto é o que lhes farás para os santificar, para que me sirvam como sacerdotes: toma um novilho, filho de vaca, e dois carneiros sem defeito.'),
(2339, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 2, 'OT', 'Pão sem fermento, e bolos sem fermento amassados com azeite, e pães finos sem fermento untados com azeite: de flor de farinha de trigo os farás.'),
(2340, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 3, 'OT', 'E os porás num cesto, e os trarás no cesto, juntamente com o novilho e os dois carneiros.'),
(2341, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 4, 'OT', 'Farás chegar Arão e seus filhos à entrada da tenda do encontro, e os lavarás com água.'),
(2342, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 5, 'OT', 'Toma as vestes e veste Arão com a túnica, o manto do éfode, o próprio éfode e o peitoral; e cinge-o com o cinto do éfode.'),
(2343, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 6, 'OT', 'E porás a mitra sobre a sua cabeça; e colocarás a coroa da santidade sobre a mitra.'),
(2344, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 7, 'OT', 'Tomarás o óleo da unção e o derramarás sobre a cabeça dele; assim o ungirás.'),
(2345, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 8, 'OT', 'Farás chegar também seus filhos e os vestirás com túnicas.'),
(2346, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 9, 'OT', 'E os cingirás com o cinto, a Arão e a seus filhos, e lhes atarás as tiaras; e o sacerdócio será para eles por estatuto perpétuo. E consagrarás a Arão e a seus filhos.'),
(2347, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 10, 'OT', 'E trarás o novilho diante da tenda do encontro, e Arão e seus filhos porão as mãos sobre a cabeça do novilho.'),
(2348, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 11, 'OT', 'E sacrificarás o novilho diante do SENHOR, à entrada da tenda do encontro.'),
(2349, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 12, 'OT', 'Tomarás do sangue do novilho e o porás com o teu dedo sobre os chifres do altar, e todo o restante do sangue derramarás na base do altar.'),
(2350, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 13, 'OT', 'Tomarás toda a gordura que cobre as entranhas, e o redenho sobre o fígado, e os dois rins, e a gordura que está sobre eles, e os queimarás sobre o altar.'),
(2351, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 14, 'OT', 'Mas a carne do novilho, e a sua pele, e o seu esterco queimarás com fogo fora do acampamento; é oferta pelo pecado.'),
(2352, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 15, 'OT', 'Tomarás um dos carneiros, e Arão e seus filhos porão as mãos sobre a cabeça do carneiro.'),
(2353, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 16, 'OT', 'Degolarás o carneiro, tomarás o seu sangue e o aspergirás sobre o altar ao redor.'),
(2354, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 17, 'OT', 'E partirás o carneiro em seus pedaços, e lavarás as suas entranhas e as suas pernas, e as porás sobre os seus pedaços e sobre a sua cabeça.'),
(2355, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 18, 'OT', 'Queimarás todo o carneiro sobre o altar; é holocausto ao SENHOR, cheiro suave, oferta queimada ao SENHOR.'),
(2356, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 19, 'OT', 'Tomarás o segundo carneiro, e Arão e seus filhos porão as mãos sobre a cabeça do carneiro.'),
(2357, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 20, 'OT', 'E sacrificarás o carneiro, tomarás do seu sangue e o porás sobre o lóbulo da orelha direita de Arão, sobre o lóbulo da orelha direita de seus filhos, sobre o polegar da mão direita deles e sobre o polegar do pé direito deles; e aspergirás o sangue sobre o altar, ao redor.'),
(2358, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 21, 'OT', 'Toma do sangue que está sobre o altar e do óleo da unção, e asperge sobre Arão e sobre suas vestes, e sobre seus filhos e sobre as vestes de seus filhos com ele; assim ele será santificado, e as suas vestes, e seus filhos, e as vestes de seus filhos com ele.'),
(2359, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 22, 'OT', 'Tomarás também do carneiro a gordura, a cauda gorda, a gordura que cobre as entranhas, o redenho do fígado, os dois rins com a gordura que está sobre eles, e a coxa direita, porque é carneiro de consagração.'),
(2360, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 23, 'OT', 'E um cesto de pão sem fermento, e um pão fino com azeite, e um pão ázimo, do cesto dos pães sem fermento que está diante do SENHOR.'),
(2361, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 24, 'OT', 'E porás tudo nas mãos de Arão e nas mãos de seus filhos, e o moverás com movimento de oferta perante o SENHOR.'),
(2362, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 25, 'OT', 'Toma-os das suas mãos e queima-os no altar sobre o holocausto, como aroma agradável perante o SENHOR; é oferta queimada ao SENHOR.'),
(2363, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 26, 'OT', 'Tomarás o peito do carneiro das consagrações, que é de Arão, e o moverás com movimento perante o SENHOR; e isto será a tua porção.'),
(2364, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 27, 'OT', 'Santificarás o peito da oferta movida e a coxa da oferta alçada, que foi movida e alçada do carneiro das consagrações, que é de Arão e de seus filhos.'),
(2365, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 28, 'OT', 'E será para Arão e para seus filhos um estatuto perpétuo da parte dos filhos de Israel, porque é oferta; e a oferta será da parte dos filhos de Israel, dos seus sacrifícios pacíficos, a sua oferta ao SENHOR.'),
(2366, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 29, 'OT', 'E as vestes sagradas de Arão passarão aos seus filhos depois dele, para que nelas sejam ungidos e nelas sejam consagrados.'),
(2367, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 30, 'OT', 'Sete dias os vestirá o sacerdote que, dentre seus filhos, o suceder, quando entrar na tenda do encontro para ministrar no santuário.'),
(2368, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 31, 'OT', 'Tomarás o carneiro das consagrações e cozerás a sua carne em lugar santo.'),
(2369, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 32, 'OT', 'E Arão e seus filhos comerão a carne do carneiro e o pão que está no cesto, à entrada da tenda do encontro.'),
(2370, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 33, 'OT', 'Eles comerão aquilo com que foi feita expiação, para consagrá-los e santificá-los; mas nenhum estranho comerá, porque são santas.'),
(2371, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 34, 'OT', 'E se sobrar algo da carne das consagrações ou do pão até a manhã, queimarás o restante no fogo; não se comerá, porque é santo.'),
(2372, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 35, 'OT', 'Assim farás a Arão e a seus filhos, conforme tudo o que te ordenei: por sete dias consagrarás as suas mãos.'),
(2373, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 36, 'OT', 'Também oferecerás um novilho como oferta pelo pecado a cada dia, para as expiações; e purificarás o altar, fazendo expiação por ele; e o ungirás para santificá-lo.'),
(2374, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 37, 'OT', 'Sete dias farás expiação pelo altar e o santificarás; e o altar será santíssimo; tudo o que tocar o altar será santo.'),
(2375, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 38, 'OT', 'Isto é o que oferecerás sobre o altar: dois cordeiros de um ano, cada dia, continuamente.'),
(2376, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 39, 'OT', 'Um cordeiro oferecerás pela manhã, e o outro cordeiro oferecerás entre as duas tardes.'),
(2377, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 40, 'OT', 'E com um décimo de flor de farinha misturada com um quarto de him de azeite batido, e para libação um quarto de him de vinho, para cada cordeiro.'),
(2378, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 41, 'OT', 'E o segundo cordeiro oferecerás entre as duas tardes; com a oferta de manhã e com a sua libação o farás, em cheiro suave, oferta queimada ao SENHOR.'),
(2379, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 42, 'OT', 'Este será o holocausto contínuo por vossas gerações, à porta da tenda da congregação, perante o SENHOR, onde vos encontrarei, para falar contigo ali.'),
(2380, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 43, 'OT', 'E ali me encontrarei com os filhos de Israel, e o lugar será santificado pela minha glória.'),
(2381, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 44, 'OT', 'E consagrarei a tenda do encontro e o altar; também consagrarei Arão e seus filhos, para que me sirvam como sacerdotes.'),
(2382, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 45, 'OT', 'E habitarei no meio dos filhos de Israel, e lhes serei por Deus.'),
(2383, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 29, 46, 'OT', 'E saberão que eu sou o SENHOR, seu Deus, que os tirei da terra do Egito para habitar no meio deles. Eu sou o SENHOR, seu Deus.'),
(2384, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 1, 'OT', 'Farás um altar para queimar incenso; de madeira de acácia o farás.'),
(2385, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 2, 'OT', 'Um côvado de comprimento, e um côvado de largura; será quadrado, e dois côvados a sua altura; dele mesmo serão as suas pontas.'),
(2386, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 3, 'OT', 'E o cobrirás com ouro puro: o seu tampo, as suas paredes ao redor e as suas pontas; e lhe farás uma moldura de ouro ao redor.'),
(2387, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 4, 'OT', 'Farás também duas argolas de ouro debaixo da sua moldura, nos dois lados; fá-las-ás nos dois cantos, e servirão de suportes para os varais, com que se levará o altar.'),
(2388, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 5, 'OT', 'Farás as varas de madeira de acácia e as cobrirás de ouro.'),
(2389, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 6, 'OT', 'E o porás diante do véu que está diante da arca do testemunho, diante do propiciatório que está sobre o testemunho, onde eu me encontrarei contigo ali.'),
(2390, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 7, 'OT', 'E Arão queimará sobre ele incenso de especiarias; cada manhã, ao preparar as lâmpadas, o queimará.'),
(2391, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 8, 'OT', 'E quando Arão acender as lâmpadas ao entardecer, queimará o incenso; incenso contínuo perante o SENHOR, pelas vossas gerações.'),
(2392, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 9, 'OT', 'Não oferecereis sobre ele incenso estranho, nem holocausto, nem oferta de manjares; nem derramareis sobre ele libação.'),
(2393, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 10, 'OT', 'E uma vez por ano Arão fará expiação sobre os seus chifres com o sangue da oferta pelo pecado das expiações; uma vez por ano fará expiação sobre ele, pelas vossas gerações; santíssimo é ao SENHOR.'),
(2394, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 11, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(2395, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 12, 'OT', 'Quando tomares o censo dos filhos de Israel, conforme a sua contagem, cada um dará ao SENHOR o resgate da sua vida, ao serem contados, para que não haja entre eles praga alguma, quando os contares.'),
(2396, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 13, 'OT', 'Todo aquele que passar ao recenseamento dará isto: a metade de um siclo, segundo o siclo do santuário (o siclo tem vinte geras); a metade de um siclo é oferta ao SENHOR.'),
(2397, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 14, 'OT', 'Todo aquele que passar pelo recenseamento, de vinte anos para cima, dará a oferta ao SENHOR.'),
(2398, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 15, 'OT', 'O rico não dará mais, e o pobre não dará menos do que meio siclo, ao oferecer a contribuição ao SENHOR, para fazer expiação por vossas vidas.'),
(2399, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 16, 'OT', 'Tomarás o dinheiro das expiações dos filhos de Israel e o darás para o serviço da tenda da congregação; e será para os filhos de Israel por memorial diante do SENHOR, para fazer expiação pelas vossas vidas.'),
(2400, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 17, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2401, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 18, 'OT', 'Farás também uma bacia de bronze com a sua base de bronze, para lavar; e a porás entre a tenda do encontro e o altar, e nela porás água.'),
(2402, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 19, 'OT', 'E Arão e seus filhos lavarão nele as suas mãos e os seus pés.'),
(2403, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 20, 'OT', 'Quando entrarem na tenda do encontro, lavar-se-ão com água, para que não morram; ou quando se aproximarem do altar para ministrar, para queimar oferta queimada ao SENHOR.'),
(2404, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 21, 'OT', 'Lavarão as suas mãos e os seus pés, para que não morram; e isto lhes será por estatuto perpétuo, a ele e à sua descendência, nas suas gerações.'),
(2405, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 22, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2406, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 23, 'OT', 'Toma para ti das especiarias mais finas: da mirra pura, quinhentos siclos; e de canela aromática, a metade, duzentos e cinquenta siclos; e de cálamo aromático, duzentos e cinquenta siclos.'),
(2407, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 24, 'OT', 'E de cássia, quinhentos siclos, segundo o siclo do santuário, e um him de azeite de oliveiras.'),
(2408, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 25, 'OT', 'Farás dele o óleo da unção sagrada, perfume composto segundo a obra do perfumista; será o óleo da unção sagrada.'),
(2409, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 26, 'OT', 'E com ele ungirás a tenda da congregação e a arca do testemunho.'),
(2410, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 27, 'OT', 'E a mesa com todos os seus utensílios, e o candelabro com os seus utensílios, e o altar do incenso.'),
(2411, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 28, 'OT', 'E o altar do holocausto com todos os seus utensílios, e a bacia com a sua base.'),
(2412, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 29, 'OT', 'Santificarás estas coisas, e elas serão santíssimas; tudo o que tocar nelas será santo.'),
(2413, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 30, 'OT', 'Ungirás também Arão e seus filhos, e os santificarás para me servirem como sacerdotes.'),
(2414, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 31, 'OT', 'Fala aos filhos de Israel, dizendo: Este será para mim o óleo da santa unção, nas vossas gerações.'),
(2415, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 32, 'OT', 'Não se derramará sobre carne humana, e não fareis outro semelhante conforme a sua composição; santo é, e santo será para vós.'),
(2416, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 33, 'OT', 'O homem que fizer como este, ou que puser dele sobre um estranho, será cortado do seu povo.'),
(2417, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 34, 'OT', 'Disse o SENHOR a Moisés: Toma para ti especiarias: estoraque, e onicha, e galbano; estas especiarias e incenso puro, em igual peso, serão.'),
(2418, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 35, 'OT', 'E disto farás incenso, perfume segundo a arte do perfumista, temperado, puro e santo.'),
(2419, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 36, 'OT', 'E moendo-a, reduzi-la-ás a pó fino, e dela porás diante do testemunho, na tenda da congregação, onde eu virei a ti; será coisa santíssima para vós.'),
(2420, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 37, 'OT', 'O incenso que fizeres segundo esta composição, não o fareis para vós mesmos; santo será para o SENHOR.'),
(2421, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 30, 38, 'OT', 'O homem que fizer como esta para cheirar será eliminado do seu povo.'),
(2422, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2423, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 2, 'OT', 'Eis que chamei pelo nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá.'),
(2424, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 3, 'OT', 'E o enchi do Espírito de Deus, de sabedoria, e de entendimento, e de conhecimento, em toda obra,'),
(2425, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 4, 'OT', 'Para inventar obras de arte, para trabalhar em ouro, em prata e em bronze.'),
(2426, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 5, 'OT', 'e em lavramento de pedras para engastar, e em lavor de madeira, para fazer toda obra.'),
(2427, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 6, 'OT', 'E eis que eu mesmo designei com ele Aoliabe, filho de Aquisamaque, da tribo de Dã; e ao coração de todo homem sábio de coração dei sabedoria, para que façam tudo o que te ordenei.'),
(2428, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 7, 'OT', 'A tenda do encontro, e a arca do testemunho, e o propiciatório que está sobre ela, e todos os utensílios da tenda.'),
(2429, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 8, 'OT', 'E a mesa com os seus utensílios, e o candelabro puro com todos os seus utensílios, e o altar do incenso;'),
(2430, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 9, 'OT', 'E o altar do holocausto com todos os seus utensílios, e a bacia com a sua base.'),
(2431, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 10, 'OT', 'E as vestes do serviço sagrado, e as vestes santas para Arão, o sacerdote, e as vestes de seus filhos, para ministrarem como sacerdotes.'),
(2432, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 11, 'OT', 'E o óleo da unção e o incenso aromático para o santuário: farão conforme tudo o que te ordenei.'),
(2433, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 12, 'OT', 'E disse o SENHOR a Moisés, dizendo:'),
(2434, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 13, 'OT', 'Fala tu aos filhos de Israel, dizendo: Certamente guardareis os meus sábados, pois isto é um sinal entre mim e vós, nas vossas gerações, para que saibais que eu sou o SENHOR que vos santifica.'),
(2435, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 14, 'OT', 'Guardareis o sábado, porque é santo para vós; aquele que o profanar certamente morrerá; pois qualquer que nele fizer alguma obra, essa alma será eliminada do meio do seu povo.'),
(2436, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 15, 'OT', 'Seis dias se fará trabalho, mas o sétimo dia é sábado de descanso solene, santo ao SENHOR; qualquer que fizer trabalho no dia do sábado certamente será morto.'),
(2437, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 16, 'OT', 'Guardarão, pois, os filhos de Israel o sábado, celebrando o sábado nas suas gerações por aliança eterna.'),
(2438, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 17, 'OT', 'Entre mim e os filhos de Israel será um sinal para sempre; porque em seis dias fez o SENHOR os céus e a terra, e ao sétimo dia descansou e respirou.'),
(2439, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 31, 18, 'OT', 'E deu a Moisés, quando acabou de falar com ele no monte Sinai, as duas tábuas do testemunho, tábuas de pedra, escritas pelo dedo de Deus.'),
(2440, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 1, 'OT', 'Vendo o povo que Moisés tardava em descer do monte, reuniu-se o povo contra Arão e lhe disse: Levanta-te, faze-nos deuses que vão adiante de nós, porque a este Moisés, o homem que nos tirou da terra do Egito, não sabemos o que lhe aconteceu.'),
(2441, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 2, 'OT', 'Disse-lhes Arão: Arrancai os pendentes de ouro que estão nas orelhas de vossas mulheres, de vossos filhos e de vossas filhas, e trazei-mos.'),
(2442, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 3, 'OT', 'Então todo o povo arrancou os brincos de ouro que estavam em suas orelhas e os trouxe a Arão.'),
(2443, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 4, 'OT', 'Ele os tomou das suas mãos, e o moldou com um cinzel, e fez dele um bezerro de fundição. Então disseram: Estes são os teus deuses, ó Israel, que te tiraram da terra do Egito.'),
(2444, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 5, 'OT', 'E Arão, vendo isso, edificou um altar diante dele; e Arão proclamou, dizendo: Amanhã será festa ao SENHOR.'),
(2445, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 6, 'OT', 'Levantaram-se cedo no dia seguinte, ofereceram holocaustos e trouxeram ofertas pacíficas; e o povo assentou-se para comer e beber, e levantou-se para se divertir.'),
(2446, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 7, 'OT', 'Então o SENHOR disse a Moisés: "Vai, desce, porque o teu povo, que fizeste subir da terra do Egito, se corrompeu.'),
(2447, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 8, 'OT', 'Depressa se desviaram do caminho que lhes ordenei; fizeram para si um bezerro fundido, e se prostraram diante dele, e lhe sacrificaram, e disseram: "Estes são os teus deuses, ó Israel, que te tiraram da terra do Egito."'),
(2448, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 9, 'OT', 'Disse o SENHOR a Moisés: Tenho visto este povo, e eis que é povo de dura cerviz.'),
(2449, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 10, 'OT', 'Agora, pois, deixa-me, e o meu furor se acenderá contra eles, e eu os consumirei; e farei de ti uma grande nação.'),
(2450, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 11, 'OT', 'Moisés suplicou ao SENHOR, seu Deus, e disse: Ó SENHOR, por que se acende a tua ira contra o teu povo, que tiraste da terra do Egito com grande poder e com mão forte?'),
(2451, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 12, 'OT', 'Por que os egípcios diriam: "Foi com maldade que ele os tirou, para matá-los nos montes e exterminá-los da face da terra"? Torna-te da tua ira ardente e arrepende-te deste mal contra o teu povo.'),
(2452, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 13, 'OT', 'Lembra-te de Abraão, de Isaque e de Israel, teus servos, aos quais juraste por ti mesmo e lhes disseste: Multiplicarei a vossa descendência como as estrelas do céu, e darei a vossa descendência toda esta terra, da qual falei, e eles a herdarão para sempre.'),
(2453, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 14, 'OT', 'Então o SENHOR se arrependeu do mal que dissera que faria ao seu povo.'),
(2454, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 15, 'OT', 'E virou-se Moisés e desceu do monte, com as duas tábuas do testemunho em sua mão; tábuas escritas de ambos os seus lados; de um lado e do outro estavam escritas.'),
(2455, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 16, 'OT', 'E as tábuas eram obra de Deus, e a escritura era escritura de Deus, gravada sobre as tábuas.'),
(2456, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 17, 'OT', 'Ouvindo Josué a voz do povo que gritava, disse a Moisés: Há som de guerra no acampamento.'),
(2457, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 18, 'OT', 'Não é voz de grito de vitória, nem voz de grito de derrota; mas voz de canto eu ouço.'),
(2458, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 19, 'OT', 'E aconteceu que, ao aproximar-se do acampamento, viu o bezerro e as danças; e acendeu-se a ira de Moisés, e ele lançou das suas mãos as tábuas, e as quebrou ao pé do monte.'),
(2459, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 20, 'OT', 'Tomou o bezerro que tinham feito, queimou-o no fogo, moeu-o até que se tornou pó, e o espalhou sobre as águas, e o deu a beber aos filhos de Israel.'),
(2460, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 21, 'OT', 'Moisés disse a Arão: "Que te fez este povo, que trouxeste sobre ele tão grande pecado?"'),
(2461, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 22, 'OT', 'Não se acenda a ira do meu senhor; tu sabes que este povo é inclinado ao mal.'),
(2462, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 23, 'OT', 'E eles me disseram: Faze-nos deuses que vão adiante de nós; porque não sabemos o que aconteceu a este Moisés, o homem que nos tirou da terra do Egito.'),
(2463, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 24, 'OT', 'Então eu lhes disse: Quem tem ouro, arranque-o. E eles o deram a mim, e eu o lancei no fogo, e saiu este bezerro.'),
(2464, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 25, 'OT', 'Vendo Moisés que o povo estava desenfreado, porque Arão os havia deixado sem freio, para vergonha diante dos seus adversários,'),
(2465, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 26, 'OT', 'Poz-se Moisés em pé na porta do arraial e disse: Quem é do SENHOR, venha a mim. E ajuntaram-se a ele todos os filhos de Levi.'),
(2466, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 27, 'OT', 'Assim diz o SENHOR, o Deus de Israel: Cada um ponha a sua espada sobre a coxa; passai e voltai de porta em porta pelo acampamento, e mate cada um o seu irmão, cada um o seu amigo e cada um o seu parente.'),
(2467, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 28, 'OT', 'E os filhos de Levi fizeram conforme a palavra de Moisés; e caíram do povo naquele dia cerca de três mil homens.'),
(2468, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 29, 'OT', 'Consagrem-se hoje ao SENHOR, pois cada um se opôs ao seu filho e ao seu irmão, para que ele lhes conceda hoje uma bênção.'),
(2469, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 30, 'OT', 'No dia seguinte, Moisés disse ao povo: Vós cometestes um grande pecado; agora, porém, subirei ao SENHOR; talvez possa fazer expiação pelo vosso pecado.'),
(2470, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 31, 'OT', 'Voltou Moisés ao SENHOR e disse: "Ah! Este povo cometeu um grande pecado, fazendo para si deuses de ouro."'),
(2471, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 32, 'OT', 'Agora, se perdoas o seu pecado, perdoa; mas, se não, risca-me, peço-te, do teu livro que escreveste.'),
(2472, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 33, 'OT', 'Então disse o SENHOR a Moisés: Aquele que pecou contra mim, a este riscarei do meu livro.'),
(2473, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 34, 'OT', 'Agora vai, conduze este povo para onde te falei; eis que o meu anjo irá adiante de ti; porém no dia da minha visitação, visitarei sobre eles o seu pecado.'),
(2474, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 32, 35, 'OT', 'E feriu o SENHOR o povo, porquanto fizeram o bezerro que Arão tinha feito.'),
(2475, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 1, 'OT', 'Falou o SENHOR a Moisés: Vai, sobe daqui, tu e o povo que fizeste subir da terra do Egito, para a terra que jurei a Abraão, a Isaque e a Jacó, dizendo: À tua descendência a darei.'),
(2476, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 2, 'OT', 'Enviarei um anjo diante de ti, e expulsarei os cananeus, os amorreus, os hititas, os perizeus, os heveus e os jebuseus.'),
(2477, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 3, 'OT', 'A uma terra que mana leite e mel, porque não subirei no meio de ti, pois és povo de dura cerviz, para que não te consuma no caminho.'),
(2478, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 4, 'OT', 'O povo ouviu esta palavra má e se entristeceu, e ninguém colocou sobre si os seus enfeites.'),
(2479, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 5, 'OT', 'Disse o SENHOR a Moisés: Dize aos filhos de Israel: Vós sois um povo de dura cerviz; se eu subir no meio de ti por um momento, te consumirei. Agora, pois, tira de ti os teus enfeites, para que eu saiba o que te hei de fazer.'),
(2480, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 6, 'OT', 'Então os filhos de Israel se despojaram dos seus enfeites, desde o monte Horebe.'),
(2481, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 7, 'OT', 'E Moisés tomava a tenda e a armava para si fora do acampamento, bem longe do acampamento, e chamava-a tenda do encontro; e todo aquele que buscava o SENHOR saía à tenda do encontro, que estava fora do acampamento.'),
(2482, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 8, 'OT', 'E acontecia que, saindo Moisés à tenda, todo o povo se levantava, e cada um ficava em pé à porta da sua tenda; e olhavam após Moisés, até que ele entrava na tenda.'),
(2483, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 9, 'OT', 'E acontecia que, ao entrar Moisés na tenda, a coluna de nuvem descia e se punha à entrada da tenda; e o SENHOR falava com Moisés.'),
(2484, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 10, 'OT', 'Todo o povo via a coluna de nuvem parada à entrada da tenda; então todo o povo se levantava e se curvava, cada um à entrada da sua tenda.'),
(2485, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 11, 'OT', 'E o SENHOR falava a Moisés face a face, como um homem fala com o seu amigo; e ele voltava ao acampamento, mas o seu servo Josué, filho de Num, jovem, não se apartava do meio da tenda.'),
(2486, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 12, 'OT', 'E Moisés disse ao SENHOR: Eis que tu me dizes: Faze subir este povo, mas não me fizeste saber a quem enviarás comigo; e tu disseste: Conheço-te por nome, e também achaste graça aos meus olhos.'),
(2487, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 13, 'OT', 'Agora, se encontrei favor aos teus olhos, rogo-te que me faças saber o teu caminho, para que eu te conheça e continue achando favor aos teus olhos; e considera que esta nação é o teu povo.'),
(2488, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 14, 'OT', 'A minha presença irá contigo, e eu te darei descanso.'),
(2489, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 15, 'OT', 'Se a tua presença não for conosco, não nos faças subir daqui.'),
(2490, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 16, 'OT', 'Como, pois, se saberá que achei graça aos teus olhos, eu e o teu povo? Não é por andares tu conosco, de modo que eu e o teu povo sejamos separados de todo o povo que há sobre a face da terra?'),
(2491, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 17, 'OT', 'Disse o SENHOR a Moisés: Farei também isto que disseste, porque achaste graça aos meus olhos, e te conheço por nome.'),
(2492, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 18, 'OT', 'Rogo-te que me mostres a tua glória.'),
(2493, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 19, 'OT', 'E ele disse: "Farei passar toda a minha bondade diante de ti, e proclamarei o nome do SENHOR diante de ti; e terei misericórdia de quem eu tiver misericórdia, e me compadecerei de quem eu me compadecer."'),
(2494, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 20, 'OT', 'Não poderás ver a minha face, pois nenhum homem me verá e viverá.'),
(2495, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 21, 'OT', 'Eis que há um lugar junto a mim; e tu ficarás sobre a rocha.'),
(2496, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 22, 'OT', 'E acontecerá que, quando a minha glória passar, eu te porei numa fenda da rocha, e te cobrirei com a minha mão, até que eu tenha passado.'),
(2497, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 33, 23, 'OT', 'E, havendo eu tirado a minha mão, verás as minhas costas; mas a minha face não se verá.'),
(2498, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 1, 'OT', 'Então disse o SENHOR a Moisés: Lavra-te duas tábuas de pedra, como as primeiras; e escreverei nas tábuas as palavras que estavam nas primeiras tábuas, que tu quebraste.'),
(2499, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 2, 'OT', 'Prepara-te para a manhã, e sobe pela manhã ao monte Sinai, e apresenta-te ali diante de mim no cume do monte.'),
(2500, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 3, 'OT', 'Ninguém subirá contigo, e também ninguém aparecerá em todo o monte; nem ovelhas nem bois pastarão diante daquele monte.'),
(2501, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 4, 'OT', 'Então Moisés lavrou duas tábuas de pedra, como as primeiras; e, levantando-se de manhã cedo, subiu ao monte Sinai, como o SENHOR lhe havia ordenado; e tomou nas suas mãos as duas tábuas de pedra.'),
(2502, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 5, 'OT', 'E o SENHOR desceu na nuvem e se pôs ali com ele, e proclamou o nome do SENHOR.'),
(2503, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 6, 'OT', 'E passou o SENHOR diante da sua face e clamou: SENHOR, SENHOR, Deus misericordioso e compassivo, tardio em irar-se e grande em benignidade e verdade.'),
(2504, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 7, 'OT', 'Que guarda a bondade para milhares, que perdoa a iniquidade, a transgressão e o pecado; mas não inocenta o culpado, que visita a iniquidade dos pais sobre os filhos e sobre os filhos dos filhos, até a terceira e quarta geração.'),
(2505, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 8, 'OT', 'Moisés apressou-se, inclinou-se à terra e adorou.'),
(2506, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 9, 'OT', 'E disse: Se agora achei graça aos teus olhos, ó Senhor, vá o Senhor no meio de nós; porque este é povo de dura cerviz; perdoa a nossa iniquidade e o nosso pecado, e toma-nos por tua herança.'),
(2507, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 10, 'OT', 'Então o SENHOR disse: Eis que eu faço uma aliança; diante de todo o teu povo farei maravilhas que nunca foram criadas em toda a terra, nem em todas as nações; e todo o povo em cujo meio tu estás verá a obra do SENHOR, porque terrível é o que eu farei contigo.'),
(2508, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 11, 'OT', 'Guarda o que hoje te ordeno: eis que expulsarei de diante de ti os amorreus, os cananeus, os hititas, os perizeus, os heveus e os jebuseus.'),
(2509, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 12, 'OT', 'Guarda-te de fazeres aliança com os moradores da terra onde vais entrar, para que não seja por laço no meio de ti.'),
(2510, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 13, 'OT', 'Pois derrubareis os seus altares, quebrareis as suas colunas sagradas e cortareis os seus postes de Aserá.'),
(2511, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 14, 'OT', 'Porque não te prostrarás diante de outro deus, pois o SENHOR, cujo nome é Zeloso, é Deus zeloso.'),
(2512, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 15, 'OT', 'Não faças aliança com os moradores da terra, para que eles não se prostituam após os seus deuses, nem sacrifiquem aos seus deuses, e te convidem, e comas dos seus sacrifícios.'),
(2513, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 16, 'OT', 'E tomarás das suas filhas para os teus filhos, e as suas filhas se prostituirão após os seus deuses, e farão que os teus filhos também se prostituam após os seus deuses.'),
(2514, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 17, 'OT', 'Não farás para ti deuses de metal fundido.'),
(2515, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 18, 'OT', 'Guardarás a festa dos pães sem fermento; sete dias comerás pães sem fermento, como te ordenei, no tempo determinado do mês de Abibe; porque no mês de Abibe saíste do Egito.'),
(2516, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 19, 'OT', 'Todo primogênito que abre o ventre é meu; e todo macho do teu rebanho, o primogênito de bois e de ovelhas.'),
(2517, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 20, 'OT', 'O primogênito do jumento resgatarás com um cordeiro; mas, se não o resgatares, quebrar-lhe-ás o pescoço. Todo primogênito de teus filhos resgatarás. E ninguém aparecerá diante de mim de mãos vazias.'),
(2518, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 21, 'OT', 'Seis dias trabalharás, mas no sétimo dia descansarás; no arado e na colheita descansarás.'),
(2519, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 22, 'OT', 'Celebrarás a festa das semanas, as primícias da colheita do trigo, e a festa da colheita na virada do ano.'),
(2520, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 23, 'OT', 'Três vezes ao ano, todo o seu homem aparecerá diante do SENHOR, JEHOVAH, Deus de Israel.'),
(2521, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 24, 'OT', 'Porque expulsarei as nações de diante de ti e alargarei as tuas fronteiras; ninguém cobiçará a tua terra, quando subires para aparecer diante do SENHOR, teu Deus, três vezes no ano.'),
(2522, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 25, 'OT', 'Não sacrificarás o sangue do meu sacrifício com pão levedado, nem o sacrifício da festa da Páscoa ficará da noite para a manhã.'),
(2523, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 26, 'OT', 'As primícias dos primeiros frutos da tua terra trarás à casa do SENHOR, teu Deus; não cozerás o cabrito no leite de sua mãe.'),
(2524, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 27, 'OT', 'Disse o SENHOR a Moisés: Escreve-te estas palavras, porque conforme estas palavras fiz aliança contigo e com Israel.'),
(2525, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 28, 'OT', 'E esteve ali com o SENHOR quarenta dias e quarenta noites; não comeu pão, nem bebeu água; e escreveu nas tábuas as palavras da aliança, os dez mandamentos.'),
(2526, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 29, 'OT', 'E aconteceu que, ao descer Moisés do monte Sinai, trazendo as duas tábuas do testemunho em sua mão, ao descer do monte, Moisés não sabia que a pele do seu rosto resplandecia por ter falado com ele.'),
(2527, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 30, 'OT', 'E Arão e todos os filhos de Israel viram Moisés, e eis que a pele do seu rosto resplandecia; e temeram de se aproximar dele.'),
(2528, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 31, 'OT', 'Então Moisés os chamou, e Arão e todos os líderes da congregação voltaram a ele; e Moisés lhes falou.'),
(2529, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 32, 'OT', 'Depois disso, todos os filhos de Israel se aproximaram, e ele lhes ordenou tudo o que o SENHOR havia falado com ele no monte Sinai.'),
(2530, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 33, 'OT', 'E terminou Moisés de falar com eles, e pôs um véu sobre o seu rosto.'),
(2531, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 34, 'OT', 'Quando Moisés entrava diante do SENHOR para falar com ele, retirava o véu até sair; e, ao sair, dizia aos filhos de Israel o que lhe era ordenado.'),
(2532, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 34, 35, 'OT', 'Os filhos de Israel viam o rosto de Moisés, pois a pele do seu rosto resplandecia; e Moisés tornava a pôr o véu sobre o rosto, até entrar para falar com ele.'),
(2533, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 1, 'OT', 'Moisés reuniu toda a congregação dos filhos de Israel e lhes disse: Estas são as palavras que o SENHOR ordenou que se fizessem.'),
(2534, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 2, 'OT', 'Seis dias se fará trabalho, mas o sétimo dia vos será santo, um sábado de descanso solene ao SENHOR; todo aquele que nele fizer trabalho será morto.'),
(2535, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 3, 'OT', 'Não acendereis fogo em nenhuma das vossas moradas no dia do sábado.'),
(2536, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 4, 'OT', 'E Moisés falou a toda a congregação dos filhos de Israel, dizendo: Esta é a palavra que o SENHOR ordenou, dizendo:'),
(2537, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 5, 'OT', 'Tomai de entre vós uma oferta para o SENHOR; todo aquele cujo coração for voluntário a trará como oferta ao SENHOR: ouro, prata e bronze.'),
(2538, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 6, 'OT', 'E azul, e púrpura, e carmesim, e linho fino, e pelos de cabras.'),
(2539, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 7, 'OT', 'E peles de carneiros tingidas de vermelho, peles de animais marinhos, e madeira de acácia.'),
(2540, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 8, 'OT', 'E azeite para a luminária, e especiarias para o óleo da unção, e para o incenso aromático.'),
(2541, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 9, 'OT', 'E pedras de ônix e pedras de engaste, para o éfode e para o peitoral.'),
(2542, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 10, 'OT', 'E todos os sábios de coração entre vós virão e farão tudo o que o SENHOR ordenou.'),
(2543, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 11, 'OT', 'O tabernáculo, a sua tenda e a sua coberta, os seus colchetes e as suas tábuas, os seus travessões, as suas colunas e as suas bases,'),
(2544, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 12, 'OT', 'A arca e os seus varais, o propiciatório e o véu da cortina.'),
(2545, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 13, 'OT', 'A mesa e os seus varais, e todos os seus utensílios; e o pão da presença.'),
(2546, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 14, 'OT', 'E o candelabro da luz, e os seus utensílios, e as suas lâmpadas, e o azeite para a luz.'),
(2547, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 15, 'OT', 'E o altar do incenso e os seus varais, e o óleo da unção, e o incenso aromático, e o véu da porta à entrada do tabernáculo.'),
(2548, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 16, 'OT', 'O altar do holocausto e a grelha de bronze que lhe pertence, os seus cabos e todos os seus utensílios, a bacia e a sua base.'),
(2549, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 17, 'OT', 'As cortinas do pátio, as suas colunas e as suas bases, e a cortina da porta do pátio,'),
(2550, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 18, 'OT', 'As estacas do tabernáculo, e as estacas do pátio, e as suas cordas.'),
(2551, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 19, 'OT', 'As vestes de serviço para ministrar no santuário, as vestes sagradas para Arão, o sacerdote, e as vestes de seus filhos, para oficiarem como sacerdotes.'),
(2552, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 20, 'OT', 'Então toda a congregação dos filhos de Israel saiu da presença de Moisés.'),
(2553, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 21, 'OT', 'E veio todo homem cujo coração o moveu, e todo aquele cujo espírito voluntariamente o excitou, e trouxeram a oferta ao SENHOR para a obra da tenda da congregação, e para todo o seu serviço, e para as vestes sagradas.'),
(2554, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 22, 'OT', 'Vieram homens e mulheres, todos os de coração generoso; trouxeram broches, pendentes, anéis e braceletes, todo tipo de joia de ouro; e cada homem que oferecia oferta de ouro ao SENHOR.'),
(2555, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 23, 'OT', 'E todo homem que se achou com fio azul, e púrpura, e carmesim, e linho fino, e pelos de cabra, e peles de carneiro tingidas de vermelho, e peles de animais marinhos, os trouxe.'),
(2556, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 24, 'OT', 'Todo aquele que oferecia oferta de prata ou de bronze a trazia como oferta ao SENHOR; e todo aquele que tinha consigo madeira de acácia para qualquer obra do serviço, a trazia.'),
(2557, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 25, 'OT', 'E todas as mulheres sábias de coração fiavam com as suas mãos, e traziam o fio fiado: o azul, a púrpura, o carmesim e o linho fino.'),
(2558, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 26, 'OT', 'E todas as mulheres cujo coração as moveu em sabedoria fiavam os pelos das cabras.'),
(2559, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 27, 'OT', 'E os líderes trouxeram as pedras de ônix e as pedras de engaste, para o éfode e para o peitoral.'),
(2560, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 28, 'OT', 'E as especiarias, e o azeite para a luz, e para o azeite da unção, e para o incenso aromático.'),
(2561, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 29, 'OT', 'Todo homem e mulher cujo coração voluntariamente se moveu a trazer algo para toda a obra que o SENHOR ordenara fazer por meio de Moisés, esses trouxeram os filhos de Israel como oferta voluntária ao SENHOR.'),
(2562, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 30, 'OT', 'E disse Moisés aos filhos de Israel: Vede, o SENHOR chamou pelo nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá.'),
(2563, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 31, 'OT', 'E o encheu do Espírito de Deus, em sabedoria, em entendimento e em conhecimento, e em toda obra.'),
(2564, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 32, 'OT', 'E para elaborar desenhos artísticos, para trabalhar em ouro, em prata e em bronze,'),
(2565, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 33, 'OT', 'e em lavramento de pedras para engastar, e em lavramento de madeira, para fazer toda obra engenhosa.'),
(2566, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 34, 'OT', 'E para ensinar, pôs em seu coração, ele e Aoliabe, filho de Aisamaque, da tribo de Dã.'),
(2567, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 35, 35, 'OT', 'Encheu-os de sabedoria do coração, para fazer toda a obra de artífice, e de desenhista, e de bordador em azul, e em púrpura, em carmesim, e em linho fino, e de tecelão; fazendo toda a obra e inventando invenções.'),
(2568, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 1, 'OT', 'Fez, pois, Bezalel e Aoliabe, e todo homem sábio de coração, a quem o SENHOR deu sabedoria e entendimento, para saberem fazer toda a obra do serviço do santuário, conforme tudo o que o SENHOR havia ordenado.'),
(2569, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 2, 'OT', 'Moisés chamou Bezalel, Aoliabe e todos os homens sábios de coração, em cujo coração o SENHOR tinha dado sabedoria, todo aquele cujo coração o impeliu a se aproximar da obra para fazê-la.'),
(2570, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 3, 'OT', 'E tomaram de diante de Moisés toda a oferta que os filhos de Israel haviam trazido para a obra do serviço do santuário, para fazê-la; e ainda lhe traziam oferta voluntária, manhã após manhã.'),
(2571, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 4, 'OT', 'E vieram todos os sábios que faziam toda a obra do santuário, cada um da sua obra que estavam fazendo.'),
(2572, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 5, 'OT', 'E falaram a Moisés, dizendo: O povo traz muito mais do que é necessário para a obra que o SENHOR ordenou fazer.'),
(2573, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 6, 'OT', 'Então Moisés ordenou, e fizeram passar uma voz pelo acampamento, dizendo: Nenhum homem nem mulher faça mais obra alguma para a oferta do santuário. Assim o povo foi impedido de trazer mais.'),
(2574, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 7, 'OT', 'E a obra era suficiente para toda a obra que se havia de fazer, e ainda sobrava.'),
(2575, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 8, 'OT', 'Todos os sábios de coração entre os que faziam a obra fizeram o tabernáculo com dez cortinas de linho fino torcido, e de azul, e de púrpura, e de carmesim, com querubins; obra de artífice as fizeram.'),
(2576, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 9, 'OT', 'O comprimento de uma cortina era de vinte e oito côvados, e a largura de uma cortina era de quatro côvados; todas as cortinas tinham a mesma medida.'),
(2577, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 10, 'OT', 'E uniu as cinco cortinas uma à outra; e as outras cinco cortinas uniu uma à outra.'),
(2578, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 11, 'OT', 'Fez laçadas de azul na borda da cortina, na extremidade, na juntura; assim também fez na borda da cortina que estava na extremidade da segunda juntura.'),
(2579, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 12, 'OT', 'Cinquenta laçadas fez numa cortina, e cinquenta laçadas fez na extremidade da cortina que se ligava com a segunda; as laçadas correspondiam uma à outra.'),
(2580, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 13, 'OT', 'Fez também cinquenta colchetes de ouro e uniu as cortinas uma à outra com os colchetes; e o tabernáculo tornou-se um só.'),
(2581, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 14, 'OT', 'Fez também cortinas de pelos de cabra para a tenda sobre o tabernáculo; de onze cortinas as fez.'),
(2582, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 15, 'OT', 'O comprimento de uma cortina era de trinta côvados, e a largura de uma cortina era de quatro côvados; todas as onze cortinas tinham a mesma medida.'),
(2583, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 16, 'OT', 'E uniu as cinco cortinas à parte, e as seis cortinas à parte.'),
(2584, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 17, 'OT', 'Fez cinquenta laçadas na borda da cortina exterior, na junção, e fez cinquenta laçadas na borda da cortina da segunda junção.'),
(2585, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 18, 'OT', 'Fez também cinquenta colchetes de bronze, para unir a tenda, a fim de que viesse a ser uma só.'),
(2586, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 19, 'OT', 'Fez também para a tenda uma coberta de peles de carneiros tingidas de vermelho, e por cima uma coberta de peles de animais marinhos.'),
(2587, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 20, 'OT', 'Fez também as tábuas para o tabernáculo, de madeira de acácia, em pé.'),
(2588, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 21, 'OT', 'Dez côvados o comprimento de cada tábua, e um côvado e meio a largura de cada tábua.'),
(2589, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 22, 'OT', 'Duas mãos para cada armação, unidas uma à outra; assim fez para todas as armações do tabernáculo.'),
(2590, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 23, 'OT', 'Fez também as tábuas para o tabernáculo: vinte tábuas para o lado sul, ao meio-dia.'),
(2591, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 24, 'OT', 'E quarenta bases de prata fez debaixo das vinte tábuas: duas bases debaixo de uma tábua para os seus dois encaixes, e duas bases debaixo de outra tábua para os seus dois encaixes.'),
(2592, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 25, 'OT', 'Também para o segundo lado do tabernáculo, o lado norte, fez vinte tábuas.'),
(2593, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 26, 'OT', 'E as suas quarenta bases de prata: duas bases debaixo de uma armação, e duas bases debaixo de outra armação.'),
(2594, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 27, 'OT', 'E para as extremidades do tabernáculo, ao ocidente, fez seis tábuas.'),
(2595, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 28, 'OT', 'Fez também duas tábuas para os cantos do tabernáculo, nos dois lados.'),
(2596, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 29, 'OT', 'Eram parelhas desde a parte inferior e juntas se uniam até o topo, junto à primeira argola; assim fez com ambas, nos dois cantos.'),
(2597, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 30, 'OT', 'Eram oito tábuas, e as suas bases de prata eram dezesseis bases: duas bases debaixo de cada tábua.'),
(2598, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 31, 'OT', 'Fez também travessões de madeira de acácia: cinco para as armações de um lado do tabernáculo.'),
(2599, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 32, 'OT', 'E cinco travessões para as armações do lado segundo do tabernáculo, e cinco travessões para as armações do tabernáculo, do lado do oeste, na parte posterior.'),
(2600, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 33, 'OT', 'E fez a barra do meio para passar pelo meio das tábuas, de uma extremidade à outra.'),
(2601, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 34, 'OT', 'E cobriu as tábuas de ouro, e fez de ouro as suas argolas como suportes para os travessões; e revestiu os travessões de ouro.'),
(2602, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 35, 'OT', 'Fez também o véu de azul, púrpura, carmesim e linho fino torcido; obra de artífice o fez com querubins.'),
(2603, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 36, 'OT', 'Fez-lhe quatro colunas de madeira de acácia, e as revestiu de ouro; e seus ganchos fez de ouro, e fundiu-lhes quatro bases de prata.'),
(2604, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 37, 'OT', 'Fez também uma cortina para a entrada da tenda, de azul, púrpura, carmesim e linho fino torcido, obra de bordador.'),
(2605, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 36, 38, 'OT', 'E as suas cinco colunas e os seus colchetes; e as suas cabeças e as suas molduras cobriu de ouro; e as suas cinco bases eram de bronze.'),
(2606, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 1, 'OT', 'Fez também Bezalel a arca de madeira de acácia; o seu comprimento era de dois côvados e meio, e a sua largura de um côvado e meio, e a sua altura de um côvado e meio.'),
(2607, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 2, 'OT', 'E cobriu-a de ouro puro por dentro e por fora, e fez-lhe uma moldura de ouro ao redor.'),
(2608, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 3, 'OT', 'E fundiu para ele quatro argolas de ouro nos seus quatro cantos: duas argolas num lado e duas argolas no outro lado.'),
(2609, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 4, 'OT', 'E fez varais de madeira de acácia e os cobriu de ouro.'),
(2610, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 5, 'OT', 'E introduziu os varais nas argolas, aos lados da arca, para levar a arca.'),
(2611, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 6, 'OT', 'Fez também o propiciatório de ouro puro: o seu comprimento era de dois côvados e meio, e a sua largura de um côvado e meio.'),
(2612, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 7, 'OT', 'Fez dois querubins de ouro; de obra batida os fez, nas duas extremidades do propiciatório.'),
(2613, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 8, 'OT', 'Um querubim numa extremidade, e um querubim na outra extremidade; da tampa do propiciatório fez os querubins nas duas extremidades dela.'),
(2614, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 9, 'OT', 'E os querubins estendiam as asas para cima, cobrindo com elas o propiciatório; e os seus rostos estavam um de frente para o outro; os rostos dos querubins estavam voltados para o propiciatório.'),
(2615, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 10, 'OT', 'Fez a mesa de madeira de acácia; o seu comprimento era de dois côvados, e a sua largura, de um côvado, e a sua altura, de um côvado e meio.'),
(2616, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 11, 'OT', 'E cobriu-a de ouro puro e fez-lhe uma moldura de ouro ao redor.'),
(2617, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 12, 'OT', 'Fez-lhe uma moldura da largura de um palmo ao redor, e fez uma coroa de ouro ao redor da sua moldura.'),
(2618, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 13, 'OT', 'Fundiu-lhe quatro argolas de ouro e pôs as argolas nos quatro cantos que estavam nos seus quatro pés.'),
(2619, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 14, 'OT', 'Defronte da moldura estavam as argolas, como suportes para os varais, para levar a mesa.'),
(2620, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 15, 'OT', 'Fez também as varas de madeira de acácia e as cobriu de ouro, para levar a mesa.'),
(2621, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 16, 'OT', 'E fez os utensílios que estavam sobre a mesa: os seus pratos, as suas colheres, as suas tigelas e os seus cântaros, com que se faziam as libações, de ouro puro.'),
(2622, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 17, 'OT', 'Fez o candelabro de ouro puro; de obra batida fez o candelabro: a sua base e a sua haste, os seus copos, as suas maçãs e as suas flores eram todos de uma só peça com ele.'),
(2623, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 18, 'OT', 'E seis braços saíam dos seus lados: três braços do candelabro de um lado, e três braços do candelabro do outro lado.'),
(2624, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 19, 'OT', 'Em um ramo havia três cálices em forma de flor de amêndoa, com um botão e uma flor; e em outro ramo, três cálices em forma de flor de amêndoa, com um botão e uma flor; assim se fez para os seis ramos que saíam do candelabro.'),
(2625, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 20, 'OT', 'E no candelabro havia quatro cálices em forma de flor de amendoeira, com seus botões e suas flores.'),
(2626, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 21, 'OT', 'E havia um botão debaixo de cada par de hastes que saíam dela, e um botão debaixo de cada par de hastes que saíam dela, e um botão debaixo de cada par de hastes que saíam dela, para as seis hastes que saíam dela.'),
(2627, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 22, 'OT', 'Os seus botões e os seus ramos eram da mesma peça; tudo era uma só obra batida de ouro puro.'),
(2628, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 23, 'OT', 'Fez-lhe sete lâmpadas; os seus espevitadores e os seus apagadores eram de ouro puro.'),
(2629, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 24, 'OT', 'De um talento de ouro puro a fez, e todos os seus utensílios.'),
(2630, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 25, 'OT', 'Fez também o altar do incenso de madeira de acácia; de um côvado era o seu comprimento, e de um côvado a sua largura, quadrado; e de dois côvados a sua altura; dele mesmo eram as suas pontas.'),
(2631, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 26, 'OT', 'E cobriu-o de ouro puro: o seu tampo, as suas paredes ao redor e as suas pontas; e fez-lhe uma moldura de ouro ao redor.'),
(2632, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 27, 'OT', 'Fez-lhe duas argolas de ouro debaixo da sua moldura, nos seus dois lados, nos dois cantos, como suportes para os varais, para com eles carregar a mesa.'),
(2633, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 28, 'OT', 'E fez as varas de madeira de acácia e as revestiu de ouro.'),
(2634, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 37, 29, 'OT', 'Fez também o óleo sagrado da unção e o incenso aromático puro, obra de perfumista.'),
(2635, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 1, 'OT', 'Fez também o altar do holocausto de madeira de acácia; de cinco côvados era o seu comprimento, e de cinco côvados a sua largura, quadrado; e de três côvados a sua altura.'),
(2636, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 2, 'OT', 'E fez os seus chifres nos seus quatro cantos; os chifres eram da mesma peça; e revestiu-o de bronze.'),
(2637, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 3, 'OT', 'Fez também todos os utensílios do altar: os caldeirões, as pás, as bacias, os garfos e os braseiros; todos os seus utensílios fez de bronze.'),
(2638, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 4, 'OT', 'Fez também para o altar uma grelha de bronze, em forma de rede, debaixo da sua borda, desde a parte inferior até o meio dele.'),
(2639, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 5, 'OT', 'E fundiu quatro argolas nas quatro extremidades da grelha de bronze, como suportes para os varais.'),
(2640, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 6, 'OT', 'E fez os varais de madeira de acácia e os revestiu de bronze.'),
(2641, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 7, 'OT', 'E introduziu os varais nas argolas, aos lados do altar, para levá-lo com eles; fê-lo oco de tábuas.'),
(2642, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 8, 'OT', 'Fez também a bacia de bronze e a sua base de bronze, dos espelhos das mulheres que se reuniam em serviço à entrada da tenda do encontro.'),
(2643, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 9, 'OT', 'Fez também o átrio do lado sul, para o sul: as cortinas do átrio eram de linho fino torcido, de cem côvados.'),
(2644, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 10, 'OT', 'As suas vinte colunas e as suas vinte bases eram de bronze; os ganchos das colunas e as suas faixas eram de prata.'),
(2645, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 11, 'OT', 'E do lado norte, cem côvados; as suas vinte colunas e as suas vinte bases eram de bronze; os colchetes das colunas e as suas molduras eram de prata.'),
(2646, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 12, 'OT', 'E do lado do ocidente, cortinas de cinquenta côvados; as suas colunas, dez, e as suas bases, dez; os colchetes das colunas e as suas molduras eram de prata.'),
(2647, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 13, 'OT', 'E para o lado oriental, para o nascente, cinquenta côvados.'),
(2648, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 14, 'OT', 'As cortinas de um lado da entrada tinham quinze côvados: as suas colunas eram três, e as suas bases, três.'),
(2649, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 15, 'OT', 'E para o segundo lado, de um e de outro lado da porta do pátio, havia cortinas de quinze côvados; as suas colunas eram três, e as suas bases, três.'),
(2650, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 16, 'OT', 'Todas as cortinas do pátio ao redor eram de linho fino torcido.'),
(2651, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 17, 'OT', 'As bases das colunas eram de bronze; os ganchos das colunas e suas faixas eram de prata, e o revestimento dos seus capitéis era de prata; e todas as colunas do pátio eram cingidas de prata.'),
(2652, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 18, 'OT', 'A cortina da porta do pátio era obra de bordador, de azul, púrpura, carmesim e linho fino torcido; o comprimento era de vinte côvados, e a altura, na largura, de cinco côvados, correspondendo às cortinas do pátio.'),
(2653, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 19, 'OT', 'As suas quatro colunas e as suas quatro bases eram de bronze; os seus ganchos eram de prata, e o revestimento dos seus capitéis e as suas molduras eram de prata.'),
(2654, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 20, 'OT', 'E todas as estacas do tabernáculo e do pátio, ao redor, eram de bronze.'),
(2655, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 21, 'OT', 'Estas são as coisas contadas do tabernáculo, o tabernáculo do testemunho, que foram contadas por ordem de Moisés, para o serviço dos levitas, pela mão de Itamar, filho de Arão, o sacerdote.'),
(2656, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 22, 'OT', 'E Bezalel, filho de Uri, filho de Hur, da tribo de Judá, fez tudo o que o SENHOR ordenou a Moisés.'),
(2657, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 23, 'OT', 'E com ele Aoliabe, filho de Aisamaque, da tribo de Dã, artífice e desenhista, e bordador em azul, em púrpura, em carmesim e em linho fino.'),
(2658, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 24, 'OT', 'Todo o ouro empregado na obra, em toda a obra do santuário, a saber, o ouro da oferta movida, foi vinte e nove talentos e setecentos e trinta siclos, conforme o siclo do santuário.'),
(2659, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 25, 'OT', 'E a prata dos contados da congregação foi cem talentos e mil e setecentos e setenta e cinco siclos, conforme o siclo do santuário.'),
(2660, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 26, 'OT', 'Um beca por cabeça, isto é, meio siclo, conforme o siclo do santuário, para todo aquele que passava ao rol dos contados, de vinte anos para cima: seiscentos e três mil e quinhentos e cinquenta.'),
(2661, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 27, 'OT', 'E houve cem talentos de prata para fundir as bases do santuário e as bases do véu: cem talentos para cem bases, um talento para cada base.'),
(2662, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 28, 'OT', 'E dos mil setecentos e setenta e cinco siclos fez ganchos para as colunas, e revestiu os seus capitéis, e os cingiu com filetes.'),
(2663, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 29, 'OT', 'E o bronze da oferta movida foi setenta talentos e dois mil e quatrocentos siclos.'),
(2664, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 30, 'OT', 'E dela fez as bases da entrada da tenda do encontro, o altar de bronze, a grelha de bronze que lhe pertencia e todos os utensílios do altar.'),
(2665, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 38, 31, 'OT', 'E as bases do pátio ao redor, e as bases da porta do pátio, e todas as estacas do tabernáculo, e todas as estacas do pátio ao redor.'),
(2666, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 1, 'OT', 'E do azul, e da púrpura, e do carmesim fizeram as vestes de ministério para ministrar no santuário; e fizeram as vestes sagradas para Arão, como o SENHOR ordenara a Moisés.'),
(2667, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 2, 'OT', 'Fez o éfode de ouro, de fios de azul, e de púrpura, e de carmesim, e de linho fino torcido.'),
(2668, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 3, 'OT', 'Bateram o ouro em lâminas e o cortaram em fios, para entretecer no azul, na púrpura, no carmesim e no linho fino, em obra esmerada.'),
(2669, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 4, 'OT', 'Fizeram-lhe ombreiras que se uniam; nas suas duas extremidades era unido.'),
(2670, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 5, 'OT', 'E o cinto do éfode, que estava sobre ele, era da mesma obra, de ouro, de azul, de púrpura, de carmesim e de linho fino torcido, como o SENHOR ordenara a Moisés.'),
(2671, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 6, 'OT', 'Fizeram também as pedras de ônix, engastadas em filigranas de ouro, lavradas com gravuras de selo, com os nomes dos filhos de Israel.'),
(2672, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 7, 'OT', 'E as pôs sobre as ombreiras do éfode como pedras de memorial para os filhos de Israel, conforme o SENHOR havia ordenado a Moisés.'),
(2673, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 8, 'OT', 'Fez também o peitoral de obra de artífice, como a obra do éfode: de ouro, de azul, e de púrpura, e de carmesim, e de linho fino torcido.'),
(2674, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 9, 'OT', 'Quadrado era; dobrado fizeram o peitoral: o seu comprimento era de um palmo, e a sua largura de um palmo dobrado.'),
(2675, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 10, 'OT', 'E encheram-no com quatro fileiras de pedras: uma fileira de sárdio, topázio e esmeralda; esta era a primeira fileira.'),
(2676, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 11, 'OT', 'E a segunda fileira: um carbúnculo, uma safira e um jaspe.'),
(2677, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 12, 'OT', 'E a terceira fileira: um lésem, um shevô e um ágata.'),
(2678, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 13, 'OT', 'E a quarta fileira era de berilo, ônix e jaspe, engastados em filigranas de ouro nos seus encaixes.'),
(2679, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 14, 'OT', 'E as pedras eram conforme os nomes dos filhos de Israel, doze conforme os seus nomes; gravadas como selos, cada uma com o seu nome, para as doze tribos.'),
(2680, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 15, 'OT', 'Fizeram sobre o peitoral correntes trançadas, obra de cordas, de ouro puro.'),
(2681, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 16, 'OT', 'Fizeram dois engastes de ouro e duas argolas de ouro, e puseram as duas argolas nas duas extremidades do peitoral.'),
(2682, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 17, 'OT', 'E puseram as duas correntes de ouro nas duas argolas, nas extremidades do peitoral.'),
(2683, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 18, 'OT', 'E as duas pontas das duas correntes entrelaçadas puseram sobre os dois engastes, e as colocaram sobre as ombreiras do éfode, em frente à sua frente.'),
(2684, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 19, 'OT', 'Fizeram duas argolas de ouro e as puseram nas duas extremidades do peitoral, na sua borda que estava junto ao éfode, por dentro.'),
(2685, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 20, 'OT', 'Fizeram também duas argolas de ouro e as puseram nas duas ombreiras do éfode, por baixo, na frente dele, junto à sua costura, acima do cinto de obra bordada do éfode.'),
(2686, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 21, 'OT', 'E ligaram o peitoral pelas suas argolas às argolas do éfode com um cordão de azul, para que ficasse sobre o cinto do éfode, e o peitoral não se desprendesse do éfode, como o SENHOR havia ordenado a Moisés.'),
(2687, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 22, 'OT', 'E fez o manto do éfode, obra de tecelão, todo de azul.'),
(2688, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 23, 'OT', 'E a abertura do manto estava no seu meio, como a abertura de uma cota de malha; havia uma borda ao redor da sua abertura, para que não se rompesse.'),
(2689, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 24, 'OT', 'Fizeram nas bordas do manto romãs de azul, de púrpura e de carmesim, em fio torcido.'),
(2690, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 25, 'OT', 'Fizeram campainhas de ouro puro e as puseram no meio das romãs, na borda do manto, ao redor, entre as romãs.'),
(2691, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 26, 'OT', 'Uma campainha e uma romã, outra campainha e outra romã, ao redor da borda do manto, para ministrar, como o SENHOR ordenou a Moisés.'),
(2692, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 27, 'OT', 'Fizeram as túnicas de linho fino, obra de tecelão, para Arão e para seus filhos.'),
(2693, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 28, 'OT', 'E o turbante de linho fino, e o ornato das tiaras de linho fino, e os calções de linho fino torcido.'),
(2694, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 29, 'OT', 'E o cinto de linho fino torcido, e de azul, e de púrpura, e de carmesim, obra de bordador, como o SENHOR ordenara a Moisés.'),
(2695, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 30, 'OT', 'Fizeram a lâmina da coroa sagrada de ouro puro, e nela escreveram uma inscrição como a gravação de um selo: "Santo ao SENHOR".'),
(2696, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 31, 'OT', 'E ataram-no com um cordão azul, para o pôr sobre a mitra, no alto, como o SENHOR havia ordenado a Moisés.'),
(2697, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 32, 'OT', 'Assim se acabou toda a obra do tabernáculo da tenda da congregação; e os filhos de Israel fizeram conforme tudo o que o SENHOR ordenara a Moisés; assim o fizeram.'),
(2698, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 33, 'OT', 'Trouxeram a Moisés o tabernáculo, a tenda e todos os seus utensílios: os seus colchetes, as suas tábuas, os seus travessões, as suas colunas e as suas bases.'),
(2699, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 34, 'OT', 'e a coberta de peles de carneiro tingidas de vermelho, e a coberta de peles de animais marinhos, e o véu do reposteiro.'),
(2700, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 35, 'OT', 'A arca do testemunho, e os seus varais, e o propiciatório.'),
(2701, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 36, 'OT', 'A mesa com todos os seus utensílios, e o pão da presença.'),
(2702, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 37, 'OT', 'O candelabro puro, com suas lâmpadas, as lâmpadas da disposição, e todos os seus utensílios, e o azeite para a iluminação.'),
(2703, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 38, 'OT', 'e o altar de ouro, e o óleo da unção, e o incenso aromático, e o véu da entrada da tenda.'),
(2704, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 39, 'OT', 'o altar de bronze e a sua grelha de bronze, os seus cabos e todos os seus utensílios, a bacia e a sua base;'),
(2705, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 40, 'OT', 'As cortinas do átrio, as suas colunas e as suas bases, e a cortina da entrada do átrio, as suas cordas e as suas estacas, e todos os utensílios do serviço do tabernáculo, para a tenda da congregação.'),
(2706, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 41, 'OT', 'As vestes finamente tecidas para ministrar no santuário, as vestes sagradas para Arão, o sacerdote, e as vestes de seus filhos, para oficiarem como sacerdotes.'),
(2707, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 42, 'OT', 'Conforme tudo o que o SENHOR ordenou a Moisés, assim fizeram os filhos de Israel toda a obra.'),
(2708, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 39, 43, 'OT', 'Moisés viu toda a obra, e eis que a tinham feito; como o SENHOR havia ordenado, assim a fizeram; então Moisés os abençoou.'),
(2709, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2710, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 2, 'OT', 'No primeiro dia do primeiro mês, levantarás o tabernáculo da tenda do encontro.'),
(2711, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 3, 'OT', 'E porás ali a arca do testemunho, e cobrirás a arca com o véu.'),
(2712, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 4, 'OT', 'Trarás a mesa e disporás o que se deve dispor sobre ela; trarás também o candelabro e acenderás as suas lâmpadas.'),
(2713, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 5, 'OT', 'E porás o altar de ouro para o incenso diante da arca do testemunho, e porás o véu da porta do tabernáculo.'),
(2714, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 6, 'OT', 'E porás o altar do holocausto diante da entrada do tabernáculo da tenda da congregação.'),
(2715, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 7, 'OT', 'E porás a bacia entre a tenda do encontro e o altar, e nela porás água.'),
(2716, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 8, 'OT', 'E armarás o pátio ao redor, e colocarás a cortina da porta do pátio.'),
(2717, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 9, 'OT', 'Tomarás o óleo da unção e ungirás o tabernáculo e tudo o que nele há; e o santificarás com todos os seus utensílios, e será santo.'),
(2718, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 10, 'OT', 'Ungirás o altar do holocausto e todos os seus utensílios; e santificarás o altar, e o altar será santíssimo.'),
(2719, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 11, 'OT', 'Ungirás a bacia e a sua base, e a santificarás.'),
(2720, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 12, 'OT', 'Farás chegar Arão e seus filhos à entrada da tenda do encontro, e os lavarás com água.'),
(2721, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 13, 'OT', 'Vestirás Arão com as vestes sagradas, e o ungirás, e o santificarás, para que me sirva como sacerdote.'),
(2722, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 14, 'OT', 'Farás também chegar os seus filhos e lhes vestirás as túnicas.'),
(2723, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 15, 'OT', 'E ungirás a eles como ungiste a seu pai, para que me sirvam como sacerdotes; e a sua unção lhes será por sacerdócio perpétuo nas suas gerações.'),
(2724, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 16, 'OT', 'E fez Moisés conforme tudo o que o SENHOR lhe ordenou; assim o fez.'),
(2725, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 17, 'OT', 'E aconteceu no primeiro mês, no segundo ano, no primeiro dia do mês, que o tabernáculo foi levantado.'),
(2726, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 18, 'OT', 'Moisés levantou o tabernáculo, pôs as suas bases, colocou as suas tábuas, fixou os seus travessões e ergueu as suas colunas.'),
(2727, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 19, 'OT', 'Estendeu a tenda sobre o tabernáculo e pôs a cobertura da tenda sobre ele, por cima, como o SENHOR havia ordenado a Moisés.'),
(2728, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 20, 'OT', 'Tomou o testemunho e o colocou na arca, pôs os varais sobre a arca e pôs o propiciatório sobre a arca, em cima.'),
(2729, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 21, 'OT', 'Trouxe a arca para dentro do tabernáculo, pendurou o véu da cobertura e cobriu a arca do testemunho, assim como o SENHOR havia ordenado a Moisés.'),
(2730, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 22, 'OT', 'E pôs a mesa na tenda do encontro, ao lado do tabernáculo, para o norte, fora do véu.'),
(2731, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 23, 'OT', 'E sobre ele pôs em ordem o pão perante o SENHOR, como o SENHOR havia ordenado a Moisés.'),
(2732, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 24, 'OT', 'Pôs o candelabro na tenda do encontro, defronte da mesa, ao lado do tabernáculo, para o sul.'),
(2733, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 25, 'OT', 'E acendeu as lâmpadas diante do SENHOR, como o SENHOR havia ordenado a Moisés.'),
(2734, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 26, 'OT', 'E pôs o altar de ouro na tenda da congregação, diante do véu.'),
(2735, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 27, 'OT', 'E acendeu sobre ele incenso de especiarias aromáticas, como o SENHOR havia ordenado a Moisés.'),
(2736, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 28, 'OT', 'Pôs a cortina da entrada do tabernáculo.'),
(2737, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 29, 'OT', 'E pôs o altar do holocausto à entrada do tabernáculo da tenda da congregação, e ofereceu sobre ele o holocausto e a oferta de manjares, como o SENHOR havia ordenado a Moisés.'),
(2738, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 30, 'OT', 'E pôs a bacia entre a tenda da congregação e o altar, e colocou ali água para lavar.'),
(2739, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 31, 'OT', 'E Moisés e Arão e seus filhos lavavam nela as suas mãos e os seus pés.'),
(2740, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 32, 'OT', 'Quando entravam na tenda da congregação e se aproximavam do altar, lavavam-se, conforme o SENHOR havia ordenado a Moisés.'),
(2741, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 33, 'OT', 'Levantou o pátio ao redor do tabernáculo e do altar, e pendurou a cortina da porta do pátio. Assim Moisés acabou a obra.'),
(2742, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 34, 'OT', 'A nuvem cobriu a tenda do encontro, e a glória do SENHOR encheu o tabernáculo.'),
(2743, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 35, 'OT', 'E Moisés não podia entrar na tenda do encontro, porque a nuvem permanecia sobre ela, e a glória do SENHOR enchia o tabernáculo.'),
(2744, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 36, 'OT', 'Quando a nuvem se levantava de sobre o tabernáculo, os filhos de Israel partiam em todas as suas jornadas.'),
(2745, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 37, 'OT', 'Porém, se a nuvem não se levantava, não partiam, até o dia em que ela se levantava.'),
(2746, 2, 'GOI_Pt', 'GOI_Pt', 'pt', 'EXO', 40, 38, 'OT', 'Porque a nuvem do SENHOR estava sobre o tabernáculo de dia, e fogo havia de noite sobre ele, perante os olhos de toda a casa de Israel, em todas as suas jornadas.'),
(2747, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 1, 'OT', 'E chamou o SENHOR a Moisés, e falou com ele da tenda da congregação, dizendo:'),
(2748, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: Quando algum de vós trouxer uma oferta ao SENHOR, trareis a vossa oferta do gado, do rebanho e do gado miúdo.'),
(2749, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 3, 'OT', 'Se a sua oferta for holocausto de gado, oferecerá macho sem defeito; à entrada da tenda da congregação o oferecerá, para que seja aceito diante do SENHOR.'),
(2750, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 4, 'OT', 'E porá a sua mão sobre a cabeça do holocausto, e será aceito por ele, para fazer expiação por ele.'),
(2751, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 5, 'OT', 'Degolará o bezerro perante o SENHOR; e os filhos de Arão, os sacerdotes, oferecerão o sangue e o aspergirão ao redor sobre o altar que está à entrada da tenda do encontro.'),
(2752, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 6, 'OT', 'E esfolará o holocausto, e o partirá em seus pedaços.'),
(2753, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 7, 'OT', 'Os filhos de Arão, o sacerdote, porão fogo sobre o altar e disporão a lenha sobre o fogo.'),
(2754, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 8, 'OT', 'Os filhos de Arão, os sacerdotes, disporão os pedaços, a cabeça e a gordura sobre a lenha que está no fogo sobre o altar.'),
(2755, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 9, 'OT', 'E as suas entranhas e as suas pernas, lavá-las-á com água; e o sacerdote queimará tudo isso sobre o altar: holocausto é, oferta queimada, de cheiro suave ao SENHOR.'),
(2756, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 10, 'OT', 'E se a sua oferta for do rebanho, das ovelhas ou das cabras, para holocausto, oferecerá macho sem defeito.'),
(2757, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 11, 'OT', 'E o degolará ao lado do altar, para o lado norte, perante o SENHOR; e os filhos de Arão, os sacerdotes, espargirão o seu sangue sobre o altar, ao redor.'),
(2758, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 12, 'OT', 'E o partirá em seus pedaços, com a cabeça e o redenho; e o sacerdote os disporá sobre a lenha que está no fogo sobre o altar.'),
(2759, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 13, 'OT', 'E a fressura e as pernas, lavá-las-á com água; e o sacerdote oferecerá tudo e o queimará sobre o altar; holocausto é, oferta queimada, de cheiro suave ao SENHOR.'),
(2760, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 14, 'OT', 'Se a sua oferta ao SENHOR for holocausto de aves, oferecerá a sua oferta de rolas ou de pombinhos.'),
(2761, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 15, 'OT', 'O sacerdote a trará ao altar, e lhe torcerá a cabeça, e a queimará sobre o altar; e o seu sangue será espremido na parede do altar.'),
(2762, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 16, 'OT', 'E removerá o seu papo com as suas penas e o lançará junto ao altar, para o lado oriental, no lugar da cinza.'),
(2763, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 1, 17, 'OT', 'E o fenderá pelas suas asas, porém não o dividirá; e o sacerdote o queimará sobre o altar, em cima da lenha que está sobre o fogo; holocausto é, oferta queimada de aroma agradável ao SENHOR.'),
(2764, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 1, 'OT', 'E quando alguém oferecer oferta de manjares ao SENHOR, a sua oferta será de flor de farinha; e sobre ela derramará azeite, e sobre ela porá incenso.'),
(2765, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 2, 'OT', 'E a trará aos filhos de Arão, os sacerdotes; e um deles tomará dali um punhado da sua flor de farinha e do seu azeite, com todo o seu incenso; e o sacerdote queimará o seu memorial sobre o altar: oferta queimada de cheiro suave ao SENHOR.'),
(2766, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 3, 'OT', 'O restante da oferta de cereais será de Arão e de seus filhos; é coisa santíssima, das ofertas queimadas ao SENHOR.'),
(2767, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 4, 'OT', 'Quando ofereceres oferta de cereais cozida no forno, será de bolos sem fermento de flor de farinha, amassados com azeite, e pães finos sem fermento untados com azeite.'),
(2768, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 5, 'OT', 'E, se a tua oferta for oferta de manjares cozida na assadeira, será da melhor farinha, amassada com azeite, sem fermento.'),
(2769, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 6, 'OT', 'Em pedaços a partirás, e sobre ela derramarás azeite; é oferta de cereais.'),
(2770, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 7, 'OT', 'E se a tua oferta de manjares for feita em frigideira, será de flor de farinha com azeite.'),
(2771, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 8, 'OT', 'Trazerás a oferta de cereais que se fará destas coisas ao SENHOR; e a apresentarás ao sacerdote, que a levará ao altar.'),
(2772, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 9, 'OT', 'O sacerdote tomará da oferta de manjares a sua porção memorial e a queimará sobre o altar: é oferta queimada de aroma agradável ao SENHOR.'),
(2773, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 10, 'OT', 'E o restante da oferta de cereais será de Arão e de seus filhos; é coisa santíssima, das ofertas queimadas ao SENHOR.'),
(2774, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 11, 'OT', 'Nenhuma oferta de cereais que oferecerdes ao SENHOR será feita com fermento; porque de nenhum fermento nem mel oferecereis ao SENHOR como oferta queimada.'),
(2775, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 12, 'OT', 'Oferecereis essas coisas ao SENHOR como oferta das primícias; porém não subirão sobre o altar como aroma agradável.'),
(2776, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 13, 'OT', 'E toda oferta da tua oferta de cereais salgarás com sal; e não omitirás o sal da aliança do teu Deus sobre a tua oferta de cereais; em toda a tua oferta oferecerás sal.'),
(2777, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 14, 'OT', 'Se ofereceres ao SENHOR oferta de manjares das primícias, oferecerás a tua oferta de manjares das primícias de espigas verdes, tostadas ao fogo, grãos esmagados de trigo novo.'),
(2778, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 15, 'OT', 'E sobre ela porás azeite, e sobre ela colocarás incenso; é oferta de manjares.'),
(2779, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 2, 16, 'OT', 'O sacerdote queimará a porção memorial dela, do seu grão esmagado e do seu azeite, com todo o seu incenso, como oferta queimada ao SENHOR.'),
(2780, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 1, 'OT', 'E se a sua oferta for sacrifício pacífico, se a oferecer do gado, macho ou fêmea, a oferecerá sem defeito diante do SENHOR.'),
(2781, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 2, 'OT', 'E porá a sua mão sobre a cabeça da sua oferta, e a degolará à entrada da tenda da congregação; e os filhos de Arão, os sacerdotes, espargirão o sangue sobre o altar ao redor.'),
(2782, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 3, 'OT', 'E oferecerá do sacrifício pacífico uma oferta queimada ao SENHOR: a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas.'),
(2783, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 4, 'OT', 'E os dois rins, e a gordura que está sobre eles, que está sobre os lombos, e o redenho que está sobre o fígado, com os rins, ele removerá.'),
(2784, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 5, 'OT', 'E os filhos de Arão o queimarão sobre o altar, sobre o holocausto que está sobre a lenha que está no fogo; é oferta queimada de aroma agradável ao SENHOR.'),
(2785, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 6, 'OT', 'E, se a sua oferta for de ovelhas ou cabras, como sacrifício pacífico ao SENHOR, seja macho ou fêmea, sem defeito o oferecerá.'),
(2786, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 7, 'OT', 'Se a sua oferta for um cordeiro, ele o apresentará diante do SENHOR.'),
(2787, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 8, 'OT', 'E porá a sua mão sobre a cabeça da sua oferta, e a degolará diante da tenda da congregação; e os filhos de Arão espargirão o seu sangue sobre o altar ao redor.'),
(2788, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 9, 'OT', 'E do sacrifício das ofertas pacíficas trará ao SENHOR uma oferta queimada: a sua gordura, a cauda inteira, que tirará rente ao espinhaço, e a gordura que cobre as entranhas, e toda a gordura que está sobre as entranhas.'),
(2789, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 10, 'OT', 'E as duas os rins, e a gordura que está sobre eles, que está sobre os lombos, e o redenho que está sobre o fígado, com os rins, ele o removerá.'),
(2790, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 11, 'OT', 'E o sacerdote o queimará sobre o altar; é alimento de oferta queimada ao SENHOR.'),
(2791, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 12, 'OT', 'Se a sua oferta for uma cabra, ele a apresentará diante do SENHOR.'),
(2792, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 13, 'OT', 'E porá a sua mão sobre a cabeça do animal, e o degolará diante da tenda da congregação; e os filhos de Arão aspergirão o seu sangue sobre o altar, ao redor.'),
(2793, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 14, 'OT', 'E dela apresentará a sua oferta, como oferta queimada ao SENHOR: a gordura que cobre as entranhas e toda a gordura que está sobre as entranhas.'),
(2794, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 15, 'OT', 'E também os dois rins, e a gordura que está sobre eles, junto aos lombos, e o redenho que está sobre o fígado, com os rins, ele o removerá.'),
(2795, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 16, 'OT', 'O sacerdote os queimará sobre o altar; é alimento de oferta queimada de aroma agradável. Toda a gordura será do SENHOR.'),
(2796, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 3, 17, 'OT', 'Estatuto perpétuo será para as vossas gerações, em todas as vossas habitações: nenhuma gordura nem sangue algum comereis.'),
(2797, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(2798, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 2, 'OT', 'Fala aos filhos de Israel, dizendo: Quando uma alma pecar por ignorância contra algum dos mandamentos do SENHOR, acerca do que não se deve fazer, e fizer alguma dessas coisas,'),
(2799, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 3, 'OT', 'Se o sacerdote ungido pecar, trazendo culpa sobre o povo, oferecerá pelo seu pecado, que cometeu, um novilho sem defeito ao SENHOR, como oferta pelo pecado.'),
(2800, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 4, 'OT', 'E trará o novilho à entrada da tenda do encontro, perante o SENHOR, e porá a mão sobre a cabeça do novilho, e o degolará perante o SENHOR.'),
(2801, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 5, 'OT', 'E o sacerdote ungido tomará do sangue do novilho e o trará à tenda do encontro.'),
(2802, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 6, 'OT', 'E o sacerdote molhará o seu dedo no sangue e aspergirá daquele sangue sete vezes diante do SENHOR, perante o véu do santuário.'),
(2803, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 7, 'OT', 'E o sacerdote porá do sangue sobre os cornos do altar do incenso aromático diante do SENHOR, que está na tenda da congregação; e todo o restante do sangue do novilho derramará na base do altar do holocausto, que está à entrada da tenda da congregação.'),
(2804, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 8, 'OT', 'E toda a gordura do novilho da oferta pela culpa ele removerá dela: a gordura que cobre as entranhas, e toda a gordura que está sobre as entranhas.'),
(2805, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 9, 'OT', 'E os dois rins, e a gordura que está sobre eles, que está sobre os lombos, e o redenho sobre o fígado, com os rins, ele o removerá.'),
(2806, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 10, 'OT', 'como se tira do boi do sacrifício pacífico; e o sacerdote os queimará sobre o altar do holocausto.'),
(2807, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 11, 'OT', 'Mas o couro do novilho, e toda a sua carne, com a sua cabeça e as suas pernas, e as suas entranhas, e o seu esterco,'),
(2808, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 12, 'OT', 'E levará todo o novilho para fora do acampamento, a um lugar limpo, onde se lança a cinza, e o queimará sobre a lenha no fogo; sobre o monte de cinzas será queimado.'),
(2809, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 13, 'OT', 'Se toda a congregação de Israel errar, e o assunto for oculto aos olhos da assembleia, e eles fizerem alguma de todas as ordenanças do SENHOR que não devem ser feitas, e forem culpados,'),
(2810, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 14, 'OT', 'E quando o pecado que cometeram contra ela for conhecido, a congregação oferecerá um novilho como oferta pelo pecado e o trará diante da tenda do encontro.'),
(2811, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 15, 'OT', 'E os anciãos da congregação porão as suas mãos sobre a cabeça do novilho perante o SENHOR; e degolarão o novilho perante o SENHOR.'),
(2812, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 16, 'OT', 'E o sacerdote ungido trará do sangue do novilho à tenda da congregação.'),
(2813, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 17, 'OT', 'O sacerdote molhará o seu dedo no sangue e o aspergirá sete vezes diante do SENHOR, diante do véu.'),
(2814, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 18, 'OT', 'E do sangue porá sobre os chifres do altar que está diante do SENHOR, na tenda do encontro; e todo o restante do sangue derramará na base do altar do holocausto, que está à entrada da tenda do encontro.'),
(2815, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 19, 'OT', 'E tirará dele toda a sua gordura e a queimará sobre o altar.'),
(2816, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 20, 'OT', 'E fará com o novilho como fez com o novilho da oferta pelo pecado; assim fará com ele. E o sacerdote fará expiação por eles, e lhes será perdoado.'),
(2817, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 21, 'OT', 'E levará o novilho para fora do acampamento e o queimará, assim como queimou o primeiro novilho; é oferta pelo pecado da congregação.'),
(2818, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 22, 'OT', 'Quando um líder pecar, e sem intenção transgredir qualquer dos mandamentos do SENHOR, seu Deus, fazendo o que não se deve fazer, e assim for culpado,'),
(2819, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 23, 'OT', 'ou se o seu pecado, no qual pecou, lhe for notificado, então trará como sua oferta um bode, macho sem defeito.'),
(2820, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 24, 'OT', 'E porá a sua mão sobre a cabeça do bode, e o degolará no lugar onde se degola o holocausto, perante o SENHOR; é oferta pela culpa.'),
(2821, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 25, 'OT', 'E o sacerdote tomará com o dedo do sangue da oferta pela culpa, e o porá sobre as pontas do altar do holocausto; e o restante do sangue derramará na base do altar do holocausto.'),
(2822, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 26, 'OT', 'E todo o seu sebo queimará sobre o altar, como o sebo do sacrifício de paz; e o sacerdote fará expiação por ele do seu pecado, e lhe será perdoado.'),
(2823, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 27, 'OT', 'E se uma pessoa do povo da terra pecar por ignorância, fazendo alguma das coisas que o SENHOR ordenou que não se fizessem, e assim se tornar culpada,'),
(2824, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 28, 'OT', 'Ou, se o seu pecado, que cometeu, lhe for notificado, então trará como sua oferta uma cabra sem defeito, fêmea, pelo pecado que cometeu.'),
(2825, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 29, 'OT', 'E porá a sua mão sobre a cabeça da oferta pelo pecado, e a degolará no lugar do holocausto.'),
(2826, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 30, 'OT', 'O sacerdote tomará do seu sangue com o dedo e o porá sobre os chifres do altar do holocausto; e todo o restante do seu sangue derramará na base do altar.'),
(2827, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 31, 'OT', 'E tirará toda a sua gordura, como se tira a gordura do sacrifício pacífico; e o sacerdote a queimará sobre o altar como aroma agradável ao SENHOR; e o sacerdote fará expiação por ele, e ele será perdoado.'),
(2828, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 32, 'OT', 'E se trouxer uma ovelha como sua oferta pelo pecado, trará uma fêmea sem defeito.'),
(2829, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 33, 'OT', 'E porá a sua mão sobre a cabeça da oferta pela culpa, e a degolará como oferta pela culpa, no lugar onde se degola o holocausto.'),
(2830, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 34, 'OT', 'E o sacerdote tomará com o seu dedo do sangue da oferta pela culpa e o porá sobre os chifres do altar do holocausto; e todo o restante do seu sangue derramará na base do altar.'),
(2831, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 4, 35, 'OT', 'E tirará toda a sua gordura, como se tira a gordura do cordeiro do sacrifício pacífico; e o sacerdote os queimará sobre o altar, em cima das ofertas queimadas ao SENHOR; e o sacerdote fará expiação por ele do seu pecado que cometeu, e lhe será perdoado.'),
(2832, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 1, 'OT', 'E se alguém pecar, ouvindo a voz de uma maldição, e for testemunha, seja porque viu ou porque soube, se não o declarar, levará a sua iniquidade.'),
(2833, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 2, 'OT', 'Ou, se alguém tocar em qualquer coisa impura, seja o cadáver de um animal selvagem impuro, seja o cadáver de um animal doméstico impuro, seja o cadáver de um réptil impuro, ainda que isso lhe esteja oculto, ele será impuro e culpado.'),
(2834, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 3, 'OT', 'Ou, se tocar a impureza de um homem, qualquer que seja a sua impureza, pela qual se torne impuro, e isso lhe for oculto, e depois o souber, será culpado.'),
(2835, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 4, 'OT', 'Ou, se alguém jurar, pronunciando precipitadamente com os lábios, para fazer o mal ou para fazer o bem, em tudo o que o homem pronunciar precipitadamente com juramento, e isso lhe for oculto, e depois ele o souber, será culpado numa destas coisas.'),
(2836, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 5, 'OT', 'E quando for culpado de uma destas coisas, confessará aquilo em que pecou.'),
(2837, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 6, 'OT', 'E a sua oferta pela culpa trará ao SENHOR: uma fêmea do rebanho, uma cordeira ou uma cabra, como oferta pela culpa; e o sacerdote fará expiação por ela pelo seu pecado.'),
(2838, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 7, 'OT', 'Mas, se a sua mão não alcançar o suficiente para um cordeiro, então trará, pela sua culpa que cometeu, ao SENHOR duas rolas ou dois pombinhos: um para a oferta pelo pecado e o outro para o holocausto.'),
(2839, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 8, 'OT', 'E os trará ao sacerdote, que oferecerá primeiro o que é para a oferta pela culpa; e lhe torcerá a cabeça junto ao pescoço, mas não a separará.'),
(2840, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 9, 'OT', 'E do sangue da oferta pela culpa aspergirá sobre a parede do altar, e o restante do sangue será espremido na base do altar; é oferta pela culpa.'),
(2841, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 10, 'OT', 'E do segundo fará holocausto conforme o rito; assim o sacerdote fará expiação por ele do seu pecado que cometeu, e lhe será perdoado.'),
(2842, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 11, 'OT', 'Se a sua mão não alcançar duas rolas ou dois pombinhos, então trará a sua oferta pelo que pecou: um décimo de efa de flor de farinha para oferta pelo pecado; não derramará azeite sobre ela, nem lhe porá incenso em cima, porque é oferta pelo pecado.'),
(2843, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 12, 'OT', 'E a trará ao sacerdote, e o sacerdote tomará dela um punhado cheio, como memorial dela, e o queimará sobre o altar, em cima das ofertas queimadas ao SENHOR; é oferta pela culpa.'),
(2844, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 13, 'OT', 'E o sacerdote fará expiação por ele pelo seu pecado, que pecou em alguma destas coisas, e lhe será perdoado; e o restante será do sacerdote, como a oferta de manjares.'),
(2845, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 14, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(2846, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 15, 'OT', 'Se alguém cometer uma transgressão e pecar sem intenção contra as coisas sagradas do SENHOR, trará ao SENHOR, como oferta pela culpa, um carneiro sem defeito do rebanho, avaliado por ti em siclos de prata, segundo o siclo do santuário, para oferta pela culpa.'),
(2847, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 16, 'OT', 'E aquilo de que pecou contra as coisas santas, restituirá, e acrescentará a isso um quinto, e o dará ao sacerdote; e o sacerdote fará expiação por ele com o carneiro da oferta pela culpa, e lhe será perdoado.'),
(2848, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 17, 'OT', 'E se uma pessoa pecar e cometer alguma de todas as coisas que o SENHOR ordenou que não se fizessem, ainda que não o soubesse, será culpada e levará a sua iniquidade.'),
(2849, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 18, 'OT', 'E trará um carneiro sem defeito do rebanho, conforme a tua avaliação, como oferta pela culpa, ao sacerdote; e o sacerdote fará expiação por ele pelo seu erro que cometeu sem saber; e lhe será perdoado.'),
(2850, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 5, 19, 'OT', 'É oferta pela culpa; certamente ele se fez culpado diante do SENHOR.'),
(2851, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2852, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 2, 'OT', 'Quando alguém pecar e cometer transgressão contra o SENHOR, e negar ao seu próximo o que lhe foi confiado em depósito, ou o que foi posto em sua mão, ou o que foi roubado, ou o que extorquir do seu próximo,'),
(2853, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 3, 'OT', 'ou se achou algo perdido e o negou, jurando falsamente a respeito; ou se fez qualquer outra coisa de todas em que o homem costuma pecar.'),
(2854, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 4, 'OT', 'E será que, havendo pecado e sido culpado, restituirá o que roubou, ou o que extorquiu, ou o depósito que lhe foi confiado, ou a coisa perdida que achou.'),
(2855, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 5, 'OT', 'ou de tudo aquilo sobre o que jurou falsamente; e o restituirá em seu valor total, e sobre isso acrescentará um quinto; àquele a quem pertence, o dará no dia em que se declarar culpado.'),
(2856, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 6, 'OT', 'E a sua oferta pela culpa trará ao SENHOR: um carneiro sem defeito do rebanho, conforme a tua avaliação, como oferta pela culpa, ao sacerdote.'),
(2857, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 7, 'OT', 'E o sacerdote fará expiação por ele diante do SENHOR, e será perdoado, seja qual for a ofensa que tenha cometido para tornar-se culpado.'),
(2858, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 8, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2859, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 9, 'OT', 'Ordena a Arão e a seus filhos, dizendo: Esta é a lei do holocausto: o holocausto ficará sobre a sua brasa, sobre o altar, toda a noite, até a manhã, e o fogo do altar arderá nele.'),
(2860, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 10, 'OT', 'O sacerdote vestirá a sua túnica de linho e as calças de linho sobre o seu corpo; e removerá a cinza que o fogo consumiu do holocausto sobre o altar, e a colocará ao lado do altar.'),
(2861, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 11, 'OT', 'Depois despirá as suas vestes e vestirá outras vestes, e levará a cinza para fora do acampamento, a um lugar limpo.'),
(2862, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 12, 'OT', 'O fogo sobre o altar arderá nele; não se apagará. O sacerdote acenderá lenha nele cada manhã, pela manhã, e disporá sobre ele o holocausto, e queimará sobre ele a gordura das ofertas pacíficas.'),
(2863, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 13, 'OT', 'O fogo arderá continuamente sobre o altar; não se apagará.'),
(2864, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 14, 'OT', 'E esta é a lei da oferta de cereais: os filhos de Arão a apresentarão diante do SENHOR, diante do altar.'),
(2865, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 15, 'OT', 'E dela tomará um punhado da flor de farinha da oferta de manjares e do seu azeite, e todo o incenso que estiver sobre a oferta de manjares; e o queimará sobre o altar, cheiro suave, memorial ao SENHOR.'),
(2866, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 16, 'OT', 'E o restante dela comerão Arão e seus filhos; sem fermento se comerá em lugar santo, no pátio da tenda da congregação o comerão.'),
(2867, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 17, 'OT', 'Não será assado com fermento; dei-lhes essa porção das minhas ofertas queimadas. É coisa santíssima, como a oferta pelo pecado e como a oferta pela culpa.'),
(2868, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 18, 'OT', 'Todo homem entre os filhos de Arão comerá dela; é estatuto perpétuo para as vossas gerações, das ofertas queimadas ao SENHOR; tudo o que tocar nelas será santo.'),
(2869, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 19, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2870, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 20, 'OT', 'Este é o sacrifício de Arão e de seus filhos, que oferecerão ao SENHOR no dia em que ele for ungido: um décimo de efa de flor de farinha como oferta de cereais contínua, metade dela pela manhã e metade dela à tarde.'),
(2871, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 21, 'OT', 'Numa assadeira, com azeite, será feita; amassada a trarás; em pedaços cozidos, a oferta de cereais apresentarás como aroma agradável ao SENHOR.'),
(2872, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 22, 'OT', 'E o sacerdote ungido, dentre seus filhos, em seu lugar, fará a mesma oferta; é estatuto perpétuo para o SENHOR: será queimada por completo.'),
(2873, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 23, 'OT', 'E toda oferta de cereais do sacerdote será totalmente queimada; não se comerá.'),
(2874, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 24, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2875, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 25, 'OT', 'Fala a Arão e a seus filhos, dizendo: Esta é a lei da oferta pela culpa: no lugar onde se imola o holocausto, será imolada a oferta pela culpa diante do SENHOR; é coisa santíssima.'),
(2876, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 26, 'OT', 'O sacerdote que a oferecer pelo pecado a comerá; em lugar santo se comerá, no pátio da tenda da congregação.'),
(2877, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 27, 'OT', 'Tudo o que tocar a sua carne será santo; e se alguém aspergir do seu sangue sobre a roupa, lavarás aquilo sobre o que caiu em lugar santo.'),
(2878, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 28, 'OT', 'E o vaso de barro em que for cozida será quebrado; mas, se for cozida em vaso de bronze, será esfregado e lavado em água.'),
(2879, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 29, 'OT', 'Todo homem entre os sacerdotes a comerá; coisa santíssima é.'),
(2880, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 6, 30, 'OT', 'E toda oferta pela culpa, cujo sangue for trazido à tenda da congregação, para fazer expiação no santuário, não será comida; será queimada no fogo.'),
(2881, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 1, 'OT', 'E esta é a lei da oferta pela culpa: é santíssima.'),
(2882, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 2, 'OT', 'No lugar onde se degola o holocausto, degolarão a oferta pela culpa, e o seu sangue se aspergirá sobre o altar ao redor.'),
(2883, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 3, 'OT', 'E de tudo isso oferecerá toda a gordura: a cauda gorda e a gordura que cobre as entranhas.'),
(2884, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 4, 'OT', 'E os dois rins, e a gordura que está sobre eles, que está sobre os lombos, e o redenho sobre o fígado, com os rins o removerá.'),
(2885, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 5, 'OT', 'O sacerdote os queimará sobre o altar como oferta queimada ao SENHOR; é oferta pela culpa.'),
(2886, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 6, 'OT', 'Todo homem entre os sacerdotes a comerá; em lugar santo se comerá; santíssima é.'),
(2887, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 7, 'OT', 'Como a oferta pela culpa, assim é a oferta pelo pecado; uma só lei há para elas; será do sacerdote que com ela fizer expiação.'),
(2888, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 8, 'OT', 'O sacerdote que oferecer o holocausto de alguém terá para si a pele do holocausto que ofereceu.'),
(2889, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 9, 'OT', 'E toda oferta de cereais que for assada no forno, e tudo o que for feito na frigideira e na assadeira, será do sacerdote que a oferece; dele será.'),
(2890, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 10, 'OT', 'E toda oferta de cereais amassada com azeite, ou seca, será de todos os filhos de Arão, tanto de um como de outro.'),
(2891, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 11, 'OT', 'E esta é a lei do sacrifício de ofertas pacíficas que se oferecerá ao SENHOR:'),
(2892, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 12, 'OT', 'Se ele o oferecer por ação de graças, então, com o sacrifício de ação de graças, oferecerá bolos sem fermento amassados com azeite, e pães finos sem fermento untados com azeite, e flor de farinha bem amassada, em bolos amassados com azeite.'),
(2893, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 13, 'OT', 'Com os bolos de pão levedado apresentará a sua oferta, junto com o sacrifício de ação de graças das suas ofertas pacíficas.'),
(2894, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 14, 'OT', 'E de toda a oferta trará uma parte como oferta alçada ao SENHOR; será do sacerdote que aspergir o sangue da oferta pacífica.'),
(2895, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 15, 'OT', 'A carne do sacrifício de ação de graças das suas ofertas pacíficas será comida no dia em que for oferecida; nada se deixará dela até a manhã.'),
(2896, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 16, 'OT', 'E, se for voto ou oferta voluntária o sacrifício da sua oferta, no dia em que o oferecer, o seu sacrifício será comido; e o que sobrar dele será comido no dia seguinte.'),
(2897, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 17, 'OT', 'E o que restar da carne do sacrifício, ao terceiro dia, será queimado no fogo.'),
(2898, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 18, 'OT', 'E se, de fato, for comida da carne do sacrifício das suas ofertas pacíficas ao terceiro dia, não será aceito; aquele que o oferece não lhe será imputado; coisa abominável será, e a pessoa que comer dela levará a sua iniquidade.'),
(2899, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 19, 'OT', 'E a carne que tocar qualquer coisa impura não se comerá; será queimada no fogo. Mas a carne, todo aquele que estiver puro comerá dela.'),
(2900, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 20, 'OT', 'E a pessoa que comer carne do sacrifício pacífico que pertence ao SENHOR, tendo a sua impureza sobre si, essa pessoa será cortada do seu povo.'),
(2901, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 21, 'OT', 'E se alguém tocar em qualquer coisa impura, seja impureza humana, seja animal impuro, seja qualquer abominação impura, e comer da carne do sacrifício pacífico que pertence ao SENHOR, essa pessoa será eliminada do seu povo.'),
(2902, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 22, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2903, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 23, 'OT', 'Fala aos filhos de Israel, dizendo: Nenhuma gordura de boi, nem de ovelha, nem de cabra comereis.'),
(2904, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 24, 'OT', 'A gordura de animal encontrado morto e a gordura de animal dilacerado poderá ser usada para qualquer outra finalidade, mas de maneira alguma vocês a comerão.'),
(2905, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 25, 'OT', 'Porque todo aquele que comer gordura de animal, do qual se oferecer oferta queimada ao SENHOR, essa pessoa que comer será eliminada do seu povo.'),
(2906, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 26, 'OT', 'E nenhum sangue comereis em todas as vossas habitações, quer de aves, quer de animais.'),
(2907, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 27, 'OT', 'Qualquer pessoa que comer qualquer sangue, essa pessoa será eliminada do seu povo.'),
(2908, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 28, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2909, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 29, 'OT', 'Fala aos filhos de Israel, dizendo: Aquele que oferecer o seu sacrifício pacífico ao SENHOR trará a sua oferta ao SENHOR do seu sacrifício pacífico.'),
(2910, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 30, 'OT', 'As suas próprias mãos trarão as ofertas queimadas ao SENHOR; a gordura do peito com o peito trará, para mover o peito como oferta movida perante o SENHOR.'),
(2911, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 31, 'OT', 'O sacerdote queimará a gordura sobre o altar, mas o peito será de Arão e de seus filhos.'),
(2912, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 32, 'OT', 'E o ombro direito dareis ao sacerdote por oferta movida, dos vossos sacrifícios pacíficos.'),
(2913, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 33, 'OT', 'Aquele que oferecer o sangue das ofertas pacíficas e a gordura, dentre os filhos de Arão, terá a coxa direita como sua porção.'),
(2914, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 34, 'OT', 'Porque o peito da oferta movida e a coxa da oferta alçada tomei dos filhos de Israel, dos seus sacrifícios pacíficos, e os dei a Arão, o sacerdote, e a seus filhos, por estatuto perpétuo, dos filhos de Israel.'),
(2915, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 35, 'OT', 'Esta é a porção de Arão e a porção de seus filhos, das ofertas queimadas ao SENHOR, no dia em que os apresentou para servirem como sacerdotes ao SENHOR.'),
(2916, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 36, 'OT', 'o que o SENHOR ordenou que se lhes desse, no dia em que os ungiu, da parte dos filhos de Israel: estatuto perpétuo para as suas gerações.'),
(2917, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 37, 'OT', 'Esta é a lei do holocausto, da oferta de cereais, e da oferta pelo pecado, e da oferta pela culpa, e das ofertas de consagração, e do sacrifício de paz.'),
(2918, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 7, 38, 'OT', 'Que o SENHOR ordenou a Moisés no monte Sinai, no dia em que ordenou aos filhos de Israel que oferecessem as suas ofertas ao SENHOR no deserto de Sinai.'),
(2919, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(2920, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 2, 'OT', 'Toma Arão e seus filhos com ele, e as vestes, e o óleo da unção, e o novilho da oferta pelo pecado, e os dois carneiros, e o cesto dos pães sem fermento.'),
(2921, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 3, 'OT', 'E ajunta toda a congregação à entrada da tenda do encontro.'),
(2922, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 4, 'OT', 'Fez Moisés como o SENHOR lhe ordenara, e a congregação se reuniu à entrada da tenda do encontro.'),
(2923, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 5, 'OT', 'Então disse Moisés à congregação: Isto é o que o SENHOR ordenou que se fizesse.'),
(2924, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 6, 'OT', 'E Moisés fez chegar Arão e seus filhos, e os lavou com água.'),
(2925, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 7, 'OT', 'E vestiu-lhe a túnica, cingiu-o com o cinto, pôs sobre ele o manto, e sobre ele colocou o éfode, cingindo-o com o cinto do éfode, e o apertou com ele.'),
(2926, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 8, 'OT', 'Pôs sobre ele o peitoral e, no peitoral, colocou o Urim e o Tumim.'),
(2927, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 9, 'OT', 'E pôs a mitra sobre a sua cabeça, e sobre a mitra, diante do seu rosto, pôs a lâmina de ouro, o diadema da santidade, como o SENHOR havia ordenado a Moisés.'),
(2928, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 10, 'OT', 'Então Moisés tomou o óleo da unção, ungiu o tabernáculo e tudo o que havia nele, e os santificou.'),
(2929, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 11, 'OT', 'E dele aspergiu sete vezes sobre o altar, e ungiu o altar e todos os seus utensílios, e a bacia e a sua base, para santificá-los.'),
(2930, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 12, 'OT', 'Derramou do óleo da unção sobre a cabeça de Arão e o ungiu para santificá-lo.'),
(2931, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 13, 'OT', 'E Moisés fez chegar os filhos de Arão, e vestiu-lhes as túnicas, e cingiu-os com os cintos, e lhes atou as tiaras, como o SENHOR havia ordenado a Moisés.'),
(2932, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 14, 'OT', 'Então ele trouxe o novilho da oferta pelo pecado, e Arão e seus filhos puseram as mãos sobre a cabeça do novilho da oferta pelo pecado.'),
(2933, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 15, 'OT', 'E o degolou; e Moisés tomou o sangue, e com o seu dedo o pôs sobre os chifres do altar ao redor, e purificou o altar; e o restante do sangue derramou na base do altar, e o santificou, para fazer expiação sobre ele.'),
(2934, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 16, 'OT', 'Tomou todo o sebo que está sobre as entranhas, e o redenho do fígado, e os dois rins e o seu sebo; e Moisés os queimou sobre o altar.'),
(2935, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 17, 'OT', 'Mas o novilho, com o seu couro, a sua carne e o seu esterco, queimou com fogo fora do acampamento, como o SENHOR ordenara a Moisés.'),
(2936, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 18, 'OT', 'Trouxe o carneiro do holocausto; e Arão e seus filhos puseram as mãos sobre a cabeça do carneiro.'),
(2937, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 19, 'OT', 'E o degolou; e Moisés aspergiu o sangue sobre o altar, ao redor.'),
(2938, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 20, 'OT', 'E o carneiro foi partido em seus pedaços; e Moisés queimou a cabeça, os pedaços e a gordura.'),
(2939, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 21, 'OT', 'Lavou o interior e as pernas com água, e Moisés queimou todo o carneiro sobre o altar: holocausto de aroma agradável, oferta queimada ao SENHOR, como o SENHOR havia ordenado a Moisés.'),
(2940, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 22, 'OT', 'Depois trouxe o segundo carneiro, o carneiro da consagração; e Arão e seus filhos puseram as mãos sobre a cabeça do carneiro.'),
(2941, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 23, 'OT', 'E o degolou; e Moisés tomou do seu sangue, e o pôs sobre a ponta da orelha direita de Arão, e sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito.'),
(2942, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 24, 'OT', 'E Moisés trouxe os filhos de Arão, e pôs do sangue sobre o lóbulo da orelha direita deles, e sobre o polegar da mão direita deles, e sobre o polegar do pé direito deles; e Moisés aspergiu o sangue sobre o altar ao redor.'),
(2943, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 25, 'OT', 'Tomou a gordura, a cauda, toda a gordura que está sobre as entranhas, o redenho do fígado, os dois rins com a sua gordura e a coxa direita.'),
(2944, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 26, 'OT', 'E do cesto dos pães sem fermento que estava diante do SENHOR tomou um pão sem fermento, e um pão de azeite, e um pão fino, e os pôs sobre a gordura e sobre a coxa direita.'),
(2945, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 27, 'OT', 'E tudo isso pôs nas mãos de Arão e nas mãos de seus filhos, e os moveu como oferta movida perante o SENHOR.'),
(2946, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 28, 'OT', 'Então Moisés os tomou das suas mãos e os queimou no altar sobre o holocausto; eram ofertas de consagração, por aroma agradável, oferta queimada ao SENHOR.'),
(2947, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 29, 'OT', 'Tomou Moisés o peito e o moveu como oferta de movimento perante o SENHOR; do carneiro da consagração, essa foi a porção de Moisés, como o SENHOR havia ordenado a Moisés.'),
(2948, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 30, 'OT', 'Tomou Moisés do óleo da unção e do sangue que estava sobre o altar, e o aspergiu sobre Arão, sobre as suas vestes, sobre os seus filhos e sobre as vestes dos seus filhos com ele; e santificou Arão, as suas vestes, os seus filhos e as vestes dos seus filhos com ele.'),
(2949, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 31, 'OT', 'E Moisés disse a Arão e a seus filhos: Cozei a carne à entrada da tenda do encontro, e ali a comereis com o pão que está no cesto da consagração, como ordenei, dizendo: Arão e seus filhos a comerão.'),
(2950, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 32, 'OT', 'E o que restar da carne e do pão, queimareis com fogo.'),
(2951, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 33, 'OT', 'Não saireis da porta da tenda da congregação por sete dias, até o dia em que se cumprirem os dias da vossa consagração; porque por sete dias ele vos consagrará.'),
(2952, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 34, 'OT', 'Como se fez neste dia, assim o SENHOR ordenou que se fizesse, para fazer expiação por vós.'),
(2953, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 35, 'OT', 'Ficareis à porta da tenda da congregação dia e noite, por sete dias, e guardareis a guarda do SENHOR, para que não morrais; porque assim me foi ordenado.'),
(2954, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 8, 36, 'OT', 'E Arão e seus filhos fizeram todas as coisas que o SENHOR ordenou por meio de Moisés.'),
(2955, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 1, 'OT', 'E aconteceu, no dia oitavo, que Moisés chamou Arão e seus filhos, e os anciãos de Israel.'),
(2956, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 2, 'OT', 'E disse a Arão: Toma-te um bezerro para oferta pela culpa e um carneiro para holocausto, sem defeito, e apresenta-os perante o SENHOR.'),
(2957, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 3, 'OT', 'E falarás aos filhos de Israel, dizendo: Tomai um bode para oferta pela culpa, e um bezerro e um cordeiro de um ano, sem defeito, para holocausto.'),
(2958, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 4, 'OT', 'Um boi e um carneiro para oferta pacífica, para sacrificar perante o SENHOR, e oferta de cereais amassada com azeite; porque hoje o SENHOR vos aparecerá.'),
(2959, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 5, 'OT', 'E tomaram o que Moisés ordenara, diante da tenda da congregação; e chegou-se toda a congregação, e puseram-se perante o SENHOR.'),
(2960, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 6, 'OT', 'E disse Moisés: Isto é o que o SENHOR ordenou que façais; e a glória do SENHOR vos aparecerá.'),
(2961, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 7, 'OT', 'E disse Moisés a Arão: Chega-te ao altar, e faze a tua oferta pelo pecado e o teu holocausto, e faze expiação por ti e pelo povo; e faze a oferta do povo, e faze expiação por eles, como ordenou o SENHOR.'),
(2962, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 8, 'OT', 'Então Arão se aproximou do altar e sacrificou o bezerro da oferta pelo pecado que era dele.'),
(2963, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 9, 'OT', 'Os filhos de Arão trouxeram-lhe o sangue; ele molhou o dedo no sangue e o pôs sobre as pontas do altar, e o restante do sangue derramou na base do altar.'),
(2964, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 10, 'OT', 'Mas a gordura, os rins e o redenho do fígado da oferta pelo pecado, ele queimou sobre o altar, como o SENHOR havia ordenado a Moisés.'),
(2965, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 11, 'OT', 'Mas a carne e o couro queimou com fogo fora do acampamento.'),
(2966, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 12, 'OT', 'Ele degolou o holocausto, e os filhos de Arão lhe trouxeram o sangue, e ele o aspergiu sobre o altar ao redor.'),
(2967, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 13, 'OT', 'E trouxeram-lhe o holocausto em seus pedaços, com a cabeça; e ele o queimou sobre o altar.'),
(2968, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 14, 'OT', 'E lavou as entranhas e as pernas, e as queimou sobre o holocausto no altar.'),
(2969, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 15, 'OT', 'Trouxe também a oferta do povo; tomou o bode da oferta pelo pecado, que era do povo, e o sacrificou, e fez expiação por ele, como no primeiro.'),
(2970, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 16, 'OT', 'Trouxe também a oferta queimada e a preparou conforme o rito.'),
(2971, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 17, 'OT', 'E trouxe a oferta de cereais, encheu a mão com ela e a queimou sobre o altar, além do holocausto da manhã.'),
(2972, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 18, 'OT', 'Ele degolou o boi e o carneiro em sacrifício pacífico, que era do povo; e os filhos de Arão lhe trouxeram o sangue, e ele o aspergiu sobre o altar ao redor.'),
(2973, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 19, 'OT', 'e a gordura do boi e do carneiro: a cauda gorda, a gordura que cobre as entranhas, os rins e o redenho do fígado.'),
(2974, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 20, 'OT', 'E puseram a gordura sobre os peitos, e queimou a gordura sobre o altar.'),
(2975, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 21, 'OT', 'E os peitos e a coxa direita, Arão os moveu como oferta movida perante o SENHOR, conforme Moisés havia ordenado.'),
(2976, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 22, 'OT', 'Levantou Arão as suas mãos para o povo e os abençoou; e desceu, depois de oferecer a oferta pelo pecado, o holocausto e as ofertas pacíficas.'),
(2977, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 23, 'OT', 'Então Moisés e Arão entraram na tenda do encontro; e, ao saírem, abençoaram o povo; e a glória do SENHOR apareceu a todo o povo.'),
(2978, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 9, 24, 'OT', 'Saiu fogo de diante do SENHOR e consumiu sobre o altar o holocausto e a gordura; e todo o povo viu isso, jubilou e caiu sobre o seu rosto.'),
(2979, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 1, 'OT', 'Os filhos de Arão, Nadabe e Abiú, tomaram cada um o seu incensário, e puseram fogo neles, e colocaram incenso sobre o fogo, e trouxeram fogo estranho diante do SENHOR, o que ele não lhes havia ordenado.'),
(2980, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 2, 'OT', 'Saiu fogo de diante do SENHOR e os consumiu; e morreram perante o SENHOR.'),
(2981, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 3, 'OT', 'E Moisés disse a Arão: Isto é o que o SENHOR falou, dizendo: Serei santificado naqueles que se aproximam de mim, e serei glorificado diante de todo o povo. E Arão ficou em silêncio.'),
(2982, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 4, 'OT', 'Chamou Moisés a Misael e a Elzafã, filhos de Uziel, tio de Arão, e disse-lhes: Aproximai-vos, levai vossos irmãos de diante do santuário para fora do acampamento.'),
(2983, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 5, 'OT', 'E chegaram e os levaram em suas túnicas para fora do acampamento, como Moisés tinha dito.'),
(2984, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 6, 'OT', 'E Moisés disse a Arão e a seus filhos Eleazar e Itamar: "Não descubrais as vossas cabeças, nem rasgueis as vossas vestes, para que não morrais, e para que a ira não venha sobre toda a congregação; mas vossos irmãos, toda a casa de Israel, chorem o incêndio que o SENHOR acendeu."'),
(2985, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 7, 'OT', 'Não saireis da entrada da tenda da congregação, para que não morrais, porque o óleo da unção do SENHOR está sobre vós. E eles fizeram conforme a palavra de Moisés.'),
(2986, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 8, 'OT', 'E falou o SENHOR a Arão, dizendo:'),
(2987, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 9, 'OT', 'Não bebereis vinho nem bebida forte, nem tu nem teus filhos contigo, quando entrardes na tenda da congregação, para que não morrais; estatuto perpétuo será isso para as vossas gerações.'),
(2988, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 10, 'OT', 'E para fazer distinção entre o santo e o profano, e entre o impuro e o puro,'),
(2989, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 11, 'OT', 'E para ensinar aos filhos de Israel todos os estatutos que o SENHOR lhes falou por meio de Moisés.'),
(2990, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 12, 'OT', 'E Moisés falou a Arão e a Eleazar e a Itamar, seus filhos que restaram: Tomai a oferta de manjares que restou das ofertas queimadas do SENHOR e comei-a sem fermento junto ao altar, porque é santíssima.'),
(2991, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 13, 'OT', 'Comê-la-eis em lugar santo, porque isto é a tua porção e a porção de teus filhos, das ofertas queimadas ao SENHOR; porque assim me foi ordenado.'),
(2992, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 14, 'OT', 'E o peito da oferta movida e a coxa da oferta alçada comereis em lugar puro, tu, e teus filhos, e tuas filhas contigo; porque são dados como tua porção e porção de teus filhos, dos sacrifícios pacíficos dos filhos de Israel.'),
(2993, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 15, 'OT', 'A coxa da oferta alçada e o peito da oferta movida trarão juntamente com as ofertas queimadas de gordura, para os mover como oferta movida perante o SENHOR; e isso será para ti e para teus filhos contigo, por estatuto perpétuo, como o SENHOR ordenou.'),
(2994, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 16, 'OT', 'E Moisés buscou diligentemente o bode da oferta pelo pecado, e eis que já havia sido queimado; e indignou-se contra Eleazar e contra Itamar, os filhos de Arão que restaram, dizendo:'),
(2995, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 17, 'OT', 'Por que não comestes a oferta pelo pecado no lugar santo? Pois é coisa santíssima, e ele a deu a vós para levar a iniquidade da congregação, para fazer expiação por eles diante do SENHOR.'),
(2996, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 18, 'OT', 'Eis-que o sangue dela não foi trazido para dentro do santuário; certamente a comereis no santuário, como ordenei.'),
(2997, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 19, 'OT', 'Então Arão disse a Moisés: Eis-que hoje ofereceram a sua oferta pelo pecado e o seu holocausto perante o SENHOR, e tais coisas me aconteceram; se eu tivesse comido a oferta pelo pecado hoje, seria isso aceitável aos olhos do SENHOR?'),
(2998, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 10, 20, 'OT', 'E Moisés ouviu isso, e foi-lhe agradável aos seus olhos.'),
(2999, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 1, 'OT', 'E o SENHOR falou a Moisés e a Arão, dizendo-lhes:'),
(3000, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 2, 'OT', 'Falai aos filhos de Israel, dizendo: Estes são os animais que comereis de todos os quadrúpedes que há sobre a terra.'),
(3001, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 3, 'OT', 'Todo animal que tem casco fendido, dividido em duas partes, e que rumina, entre os animais, esse comereis.'),
(3002, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 4, 'OT', 'Mas, entre estes, não comereis dos que ruminam nem dos que têm a pata fendida: o camelo, porque rumina, mas não tem a pata fendida; ele será impuro para vós.'),
(3003, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 5, 'OT', 'E o arganaz, porque rumina, mas não tem a pata fendida; ele é impuro para vocês.'),
(3004, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 6, 'OT', 'E a lebre, porque rumina, mas não fende a pata, ela é impura para vocês.'),
(3005, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 7, 'OT', 'Também o porco, porque tem casco fendido e a fenda do casco se divide em duas, mas não rumina; ele é impuro para vocês.'),
(3006, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 8, 'OT', 'Da sua carne não comereis, e no seu cadáver não tocareis; eles são impuros para vós.'),
(3007, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 9, 'OT', 'Isto comereis de tudo o que há nas águas: tudo o que tem barbatanas e escamas nas águas, nos mares e nos rios, isso comereis.'),
(3008, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 10, 'OT', 'E tudo o que não tem barbatanas nem escamas, nos mares e nos rios, de todo o enxame das águas e de toda a alma vivente que há nas águas, estes serão para vós abominação.'),
(3009, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 11, 'OT', 'Ser-vos-hão por abominação: da sua carne não comereis, e abominareis o seu cadáver.'),
(3010, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 12, 'OT', 'Tudo o que não tem barbatanas nem escamas nas águas será para vós abominação.'),
(3011, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 13, 'OT', 'E estas abominareis entre as aves; não se comerão, são abominação: a águia, o quebrantosso e o xofrango.'),
(3012, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 14, 'OT', 'e o milhafre, e o abutre segundo a sua espécie.'),
(3013, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 15, 'OT', 'Todo corvo, segundo a sua espécie.'),
(3014, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 16, 'OT', 'e o avestruz, e o mocho, e a gaivota, e o gavião segundo a sua espécie.'),
(3015, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 17, 'OT', 'e o corujão, e o corvo-marinho, e a coruja-das-torres'),
(3016, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 18, 'OT', 'E a coruja-das-torres, e o corvo-marinho, e o abutre.'),
(3017, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 19, 'OT', 'e a cegonha, a garça segundo a sua espécie, e a poupa, e o morcego.'),
(3018, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 20, 'OT', 'Todo réptil alado que anda sobre quatro pés será para vós uma abominação.'),
(3019, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 21, 'OT', 'Todavia, entre todos os insetos alados que andam sobre quatro pés, comereis aqueles que têm pernas acima dos pés, para saltar com elas sobre a terra.'),
(3020, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 22, 'OT', 'Deles comereis estes: o gafanhoto segundo a sua espécie, e o solhão segundo a sua espécie, e o hargol segundo a sua espécie, e o hagabe segundo a sua espécie.'),
(3021, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 23, 'OT', 'E todo inseto alado que tem quatro patas será para vocês uma abominação.'),
(3022, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 24, 'OT', 'E por estes sereis imundos: todo aquele que tocar nos seus cadáveres será imundo até a tarde.'),
(3023, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 25, 'OT', 'Todo aquele que carregar algum dos seus cadáveres lavará as suas roupas e ficará impuro até a tarde.'),
(3024, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 26, 'OT', 'Todo animal que tem casco fendido, mas a fenda não se divide em duas, e que não rumina, será impuro para vocês; qualquer que tocar neles ficará impuro.'),
(3025, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 27, 'OT', 'E tudo o que anda sobre as patas, entre todo animal que anda sobre quatro pés, esses são impuros para vocês; todo aquele que tocar nos seus cadáveres ficará impuro até a tarde.'),
(3026, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 28, 'OT', 'E quem carregar os seus cadáveres lavará as suas roupas e ficará impuro até a tarde; eles serão impuros para vocês.'),
(3027, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 29, 'OT', 'Estes serão para vós imundos entre os répteis que se movem sobre a terra: a doninha, o rato e o lagarto, segundo a sua espécie.'),
(3028, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 30, 'OT', 'e o musaranho, e o lagarto, e a lagartixa, e o geco, e o camaleão.'),
(3029, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 31, 'OT', 'Estes são os que serão imundos para vós entre todos os animais que se movem sobre a terra; todo aquele que os tocar, estando eles mortos, será imundo até a tarde.'),
(3030, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 32, 'OT', 'E tudo aquilo sobre o que cair alguma coisa deles, estando eles mortos, será imundo; seja vaso de madeira, ou vestido, ou pele, ou saco, qualquer instrumento com que se faz alguma obra, será mergulhado em água, e ficará imundo até a tarde; então será limpo.'),
(3031, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 33, 'OT', 'E todo vaso de barro em que cair alguma coisa deles, tudo o que houver nele será imundo, e o vaso quebrareis.'),
(3032, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 34, 'OT', 'De todo alimento que se come, sobre o qual vier água, será imundo; e toda bebida que se bebe, em qualquer vaso, será imunda.'),
(3033, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 35, 'OT', 'E tudo aquilo sobre o que cair algo do seu corpo morto será imundo; o forno e o fogareiro serão derrubados; imundos são, e imundos serão para vós.'),
(3034, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 36, 'OT', 'Todavia, a fonte e a cisterna, onde se ajuntam águas, serão limpas; mas quem tocar no seu cadáver ficará imundo.'),
(3035, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 37, 'OT', 'E, se dos seus cadáveres cair alguma coisa sobre qualquer semente que se há de semear, ela será limpa.'),
(3036, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 38, 'OT', 'Mas se for derramada água sobre a semente, e dela cair alguma coisa do seu cadáver, imunda será para vós.'),
(3037, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 39, 'OT', 'E se morrer algum dos animais que vos servem de alimento, quem tocar no seu cadáver ficará impuro até a tarde.'),
(3038, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 40, 'OT', 'E quem comer da sua carcaça lavará as suas roupas e ficará impuro até a tarde; e quem carregar a sua carcaça lavará as suas roupas e ficará impuro até a tarde.'),
(3039, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 41, 'OT', 'Todo réptil que se move sobre a terra será abominação; não se comerá.'),
(3040, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 42, 'OT', 'Todo o que anda sobre o ventre, e todo o que anda sobre quatro pés, ou que tem muitos pés, entre todo réptil que se arrasta sobre a terra, não comereis, porque são abominação.'),
(3041, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 43, 'OT', 'Não contaminem a si mesmos com nenhum animal que se move rente ao chão; não se tornem impuros por meio deles, para que não fiquem contaminados.'),
(3042, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 44, 'OT', 'Porque eu sou o SENHOR, o vosso Deus; portanto, santificai-vos e sede santos, porque eu sou santo; e não contamineis as vossas almas com nenhum animal que se arrasta sobre a terra.'),
(3043, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 45, 'OT', 'Porque eu sou o SENHOR, que vos fiz subir da terra do Egito, para ser o vosso Deus; portanto, sede santos, porque eu sou santo.'),
(3044, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 46, 'OT', 'Esta é a lei dos animais, e das aves, e de todo ser vivo que se move nas águas, e de todo ser que rasteja sobre a terra.'),
(3045, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 11, 47, 'OT', 'para fazer separação entre o impuro e o puro, e entre os animais que se podem comer e os animais que não se podem comer.'),
(3046, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3047, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 2, 'OT', 'Fala aos filhos de Israel, dizendo: Se uma mulher conceber e der à luz um menino, será imunda sete dias; assim como nos dias da separação da sua enfermidade, será imunda.'),
(3048, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 3, 'OT', 'No oitavo dia, será circuncidada a carne do seu prepúcio.'),
(3049, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 4, 'OT', 'Ela permanecerá trinta e três dias no sangue da sua purificação; não tocará em nenhuma coisa santa, e não entrará no santuário, até que se completem os dias da sua purificação.'),
(3050, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 5, 'OT', 'Mas, se der à luz uma menina, será impura por duas semanas, como na sua menstruação; e ficará sessenta e seis dias no sangue da sua purificação.'),
(3051, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 6, 'OT', 'E quando se cumprirem os dias da sua purificação, por filho ou por filha, ela trará um cordeiro de um ano para holocausto e um pombinho ou uma rola para oferta pelo pecado, à entrada da tenda da congregação, ao sacerdote.'),
(3052, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 7, 'OT', 'Ele o oferecerá perante o SENHOR e fará expiação por ela, e ela ficará purificada do fluxo do seu sangue. Esta é a lei da que dá à luz, seja menino ou menina.'),
(3053, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 12, 8, 'OT', 'E se a sua mão não alcançar o bastante para um cordeiro, então ela tomará duas rolas ou dois pombinhos, um para o holocausto e outro para a oferta pelo pecado; e o sacerdote fará expiação por ela, e ela será limpa.'),
(3054, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 1, 'OT', 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
(3055, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 2, 'OT', 'Quando um homem tiver na pele da sua carne inchação, ou crosta, ou mancha branca, e na pele da sua carne houver praga de lepra, será levado a Arão, o sacerdote, ou a um de seus filhos, os sacerdotes.'),
(3056, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 3, 'OT', 'E o sacerdote examinará a praga na pele da carne; se o cabelo na praga se tornou branco, e a praga parecer mais profunda do que a pele da sua carne, é praga de lepra; o sacerdote o examinará e o declarará imundo.'),
(3057, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 4, 'OT', 'Se, porém, a mancha for branca na pele da sua carne, e não parecer mais profunda do que a pele, e o pelo não se tiver tornado branco, então o sacerdote encerrará o que tem a praga por sete dias.'),
(3058, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 5, 'OT', 'E o sacerdote o examinará no sétimo dia; e eis que, se a praga parou aos seus olhos, e a praga não se estendeu na pele, então o sacerdote o encerrará por outros sete dias.'),
(3059, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 6, 'OT', 'E o sacerdote o examinará novamente no sétimo dia; e se a praga tiver diminuído, e a praga não se tiver espalhado na pele, então o sacerdote o declarará limpo: é uma erupção; e ele lavará as suas vestes, e será limpo.'),
(3060, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 7, 'OT', 'Mas, se a praga se espalhar grandemente na pele, depois que foi mostrada ao sacerdote para a sua purificação, será mostrada novamente ao sacerdote.'),
(3061, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 8, 'OT', 'E o sacerdote examinará, e eis que, se a mancha se estendeu na pele, o sacerdote o declarará imundo: é lepra.'),
(3062, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 9, 'OT', 'Quando houver praga de lepra em um homem, ele será levado ao sacerdote.'),
(3063, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 10, 'OT', 'O sacerdote examinará, e eis que, se houver inchaço branco na pele, e ela tiver tornado o cabelo branco, e houver carne viva na inchação,'),
(3064, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 11, 'OT', 'Lepra crônica é na pele da sua carne; portanto, o sacerdote o declarará imundo; não o isolará, porque imundo é.'),
(3065, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 12, 'OT', 'E se a lepra florescer na pele e cobrir toda a pele da pessoa que tem a praga, desde a cabeça até os pés, conforme tudo o que os olhos do sacerdote podem ver.'),
(3066, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 13, 'OT', 'O sacerdote examinará, e se a lepra tiver coberto todo o seu corpo, declarará limpo o que tem a praga: tudo se tornou branco; ele está limpo.'),
(3067, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 14, 'OT', 'No dia em que a carne viva aparecer nele, ele será impuro.'),
(3068, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 15, 'OT', 'O sacerdote examinará a carne viva e o declarará imundo; a carne viva é imunda, é lepra.'),
(3069, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 16, 'OT', 'Ou, se a carne viva voltar e se tornar branca, então virá ao sacerdote.'),
(3070, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 17, 'OT', 'O sacerdote o examinará, e se a praga se tornou branca, o sacerdote declarará a praga limpa; ele está limpo.'),
(3071, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 18, 'OT', 'E quando a carne tiver na pele uma úlcera, e ela sarar,'),
(3072, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 19, 'OT', 'E, no lugar da úlcera, houver uma inchação branca ou uma mancha branca avermelhada, será mostrada ao sacerdote.'),
(3073, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 20, 'OT', 'O sacerdote examinará, e se a aparência for mais profunda que a pele, e o cabelo dela se tornou branco, o sacerdote o declarará imundo: é praga de lepra que brotou na úlcera.'),
(3074, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 21, 'OT', 'E, se o sacerdote a examinar, e eis que nela não há pelo branco, nem está mais funda do que a pele, mas está esmaecida, então o sacerdote o encerrará por sete dias.'),
(3075, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 22, 'OT', 'E se a mancha se espalhar na pele, o sacerdote o declarará imundo; é praga.'),
(3076, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 23, 'OT', 'Mas, se a mancha permanecer no seu lugar e não se espalhar, é cicatriz da úlcera; o sacerdote o declarará limpo.'),
(3077, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 24, 'OT', 'Ou, quando na pele da carne houver queimadura de fogo, e a carne viva da queimadura for uma mancha branca, avermelhada ou branca,'),
(3078, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 25, 'OT', 'E o sacerdote a examinará; e eis que, se o cabelo na mancha se tornou branco, e a aparência dela é mais profunda do que a pele, é lepra que brotou na queimadura; portanto, o sacerdote o declarará imundo; é praga de lepra.'),
(3079, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 26, 'OT', 'E se o sacerdote a examinar, e eis que na mancha não há pelo branco, e ela não está mais funda do que a pele, mas está esmaecida, então o sacerdote o isolará por sete dias.'),
(3080, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 27, 'OT', 'O sacerdote o examinará no sétimo dia; se a mancha tiver se espalhado na pele, o sacerdote o declarará imundo; é praga de lepra.'),
(3081, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 28, 'OT', 'Mas se a mancha permanecer no seu lugar, não se espalhando pela pele, e tiver diminuído, é a elevação da queimadura; o sacerdote o declarará limpo, pois é cicatriz da queimadura.'),
(3082, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 29, 'OT', 'E quando um homem ou uma mulher tiver uma ferida na cabeça ou na barba,'),
(3083, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 30, 'OT', 'O sacerdote examinará a praga, e se ela parecer mais profunda do que a pele, e nela houver cabelo amarelo e fino, o sacerdote o declarará imundo; é tinha, é lepra da cabeça ou da barba.'),
(3084, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 31, 'OT', 'Se o sacerdote examinar a praga da tinha, e eis que a sua aparência não é mais profunda do que a pele, e não há nela pelo preto, então o sacerdote encerrará aquele que tem a praga da tinha por sete dias.'),
(3085, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 32, 'OT', 'O sacerdote examinará a praga no sétimo dia; e eis que, se a tinha não se estendeu, e não há nela pelo amarelo, nem a tinha parece mais funda do que a pele,'),
(3086, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 33, 'OT', 'Então se rapará, mas não rapará a tinha; e o sacerdote o encerrará por mais sete dias.'),
(3087, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 34, 'OT', 'E o sacerdote examinará a tinha no sétimo dia; e eis que, se a tinha não se tiver espalhado na pele, e a sua aparência não for mais profunda do que a pele, o sacerdote o declarará limpo; e ele lavará as suas vestes, e será limpo.'),
(3088, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 35, 'OT', 'Mas, se a tinha se estender grandemente na pele, depois da sua purificação,'),
(3089, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 36, 'OT', 'O sacerdote o examinará, e se a tinha tiver se espalhado na pele, o sacerdote não procurará pelo cabelo amarelo; ele está impuro.'),
(3090, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 37, 'OT', 'Mas, se aos seus olhos a tinha parou, e nela cresceu pelo preto, a tinha está curada; ele está limpo; e o sacerdote o declarará limpo.'),
(3091, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 38, 'OT', 'E quando um homem ou uma mulher tiver na pele da sua carne manchas brancas,'),
(3092, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 39, 'OT', 'O sacerdote examinará, e se na pele da sua carne houver manchas esbranquiçadas e apagadas, é eczema que floresceu na pele; ele está limpo.'),
(3093, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 40, 'OT', 'E quando um homem perder o cabelo da cabeça, é calvo; está limpo.'),
(3094, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 41, 'OT', 'Se lhe cair o cabelo da parte da frente da cabeça, é meio calvo; está limpo.'),
(3095, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 42, 'OT', 'E se na calva ou na meia-calva houver uma ferida branca avermelhada, é lepra florescendo na sua calva ou na sua meia-calva.'),
(3096, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 43, 'OT', 'O sacerdote o examinará, e se a elevação da praga estiver branca e avermelhada na calva ou na meia-calva, como a aparência da lepra na pele da carne,'),
(3097, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 44, 'OT', 'O homem é leproso; ele é impuro. O sacerdote o declarará impuro; na sua cabeça está a sua praga.'),
(3098, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 45, 'OT', 'E o leproso que tiver a praga, as suas vestes serão rasgadas, e a sua cabeça estará descoberta, e cobrirá o lábio superior, e clamará: Imundo, imundo!'),
(3099, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 46, 'OT', 'Todos os dias em que a praga estiver nele, será impuro; impuro está; habitará sozinho; fora do acampamento será a sua habitação.'),
(3100, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 47, 'OT', 'E a roupa, quando houver nela praga de lepra, em roupa de lã ou em roupa de linho,'),
(3101, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 48, 'OT', 'ou no fio urdido, ou no fio tecido, seja de linho, seja de lã, ou em couro, ou em qualquer obra de couro.'),
(3102, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 49, 'OT', 'E se a praga no vestido, ou na pele, ou no fio urdido, ou no fio tecido, ou em qualquer utensílio de couro, for esverdeada ou avermelhada, é praga de lepra; e será mostrada ao sacerdote.'),
(3103, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 50, 'OT', 'O sacerdote examinará a praga e encerrará a pessoa com a praga por sete dias.'),
(3104, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 51, 'OT', 'E examinará a praga no sétimo dia; se a praga se tiver espalhado no vestido, ou no fio urdido, ou no fio tecido, ou na pele, para qualquer obra que se faça da pele, é lepra maligna; a praga é imunda.'),
(3105, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 52, 'OT', 'Queimará o vestido, ou o fio urdido, ou o fio tecido, seja de lã ou de linho, ou qualquer objeto de couro em que estiver a praga, porque é lepra maligna; será queimado no fogo.'),
(3106, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 53, 'OT', 'Se o sacerdote examinar, e eis que a praga não se espalhou na roupa, ou no fio urdido, ou no tecido, ou em qualquer objeto de couro,'),
(3107, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 54, 'OT', 'Então o sacerdote ordenará que lavem aquilo em que está a praga, e o isolará por mais sete dias.'),
(3108, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 55, 'OT', 'E o sacerdote examinará a praga depois de ter sido lavada; e se a praga não mudou a sua aparência, e a praga não se espalhou, imundo é; com fogo a queimarás; é corrosão, seja na calva ou na testa.'),
(3109, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 56, 'OT', 'Se o sacerdote examinar e a mancha tiver diminuído depois de ter sido lavada, então ele a rasgará da roupa, ou do couro, ou do fio urdido, ou do fio tecido.'),
(3110, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 57, 'OT', 'E se ainda aparecer no vestido, ou no fio urdido ou tecido, ou em qualquer coisa de couro, é lepra brotante; com fogo queimarás aquilo em que estiver a praga.'),
(3111, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 58, 'OT', 'O vestido, ou o fio urdido, ou o tecido, ou qualquer coisa de couro que lavares, e a praga se retirar deles, será lavado segunda vez, e ficará limpo.'),
(3112, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 13, 59, 'OT', 'Esta é a lei da praga da lepra na roupa de lã ou de linho, ou no fio urdido ou tecido, ou em qualquer artigo de couro, para declará-la limpa ou para declará-la impura.'),
(3113, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3114, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 2, 'OT', 'Aqui está a tradução de Levítico 14:2: Esta será a lei do leproso no dia da sua purificação: será levado ao sacerdote.'),
(3115, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 3, 'OT', 'E o sacerdote sairá para fora do acampamento, e o sacerdote examinará, e eis que, se a praga da lepra do leproso estiver sarada,'),
(3116, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 4, 'OT', 'O sacerdote ordenará que, para aquele que se purifica, se tomem duas aves vivas e limpas, madeira de cedro, fio de carmesim e hissopo.'),
(3117, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 5, 'OT', 'E o sacerdote ordenará que se degole uma das aves num vaso de barro sobre águas vivas.'),
(3118, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 6, 'OT', 'Tomará a ave viva, e o pau de cedro, e o carmesim, e o hissopo, e os molhará, juntamente com a ave viva, no sangue da ave degolada sobre as águas vivas.'),
(3119, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 7, 'OT', 'E aspergirá sete vezes sobre o que se purifica da lepra; e o declarará limpo, e soltará a ave viva sobre a face do campo.'),
(3120, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 8, 'OT', 'E o que se purifica lavará as suas vestes, rapará todo o seu cabelo, e se banhará em água; assim será limpo. Depois entrará no acampamento, mas ficará fora da sua tenda por sete dias.'),
(3121, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 9, 'OT', 'E será que, no sétimo dia, rapará todo o seu cabelo: a cabeça, a barba e as sobrancelhas dos olhos; e rapará todo o seu outro cabelo; e lavará as suas vestes, e lavará o seu corpo com água, e será limpo.'),
(3122, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 10, 'OT', 'E ao oitavo dia tomará dois cordeiros sem defeito, e uma cordeira de um ano sem defeito, e três décimos de flor de farinha para oferta de manjares, amassada com azeite, e um log de azeite;'),
(3123, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 11, 'OT', 'E o sacerdote que purifica apresentará o homem que está sendo purificado, juntamente com aquelas ofertas, perante o SENHOR, à entrada da tenda do encontro.'),
(3124, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 12, 'OT', 'E o sacerdote tomará um dos cordeiros e o oferecerá como oferta pela culpa, juntamente com o logue de azeite, e os moverá como oferta movida perante o SENHOR.'),
(3125, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 13, 'OT', 'E degolará o cordeiro no lugar onde se degola a oferta pela culpa e o holocausto, no lugar santo; porque, assim como a oferta pela culpa, ele pertence ao sacerdote; é coisa santíssima.'),
(3126, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 14, 'OT', 'O sacerdote tomará do sangue da oferta pela culpa e o porá sobre o lóbulo da orelha direita daquele que se purifica, sobre o polegar da sua mão direita e sobre o polegar do seu pé direito.'),
(3127, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 15, 'OT', 'O sacerdote tomará do log de azeite e o derramará na palma da sua própria mão esquerda.'),
(3128, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 16, 'OT', 'O sacerdote molhará o seu dedo direito no azeite que está na sua mão esquerda, e com o seu dedo aspergirá do azeite sete vezes diante do SENHOR.'),
(3129, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 17, 'OT', 'E do restante do azeite que está na sua mão, o sacerdote porá sobre a ponta da orelha direita daquele que se purifica, e sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito, sobre o sangue da oferta pela culpa.'),
(3130, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 18, 'OT', 'E o restante do azeite que está na mão do sacerdote, ele o porá sobre a cabeça daquele que se purifica; e o sacerdote fará expiação por ele diante do SENHOR.'),
(3131, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 19, 'OT', 'O sacerdote oferecerá a oferta pelo pecado e fará expiação por aquele que se purifica da sua impureza; e depois sacrificará o holocausto.'),
(3132, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 20, 'OT', 'E o sacerdote oferecerá o holocausto e a oferta de cereais sobre o altar; assim o sacerdote fará expiação por ele, e ele será limpo.'),
(3133, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 21, 'OT', 'Se, porém, for pobre e a sua mão não alcançar tanto, tomará um cordeiro para oferta pela culpa, para oferta de movimento, para fazer expiação por ele, e um décimo de flor de farinha amassada com azeite, para oferta de manjares, e um logue de azeite.'),
(3134, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 22, 'OT', 'E duas rolas ou dois pombinhos, conforme a sua mão puder alcançar; um será para oferta pelo pecado, e o outro para holocausto.'),
(3135, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 23, 'OT', 'E ao oitavo dia da sua purificação, os trará ao sacerdote, à entrada da tenda da congregação, perante o SENHOR.'),
(3136, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 24, 'OT', 'O sacerdote tomará o cordeiro da oferta pela culpa e o log de azeite, e o sacerdote os moverá como oferta movida perante o SENHOR.'),
(3137, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 25, 'OT', 'E degolará o cordeiro da oferta pela culpa, e o sacerdote tomará do sangue da oferta pela culpa, e o porá sobre o lóbulo da orelha direita daquele que se purifica, e sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito.'),
(3138, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 26, 'OT', 'E o sacerdote derramará do azeite sobre a palma da sua própria mão esquerda.'),
(3139, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 27, 'OT', 'E o sacerdote aspergirá com o seu dedo direito do óleo que está na sua mão esquerda, sete vezes perante o SENHOR.'),
(3140, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 28, 'OT', 'E o sacerdote porá do óleo que está na sua mão sobre o lóbulo da orelha direita daquele que se purifica, e sobre o polegar da sua mão direita, e sobre o polegar do seu pé direito, no lugar do sangue da oferta pela culpa.'),
(3141, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 29, 'OT', 'E o restante do azeite que está na mão do sacerdote, ele o porá sobre a cabeça daquele que se purifica, para fazer expiação por ele perante o SENHOR.'),
(3142, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 30, 'OT', 'E oferecerá uma das rolas ou um dos pombinhos, conforme a sua mão alcançar.'),
(3143, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 31, 'OT', 'Daquilo que a sua mão alcançar, um será para a oferta pela culpa e o outro para o holocausto, juntamente com a oferta de cereais; e o sacerdote fará expiação por aquele que se purifica diante do SENHOR.'),
(3144, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 32, 'OT', 'Esta é a lei daquele em quem houver praga de lepra, cuja mão não alcançar o necessário para a sua purificação.'),
(3145, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 33, 'OT', 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
(3146, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 34, 'OT', 'Quando vocês entrarem na terra de Canaã, que eu lhes dou por possessão, e eu enviar uma praga de lepra em alguma casa da terra da possessão de vocês,'),
(3147, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 35, 'OT', 'Então virá aquele a quem pertence a casa e dirá ao sacerdote: "Parece-me que há uma praga em minha casa."'),
(3148, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 36, 'OT', 'O sacerdote ordenará que esvaziem a casa antes que ele entre para examinar a praga, para que nada do que está na casa se torne impuro; e depois o sacerdote entrará para examinar a casa.'),
(3149, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 37, 'OT', 'E, examinando a praga, eis que a praga nas paredes da casa tem depressões esverdeadas ou avermelhadas, e a sua aparência é mais funda do que a parede.'),
(3150, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 38, 'OT', 'O sacerdote sairá da casa até a entrada da casa, e fechará a casa por sete dias.'),
(3151, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 39, 'OT', 'E o sacerdote voltará no sétimo dia e examinará; e eis que a praga se espalhou nas paredes da casa.'),
(3152, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 40, 'OT', 'Então o sacerdote ordenará que arranquem as pedras em que estiver a praga e as lancem para fora da cidade, num lugar impuro.'),
(3153, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 41, 'OT', 'E fará raspar a casa por dentro ao redor, e o pó que houverem raspado lançarão fora da cidade, num lugar imundo.'),
(3154, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 42, 'OT', 'Tomarão outras pedras e as colocarão no lugar das primeiras pedras; e tomarão outro barro e rebocarão a casa.'),
(3155, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 43, 'OT', 'Porém, se a praga voltar e brotar na casa, depois de se arrancarem as pedras, e depois de se raspar a casa, e depois de se rebocar,'),
(3156, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 44, 'OT', 'O sacerdote entrará e examinará; e eis que, se a praga se tiver espalhado na casa, é lepra roedora na casa; imunda está.'),
(3157, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 45, 'OT', 'Derribará a casa, as suas pedras, a sua madeira e todo o pó da casa, e levará tudo para fora da cidade, a um lugar impuro.'),
(3158, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 46, 'OT', 'E quem entrar na casa em qualquer dia em que ela estiver fechada ficará impuro até a tarde.'),
(3159, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 47, 'OT', 'E quem se deitar na casa lavará as suas roupas; e quem comer na casa lavará as suas roupas.'),
(3160, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 48, 'OT', 'E, se o sacerdote entrar e examinar, e eis que a praga não se espalhou na casa depois que a casa foi rebocada, então o sacerdote declarará a casa limpa, porque a praga está curada.'),
(3161, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 49, 'OT', 'Tomará, para expiar a casa, duas aves, madeira de cedro, fio de carmesim e hissopo.'),
(3162, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 50, 'OT', 'E degolará uma das aves num vaso de barro sobre águas vivas.'),
(3163, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 51, 'OT', 'Então tomará o pau de cedro, o hissopo, o carmesim e a ave viva, e os molhará no sangue da ave degolada e nas águas vivas, e aspergirá a casa sete vezes.'),
(3164, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 52, 'OT', 'E assim purificará a casa com o sangue da ave, e com as águas vivas, e com a ave viva, e com a madeira de cedro, e com o hissopo, e com o carmesim.'),
(3165, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 53, 'OT', 'Soltará a ave viva para fora da cidade, sobre a face do campo; assim fará expiação pela casa, e ela será limpa.'),
(3166, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 54, 'OT', 'Esta é a lei para toda praga da lepra e para a tinha.'),
(3167, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 55, 'OT', 'e para a lepra das roupas e das casas,'),
(3168, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 56, 'OT', 'e para a inchação, e para a erupção, e para a mancha brilhante.'),
(3169, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 14, 57, 'OT', 'para ensinar quando algo está impuro e quando está puro. Esta é a lei da lepra.'),
(3170, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 1, 'OT', 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
(3171, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 2, 'OT', 'Falem aos filhos de Israel e digam-lhes: Qualquer homem que tiver fluxo da sua carne, esse fluxo o torna impuro.'),
(3172, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 3, 'OT', 'Esta será a sua impureza por causa do seu fluxo: se a sua carne escorre do seu fluxo, ou se a sua carne se retém do seu fluxo, esta é a sua impureza.'),
(3173, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 4, 'OT', 'Todo leito sobre o qual se deitar aquele que tem fluxo será impuro, e todo objeto sobre o qual se assentar será impuro.'),
(3174, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 5, 'OT', 'E o homem que tocar na sua cama lavará as suas roupas, banhar-se-á em água e ficará impuro até a tarde.'),
(3175, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 6, 'OT', 'E quem se assentar sobre aquilo em que se assentou o que tem o fluxo, lavará as suas vestes, banhar-se-á em água e será imundo até a tarde.'),
(3176, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 7, 'OT', 'E quem tocar a carne do que tem fluxo lavará as suas vestes, banhar-se-á em água e será imundo até a tarde.'),
(3177, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 8, 'OT', 'E se o que tem fluxo cuspir sobre alguém limpo, lavará as suas vestes, banhar-se-á em água e ficará imundo até a tarde.'),
(3178, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 9, 'OT', 'E todo o veículo sobre o qual cavalgar o que tem fluxo será imundo.'),
(3179, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 10, 'OT', 'E todo aquele que tocar em qualquer coisa que estiver debaixo dele ficará impuro até a tarde; e aquele que as carregar lavará as suas roupas, banhar-se-á em água e ficará impuro até a tarde.'),
(3180, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 11, 'OT', 'Todo aquele em quem tocar o que tem fluxo, sem ter lavado as mãos com água, lavará as suas vestes, banhar-se-á em água e será imundo até a tarde.'),
(3181, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 12, 'OT', 'E o vaso de barro que o homem com fluxo tocar será quebrado; e todo vaso de madeira será lavado com água.'),
(3182, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 13, 'OT', 'Quando o homem com fluxo ficar limpo do seu fluxo, contará para si sete dias para a sua purificação, e lavará as suas vestes, e banhará o seu corpo em águas vivas, e será limpo.'),
(3183, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 14, 'OT', 'E no oitavo dia tomará para si duas rolas ou dois pombinhos, e virá perante o SENHOR, à entrada da tenda da congregação, e os dará ao sacerdote.'),
(3184, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 15, 'OT', 'E o sacerdote os oferecerá: um como oferta pela culpa e o outro como holocausto; e o sacerdote fará expiação por ele diante do SENHOR por causa do seu fluxo.'),
(3185, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 16, 'OT', 'E se um homem tiver emissão de sêmen, banhará todo o seu corpo em água e ficará impuro até a tarde.'),
(3186, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 17, 'OT', 'Todo vestido e toda pele sobre a qual houver semente de relação sexual será lavado com água, e ficará imundo até a tarde.'),
(3187, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 18, 'OT', 'E também a mulher com quem um homem se deitar com semente de cópula, ambos se banharão em água e ficarão impuros até a tarde.'),
(3188, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 19, 'OT', 'E a mulher, quando tiver fluxo, e o seu fluxo de sangue estiver na sua carne, estará sete dias na sua separação; e qualquer que a tocar será imundo até a tarde.'),
(3189, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 20, 'OT', 'E tudo sobre o que ela se deitar durante a sua impureza será impuro; e tudo sobre o que ela se assentar será impuro.'),
(3190, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 21, 'OT', 'E todo aquele que tocar na sua cama lavará as suas roupas, banhar-se-á em água e ficará impuro até a tarde.'),
(3191, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 22, 'OT', 'E todo aquele que tocar em qualquer coisa sobre a qual ela se tenha assentado lavará as suas vestes, banhar-se-á em água e ficará imundo até a tarde.'),
(3192, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 23, 'OT', 'Se também estiver sobre a cama, ou sobre o objeto em que ela se assenta, ao tocá-lo, ficará impuro até a tarde.'),
(3193, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 24, 'OT', 'E se um homem se deitar com ela, e a sua impureza estiver sobre ele, será imundo por sete dias; e toda cama sobre a qual se deitar será imunda.'),
(3194, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 25, 'OT', 'E se uma mulher tiver fluxo de sangue por muitos dias, fora do tempo da sua menstruação, ou se tiver fluxo além do tempo da sua menstruação, todos os dias do fluxo da sua impureza serão como os dias da sua menstruação; ela será impura.'),
(3195, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 26, 'OT', 'Toda cama sobre a qual se deitar durante todos os dias do seu fluxo será para ela como a cama da sua impureza menstrual; e todo objeto sobre o qual se assentar será impuro, conforme a impureza da sua menstruação.'),
(3196, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 27, 'OT', 'E qualquer que os tocar será imundo; portanto, lavará as suas vestes, e se banhará em água, e será imundo até a tarde.'),
(3197, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 28, 'OT', 'E se ela ficar limpa do seu fluxo, contará para si sete dias, e depois será limpa.'),
(3198, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 29, 'OT', 'E ao oitavo dia tomará para si duas rolas ou dois pombinhos, e os trará ao sacerdote, à entrada da tenda da congregação.'),
(3199, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 30, 'OT', 'O sacerdote oferecerá um como oferta pela culpa e o outro como holocausto; e o sacerdote fará expiação por ela diante do SENHOR, por causa do fluxo da sua impureza.'),
(3200, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 31, 'OT', 'Assim vocês manterão os filhos de Israel separados da sua impureza, para que não morram na sua impureza, por contaminarem o meu tabernáculo, que está no meio deles.'),
(3201, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 32, 'OT', 'Esta é a lei daquele que tem fluxo e daquele de quem sai emissão de sêmen, tornando-se impuro por ela.'),
(3202, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 15, 33, 'OT', 'e da mulher no seu período de impureza, e do homem que tem fluxo, seja homem ou mulher, e do homem que se deita com mulher impura.'),
(3203, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 1, 'OT', 'Falou o SENHOR a Moisés, depois da morte dos dois filhos de Arão, quando se aproximaram diante do SENHOR e morreram.'),
(3204, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 2, 'OT', 'Disse o SENHOR a Moisés: Fala a Arão, teu irmão, que não entre em todo tempo no lugar santo, para dentro do véu, diante do propiciatório que está sobre a arca, para que não morra; porque na nuvem eu apareço sobre o propiciatório.'),
(3205, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 3, 'OT', 'Com isto Arão entrará no santuário: com um novilho para oferta pela culpa e um carneiro para holocausto.'),
(3206, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 4, 'OT', 'Vestirá a túnica sagrada de linho, e terá calções de linho sobre o seu corpo, e cingir-se-á com um cinto de linho, e cobrirá a cabeça com uma mitra de linho; estas são vestes sagradas. Banhará o seu corpo com água e as vestirá.'),
(3207, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 5, 'OT', 'E da congregação dos filhos de Israel tomará dois bodes para oferta pelo pecado e um carneiro para holocausto.'),
(3208, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 6, 'OT', 'E Arão apresentará o novilho da oferta pela culpa, que é dele, e fará expiação por si mesmo e pela sua casa.'),
(3209, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 7, 'OT', 'Tomará os dois bodes e os colocará diante do SENHOR, à entrada da tenda do encontro.'),
(3210, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 8, 'OT', 'E Arão lançará sortes sobre os dois bodes: uma sorte para o SENHOR, e a outra sorte para Azazel.'),
(3211, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 9, 'OT', 'Então Arão apresentará o bode sobre o qual caiu a sorte para o SENHOR e o oferecerá como oferta pelo pecado.'),
(3212, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 10, 'OT', 'Mas o bode sobre o qual caiu a sorte para Azazel será apresentado vivo diante do SENHOR, para fazer expiação por ele, a fim de enviá-lo ao deserto como Azazel.'),
(3213, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 11, 'OT', 'E Arão apresentará o novilho da oferta pelo pecado, que é dele, e fará expiação por si mesmo e pela sua casa; e degolará o novilho da oferta pelo pecado, que é dele.'),
(3214, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 12, 'OT', 'Tomará o incensário cheio de brasas de fogo do altar, de diante do SENHOR, e as suas mãos cheias de incenso aromático moído, e o trará para dentro do véu.'),
(3215, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 13, 'OT', 'E porá o incenso sobre o fogo perante o SENHOR, e a nuvem do incenso cobrirá o propiciatório que está sobre o testemunho, para que não morra.'),
(3216, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 14, 'OT', 'E tomará do sangue do novilho e com o seu dedo aspergirá sobre a frente do propiciatório, para o lado oriental; e diante do propiciatório aspergirá sete vezes do sangue com o seu dedo.'),
(3217, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 15, 'OT', 'E matará o bode da oferta pelo pecado, que é para o povo, e trará o seu sangue para dentro do véu; e fará com o seu sangue como fez com o sangue do novilho, e o aspergirá sobre o propiciatório e diante do propiciatório.'),
(3218, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 16, 'OT', 'E assim fará expiação pelo santuário, por causa das impurezas dos filhos de Israel e das suas transgressões, segundo todos os seus pecados; e assim fará pela tenda do encontro, que habita com eles no meio das suas impurezas.'),
(3219, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 17, 'OT', 'Nenhum homem estará na tenda do encontro quando ele entrar para fazer expiação no santuário, até que ele saia; e ele fará expiação por si mesmo, pela sua casa e por toda a congregação de Israel.'),
(3220, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 18, 'OT', 'Então sairá ao altar que está diante do SENHOR e fará expiação por ele; e tomará do sangue do novilho e do sangue do bode, e o porá sobre os chifres do altar ao redor.'),
(3221, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 19, 'OT', 'E daquele sangue espargirá sobre ele com o seu dedo sete vezes, e o purificará e o santificará das impurezas dos filhos de Israel.'),
(3222, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 20, 'OT', 'E, tendo terminado de fazer expiação pelo santuário, pela tenda da congregação e pelo altar, apresentará o bode vivo.'),
(3223, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 21, 'OT', 'E Arão porá as suas duas mãos sobre a cabeça do bode vivo e confessará sobre ele todas as iniquidades dos filhos de Israel e todas as suas transgressões, segundo todos os seus pecados; e os porá sobre a cabeça do bode, e o enviará ao deserto pela mão de um homem designado para isso.'),
(3224, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 22, 'OT', 'O bode levará sobre si todas as iniquidades deles para uma terra árida; e enviará o bode ao deserto.'),
(3225, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 23, 'OT', 'Então Arão virá à tenda do encontro, e despirá as vestes de linho que vestira ao entrar no lugar santo, e as deixará ali.'),
(3226, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 24, 'OT', 'E lavará o seu corpo com água no lugar santo e vestirá as suas vestes; então sairá e oferecerá o seu holocausto e o holocausto do povo, e fará expiação por si mesmo e pelo povo.'),
(3227, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 25, 'OT', 'Também queimará sobre o altar a gordura da oferta pelo pecado.'),
(3228, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 26, 'OT', 'E aquele que soltar o bode para Azazel lavará as suas vestes e banhará o seu corpo em água; e depois disso entrará no acampamento.'),
(3229, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 27, 'OT', 'E o novilho da oferta pelo pecado e o bode da oferta pelo pecado, cujo sangue foi trazido para fazer expiação no santuário, serão levados para fora do acampamento; e queimarão no fogo as suas peles, a sua carne e o seu esterco.'),
(3230, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 28, 'OT', 'E aquele que os queimar lavará as suas roupas e banhará o seu corpo em água; e depois disso entrará no acampamento.'),
(3231, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 29, 'OT', 'E isto vos será por estatuto perpétuo: no sétimo mês, aos dez do mês, afligireis as vossas almas, e nenhuma obra fareis, nem o natural nem o estrangeiro que peregrina entre vós.'),
(3232, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 30, 'OT', 'Porque neste dia se fará expiação por vós, para vos purificar; de todos os vossos pecados sereis purificados perante o SENHOR.'),
(3233, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 31, 'OT', 'É um sábado de descanso solene para vós, e afligireis as vossas almas; é estatuto perpétuo.'),
(3234, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 32, 'OT', 'E o sacerdote que for ungido e consagrado para ministrar como sacerdote no lugar de seu pai fará a expiação, vestindo as vestes de linho, as vestes santas.'),
(3235, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 33, 'OT', 'E assim fará expiação pelo santuário santíssimo, e pela tenda da congregação, e pelo altar; e fará expiação pelos sacerdotes e por todo o povo da congregação.'),
(3236, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 16, 34, 'OT', 'Isto será para vós um estatuto perpétuo, para fazer expiação pelos filhos de Israel de todos os seus pecados, uma vez por ano. E fez como o SENHOR ordenou a Moisés.'),
(3237, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3238, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 2, 'OT', 'Fala a Arão e a seus filhos e a todos os filhos de Israel, e dize-lhes: Esta é a palavra que o SENHOR ordenou, dizendo:'),
(3239, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 3, 'OT', 'Qualquer homem da casa de Israel que sacrificar boi, ou ovelha, ou cabra, no acampamento, ou que os sacrificar fora do acampamento,'),
(3240, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 4, 'OT', 'E não o trouxer à porta da tenda da congregação, para oferecer oferta ao SENHOR diante do tabernáculo do SENHOR, a esse homem será imputado o sangue; derramou sangue; e esse homem será eliminado do meio do seu povo.'),
(3241, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 5, 'OT', 'Para que os filhos de Israel tragam os seus sacrifícios, que oferecem sobre a face do campo, e os apresentem ao SENHOR, à entrada da tenda da congregação, ao sacerdote, e os sacrifiquem como ofertas pacíficas ao SENHOR.'),
(3242, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 6, 'OT', 'O sacerdote aspergirá o sangue sobre o altar do SENHOR, à entrada da tenda do encontro, e queimará a gordura como aroma agradável ao SENHOR.'),
(3243, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 7, 'OT', 'E não sacrificarão mais os seus sacrifícios aos demônios, após os quais eles se prostituem; isto lhes será por estatuto perpétuo nas suas gerações.'),
(3244, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 8, 'OT', 'Dize-lhes: Qualquer homem da casa de Israel, ou do estrangeiro que peregrina no meio deles, que oferecer holocausto ou sacrifício,'),
(3245, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 9, 'OT', 'e não o trouxer à entrada da tenda do encontro, para oferecê-lo ao SENHOR, esse homem será eliminado do seu povo.'),
(3246, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 10, 'OT', 'E qualquer homem de Israel, ou dos estrangeiros que habitam entre eles, que comer qualquer sangue, contra essa alma que comer sangue porei a minha face e a eliminarei do meio do seu povo.'),
(3247, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 11, 'OT', 'Porque a vida da carne está no sangue, e eu o dei a vocês sobre o altar para fazer expiação pelas suas vidas; pois é o sangue que faz expiação pela vida.'),
(3248, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 12, 'OT', 'Portanto, tenho dito aos filhos de Israel: Nenhuma alma de entre vós comerá sangue, nem o estrangeiro que habita no meio de vós comerá sangue.'),
(3249, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 13, 'OT', 'E qualquer homem dentre os filhos de Israel, ou dentre os estrangeiros que habitam no meio deles, que caçar caça de animal ou de ave que se come, derramará o seu sangue e o cobrirá com pó.'),
(3250, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 14, 'OT', 'Porque a vida de toda carne é o seu sangue; o sangue está na vida. Por isso eu disse aos filhos de Israel: Não comereis o sangue de nenhuma carne, porque a vida de toda carne é o seu sangue; todo aquele que o comer será eliminado.'),
(3251, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 15, 'OT', 'E toda pessoa, entre os nativos ou entre os estrangeiros, que comer corpo morto ou animal dilacerado, lavará as suas vestes, banhar-se-á em água, e ficará impura até a tarde; então será limpa.'),
(3252, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 17, 16, 'OT', 'Mas, se não os lavar e não banhar o seu corpo, levará sobre si a sua iniquidade.'),
(3253, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3254, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: Eu sou o SENHOR, vosso Deus.'),
(3255, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 3, 'OT', 'Não fareis como as obras da terra do Egito, em que habitastes, nem fareis como as obras da terra de Canaã, para a qual eu vos trago, nem andareis nos seus estatutos.'),
(3256, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 4, 'OT', 'Executareis os meus juízos e guardareis os meus estatutos, para andardes neles. Eu sou o SENHOR, vosso Deus.'),
(3257, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 5, 'OT', 'Guardareis os meus estatutos e os meus juízos; o homem que os cumprir viverá por eles. Eu sou o SENHOR.'),
(3258, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 6, 'OT', 'Nenhum homem se aproximará de qualquer parenta da sua carne para descobrir a sua nudez; eu sou o SENHOR.'),
(3259, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 7, 'OT', 'Não descobrirás a nudez de teu pai nem a nudez de tua mãe; ela é tua mãe; não descobrirás a sua nudez.'),
(3260, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 8, 'OT', 'Não descobrirás a nudez da mulher de teu pai; é a nudez de teu pai.'),
(3261, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 9, 'OT', 'A nudez da tua irmã, filha do teu pai ou filha da tua mãe, nascida em casa ou nascida fora, não descobrirás a nudez delas.'),
(3262, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 10, 'OT', 'A nudez da filha do teu filho ou da filha da tua filha, não descobrirás a nudez delas; porque elas são a tua própria nudez.'),
(3263, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 11, 'OT', 'A nudez da filha da mulher de teu pai, gerada de teu pai, ela é tua irmã; não descobrirás a sua nudez.'),
(3264, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 12, 'OT', 'Não descobrirás a nudez da irmã de teu pai; ela é parenta de teu pai.'),
(3265, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 13, 'OT', 'Não descobrirás a nudez da irmã de tua mãe; pois ela é parenta de tua mãe.'),
(3266, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 14, 'OT', 'Não descobrirás a nudez do irmão de teu pai; não te aproximarás de sua mulher; ela é tua tia.'),
(3267, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 15, 'OT', 'Não descobrirás a nudez da tua nora; ela é mulher do teu filho; não descobrirás a sua nudez.'),
(3268, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 16, 'OT', 'Não descobrirás a nudez da mulher do teu irmão; é a nudez do teu irmão.'),
(3269, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 17, 'OT', 'Não descobrirás a nudez de uma mulher e de sua filha; não tomarás a filha de seu filho nem a filha de sua filha para descobrir a sua nudez; são parentas próximas; é perversidade.'),
(3270, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 18, 'OT', 'Não tomarás uma mulher juntamente com sua irmã, para torná-la rival, descobrindo a sua nudez enquanto ela viver.'),
(3271, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 19, 'OT', 'E não te aproximarás de mulher durante a impureza da sua menstruação, para descobrir a sua nudez.'),
(3272, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 20, 'OT', 'Não te deitarás com a mulher do teu próximo, para te contaminares com ela, derramando a tua semente.'),
(3273, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 21, 'OT', 'Não darás nenhum dos teus filhos para serem oferecidos a Moloque, e não profanarás o nome do teu Deus. Eu sou o SENHOR.'),
(3274, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 22, 'OT', 'Não te deitarás com um homem como quem se deita com mulher; é abominação.'),
(3275, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 23, 'OT', 'Não te deitarás com nenhum animal, para te contaminar com ele; e a mulher não se porá diante de um animal, para se ajuntar com ele; é abominação.'),
(3276, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 24, 'OT', 'Não vos contamineis com nenhuma dessas coisas, porque com todas essas coisas se contaminaram as nações que eu lanço fora de diante de vós.'),
(3277, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 25, 'OT', 'E a terra se contaminou; e eu castiguei a sua iniquidade sobre ela; e a terra vomitou os seus habitantes.'),
(3278, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 26, 'OT', 'Guardareis, pois, os meus estatutos e os meus juízos, e não fareis nenhuma destas abominações, tanto o natural como o estrangeiro que peregrina no meio de vós.'),
(3279, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 27, 'OT', 'Porque todas estas abominações cometeram os homens da terra que estavam antes de vós, e a terra foi contaminada.'),
(3280, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 28, 'OT', 'para que a terra não vos vomite, por a terdes contaminado, como vomitou a nação que estava antes de vós.'),
(3281, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 29, 'OT', 'Pois todo aquele que fizer qualquer destas abominações, as pessoas que as fizerem serão eliminadas do meio do seu povo.'),
(3282, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 18, 30, 'OT', 'Guardem os meus mandamentos, não praticando nenhum dos estatutos abomináveis que se fizeram antes de vocês, e não se contaminem com eles. Eu sou o SENHOR, o Deus de vocês.'),
(3283, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3284, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 2, 'OT', 'Fala a toda a congregação dos filhos de Israel e dize-lhes: Santos sereis, porque santo sou eu, o SENHOR, vosso Deus.'),
(3285, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 3, 'OT', 'Cada um de vocês respeitará sua mãe e seu pai, e guardará os meus sábados. Eu sou o SENHOR, o Deus de vocês.'),
(3286, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 4, 'OT', 'Não se voltem para os ídolos, nem façam para vocês deuses de metal fundido. Eu sou o SENHOR, o Deus de vocês.'),
(3287, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 5, 'OT', 'E quando oferecerdes sacrifício pacífico ao SENHOR, oferecei-o de vossa livre vontade.'),
(3288, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 6, 'OT', 'No dia em que o sacrificardes, e no dia seguinte, se comerá; mas o que sobejar até o terceiro dia será queimado no fogo.'),
(3289, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 7, 'OT', 'E, se dela se comer ao terceiro dia, é coisa abominável; não será aceita.'),
(3290, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 8, 'OT', 'Aquele que o comer levará a sua iniquidade, pois profanou o que é santo do SENHOR; e essa pessoa será eliminada do meio do seu povo.'),
(3291, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 9, 'OT', 'Quando vocês fizerem a colheita da sua terra, não colham totalmente os cantos do seu campo, nem recolham as espigas caídas da sua colheita.'),
(3292, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 10, 'OT', 'Não colherás os restos da tua vinha, nem apanharás as uvas caídas da tua vinha; deixá-las-ás para o pobre e para o estrangeiro. Eu sou o SENHOR, vosso Deus.'),
(3293, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 11, 'OT', 'Não furtareis, nem enganareis, nem mentireis uns aos outros.'),
(3294, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 12, 'OT', 'Não jurem falso pelo meu nome, profanando assim o nome do seu Deus. Eu sou o SENHOR.'),
(3295, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 13, 'OT', 'Não oprimirás o teu próximo, nem o roubarás; a paga do trabalhador não ficará contigo até a manhã.'),
(3296, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 14, 'OT', 'Não amaldiçoes o surdo, nem ponhas tropeço diante do cego; mas teme o teu Deus. Eu sou o SENHOR.'),
(3297, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 15, 'OT', 'Não cometerás injustiça no julgamento; não favorecerás o pobre nem honrarás o grande; com justiça julgarás o teu próximo.'),
(3298, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 16, 'OT', 'Não andarás como difamador entre o teu povo; não te levantarás contra a vida do teu próximo. Eu sou o SENHOR.'),
(3299, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 17, 'OT', 'Não odeies teu irmão no teu coração; repreende francamente o teu próximo, para que não participes do seu pecado.'),
(3300, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 18, 'OT', 'Não te vingarás nem guardarás rancor contra os filhos do teu povo; mas amarás o teu próximo como a ti mesmo: Eu sou o SENHOR.'),
(3301, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 19, 'OT', 'Guardarás os meus estatutos: não cruzarás os teus animais com espécies diferentes; não semearás o teu campo com duas espécies de semente; e não vestirás roupa feita de dois tipos de fio misturados.'),
(3302, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 20, 'OT', 'E se um homem se deitar com uma mulher que é serva prometida a outro homem, mas que não foi resgatada nem recebeu liberdade, haverá punição; não serão mortos, porque ela não foi libertada.'),
(3303, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 21, 'OT', 'E trará a sua oferta pela culpa ao SENHOR, à entrada da tenda do encontro, um carneiro como oferta pela culpa.'),
(3304, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 22, 'OT', 'E o sacerdote fará expiação por ele com o carneiro da oferta pela culpa diante do SENHOR, pelo seu pecado que pecou; e lhe será perdoado o pecado que pecou.'),
(3305, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 23, 'OT', 'Quando entrarem na terra e plantarem toda árvore frutífera, considerarão o seu fruto como incircunciso; por três anos ele será incircunciso para vocês; não se comerá dele.'),
(3306, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 24, 'OT', 'No quarto ano, todo o seu fruto será santo, para louvor ao SENHOR.'),
(3307, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 25, 'OT', 'E no quinto ano comereis o seu fruto, para que ele vos acrescente a sua colheita; eu sou o SENHOR, vosso Deus.'),
(3308, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 26, 'OT', 'Não comereis sobre o sangue; não praticareis adivinhações nem agouros.'),
(3309, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 27, 'OT', 'Não cortareis o cabelo nas laterais da cabeça, nem danificareis as pontas da barba.'),
(3310, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 28, 'OT', 'Não fareis cortes no vosso corpo pelos mortos, nem fareis marca de tatuagem sobre vós; eu sou o SENHOR.'),
(3311, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 29, 'OT', 'Não profanarás a tua filha, fazendo-a prostituir-se; e a terra não se prostituirá, nem se encherá de maldade.'),
(3312, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 30, 'OT', 'Guardareis os meus sábados e reverenciareis o meu santuário: Eu sou o SENHOR.'),
(3313, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 31, 'OT', 'Não se voltem para os médiuns nem para os que consultam os mortos; não os busquem, para não se contaminarem com eles. Eu sou o SENHOR, o Deus de vocês.'),
(3314, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 32, 'OT', 'Diante das cãs te levantarás, e honrarás a face do ancião; e temerás o teu Deus: Eu sou o SENHOR.'),
(3315, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 33, 'OT', 'Quando um estrangeiro habitar convosco na vossa terra, não o oprimireis.'),
(3316, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 34, 'OT', 'Como um natural entre vós será para vós o estrangeiro que habita convosco, e amá-lo-ás como a ti mesmo, pois estrangeiros fostes na terra do Egito; eu sou o SENHOR, vosso Deus.'),
(3317, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 35, 'OT', 'Não cometereis injustiça no julgamento, nem na medida, nem no peso, nem na quantidade.'),
(3318, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 36, 'OT', 'Balanças justas, pesos justos, efa justa e justo him tereis; eu sou o SENHOR, vosso Deus, que vos tirei da terra do Egito.'),
(3319, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 19, 37, 'OT', 'Guardareis todos os meus estatutos e todos os meus juízos, e os cumprireis: Eu sou o SENHOR.'),
(3320, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3321, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 2, 'OT', 'Diga aos filhos de Israel: Qualquer homem dos filhos de Israel ou dos estrangeiros que habitam em Israel que der da sua descendência a Moloque certamente será morto; o povo da terra o apedrejará.'),
(3322, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 3, 'OT', 'E eu porei a minha face contra esse homem e o eliminarei do meio do seu povo, porque deu da sua semente a Moloque, para contaminar o meu santuário e profanar o meu santo nome.'),
(3323, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 4, 'OT', 'E se o povo da terra de alguma forma fechar os olhos para aquele homem, quando ele der da sua semente a Moloque, para não o matar,'),
(3324, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 5, 'OT', 'Então porei a minha face contra aquele homem e contra a sua família, e o eliminarei do meio do seu povo, juntamente com todos os que se prostituem após ele, prostituindo-se após Moloque.'),
(3325, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 6, 'OT', 'E a pessoa que se voltar para os médiuns e para os feiticeiros, para se prostituir após eles, eu porei a minha face contra essa pessoa e a eliminarei do meio do seu povo.'),
(3326, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 7, 'OT', 'Santificai-vos e sede santos, porque eu sou o SENHOR, vosso Deus.'),
(3327, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 8, 'OT', 'Guardem os meus estatutos e pratiquem-nos. Eu sou o SENHOR que os santifica.'),
(3328, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 9, 'OT', 'Todo homem que amaldiçoar seu pai ou sua mãe certamente será morto; amaldiçoou seu pai ou sua mãe, o seu sangue será sobre ele.'),
(3329, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 10, 'OT', 'O homem que adulterar com a mulher de outro homem, que adulterar com a mulher do seu próximo, certamente será morto, tanto o adúltero quanto a adúltera.'),
(3330, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 11, 'OT', 'E o homem que se deitar com a mulher de seu pai descobriu a nudez de seu pai; ambos certamente morrerão; o seu sangue é sobre eles.'),
(3331, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 12, 'OT', 'E um homem que se deitar com a sua nora, ambos certamente morrerão; fizeram confusão; o seu sangue é sobre eles.'),
(3332, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 13, 'OT', 'E um homem que se deitar com outro homem, como quem se deita com mulher, ambos cometeram abominação; certamente serão mortos; o seu sangue cairá sobre eles.'),
(3333, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 14, 'OT', 'E, se um homem tomar uma mulher e também a mãe dela, isso é perversidade; serão queimados com fogo, ele e elas, para que não haja perversidade no meio de vocês.'),
(3334, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 15, 'OT', 'E um homem que der a sua cópula a um animal certamente será morto; e matareis o animal.'),
(3335, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 16, 'OT', 'E se uma mulher se aproximar de algum animal para se deitar com ele, matarás a mulher e o animal; certamente morrerão; o seu sangue será sobre eles.'),
(3336, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 17, 'OT', 'E se um homem tomar a sua irmã, filha de seu pai ou filha de sua mãe, e vir a nudez dela, e ela vir a nudez dele, isso é vergonha; serão eliminados diante dos filhos do seu povo. Ele descobriu a nudez de sua irmã; levará sobre si a sua iniquidade.'),
(3337, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 18, 'OT', 'E um homem que se deitar com uma mulher durante a sua menstruação e descobrir a sua nudez, expondo a sua fonte, e ela expuser a fonte do seu sangue, ambos serão cortados do meio do seu povo.'),
(3338, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 19, 'OT', 'Não descobrirás a nudez da irmã de tua mãe nem da irmã de teu pai; pois quem expõe a sua parenta carregará a sua iniquidade.'),
(3339, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 20, 'OT', 'E um homem que se deitar com a sua tia, descobriu a nudez do seu tio; levarão o seu pecado; morrerão sem filhos.'),
(3340, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 21, 'OT', 'E um homem que tomar a mulher de seu irmão, impureza é; a nudez de seu irmão descobriu; sem filhos ficarão.'),
(3341, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 22, 'OT', 'Guardem todos os meus estatutos e todos os meus juízos, e pratiquem-nos, para que a terra, para a qual eu os levo para habitar nela, não os vomite.'),
(3342, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 23, 'OT', 'E não andeis nos estatutos da nação que eu lanço fora diante de vós; porque fizeram todas estas coisas, e por isso me abominei deles.'),
(3343, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 24, 'OT', 'E eu vos disse: Vós possuireis a terra deles, e eu a darei a vós para a possuirdes, terra que mana leite e mel. Eu sou o SENHOR, vosso Deus, que vos separei dos povos.'),
(3344, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 25, 'OT', 'Separareis, pois, entre o animal limpo e o imundo, e entre a ave imunda e a limpa; e não tornareis as vossas almas abomináveis por causa do animal, ou da ave, ou de tudo o que rasteja sobre a terra, que vos separei para terdes por imundo.'),
(3345, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 26, 'OT', 'E sereis para mim santos, porque eu, o SENHOR, sou santo, e vos separei dos povos, para serdes meus.'),
(3346, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 20, 27, 'OT', 'Se um homem ou uma mulher tiver em si um espírito de adivinhação ou de feitiçaria, certamente serão mortos; serão apedrejados, e o seu sangue cairá sobre eles.'),
(3347, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 1, 'OT', 'Disse o SENHOR a Moisés: Fala aos sacerdotes, filhos de Arão, e dize-lhes: Nenhum sacerdote se contaminará por causa de um morto entre o seu povo.'),
(3348, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 2, 'OT', 'exceto por seu parente mais próximo: por sua mãe, por seu pai, por seu filho, por sua filha e por seu irmão.'),
(3349, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 3, 'OT', 'e pela sua irmã virgem, que lhe é próxima, que não teve marido; por ela se contaminará.'),
(3350, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 4, 'OT', 'Não se contaminará como marido entre o seu povo, para se profanar.'),
(3351, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 5, 'OT', 'Não farão calva na sua cabeça, não raparão as extremidades da sua barba, nem farão cortes na sua carne.'),
(3352, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 6, 'OT', 'Santos serão para o seu Deus e não profanarão o nome do seu Deus, porque oferecem as ofertas queimadas do SENHOR, o pão do seu Deus; portanto, serão santos.'),
(3353, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 7, 'OT', 'Não tomarão mulher prostituta ou desonrada, nem tomarão mulher divorciada de seu marido; pois santo é ele para o seu Deus.'),
(3354, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 8, 'OT', 'Santifica-o, pois ele oferece o pão do teu Deus; santo será para ti, porque eu, o SENHOR que vos santifico, sou santo.'),
(3355, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 9, 'OT', 'E a filha de um sacerdote, se começar a se prostituir, profana o seu pai; com fogo será queimada.'),
(3356, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 10, 'OT', 'E o sacerdote principal entre seus irmãos, sobre cuja cabeça foi derramado o óleo da unção, e que foi consagrado para vestir as vestes, não descobrirá a sua cabeça nem rasgará as suas vestes.'),
(3357, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 11, 'OT', 'E não se aproximará de nenhuma pessoa morta; nem por seu pai nem por sua mãe se contaminará.'),
(3358, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 12, 'OT', 'Não sairá do santuário, nem profanará o santuário do seu Deus, pois a consagração do óleo da unção do seu Deus está sobre ele; eu sou o SENHOR.'),
(3359, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 13, 'OT', 'Ele tomará uma mulher na sua virgindade.'),
(3360, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 14, 'OT', 'Viúva, ou divorciada, ou desonrada, ou prostituta, estas não tomará; porém tomará por mulher uma virgem do seu povo.'),
(3361, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 15, 'OT', 'E não profanará a sua semente entre o seu povo; porque eu sou o SENHOR que o santifico.'),
(3362, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 16, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3363, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 17, 'OT', 'Fala a Arão, dizendo: Nenhum homem da tua descendência, nas suas gerações, em quem houver defeito, se aproximará para oferecer o pão do seu Deus.'),
(3364, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 18, 'OT', 'Nenhum homem que tiver algum defeito se aproximará: homem cego, ou coxo, ou de nariz achatado, ou de membros desproporcionais.'),
(3365, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 19, 'OT', 'ou homem que tiver fratura no pé, ou fratura na mão,'),
(3366, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 20, 'OT', 'ou corcunda, ou anão, ou que tiver belida no olho, ou sarna, ou impigem, ou testículo esmagado.'),
(3367, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 21, 'OT', 'Nenhum homem da descendência de Arão, o sacerdote, em quem houver defeito, se aproximará para oferecer as ofertas queimadas do SENHOR; tendo ele defeito, não se aproximará para oferecer o pão do seu Deus.'),
(3368, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 22, 'OT', 'O pão do seu Deus, das ofertas santíssimas e das coisas santas, poderá comer.'),
(3369, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 23, 'OT', 'Todavia, não entrará até o véu, nem se aproximará do altar, porque tem defeito, para que não profane os meus santuários; porque eu sou o SENHOR que os santifico.'),
(3370, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 21, 24, 'OT', 'E Moisés falou a Arão e a seus filhos e a todos os filhos de Israel.'),
(3371, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 1, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3372, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 2, 'OT', 'Fala a Arão e a seus filhos que se abstenham das coisas santas dos filhos de Israel, que eles me consagram, e que não profanem o meu santo nome; eu sou o SENHOR.'),
(3373, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 3, 'OT', 'Dize-lhes: Todo homem dentre os vossos descendentes, em todas as vossas gerações, que se aproximar das coisas santas que os filhos de Israel consagram ao SENHOR, tendo sobre si a sua impureza, essa pessoa será eliminada da minha presença. Eu sou o SENHOR.'),
(3374, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 4, 'OT', 'Nenhum homem da descendência de Arão que for leproso ou tiver fluxo comerá das coisas santas, até que esteja limpo; também aquele que tocar em qualquer coisa impura de um cadáver, ou um homem de quem sair emissão de sêmen.'),
(3375, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 5, 'OT', 'ou aquele que tocar em qualquer réptil que o torne impuro, ou em um homem que o torne impuro, segundo toda a sua impureza.'),
(3376, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 6, 'OT', 'A pessoa que tocar nele ficará impura até a tarde, e não comerá das coisas santas, a menos que lave o seu corpo com água.'),
(3377, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 7, 'OT', 'E quando o sol se puser, ele estará limpo; e depois comerá das coisas santas, porque este é o seu pão.'),
(3378, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 8, 'OT', 'Não comerá animal morto ou dilacerado, para não se contaminar com eles; eu sou o SENHOR.'),
(3379, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 9, 'OT', 'Guardarão a minha ordenança, para que não levem pecado por causa dela e morram nela, pois a profanaram. Eu sou o SENHOR que os santifico.'),
(3380, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 10, 'OT', 'Nenhum estranho comerá das coisas santas; nem o hóspede do sacerdote nem o jornaleiro comerão das coisas santas.'),
(3381, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 11, 'OT', 'Mas o sacerdote que comprar alguém com o seu dinheiro, esse comerá dela; e o nascido na sua casa, esses comerão do seu pão.'),
(3382, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 12, 'OT', 'E a filha de um sacerdote, se ela se casar com um homem estranho, ela não comerá da oferta das coisas santas.'),
(3383, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 13, 'OT', 'Mas, se a filha de um sacerdote ficar viúva ou divorciada, e não tiver filhos, e voltar à casa de seu pai, como na sua juventude, comerá do pão de seu pai; mas nenhum estranho comerá dele.'),
(3384, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 14, 'OT', 'E se alguém comer uma coisa santa por engano, acrescentará a ela um quinto do seu valor, e a dará ao sacerdote com a coisa santa.'),
(3385, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 15, 'OT', 'E não profanarão as coisas santas dos filhos de Israel, que eles oferecem ao SENHOR.'),
(3386, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 16, 'OT', 'e os farão carregar a iniquidade da culpa, ao comerem as suas coisas santas; porque eu sou o SENHOR que os santifico.'),
(3387, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 17, 'OT', 'Falou mais o SENHOR a Moisés, dizendo:'),
(3388, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 18, 'OT', 'Fala a Arão, a seus filhos e a todos os filhos de Israel, e dize-lhes: Qualquer homem da casa de Israel ou dos estrangeiros em Israel que oferecer a sua oferta, seja por todos os seus votos ou por todas as suas ofertas voluntárias, que oferecerem ao SENHOR em holocausto,'),
(3389, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 19, 'OT', 'Para que seja aceito em vosso favor, será macho sem defeito, dos bois, das ovelhas ou das cabras.'),
(3390, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 20, 'OT', 'Nenhum animal que tenha defeito vocês oferecerão, pois não será aceito em favor de vocês.'),
(3391, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 21, 'OT', 'E se alguém oferecer sacrifício pacífico ao SENHOR, seja para cumprir um voto ou como oferta voluntária, de gado ou de ovelhas, será perfeito para ser aceito; nenhum defeito haverá nele.'),
(3392, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 22, 'OT', 'Cego, ou quebrado, ou mutilado, ou com tumor, ou com sarna, ou com ferida, não oferecereis esses ao SENHOR; e deles não dareis oferta queimada sobre o altar ao SENHOR.'),
(3393, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 23, 'OT', 'Touro ou ovelha com membro deformado ou atrofiado, poderás oferecer como oferta voluntária, mas como voto não será aceito.'),
(3394, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 24, 'OT', 'Não oferecereis ao SENHOR animal machucado, esmagado, arrancado ou cortado; e na vossa terra não fareis isso.'),
(3395, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 25, 'OT', 'Nem da mão do estrangeiro oferecereis o pão do vosso Deus de nenhuma dessas coisas, pois a sua corrupção está nelas; defeito há nelas; não serão aceitas por vós.'),
(3396, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 26, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3397, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 27, 'OT', 'Quando nascer um boi, ou uma ovelha, ou uma cabra, ficará sete dias debaixo da sua mãe; e desde o oitavo dia em diante, será aceito como oferta queimada ao SENHOR.'),
(3398, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 28, 'OT', 'Também o boi ou a ovelha: não o sacrificareis juntamente com o seu filho no mesmo dia.'),
(3399, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 29, 'OT', 'E quando oferecerdes sacrifício de ação de graças ao SENHOR, oferecê-lo-eis de vossa livre vontade.'),
(3400, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 30, 'OT', 'No mesmo dia será comido; nada deixareis dele até a manhã; eu sou o SENHOR.'),
(3401, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 31, 'OT', 'Guardareis os meus mandamentos e os cumprireis; eu sou o SENHOR.'),
(3402, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 32, 'OT', 'Não profanareis o meu santo nome, para que eu seja santificado no meio dos filhos de Israel. Eu sou o SENHOR que vos santifico.'),
(3403, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 22, 33, 'OT', 'que vos tirei da terra do Egito, para ser o vosso Deus: eu sou o SENHOR.'),
(3404, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 1, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3405, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: As festas fixas do SENHOR, que convocareis, serão santas convocações; estas são as minhas festas fixas.'),
(3406, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 3, 'OT', 'Seis dias se fará trabalho, mas no sétimo dia é sábado de descanso, santa convocação; nenhum trabalho fareis; é sábado dedicado ao SENHOR em todas as vossas moradas.'),
(3407, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 4, 'OT', 'Estas são as festas fixas do SENHOR, as santas convocações que vocês proclamarão no tempo determinado delas.'),
(3408, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 5, 'OT', 'No primeiro mês, no dia catorze do mês, ao entardecer, é a Páscoa do SENHOR.'),
(3409, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 6, 'OT', 'E aos quinze dias deste mês é a festa dos pães sem fermento para o SENHOR; sete dias comereis pães sem fermento.'),
(3410, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 7, 'OT', 'No primeiro dia tereis santa convocação; nenhuma obra servil fareis.'),
(3411, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 8, 'OT', 'Oferecereis oferta queimada ao SENHOR por sete dias; ao sétimo dia haverá santa convocação; nenhuma obra servil fareis.'),
(3412, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 9, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3413, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 10, 'OT', 'Fala aos filhos de Israel e dize-lhes: Quando entrardes na terra que eu vos dou e segardes a sua colheita, trareis um molho das primícias da vossa colheita ao sacerdote.'),
(3414, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 11, 'OT', 'E moverá o molho perante o SENHOR, para que sejais aceitos; no dia seguinte ao sábado, o sacerdote o moverá.'),
(3415, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 12, 'OT', 'E no dia em que oferecerdes o molho, preparareis um cordeiro sem defeito, de um ano, em holocausto ao SENHOR.'),
(3416, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 13, 'OT', 'E a sua oferta de cereais será de dois décimos de flor de farinha, amassada com azeite, como oferta queimada de aroma agradável ao SENHOR; e a sua libação será de vinho, um quarto de um him.'),
(3417, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 14, 'OT', 'E não comereis pão, nem grão tostado, nem espigas verdes, até aquele mesmo dia em que trouxerdes a oferta do vosso Deus; é estatuto perpétuo pelas vossas gerações, em todas as vossas habitações.'),
(3418, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 15, 'OT', 'E contareis para vós, desde o dia seguinte ao sábado, desde o dia em que trouxerdes o molho da oferta movida; sete semanas inteiras serão.'),
(3419, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 16, 'OT', 'Até o dia seguinte ao sétimo sábado contareis cinquenta dias; então oferecereis oferta de manjares nova ao SENHOR.'),
(3420, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 17, 'OT', 'Das vossas habitações trareis dois pães como oferta movida; de duas décimas de farinha fina serão, levedados se cozerão; primícias são ao SENHOR.'),
(3421, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 18, 'OT', 'E oferecereis com o pão sete cordeiros sem defeito, de um ano, e um novilho, e dois carneiros; serão holocausto ao SENHOR, com a sua oferta de cereais e as suas libações, oferta queimada de aroma agradável ao SENHOR.'),
(3422, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 19, 'OT', 'Oferecereis um bode como oferta pelo pecado e dois cordeiros de um ano como sacrifício de paz.'),
(3423, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 20, 'OT', 'O sacerdote os moverá como oferta movida diante do SENHOR, juntamente com o pão das primícias, sobre os dois cordeiros; serão santos ao SENHOR, para o sacerdote.'),
(3424, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 21, 'OT', 'E no mesmo dia proclamareis santa convocação; nenhuma obra servil fareis; estatuto perpétuo em todas as vossas habitações, pelas vossas gerações.'),
(3425, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 22, 'OT', 'Quando vocês fizerem a colheita da sua terra, não colham até os limites do campo, nem ajuntem as espigas caídas da sua colheita; deixem-nas para o pobre e para o estrangeiro. Eu sou o SENHOR, o Deus de vocês.'),
(3426, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 23, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3427, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 24, 'OT', 'Fala aos filhos de Israel, dizendo: No sétimo mês, no primeiro dia do mês, tereis descanso, memorial de toques de trombeta, santa convocação.'),
(3428, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 25, 'OT', 'Nenhuma obra servil fareis; e oferecereis oferta queimada ao SENHOR.'),
(3429, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 26, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3430, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 27, 'OT', 'Certamente, no décimo dia deste sétimo mês, será o Dia da Expiação; tereis santa convocação, e afligireis as vossas almas; e oferecereis oferta queimada ao SENHOR.'),
(3431, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 28, 'OT', 'Nenhuma obra fareis nesse mesmo dia, porque é o Dia da Expiação, para fazer expiação por vós perante o SENHOR, vosso Deus.'),
(3432, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 29, 'OT', 'Porque toda pessoa que não se afligir nesse mesmo dia será eliminada do seu povo.'),
(3433, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 30, 'OT', 'E toda pessoa que fizer qualquer trabalho nesse mesmo dia, eu a eliminarei do meio do seu povo.'),
(3434, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 31, 'OT', 'Nenhuma obra fareis; estatuto perpétuo é para as vossas gerações, em todas as vossas habitações.'),
(3435, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 32, 'OT', 'Será para vós um sábado de descanso completo, e afligireis as vossas almas; no dia nono do mês, à tarde, de uma tarde a outra tarde, guardareis o vosso sábado.'),
(3436, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 33, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3437, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 34, 'OT', 'Fala aos filhos de Israel, dizendo: Aos quinze dias deste sétimo mês será a festa dos tabernáculos ao SENHOR por sete dias.'),
(3438, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 35, 'OT', 'No primeiro dia haverá santa convocação; nenhuma obra servil fareis.'),
(3439, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 36, 'OT', 'Sete dias oferecereis oferta queimada ao SENHOR; ao oitavo dia tereis santa convocação, e oferecereis oferta queimada ao SENHOR; é assembleia solene; nenhum trabalho servil fareis.'),
(3440, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 37, 'OT', 'Estas são as festas fixas do SENHOR, que proclamareis como santas convocações, para oferecer ao SENHOR oferta queimada, holocausto e oferta de cereais, sacrifício e libações, cada qual no seu próprio dia.'),
(3441, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 38, 'OT', 'Além dos sábados do SENHOR, e além dos vossos dons, e além de todos os vossos votos, e além de todas as vossas ofertas voluntárias que dareis ao SENHOR.'),
(3442, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 39, 'OT', 'Todavia, no décimo quinto dia do sétimo mês, quando tiverdes colhido o produto da terra, celebrareis a festa do SENHOR por sete dias; no primeiro dia haverá descanso solene, e no oitavo dia haverá descanso solene.'),
(3443, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 40, 'OT', 'No primeiro dia, tomareis para vós frutos de árvores formosas, ramos de palmeiras, ramos de árvores frondosas e salgueiros de ribeira; e vos alegrareis perante o SENHOR, vosso Deus, por sete dias.'),
(3444, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 41, 'OT', 'Celebrareis esta festa ao SENHOR por sete dias no ano; é estatuto perpétuo para as vossas gerações; no sétimo mês a celebrareis.'),
(3445, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 42, 'OT', 'Em tendas habitareis sete dias; todo natural em Israel habitará em tendas.'),
(3446, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 43, 'OT', 'para que saibam as vossas gerações que eu fiz habitar os filhos de Israel em tendas, quando os tirei da terra do Egito; eu sou o SENHOR, vosso Deus.'),
(3447, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 23, 44, 'OT', 'E Moisés falou das festas fixas do SENHOR aos filhos de Israel.'),
(3448, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3449, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 2, 'OT', 'Ordena aos filhos de Israel que te tragam azeite de oliveira puro, batido, para a luminária, para manter acesa a lâmpada continuamente.'),
(3450, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 3, 'OT', 'Fora do véu do testemunho, na tenda da congregação, Arão o disporá diante do SENHOR, desde a tarde até a manhã, continuamente; estatuto perpétuo pelas vossas gerações.'),
(3451, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 4, 'OT', 'Sobre o candelabro puro disporá as lâmpadas perante o SENHOR continuamente.'),
(3452, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 5, 'OT', 'Tomarás flor de farinha e dela cozerás doze pães; cada pão será de duas décimas de efa.'),
(3453, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 6, 'OT', 'E os porás em duas fileiras, seis em cada fileira, sobre a mesa pura, perante o SENHOR.'),
(3454, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 7, 'OT', 'E sobre a fileira porás incenso puro, e será para o pão como memorial, oferta queimada ao SENHOR.'),
(3455, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 8, 'OT', 'No dia do sábado, no dia do sábado, o sacerdote o colocará em ordem perante o SENHOR continuamente, da parte dos filhos de Israel, como aliança eterna.'),
(3456, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 9, 'OT', 'E será de Arão e de seus filhos, e o comerão em lugar santo, porque é coisa santíssima para ele, das ofertas queimadas ao SENHOR, por estatuto perpétuo.'),
(3457, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 10, 'OT', 'E saiu o filho de uma mulher israelita, sendo ele filho de um homem egípcio, no meio dos filhos de Israel; e o filho da israelita e um homem israelita contenderam no acampamento.'),
(3458, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 11, 'OT', 'E o filho da mulher israelita blasfemou o nome do SENHOR e o amaldiçoou; então o trouxeram a Moisés. E o nome de sua mãe era Selomite, filha de Dibri, da tribo de Dã.'),
(3459, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 12, 'OT', 'E o puseram sob guarda, para que se lhes declarasse a sentença conforme a palavra do SENHOR.'),
(3460, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 13, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3461, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 14, 'OT', 'Leva o que blasfemou para fora do acampamento; e todos os que o ouviram porão as mãos sobre a cabeça dele; e toda a congregação o apedrejará.'),
(3462, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 15, 'OT', 'Fala aos filhos de Israel: Qualquer homem que amaldiçoar o seu Deus levará sobre si o seu pecado.'),
(3463, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 16, 'OT', 'E quem pronunciar o nome do SENHOR certamente morrerá; toda a congregação o apedrejará. Tanto o estrangeiro como o natural, ao pronunciar o nome, será morto.'),
(3464, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 17, 'OT', 'Quem ferir qualquer pessoa certamente será morto.'),
(3465, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 18, 'OT', 'Quem ferir um animal, o restituirá: vida por vida.'),
(3466, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 19, 'OT', 'E se alguém causar defeito no seu próximo, assim como ele fez, assim lhe será feito.'),
(3467, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 20, 'OT', 'Fratura por fratura, olho por olho, dente por dente; assim como ele tiver causado defeito em um homem, assim lhe será feito.'),
(3468, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 21, 'OT', 'Quem ferir um animal, o restituirá; mas quem ferir um homem será morto.'),
(3469, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 22, 'OT', 'Uma mesma lei haverá para vós; assim será o estrangeiro como o natural; porque eu sou o SENHOR, vosso Deus.'),
(3470, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 24, 23, 'OT', 'E Moisés falou aos filhos de Israel, e eles levaram o que havia blasfemado para fora do acampamento, e o apedrejaram com pedras. E os filhos de Israel fizeram conforme o SENHOR havia ordenado a Moisés.'),
(3471, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 1, 'OT', 'E o SENHOR falou a Moisés no monte Sinai, dizendo:'),
(3472, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: Quando entrardes na terra que eu vos dou, então a terra guardará um sábado para o SENHOR.'),
(3473, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 3, 'OT', 'Seis anos semearás o teu campo, e seis anos podarás a tua vinha, e colherás os seus frutos.'),
(3474, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 4, 'OT', 'No sétimo ano, haverá sábado de descanso para a terra, um sábado ao SENHOR; não semearás o teu campo, nem podarás a tua vinha.'),
(3475, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 5, 'OT', 'Não colherás o que brotar espontaneamente da tua colheita, nem vindimarás as uvas da tua vinha não podada; ano de descanso será para a terra.'),
(3476, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 6, 'OT', 'E o sábado da terra será para vós por alimento: para ti, para o teu servo, para a tua serva, para o teu jornaleiro e para o estrangeiro que peregrina contigo.'),
(3477, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 7, 'OT', 'E para o teu gado e para os animais que estão na tua terra, todo o seu produto será para alimento.'),
(3478, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 8, 'OT', 'Contarás para ti sete semanas de anos, sete vezes sete anos, de modo que os dias das sete semanas de anos te serão quarenta e nove anos.'),
(3479, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 9, 'OT', 'No sétimo mês, no décimo dia do mês, no Dia da Expiação, fareis soar a trombeta do jubileu; fareis soar a trombeta por toda a vossa terra.'),
(3480, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 10, 'OT', 'E consagrareis o ano quinquagésimo, e proclamareis liberdade na terra a todos os seus moradores; jubileu será para vós, e voltareis, cada um à sua possessão, e cada um à sua família voltareis.'),
(3481, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 11, 'OT', 'O quinquagésimo ano será para vós um jubileu; não semeareis, nem colhereis o que nele nascer de si mesmo, nem vindimareis as uvas das vinhas não podadas.'),
(3482, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 12, 'OT', 'Porque é jubileu, santo será para vós; do campo comereis o seu produto.'),
(3483, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 13, 'OT', 'Neste ano do jubileu, cada um voltará à sua propriedade.'),
(3484, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 14, 'OT', 'Quando venderdes alguma coisa ao vosso próximo, ou comprardes da mão do vosso próximo, não oprimais uns aos outros.'),
(3485, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 15, 'OT', 'Conforme o número de anos depois do jubileu, comprarás do teu próximo; conforme o número dos anos das colheitas, ele te venderá.'),
(3486, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 16, 'OT', 'Conforme o maior número de anos, aumentarás o seu preço, e conforme o menor número de anos, diminuirás o seu preço; porque é o número das colheitas que ele te vende.'),
(3487, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 17, 'OT', 'Não oprimas o teu próximo, mas teme o teu Deus, porque eu sou o SENHOR, o vosso Deus.'),
(3488, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 18, 'OT', 'Executai os meus estatutos, guardai os meus juízos e praticai-os; assim habitareis seguros na terra.'),
(3489, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 19, 'OT', 'A terra dará o seu fruto, e comereis até vos fartar, e habitareis nela em segurança.'),
(3490, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 20, 'OT', 'E se disserdes: Que comeremos no sétimo ano? Eis que não semearemos nem colheremos a nossa colheita.'),
(3491, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 21, 'OT', 'Então ordenarei a minha bênção sobre vós no sexto ano, e ela produzirá colheita suficiente para três anos.'),
(3492, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 22, 'OT', 'E semeareis no oitavo ano, e comereis da colheita velha; até o ano nono, até que venha a sua colheita, comereis a velha.'),
(3493, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 23, 'OT', 'A terra não será vendida em perpetuidade, porque a terra é minha; pois vós sois estrangeiros e peregrinos comigo.'),
(3494, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 24, 'OT', 'Em toda a terra da vossa possessão dareis resgate à terra.'),
(3495, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 25, 'OT', 'Se teu irmão empobrecer e vender parte da sua propriedade, então virá o seu resgatador, o parente mais próximo, e resgatará o que seu irmão vendeu.'),
(3496, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 26, 'OT', 'E se um homem não tiver resgatador, mas a sua mão alcançar e achar o suficiente para o seu resgate,'),
(3497, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 27, 'OT', 'Então contará os anos desde a sua venda, e restituirá o excedente ao homem a quem o vendeu, e voltará à sua possessão.'),
(3498, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 28, 'OT', 'Mas, se a sua mão não alcançar o suficiente para lhe restituir, então o que foi vendido permanecerá na mão do comprador até o ano do jubileu; e no jubileu sairá e voltará à sua possessão.'),
(3499, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 29, 'OT', 'E se um homem vender uma casa de moradia em cidade murada, o seu resgate será até o fim do ano da sua venda; por dias inteiros terá o seu resgate.'),
(3500, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 30, 'OT', 'Mas, se não for resgatada até que se complete um ano inteiro, então a casa que estiver na cidade que tem muro pertencerá em perpetuidade ao que a comprou, pelas suas gerações; não sairá no jubileu.'),
(3501, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 31, 'OT', 'Mas as casas das aldeias que não têm muro ao redor serão consideradas como campo da terra; haverá resgate para elas, e sairão no jubileu.'),
(3502, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 32, 'OT', 'Quanto às cidades dos levitas, as casas das cidades da sua possessão, direito perpétuo de resgate terão os levitas.'),
(3503, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 33, 'OT', 'E se alguém resgatar dos levitas, então a venda da casa e da cidade da sua possessão sairá no jubileu; porque as casas das cidades dos levitas são a sua possessão no meio dos filhos de Israel.'),
(3504, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 34, 'OT', 'Mas o campo dos arredores das suas cidades não será vendido, porque lhes é possessão perpétua.'),
(3505, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 35, 'OT', 'Se o teu irmão empobrecer e as suas forças decaírem junto a ti, então o sustentarás, como estrangeiro e peregrino, para que viva contigo.'),
(3506, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 36, 'OT', 'Não cobres dele juros nem lucro, mas teme o teu Deus, para que o teu irmão viva contigo.'),
(3507, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 37, 'OT', 'Não lhe darás teu dinheiro com juros, nem darás o teu alimento por lucro.'),
(3508, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 38, 'OT', 'Eu sou o SENHOR, vosso Deus, que vos tirei da terra do Egito, para vos dar a terra de Canaã, para ser o vosso Deus.'),
(3509, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 39, 'OT', 'E se teu irmão empobrecer, estando contigo, e se vender a ti, não o farás servir como escravo.'),
(3510, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 40, 'OT', 'Como assalariado e como residente estará contigo; até o ano do jubileu te servirá.'),
(3511, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 41, 'OT', 'Então sairá do teu serviço, ele e seus filhos com ele, e voltará à sua família e à possessão de seus pais retornará.'),
(3512, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 42, 'OT', 'Porque são meus servos, que tirei da terra do Egito; não serão vendidos como se vende um escravo.'),
(3513, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 43, 'OT', 'Não dominarás sobre ele com dureza, mas temerás o teu Deus.'),
(3514, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 44, 'OT', 'Quanto ao teu escravo e à tua escrava que tiveres, das nações ao redor de vós, delas comprareis escravo e escrava.'),
(3515, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 45, 'OT', 'Também comprareis dentre os filhos dos estrangeiros que peregrinam entre vós, deles e das suas famílias que estão convosco, que tiverem gerado na vossa terra; e eles vos serão por possessão.'),
(3516, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 46, 'OT', 'E os deixarás por herança a teus filhos depois de ti, para os possuírem como propriedade; para sempre deles te servirás. Mas sobre vossos irmãos, os filhos de Israel, cada um sobre seu irmão, não dominarás com rigor.'),
(3517, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 47, 'OT', 'E se a mão do estrangeiro ou do residente que está contigo alcançar riqueza, e teu irmão empobrecer junto dele, e se vender ao estrangeiro residente que está contigo, ou à raiz da família do estrangeiro.'),
(3518, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 48, 'OT', 'Depois de ter sido vendido, haverá resgate para ele; um de seus irmãos o resgatará.'),
(3519, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 49, 'OT', 'Ou seu tio, ou o filho de seu tio o resgatará; ou um parente próximo, da sua família, o resgatará; ou, se a sua mão alcançar recursos, ele se resgatará a si mesmo.'),
(3520, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 50, 'OT', 'E calculará com aquele que o comprou, desde o ano em que se vendeu a ele até o ano do jubileu; e o dinheiro da sua venda será conforme o número dos anos, como os dias de um jornaleiro estará com ele.'),
(3521, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 51, 'OT', 'Se ainda houver muitos anos, conforme eles restituirá o seu resgate do dinheiro pelo qual foi comprado.'),
(3522, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 52, 'OT', 'E se ainda restarem poucos anos até o ano do jubileu, então fará contas com ele; conforme os seus anos restituirá o seu resgate.'),
(3523, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 53, 'OT', 'Como um empregado contratado por ano, estará com ele; não o dominará com rigor diante dos teus olhos.'),
(3524, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 54, 'OT', 'E se não for resgatado por esses meios, sairá no ano do jubileu, ele e seus filhos com ele.'),
(3525, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 25, 55, 'OT', 'Porque os filhos de Israel me são servos; meus servos são eles, que tirei da terra do Egito. Eu sou o SENHOR, vosso Deus.'),
(3526, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 1, 'OT', 'Não fareis para vós ídolos, nem levantareis imagem esculpida ou coluna sagrada, nem poreis pedra ornamentada em vossa terra para vos prostrardes diante dela; porque eu sou o SENHOR, vosso Deus.'),
(3527, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 2, 'OT', 'Guardareis os meus sábados e reverenciareis o meu santuário: Eu sou o SENHOR.'),
(3528, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 3, 'OT', 'Se andardes nos meus estatutos, e guardardes os meus mandamentos, e os cumprirdes,'),
(3529, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 4, 'OT', 'Então darei as vossas chuvas no seu tempo, e a terra dará o seu produto, e a árvore do campo dará o seu fruto.'),
(3530, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 5, 'OT', 'A debulha se estenderá até a vindima, e a vindima até a semeadura; comereis o vosso pão com fartura e habitareis em segurança na vossa terra.'),
(3531, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 6, 'OT', 'Darei paz na terra, e vocês se deitarão sem que ninguém os amedronte. Farei cessar os animais selvagens da terra, e a espada não passará pela sua terra.'),
(3532, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 7, 'OT', 'Perseguireis os vossos inimigos, e eles cairão à espada diante de vós.'),
(3533, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 8, 'OT', 'Cinco de vós perseguirão cem, e cem de vós perseguirão dez mil; e os vossos inimigos cairão à espada diante de vós.'),
(3534, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 9, 'OT', 'Voltar-me-ei para vós, e vos farei frutificar, e vos multiplicarei, e estabelecerei a minha aliança convosco.'),
(3535, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 10, 'OT', 'Comereis o cereal velho, bem envelhecido, e tirareis o velho para dar lugar ao novo.'),
(3536, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 11, 'OT', 'E porei o meu tabernáculo no meio de vós, e a minha alma não se enfastiará de vós.'),
(3537, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 12, 'OT', 'E andarei no meio de vós, e serei o vosso Deus, e vós sereis o meu povo.'),
(3538, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 13, 'OT', 'Eu sou o SENHOR, vosso Deus, que vos tirei da terra do Egito, para que não fôsseis seus escravos; e quebrei as varas do vosso jugo e vos fiz andar eretos.'),
(3539, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 14, 'OT', 'Mas, se não me ouvirdes e não cumprirdes todos estes mandamentos,'),
(3540, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 15, 'OT', 'E se rejeitardes os meus estatutos, e a vossa alma abominar os meus juízos, não fazendo todos os meus mandamentos, para quebrantar a minha aliança,'),
(3541, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 16, 'OT', 'Então eu também farei isto contra vós: trarei sobre vós terror, a tísica e a febre ardente, que consomem os olhos e fazem definhar a alma; e semeareis em vão a vossa semente, e os vossos inimigos a comerão.'),
(3542, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 17, 'OT', 'Porei a minha face contra vós, e sereis derrotados diante dos vossos inimigos; os que vos odeiam dominarão sobre vós, e fugireis sem que ninguém vos persiga.'),
(3543, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 18, 'OT', 'E se, mesmo com estas coisas, não me ouvirdes, então eu continuarei a castigar-vos sete vezes mais por causa dos vossos pecados.'),
(3544, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 19, 'OT', 'Quebrarei a soberba da vossa força, e farei os vossos céus como ferro e a vossa terra como bronze.'),
(3545, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 20, 'OT', 'E em vão se esgotará a vossa força; a vossa terra não dará o seu produto, e as árvores da terra não darão o seu fruto.'),
(3546, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 21, 'OT', 'E se andardes comigo em hostilidade, e não quiserdes me ouvir, trarei sobre vós praga sete vezes mais, conforme os vossos pecados.'),
(3547, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 22, 'OT', 'Enviarei contra vós as feras do campo, que vos despojarão dos filhos, e destruirão o vosso gado, e vos reduzirão a poucos; e os vossos caminhos se tornarão desertos.'),
(3548, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 23, 'OT', 'Se com estas coisas ainda não vos corrigirdes para mim, mas andardes em oposição a mim,'),
(3549, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 24, 'OT', 'Também eu andarei contra vós em hostilidade, e eu mesmo vos ferirei sete vezes mais por causa dos vossos pecados.'),
(3550, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 25, 'OT', 'Trarei sobre vós a espada que executará a vingança da aliança; e, quando vos ajuntardes nas vossas cidades, enviarei a peste no meio de vós, e sereis entregues na mão do inimigo.'),
(3551, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 26, 'OT', 'Quando eu vos quebrantar o sustento do pão, dez mulheres cozerão o vosso pão num só forno, e devolver-vos-ão o pão por peso; e comereis, mas não vos fartareis.'),
(3552, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 27, 'OT', 'E se com isto ainda não me ouvirdes, e andardes comigo em teimosia,'),
(3553, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 28, 'OT', 'Também eu andarei contra vós em furor, e vos castigarei sete vezes mais por causa dos vossos pecados.'),
(3554, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 29, 'OT', 'E comereis a carne de vossos filhos, e a carne de vossas filhas comereis.'),
(3555, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 30, 'OT', 'E destruirei os vossos altos, e cortarei as vossas imagens do sol, e porei os vossos cadáveres sobre os cadáveres dos vossos ídolos; e a minha alma vos abominará.'),
(3556, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 31, 'OT', 'E porei as vossas cidades em ruínas, e devastarei os vossos santuários, e não sentirei o aroma das vossas ofertas de cheiro suave.'),
(3557, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 32, 'OT', 'E assolarei eu mesmo a terra, e os vossos inimigos que nela habitarem ficarão pasmados por causa dela.'),
(3558, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 33, 'OT', 'E vos espalharei entre as nações, e desembainharei a espada atrás de vós; e a vossa terra será assolada, e as vossas cidades serão ruínas.'),
(3559, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 34, 'OT', 'Então a terra desfrutará dos seus sábados todos os dias da sua desolação, enquanto vocês estiverem na terra dos seus inimigos; então a terra descansará e desfrutará dos seus sábados.'),
(3560, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 35, 'OT', 'Todos os dias da desolação descansará, aquilo que não descansou nos vossos sábados, quando habitáveis sobre ela.'),
(3561, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 36, 'OT', 'E aos que restarem de vós, farei entrar desânimo no coração deles nas terras dos seus inimigos; e o som de uma folha levada pelo vento os perseguirá, e fugirão como quem foge da espada, e cairão sem que ninguém os persiga.'),
(3562, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 37, 'OT', 'E tropeçarão uns nos outros, como se fugissem da espada, sem que ninguém os persiga; e não tereis força para resistir diante dos vossos inimigos.'),
(3563, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 38, 'OT', 'E perecereis entre as nações, e a terra dos vossos inimigos vos devorará.'),
(3564, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 39, 'OT', 'E os que restarem de vós apodrecerão na sua iniquidade, nas terras dos vossos inimigos; e também na iniquidade de seus pais, com eles apodrecerão.'),
(3565, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 40, 'OT', 'Confessarão a sua iniquidade e a iniquidade de seus pais, na sua transgressão com que transgrediram contra mim; e também que andaram comigo em oposição.'),
(3566, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 41, 'OT', 'Também eu andarei contra eles em hostilidade e os trarei à terra dos seus inimigos; então o seu coração incircunciso se humilhará, e então aceitarão o castigo da sua iniquidade.'),
(3567, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 42, 'OT', 'Lembrar-me-ei da minha aliança com Jacó, e também da minha aliança com Isaque, e também da minha aliança com Abraão me lembrarei, e da terra me lembrarei.'),
(3568, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 43, 'OT', 'E a terra será abandonada por eles, e desfrutará dos seus sábados, sendo assolada por causa deles; e eles aceitarão o castigo da sua iniquidade, precisamente porque rejeitaram os meus juízos, e a sua alma abominou os meus estatutos.'),
(3569, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 44, 'OT', 'E, apesar de tudo isso, quando estiverem na terra dos seus inimigos, não os rejeitarei nem os abominarei para consumi-los, quebrando a minha aliança com eles, porque eu sou o SENHOR, o seu Deus.'),
(3570, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 45, 'OT', 'E lembrar-me-ei por eles da aliança com os seus antepassados, que tirei da terra do Egito perante os olhos das nações, para lhes ser por Deus: Eu sou o SENHOR.'),
(3571, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 26, 46, 'OT', 'Estes são os estatutos, os juízos e as leis que o SENHOR estabeleceu entre si e os filhos de Israel, no monte Sinai, por meio de Moisés.'),
(3572, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3573, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: Quando alguém fizer um voto especial, as pessoas serão avaliadas segundo a tua avaliação para o SENHOR.'),
(3574, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 3, 'OT', 'Se a tua avaliação for de um homem, da idade de vinte anos até a idade de sessenta anos, a tua avaliação será de cinquenta siclos de prata, segundo o siclo do santuário.'),
(3575, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 4, 'OT', 'E se for mulher, a tua avaliação será de trinta siclos.'),
(3576, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 5, 'OT', 'E, se for de cinco anos até vinte anos, a tua avaliação do macho será vinte siclos, e da fêmea, dez siclos.'),
(3577, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 6, 'OT', 'E se for de um mês até cinco anos de idade, a tua avaliação para o homem será de cinco siclos de prata, e para a mulher a tua avaliação será de três siclos de prata.'),
(3578, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 7, 'OT', 'E, se for de sessenta anos ou mais, sendo homem, a tua avaliação será de quinze siclos; e, sendo mulher, dez siclos.'),
(3579, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 8, 'OT', 'Mas, se for pobre demais para pagar a tua avaliação, apresentar-se-á diante do sacerdote, e o sacerdote o avaliará; conforme o que a mão do que fez o voto puder alcançar, o sacerdote o avaliará.'),
(3580, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 9, 'OT', 'E se for animal dos quais se oferece oferta ao SENHOR, tudo o que alguém der dele ao SENHOR será santo.'),
(3581, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 10, 'OT', 'Não o substituirá, nem o trocará, bom por mau, ou mau por bom; e se de fato trocar animal por animal, tanto ele como o seu substituto serão santos.'),
(3582, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 11, 'OT', 'E, se for algum animal impuro, dos quais não se oferece oferta ao SENHOR, então apresentará o animal diante do sacerdote.'),
(3583, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 12, 'OT', 'O sacerdote a avaliará, entre bom e mau; conforme a avaliação do sacerdote, assim será.'),
(3584, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 13, 'OT', 'E se ele de fato a resgatar, acrescentará um quinto sobre o seu valor.'),
(3585, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 14, 'OT', 'E se alguém santificar a sua casa como santa ao SENHOR, o sacerdote a avaliará, seja boa ou seja má; como o sacerdote a avaliar, assim será.'),
(3586, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 15, 'OT', 'Mas, se aquele que santificou resgatar a sua casa, acrescentará um quinto a mais do dinheiro da tua avaliação, e será sua.'),
(3587, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 16, 'OT', 'Se alguém consagrar ao SENHOR parte do campo da sua herança, a tua avaliação será conforme a sua semente: um hômer de semente de cevada por cinquenta siclos de prata.'),
(3588, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 17, 'OT', 'Se desde o ano do jubileu ele santificar o seu campo, conforme a tua avaliação permanecerá.'),
(3589, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 18, 'OT', 'Se, porém, santificar o seu campo depois do ano do jubileu, o sacerdote lhe calculará o dinheiro conforme os anos restantes até o ano do jubileu, e isso será deduzido da tua avaliação.'),
(3590, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 19, 'OT', 'E se aquele que santificou o campo o resgatar, acrescentará um quinto do dinheiro da tua avaliação sobre ele, e lhe ficará.'),
(3591, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 20, 'OT', 'E se não resgatar o campo, e se o vender a outro homem, não será mais resgatado.'),
(3592, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 21, 'OT', 'Mas o campo, ao sair no jubileu, será santo ao SENHOR, como campo consagrado; ao sacerdote pertencerá a sua possessão.'),
(3593, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 22, 'OT', 'E se santificar ao SENHOR o campo que comprou, que não é do campo da sua herança,'),
(3594, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 23, 'OT', 'O sacerdote calculará para ele o valor da tua avaliação até o ano do jubileu; e no mesmo dia dará a tua avaliação como santidade ao SENHOR.'),
(3595, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 24, 'OT', 'No ano do jubileu, o campo voltará àquele de quem o comprou, àquele cuja era a possessão da terra.'),
(3596, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 25, 'OT', 'Toda a tua avaliação será conforme o siclo do santuário; o siclo será de vinte geras.'),
(3597, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 26, 'OT', 'Todavia, o primogênito entre os animais, que já pertence ao SENHOR, ninguém o consagrará; seja boi ou ovelha, é do SENHOR.'),
(3598, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 27, 'OT', 'Se, porém, for de animal impuro, resgatar-se-á segundo a tua avaliação, e sobre ela acrescentará um quinto; e, se não for resgatado, será vendido segundo a tua avaliação.'),
(3599, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 28, 'OT', 'Todavia, nenhuma coisa consagrada que alguém consagrar ao SENHOR, de tudo o que tiver, seja homem, animal ou campo da sua possessão, não será vendida nem resgatada; toda coisa consagrada é santíssima ao SENHOR.'),
(3600, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 29, 'OT', 'Todo consagrado que for consagrado dentre os homens não será resgatado; certamente será morto.'),
(3601, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 30, 'OT', 'Todo dízimo da terra, tanto da semente da terra como do fruto das árvores, pertence ao SENHOR; é santo ao SENHOR.'),
(3602, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 31, 'OT', 'Se alguém resgatar algo do seu dízimo, acrescentará um quinto sobre ele.'),
(3603, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 32, 'OT', 'Todo dízimo de gado e de rebanho, tudo o que passar debaixo da vara, o décimo será santo ao SENHOR.'),
(3604, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 33, 'OT', 'Não examinará entre o bom e o mau, nem o trocará; mas, se de alguma forma o trocar, tanto ele como o seu substituto serão santos; não será resgatado.'),
(3605, 3, 'GOI_Pt', 'GOI_Pt', 'pt', 'LEV', 27, 34, 'OT', 'Estes são os mandamentos que o SENHOR ordenou a Moisés para os filhos de Israel, no monte Sinai.'),
(3606, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 1, 'OT', 'Falou o SENHOR a Moisés no deserto do Sinai, na tenda do encontro, no primeiro dia do segundo mês, no segundo ano da saída deles da terra do Egito, dizendo:'),
(3607, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 2, 'OT', 'Tomai o censo de toda a congregação dos filhos de Israel, segundo as suas famílias, segundo a casa de seus pais, no número dos nomes, todo homem, cabeça por cabeça.'),
(3608, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 3, 'OT', 'Da idade de vinte anos para cima, todo aquele que sai à guerra em Israel: a estes contareis segundo os seus exércitos, tu e Arão.'),
(3609, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 4, 'OT', 'E convosco estará um homem de cada tribo, cada um chefe da casa de seus pais.'),
(3610, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 5, 'OT', 'Estes são os nomes dos homens que estarão com vocês: de Rúben, Elizur, filho de Sedeur;'),
(3611, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 6, 'OT', 'De Simeão, Selumiel, filho de Zurisadai.'),
(3612, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 7, 'OT', 'De Judá, Naassom, filho de Aminadabe;'),
(3613, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 8, 'OT', 'De Issacar, Netanel, filho de Zuar.'),
(3614, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 9, 'OT', 'De Zebulom, Eliabe, filho de Helom.'),
(3615, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 10, 'OT', 'Dos filhos de José: de Efraim, Elisama, filho de Amiúde; de Manassés, Gamaliel, filho de Pedazur.'),
(3616, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 11, 'OT', 'De Benjamim, Abidã, filho de Gideoni.'),
(3617, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 12, 'OT', 'De Dã, Aiezer, filho de Amisadai.'),
(3618, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 13, 'OT', 'De Aser, Pagiel, filho de Ocrã.'),
(3619, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 14, 'OT', 'De Gade, Eliasafe, filho de Deuel.'),
(3620, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 15, 'OT', 'De Naftali, Aira, filho de Enã.'),
(3621, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 16, 'OT', 'Estes são os convocados da congregação, os líderes das tribos de seus pais, os chefes dos milhares de Israel.'),
(3622, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 17, 'OT', 'Então Moisés e Arão tomaram estes homens, que foram designados por nome.'),
(3623, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 18, 'OT', 'E reuniram toda a congregação no primeiro dia do segundo mês, e declararam a sua linhagem segundo as suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, cabeça por cabeça.'),
(3624, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 19, 'OT', 'Como o SENHOR ordenara a Moisés, assim os contou no deserto de Sinai.'),
(3625, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 20, 'OT', 'Os filhos de Rúben, primogênito de Israel, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, cabeça por cabeça, todo homem de vinte anos para cima, todos os que podiam sair à guerra.'),
(3626, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 21, 'OT', 'Os contados deles, da tribo de Rúben, eram quarenta e seis mil e quinhentos.'),
(3627, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 22, 'OT', 'Dos filhos de Simeão, as suas gerações, pelas suas famílias, segundo a casa de seus pais; os seus contados, pelo número dos nomes, cabeça por cabeça, todo o homem de vinte anos para cima, todo aquele que saía para a guerra.'),
(3628, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 23, 'OT', 'Os contados deles, da tribo de Simeão, eram cinquenta e nove mil e trezentos.'),
(3629, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 24, 'OT', 'Dos filhos de Gade, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3630, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 25, 'OT', 'Os contados deles, da tribo de Gade, quarenta e cinco mil e seiscentos e cinquenta.'),
(3631, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 26, 'OT', 'Dos filhos de Judá, as suas gerações, pelas suas famílias, segundo a casa de seus pais; pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3632, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 27, 'OT', 'Os contados deles, da tribo de Judá, eram setenta e quatro mil e seiscentos.'),
(3633, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 28, 'OT', 'Dos filhos de Issacar, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3634, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 29, 'OT', 'Os contados deles, da tribo de Issacar, eram cinquenta e quatro mil e quatrocentos.'),
(3635, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 30, 'OT', 'Dos filhos de Zebulom, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3636, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 31, 'OT', 'Os contados deles, da tribo de Zebulom, eram cinquenta e sete mil e quatrocentos.'),
(3637, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 32, 'OT', 'Dos filhos de José, dos filhos de Efraim, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3638, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 33, 'OT', 'Os contados deles, da tribo de Efraim, quarenta mil e quinhentos.'),
(3639, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 34, 'OT', 'Dos filhos de Manassés, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3640, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 35, 'OT', 'Os contados deles, da tribo de Manassés, trinta e dois mil e duzentos.'),
(3641, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 36, 'OT', 'Dos filhos de Benjamim, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3642, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 37, 'OT', 'Os contados deles, da tribo de Benjamim, trinta e cinco mil e quatrocentos.'),
(3643, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 38, 'OT', 'Dos filhos de Dã, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3644, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 39, 'OT', 'Os contados deles, da tribo de Dã, eram sessenta e dois mil e setecentos.'),
(3645, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 40, 'OT', 'Dos filhos de Aser, as suas gerações, pelas suas famílias, segundo a casa de seus pais, pelo número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3646, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 41, 'OT', 'Os contados deles, da tribo de Aser, quarenta e um mil e quinhentos.'),
(3647, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 42, 'OT', 'Os filhos de Naftali, as suas gerações, pelas suas famílias, segundo a casa de seus pais, no número dos nomes, de vinte anos para cima, todos os que saíam para a guerra.'),
(3648, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 43, 'OT', 'Os contados deles, da tribo de Naftali, eram cinquenta e três mil e quatrocentos.'),
(3649, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 44, 'OT', 'Estes foram os contados que Moisés e Arão contaram, com os líderes de Israel: doze homens, cada um representando a casa de seus pais.'),
(3650, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 45, 'OT', 'Todos os contados dos filhos de Israel, segundo a casa de seus pais, de vinte anos para cima, todos os que podiam sair à guerra em Israel.'),
(3651, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 46, 'OT', 'Todos os contados foram seiscentos e três mil e quinhentos e cinquenta.'),
(3652, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 47, 'OT', 'Mas os levitas, segundo a tribo de seus pais, não foram contados entre eles.'),
(3653, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 48, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3654, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 49, 'OT', 'Somente a tribo de Levi não contarás, nem tomarás o censo deles entre os filhos de Israel.'),
(3655, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 50, 'OT', 'Tu, porém, designa os levitas sobre o tabernáculo do testemunho, sobre todos os seus utensílios e sobre tudo o que lhe pertence; eles levarão o tabernáculo e todos os seus utensílios, e eles o servirão; e ao redor do tabernáculo acamparão.'),
(3656, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 51, 'OT', 'Quando o tabernáculo partir, os levitas o desarmarão; e quando o tabernáculo assentar, os levitas o armarão; e o estranho que se aproximar morrerá.'),
(3657, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 52, 'OT', 'E os filhos de Israel acamparão, cada um no seu acampamento, e cada um junto à sua bandeira, segundo os seus exércitos.'),
(3658, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 53, 'OT', 'Mas os levitas acamparão ao redor do tabernáculo do testemunho, para que não haja ira sobre a congregação dos filhos de Israel; e os levitas guardarão a guarda do tabernáculo do testemunho.'),
(3659, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 1, 54, 'OT', 'Os filhos de Israel fizeram conforme tudo o que o SENHOR ordenou a Moisés; assim o fizeram.'),
(3660, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 1, 'OT', 'Falou o SENHOR a Moisés e a Arão, dizendo:'),
(3661, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 2, 'OT', 'Os filhos de Israel acamparão, cada um junto à sua bandeira, segundo os sinais da casa de seus pais; ao redor, defronte da tenda do encontro, acamparão.'),
(3662, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 3, 'OT', 'Os que acampam ao oriente, para o nascente, serão a bandeira do exército de Judá, segundo os seus esquadrões; e o líder dos filhos de Judá é Naassom, filho de Aminadabe.'),
(3663, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 4, 'OT', 'E o seu exército, e os que foram contados deles, eram setenta e quatro mil e seiscentos.'),
(3664, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 5, 'OT', 'E os que se acamparem junto a ele serão da tribo de Issacar; e o líder dos filhos de Issacar será Natanael, filho de Zuar.'),
(3665, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 6, 'OT', 'E o seu exército, e os que foram contados deles, cinquenta e quatro mil e quatrocentos.'),
(3666, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 7, 'OT', 'A tribo de Zebulom; e o líder dos filhos de Zebulom será Eliabe, filho de Helom.'),
(3667, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 8, 'OT', 'E o seu exército, e os que foram contados deles, eram cinquenta e sete mil e quatrocentos.'),
(3668, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 9, 'OT', 'Todos os contados do acampamento de Judá: cento e oitenta e seis mil e quatrocentos, segundo os seus exércitos; estes marcharão primeiro.'),
(3669, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 10, 'OT', 'A bandeira do acampamento de Rúben estará para o sul, segundo as suas tropas; e o líder dos filhos de Rúben será Elizur, filho de Sedeur.'),
(3670, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 11, 'OT', 'E o seu exército, e os que foram contados deles, eram quarenta e seis mil e quinhentos.'),
(3671, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 12, 'OT', 'E os que acamparem junto a ele serão a tribo de Simeão; e o líder dos filhos de Simeão será Selumiel, filho de Zurisadai.'),
(3672, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 13, 'OT', 'E o seu exército, e os que foram contados deles, eram cinquenta e nove mil e trezentos.'),
(3673, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 14, 'OT', 'E a tribo de Gade; e Eliasafe, filho de Reuel, será o líder dos filhos de Gade.'),
(3674, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 15, 'OT', 'E o seu exército, e os que foram contados deles, quarenta e cinco mil e seiscentos e cinquenta.'),
(3675, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 16, 'OT', 'Todos os contados no acampamento de Rúben: cento e cinquenta e um mil e quatrocentos e cinquenta, segundo os seus exércitos; e estes marcharão em segundo lugar.'),
(3676, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 17, 'OT', 'Então partirá a tenda do encontro com o acampamento dos levitas no meio dos acampamentos; como acampam, assim partirão, cada um no seu lugar, segundo as suas bandeiras.'),
(3677, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 18, 'OT', 'A bandeira do acampamento de Efraim, segundo os seus exércitos, estará para o oeste; e o líder dos filhos de Efraim será Elisama, filho de Amiúde.'),
(3678, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 19, 'OT', 'E o seu exército, e os que foram contados deles, quarenta mil e quinhentos.'),
(3679, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 20, 'OT', 'Junto a ele estará a tribo de Manassés; e o líder dos filhos de Manassés será Gamaliel, filho de Pedazur.'),
(3680, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 21, 'OT', 'O seu exército, e os que foram contados deles, trinta e dois mil e duzentos.'),
(3681, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 22, 'OT', 'E a tribo de Benjamim; e o príncipe dos filhos de Benjamim, Abidã, filho de Gideoni.'),
(3682, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 23, 'OT', 'E o seu exército, e os que foram contados deles, eram trinta e cinco mil e quatrocentos.'),
(3683, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 24, 'OT', 'Todos os contados no acampamento de Efraim: cento e oito mil e cem, segundo os seus exércitos; e estes marcharão em terceiro lugar.'),
(3684, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 25, 'OT', 'A bandeira do acampamento de Dã estará ao norte, segundo os seus exércitos; e o líder dos filhos de Dã será Aiezer, filho de Amisadai.'),
(3685, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 26, 'OT', 'E o seu exército, e os que foram contados deles: sessenta e dois mil e setecentos.'),
(3686, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 27, 'OT', 'E os que acamparem junto a ele serão a tribo de Aser; e o príncipe dos filhos de Aser será Pagiel, filho de Ocrã.'),
(3687, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 28, 'OT', 'E o seu exército, e os que foram contados deles, quarenta e um mil e quinhentos.'),
(3688, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 29, 'OT', 'E a tribo de Naftali; e o líder dos filhos de Naftali será Aira, filho de Enã.'),
(3689, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 30, 'OT', 'E o seu exército, e os que foram contados deles, eram cinquenta e três mil e quatrocentos.'),
(3690, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 31, 'OT', 'Todos os contados do acampamento de Dã foram cento e cinquenta e sete mil e seiscentos; estes marcharão por último, segundo as suas bandeiras.'),
(3691, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 32, 'OT', 'Estes são os contados dos filhos de Israel, segundo a casa de seus pais: todos os contados dos exércitos, segundo as suas tropas, foram seiscentos e três mil e quinhentos e cinquenta.'),
(3692, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 33, 'OT', 'Os levitas, porém, não foram contados entre os filhos de Israel, conforme o SENHOR havia ordenado a Moisés.'),
(3693, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 2, 34, 'OT', 'E os filhos de Israel fizeram conforme tudo o que o SENHOR ordenou a Moisés; assim acamparam segundo as suas bandeiras, e assim partiram, cada um segundo as suas famílias, segundo a casa de seus pais.'),
(3694, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 1, 'OT', 'Estas são as gerações de Arão e de Moisés, no dia em que o SENHOR falou com Moisés no monte Sinai.'),
(3695, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 2, 'OT', 'Estes são os nomes dos filhos de Arão: o primogênito Nadabe; depois Abiú, Eleazar e Itamar.'),
(3696, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 3, 'OT', 'Estes são os nomes dos filhos de Arão, os sacerdotes ungidos, cujas mãos foram consagradas para oficiar como sacerdotes.'),
(3697, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 4, 'OT', 'Nadabe e Abiú morreram perante o SENHOR, quando ofereceram fogo estranho perante o SENHOR no deserto de Sinai, e não tiveram filhos; e Eleazar e Itamar ministraram como sacerdotes diante de Arão, seu pai.'),
(3698, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 5, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3699, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 6, 'OT', 'Faze aproximar a tribo de Levi e coloca-a diante de Arão, o sacerdote, para que o sirvam.'),
(3700, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 7, 'OT', 'E guardarão a sua guarda e a guarda de toda a congregação diante da tenda da congregação, para ministrar o serviço do tabernáculo.'),
(3701, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 8, 'OT', 'E guardarão todos os utensílios da tenda da congregação e a guarda dos filhos de Israel, para ministrar no serviço do tabernáculo.'),
(3702, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 9, 'OT', 'Entregarás os levitas a Arão e a seus filhos; dados, dados lhes são eles dentre os filhos de Israel.'),
(3703, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 10, 'OT', 'E nomearás Arão e seus filhos para que guardem o seu sacerdócio; e o estranho que se aproximar será morto.'),
(3704, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 11, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3705, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 12, 'OT', 'E eu, eis que tomei os levitas do meio dos filhos de Israel, em lugar de todo primogênito que abre o ventre entre os filhos de Israel; e os levitas serão meus.'),
(3706, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 13, 'OT', 'Porque todo primogênito é meu; no dia em que feri todo primogênito na terra do Egito, santifiquei para mim todo primogênito em Israel, desde homem até animal; meus serão. Eu sou o SENHOR.'),
(3707, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 14, 'OT', 'E o SENHOR falou a Moisés no deserto de Sinai, dizendo:'),
(3708, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 15, 'OT', 'Conta os filhos de Levi, segundo a casa de seus pais, pelas suas famílias; contarás todo homem da idade de um mês para cima.'),
(3709, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 16, 'OT', 'E Moisés os contou conforme a ordem do SENHOR, como lhe havia sido ordenado.'),
(3710, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 17, 'OT', 'Estes foram os filhos de Levi, pelos seus nomes: Gérson, Coate e Merari.'),
(3711, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 18, 'OT', 'Estes são os nomes dos filhos de Gérson, segundo as suas famílias: Libni e Simei.'),
(3712, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 19, 'OT', 'E os filhos de Coate, segundo as suas famílias: Anrão, Isar, Hebrom e Uziel.'),
(3713, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 20, 'OT', 'E os filhos de Merari, segundo as suas famílias: Mali e Musi; estas são as famílias dos levitas, segundo a casa de seus pais.'),
(3714, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 21, 'OT', 'De Gérson, a família dos libnitas e a família dos simeítas; estas são as famílias dos gersonitas.'),
(3715, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 22, 'OT', 'Os contados deles, segundo o número de todo homem, de um mês de idade para cima, os contados deles foram sete mil e quinhentos.'),
(3716, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 23, 'OT', 'As famílias dos gersonitas acamparão atrás do tabernáculo, ao ocidente.'),
(3717, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 24, 'OT', 'O líder da casa paterna dos gersonitas será Eliasafe, filho de Lael.'),
(3718, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 25, 'OT', 'A responsabilidade dos filhos de Gérson na tenda do encontro será o tabernáculo e a tenda, a sua cobertura, e o véu da entrada da tenda do encontro.'),
(3719, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 26, 'OT', 'E as cortinas do átrio, e o véu da porta do átrio, que está junto ao tabernáculo e junto ao altar, ao redor; e as suas cordas para todo o seu serviço.'),
(3720, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 27, 'OT', 'De Coate, a família dos anramitas, a família dos isaritas, a família dos hebronitas e a família dos uzielitas; estas são as famílias dos coatitas.'),
(3721, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 28, 'OT', 'Na contagem de todos os homens, de um mês de idade para cima, havia oito mil e seiscentos, que guardavam a guarda do santuário.'),
(3722, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 29, 'OT', 'As famílias dos filhos de Coate acamparão ao lado do tabernáculo, para o sul.'),
(3723, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 30, 'OT', 'E o líder da casa paterna das famílias dos coatitas era Elizafã, filho de Uziel.'),
(3724, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 31, 'OT', 'E o seu encargo será a arca, e a mesa, e o candelabro, e os altares, e os utensílios do santuário com que ministram, e o véu, com todo o seu serviço.'),
(3725, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 32, 'OT', 'E o líder dos líderes dos levitas será Eleazar, filho de Arão, o sacerdote; ele terá a supervisão dos que guardam a custódia do santuário.'),
(3726, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 33, 'OT', 'De Merari, a família dos maalitas e a família dos musitas; estas são as famílias de Merari.'),
(3727, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 34, 'OT', 'E os contados deles, pelo número de todo homem, de um mês de idade para cima, eram seis mil e duzentos.'),
(3728, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 35, 'OT', 'O líder da casa paterna das famílias de Merari era Zuriel, filho de Abiail; eles acampavam ao lado do tabernáculo, para o norte.'),
(3729, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 36, 'OT', 'E o encargo da guarda dos filhos de Merari: as tábuas do tabernáculo, e os seus travessões, e as suas colunas, e as suas bases, e todos os seus utensílios, e todo o seu serviço.'),
(3730, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 37, 'OT', 'E as colunas do pátio ao redor, e as suas bases, e as suas estacas, e as suas cordas.'),
(3731, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 38, 'OT', 'E os que acampam diante do tabernáculo, ao oriente, diante da tenda da congregação, para o nascente, são Moisés e Arão e seus filhos, guardando a guarda do santuário, para a guarda dos filhos de Israel; e o estranho que se aproximar morrerá.'),
(3732, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 39, 'OT', 'Todos os contados dos levitas, que Moisés e Arão contaram por ordem do SENHOR, segundo as suas famílias, todo homem de um mês para cima, foram vinte e dois mil.'),
(3733, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 40, 'OT', 'E disse o SENHOR a Moisés: Conta todo primogênito homem entre os filhos de Israel, de um mês de idade para cima, e toma o número dos seus nomes.'),
(3734, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 41, 'OT', 'E tomarás os levitas para mim, eu sou o SENHOR, em lugar de todo primogênito entre os filhos de Israel, e os animais dos levitas, em lugar de todo primogênito entre os animais dos filhos de Israel.'),
(3735, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 42, 'OT', 'E contou Moisés, como o SENHOR lhe ordenara, todos os primogênitos entre os filhos de Israel.'),
(3736, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 43, 'OT', 'Todos os primogênitos do sexo masculino, contados pelo número dos nomes, de um mês de idade para cima, segundo o seu censo, foram vinte e dois mil, duzentos e setenta e três.'),
(3737, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 44, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3738, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 45, 'OT', 'Toma os levitas em lugar de todo primogênito entre os filhos de Israel, e os animais dos levitas em lugar dos animais deles; e os levitas serão meus: eu sou o SENHOR.'),
(3739, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 46, 'OT', 'E os resgatados, os duzentos e setenta e três, que excedem os levitas, dentre os primogênitos dos filhos de Israel,'),
(3740, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 47, 'OT', 'Tomarás cinco siclos por cabeça; conforme o siclo do santuário os tomarás, a vinte geras o siclo.'),
(3741, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 48, 'OT', 'E darás o dinheiro a Arão e a seus filhos, como resgate dos que excedem entre eles.'),
(3742, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 49, 'OT', 'Moisés tomou o dinheiro do resgate dos que excediam os resgatados pelos levitas.'),
(3743, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 50, 'OT', 'Dos primogênitos dos filhos de Israel tomou o dinheiro: mil trezentos e sessenta e cinco siclos, segundo o siclo do santuário.'),
(3744, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 3, 51, 'OT', 'E Moisés deu o dinheiro dos resgatados a Arão e a seus filhos, segundo a ordem do SENHOR, como o SENHOR havia ordenado a Moisés.'),
(3745, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 1, 'OT', 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
(3746, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 2, 'OT', 'Toma o censo dos filhos de Coate, do meio dos filhos de Levi, segundo as suas famílias, pela casa de seus pais.'),
(3747, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 3, 'OT', 'Da idade de trinta anos para cima até aos cinquenta anos, todo aquele que entrar no serviço militar para fazer a obra na tenda da congregação.'),
(3748, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 4, 'OT', 'Este é o serviço dos filhos de Coate na tenda do encontro: o lugar santíssimo.'),
(3749, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 5, 'OT', 'Quando o acampamento partir, Arão e seus filhos virão e baixarão o véu da cortina, e com ele cobrirão a arca do testemunho.'),
(3750, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 6, 'OT', 'E porão sobre ele uma cobertura de couro de animais marinhos, e sobre ela estenderão um pano todo azul, e colocarão os seus varais.'),
(3751, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 7, 'OT', 'E sobre a mesa da proposição estenderão um pano azul, e sobre ela porão os pratos, as colheres, as tigelas e as taças para as libações; e o pão contínuo estará sobre ela.'),
(3752, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 8, 'OT', 'E sobre eles estenderão um pano de carmesim, e o cobrirão com a coberta de couro de animais marinhos, e colocarão os seus varais.'),
(3753, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 9, 'OT', 'Tomarão um pano azul e cobrirão o candelabro da luz, e as suas lâmpadas, e os seus espevitadores, e os seus apagadores, e todos os seus utensílios de azeite, com que o servem.'),
(3754, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 10, 'OT', 'E a porão, ela e todos os seus utensílios, numa cobertura de couro de animais marinhos, e a colocarão sobre o suporte.'),
(3755, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 11, 'OT', 'E sobre o altar de ouro estenderão um pano azul, e o cobrirão com uma coberta de couro fino, e colocarão os seus varais.'),
(3756, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 12, 'OT', 'Tomarão todos os utensílios do serviço com que ministram no santuário, e os porão sobre um pano azul, e os cobrirão com uma coberta de couro fino, e os porão sobre os varais.'),
(3757, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 13, 'OT', 'E removerão as cinzas do altar e estenderão sobre ele um pano de púrpura.'),
(3758, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 14, 'OT', 'E sobre ele porão todos os seus utensílios com que o servem: os braseiros, os garfos, as pás e as bacias, todos os utensílios do altar; e sobre ele estenderão uma coberta de couro de animais marinhos, e porão os seus varais.'),
(3759, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 15, 'OT', 'Quando Arão e seus filhos terminarem de cobrir o santuário e todos os utensílios sagrados, ao partir o acampamento, então os filhos de Coate virão para carregá-los, mas não tocarão nas coisas sagradas, para que não morram. Esta é a carga dos filhos de Coate na tenda do encontro.'),
(3760, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 16, 'OT', 'A responsabilidade de Eleazar, filho de Arão, o sacerdote, é o azeite da luz, o incenso aromático, a oferta contínua de cereais e o azeite da unção; a responsabilidade de todo o tabernáculo e de tudo o que nele há, no santuário e nos seus utensílios.'),
(3761, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 17, 'OT', 'E o SENHOR falou a Moisés e a Arão, dizendo:'),
(3762, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 18, 'OT', 'Não corteis a tribo das famílias dos coatitas do meio dos levitas.'),
(3763, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 19, 'OT', 'Fazei isto por eles, para que vivam e não morram, quando se aproximarem do Santo dos Santos: Arão e seus filhos entrarão e designarão cada um para o seu serviço e para a sua carga.'),
(3764, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 20, 'OT', 'Porém não entrarão para ver quando o santuário for coberto, para que não morram.'),
(3765, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 21, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3766, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 22, 'OT', 'Também conta os filhos de Gérson, segundo a casa de seus pais, segundo as suas famílias.'),
(3767, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 23, 'OT', 'Da idade de trinta anos para cima até cinquenta anos, contarás todos os que entram para o serviço militar, para fazer o trabalho no serviço da tenda da congregação.'),
(3768, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 24, 'OT', 'Este é o serviço das famílias dos gersonitas, para servir e para carregar.'),
(3769, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 25, 'OT', 'Levarão as cortinas do tabernáculo, e a tenda do encontro, a sua cobertura, e a cobertura de peles de animais marinhos que está sobre ela, por cima, e o véu da entrada da tenda do encontro.'),
(3770, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 26, 'OT', 'E as cortinas do pátio, e o véu da porta do portão do pátio, que está ao redor do tabernáculo e do altar, e as suas cordas, e todos os utensílios do seu serviço, e tudo o que for feito para eles, para que sirvam.'),
(3771, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 27, 'OT', 'Conforme a ordem de Arão e de seus filhos será todo o serviço dos filhos de Gérson, para toda a sua carga e para todo o seu trabalho; e lhes designareis em guarda toda a sua carga.'),
(3772, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 28, 'OT', 'Este é o serviço das famílias dos filhos dos gersonitas na tenda do encontro; e a sua guarda estará sob a direção de Itamar, filho de Arão, o sacerdote.'),
(3773, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 29, 'OT', 'Quanto aos filhos de Merari, segundo os seus clãs e segundo a casa de seus pais, os contarás.'),
(3774, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 30, 'OT', 'Da idade de trinta anos para cima até cinquenta anos, os contarás, todos os que entram no serviço militar, para fazer a obra da tenda da congregação.'),
(3775, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 31, 'OT', 'Esta é a responsabilidade do seu serviço, em todo o seu trabalho na tenda da congregação: as tábuas do tabernáculo, os seus travessões, as suas colunas e as suas bases.'),
(3776, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 32, 'OT', 'E as colunas do pátio ao redor, e as suas bases, e as suas estacas, e as suas cordas, com todos os seus utensílios e com todo o seu serviço; e por nome contareis os utensílios do encargo do seu transporte.'),
(3777, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 33, 'OT', 'Este é o serviço das famílias dos filhos de Merari, para todo o seu trabalho na tenda do encontro, sob a direção de Itamar, filho de Arão, o sacerdote.'),
(3778, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 34, 'OT', 'Moisés, Arão e os líderes da congregação contaram os filhos dos coatitas, segundo as suas famílias e segundo a casa de seus pais.'),
(3779, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 35, 'OT', 'Da idade de trinta anos para cima até os cinquenta anos, todo aquele que entrava no serviço, para trabalhar na tenda do encontro.'),
(3780, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 36, 'OT', 'Foram contados deles, segundo as suas famílias, dois mil setecentos e cinquenta.'),
(3781, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 37, 'OT', 'Estes são os contados das famílias dos coatitas, todos os que serviam na tenda do encontro, os quais Moisés e Arão contaram, conforme a ordem do SENHOR por meio de Moisés.'),
(3782, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 38, 'OT', 'Os contados dos filhos de Gérson, segundo as suas famílias e segundo a casa de seus pais,'),
(3783, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 39, 'OT', 'Dos trinta anos para cima até os cinquenta anos, todos os que entravam no serviço, para trabalhar na tenda do encontro.'),
(3784, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 40, 'OT', 'Os que foram contados deles, segundo as suas famílias, segundo a casa de seus pais, foram dois mil e seiscentos e trinta.'),
(3785, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 41, 'OT', 'Estes são os contados das famílias dos filhos de Gérson, todos os que serviam na tenda do encontro, os quais Moisés e Arão contaram, conforme a ordem do SENHOR.'),
(3786, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 42, 'OT', 'Os contados das famílias dos filhos de Merari, segundo as suas famílias, segundo a casa de seus pais.'),
(3787, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 43, 'OT', 'Dos trinta anos para cima até os cinquenta anos, todos os que entravam no serviço, para trabalhar na tenda do encontro.'),
(3788, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 44, 'OT', 'Foram os contados deles, segundo as suas famílias, três mil e duzentos.'),
(3789, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 45, 'OT', 'Estes são os contados das famílias dos filhos de Merari, os quais Moisés e Arão contaram, conforme o mandado do SENHOR, pela mão de Moisés.'),
(3790, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 46, 'OT', 'Todos os que foram contados, os quais Moisés e Arão e os líderes de Israel contaram dentre os levitas, segundo as suas famílias e segundo a casa de seus pais.'),
(3791, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 47, 'OT', 'Dos trinta anos para cima até os cinquenta anos, todos os que entravam para cumprir o serviço do ministério e o serviço de transporte na tenda do encontro.'),
(3792, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 48, 'OT', 'Foram oito mil quinhentos e oitenta os que foram contados entre eles.'),
(3793, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 4, 49, 'OT', 'Conforme a ordem do SENHOR, por meio de Moisés, foram contados, cada um segundo o seu serviço e segundo a sua carga; e foram contados, como o SENHOR havia ordenado a Moisés.'),
(3794, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 1, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3795, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 2, 'OT', 'Ordena aos filhos de Israel que expulsem do acampamento todo leproso, todo o que tem fluxo e todo aquele que está impuro por contato com um morto.'),
(3796, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 3, 'OT', 'Do homem até a mulher, vocês os enviarão para fora do acampamento; para fora do acampamento vocês os enviarão, para que não contaminem o acampamento deles, no meio do qual eu habito.'),
(3797, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 4, 'OT', 'E os filhos de Israel fizeram assim, e os enviaram para fora do acampamento; como o SENHOR falara a Moisés, assim fizeram os filhos de Israel.'),
(3798, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 5, 'OT', 'Falou o SENHOR a Moisés, dizendo:'),
(3799, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 6, 'OT', 'Fala aos filhos de Israel: Quando um homem ou uma mulher cometer qualquer dos pecados humanos, transgredindo contra o SENHOR, essa alma será culpada.'),
(3800, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 7, 'OT', 'Confessarão o pecado que cometeram, e o culpado restituirá o valor total da sua culpa, acrescentando-lhe um quinto, e o dará àquele contra quem foi culpado.'),
(3801, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 8, 'OT', 'Mas, se o homem não tiver parente resgatador a quem restituir a culpa, então a culpa restituída será do SENHOR, pertencente ao sacerdote, além do carneiro da expiação, com o qual fará expiação por ele.'),
(3802, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 9, 'OT', 'E toda oferta de todas as coisas santas dos filhos de Israel, que trouxerem ao sacerdote, será dele.'),
(3803, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 10, 'OT', 'E o homem terá as suas coisas santas; o que alguém der ao sacerdote, isso será dele.'),
(3804, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 11, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3805, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 12, 'OT', 'Fala aos filhos de Israel e dize-lhes: Se a mulher de alguém se desviar e cometer transgressão contra ele,'),
(3806, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 13, 'OT', 'E um homem se deitar com ela em relação sexual, e isso for oculto aos olhos de seu marido, e ela se ocultar, e ela estiver contaminada, e não houver testemunha contra ela, e ela não for apanhada em flagrante.'),
(3807, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 14, 'OT', 'E se um espírito de ciúmes vier sobre ele, e ele tiver ciúmes de sua mulher, e ela estiver contaminada; ou se um espírito de ciúmes vier sobre ele, e ele tiver ciúmes de sua mulher, e ela não estiver contaminada.'),
(3808, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 15, 'OT', 'Então o homem trará a sua mulher ao sacerdote e trará a sua oferta por ela: um décimo de efa de farinha de cevada, sobre a qual não derramará azeite, nem porá incenso sobre ela, porque é oferta de manjares de ciúmes, oferta memorial que traz a iniquidade à memória.'),
(3809, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 16, 'OT', 'O sacerdote a fará aproximar e a colocará diante do SENHOR.'),
(3810, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 17, 'OT', 'O sacerdote tomará água santa num vaso de barro; e do pó que houver no chão do tabernáculo, o sacerdote tomará e o colocará na água.'),
(3811, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 18, 'OT', 'O sacerdote apresentará a mulher diante do SENHOR, descobrirá a cabeça da mulher e porá sobre as mãos dela a oferta memorial, que é a oferta de ciúmes; e nas mãos do sacerdote estarão as águas amargas que trazem maldição.'),
(3812, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 19, 'OT', 'E o sacerdote fará que ela jure, e dirá à mulher: Se nenhum homem se deitou contigo, e se não te desviaste para a impureza, estando sob teu marido, sê livre destas águas amargas que trazem maldição.'),
(3813, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 20, 'OT', 'Mas, se tu te desviaste, estando sob teu marido, e te contaminaste, e um homem se deitou contigo, fora de teu marido,'),
(3814, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 21, 'OT', 'Então o sacerdote fará a mulher jurar com o juramento de maldição, e o sacerdote dirá à mulher: O SENHOR te faça maldição e juramento no meio do teu povo, fazendo o SENHOR cair a tua coxa e inchar o teu ventre.'),
(3815, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 22, 'OT', 'E estas águas amaldiçoantes entrarão nas tuas entranhas, para inchar o ventre e fazer cair a coxa. Então a mulher dirá: Amém, amém.'),
(3816, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 23, 'OT', 'O sacerdote escreverá estas maldições num livro e as apagará com a água amarga.'),
(3817, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 24, 'OT', 'E fará a mulher beber das águas amargas que trazem maldição, e as águas que trazem maldição entrarão nela para amargura.'),
(3818, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 25, 'OT', 'O sacerdote tomará da mão da mulher a oferta de cereais da ciúme, e a moverá perante o SENHOR; e a trará ao altar.'),
(3819, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 26, 'OT', 'O sacerdote tomará um punhado da oferta de cereais, da porção memorial, e a queimará sobre o altar; e depois dará a água à mulher para beber.'),
(3820, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 27, 'OT', 'E, havendo-lhe dado a água a beber, se ela tiver sido contaminada e tiver cometido transgressão contra seu marido, as águas amaldiçoantes entrarão nela para amargura, e seu ventre se inchará, e sua coxa se definhará; e essa mulher será por maldição no meio do seu povo.'),
(3821, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 28, 'OT', 'E, se a mulher não se tiver contaminado, mas estiver limpa, então será livre e conceberá descendência.'),
(3822, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 29, 'OT', 'Esta é a lei dos ciúmes, quando uma mulher se desviar, estando sob a autoridade de seu marido, e se contaminar.'),
(3823, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 30, 'OT', 'Ou quando um homem for tomado por um espírito de ciúmes e tiver ciúmes de sua mulher, apresente a mulher perante o SENHOR, e o sacerdote execute nela toda esta lei.'),
(3824, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 5, 31, 'OT', 'O homem será livre da iniquidade, e aquela mulher levará a sua iniquidade.'),
(3825, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 1, 'OT', 'E falou o SENHOR a Moisés, dizendo:'),
(3826, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 2, 'OT', 'Fala aos filhos de Israel e dize-lhes: Quando um homem ou uma mulher fizer voto especial de nazireu, para se consagrar ao SENHOR,'),
(3827, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 3, 'OT', 'De vinho e de bebida forte se absterá; não beberá vinagre de vinho nem vinagre de bebida forte; não beberá qualquer suco de uvas, nem comerá uvas frescas ou secas.'),
(3828, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 4, 'OT', 'Todos os dias do seu nazireado, de tudo o que se faz da videira, desde as sementes até as cascas, não comerá.'),
(3829, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 5, 'OT', 'Todos os dias do voto do seu nazireado, navalha não passará sobre a sua cabeça; até que se cumpram os dias em que se consagrou ao SENHOR, santo será, deixando crescer livremente o cabelo da sua cabeça.'),
(3830, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 6, 'OT', 'Todos os dias do seu nazireado para o SENHOR, não se aproximará de pessoa morta.'),
(3831, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 7, 'OT', 'Não se contaminará por seu pai ou por sua mãe, por seu irmão ou por sua irmã, quando eles morrerem, porque o nazireado do seu Deus está sobre a sua cabeça.'),
(3832, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 8, 'OT', 'Todos os dias do seu nazireado, ele é santo ao SENHOR.'),
(3833, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 9, 'OT', 'Se alguém morrer subitamente junto a ele, contaminando a cabeça do seu nazireado, ele rapará a cabeça no dia da sua purificação; no sétimo dia a rapará.'),
(3834, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 10, 'OT', 'E no oitavo dia, trará duas rolas ou dois pombinhos ao sacerdote, à entrada da tenda do encontro.'),
(3835, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 11, 'OT', 'E o sacerdote oferecerá um para a oferta pela culpa e outro para o holocausto, e fará expiação por ele, por causa do pecado que cometeu em relação ao morto; e santificará a sua cabeça naquele mesmo dia.'),
(3836, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 12, 'OT', 'Consagrará ao SENHOR os dias do seu nazireado e trará um cordeiro de um ano como oferta pela culpa; mas os dias anteriores serão perdidos, porque o seu nazireado foi contaminado.'),
(3837, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 13, 'OT', 'E esta é a lei do nazireu: no dia em que se cumprirem os dias do seu nazireado, ele será trazido à entrada da tenda do encontro.'),
(3838, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 14, 'OT', 'E oferecerá a sua oferta ao SENHOR: um cordeiro de um ano, sem defeito, para holocausto; e uma cordeira de um ano, sem defeito, para oferta pela culpa; e um carneiro sem defeito para oferta pacífica.'),
(3839, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 15, 'OT', 'E um cesto de pães sem fermento, bolos de flor de farinha amassados com azeite, e pães finos sem fermento untados com azeite, juntamente com a sua oferta de cereais e as suas libações.'),
(3840, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 16, 'OT', 'O sacerdote os apresentará diante do SENHOR e oferecerá a sua oferta pelo pecado e o seu holocausto.'),
(3841, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 17, 'OT', 'E o carneiro ele oferecerá como sacrifício pacífico ao SENHOR, juntamente com o cesto dos pães sem fermento; e o sacerdote apresentará a sua oferta de cereais e a sua libação.'),
(3842, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 18, 'OT', 'O nazireu rapará a cabeça do seu nazireado à entrada da tenda do encontro, e tomará o cabelo da cabeça do seu nazireado e o colocará sobre o fogo que está debaixo do sacrifício de paz.'),
(3843, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 19, 'OT', 'O sacerdote tomará a coxa cozida do carneiro, um pão sem fermento do cesto e um pão fino sem fermento, e os colocará nas mãos do nazireu, depois de ele ter rapado a sua cabeça consagrada.'),
(3844, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 20, 'OT', 'E o sacerdote os moverá como oferta movida perante o SENHOR; isto é santo para o sacerdote, juntamente com o peito da oferta movida e com a coxa da oferta alçada; e depois o nazireu beberá vinho.'),
(3845, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 21, 'OT', 'Esta é a lei do nazireu que fizer voto: a sua oferta ao SENHOR pelo seu nazireado, além do que a sua mão puder alcançar; segundo o voto que fizer, assim fará, conforme a lei do seu nazireado.'),
(3846, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 22, 'OT', 'E o SENHOR falou a Moisés, dizendo:'),
(3847, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 23, 'OT', 'Fala a Arão e a seus filhos, dizendo: Assim abençoareis os filhos de Israel, dizendo-lhes:'),
(3848, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 24, 'OT', 'O SENHOR te abençoe e te guarde.'),
(3849, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 25, 'OT', 'O SENHOR faça resplandecer o seu rosto sobre ti e tenha misericórdia de ti.'),
(3850, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 26, 'OT', 'O SENHOR levante sobre ti o seu rosto e te dê paz.'),
(3851, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 6, 27, 'OT', 'E porão o meu nome sobre os filhos de Israel, e eu os abençoarei.'),
(3852, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 1, 'OT', 'E aconteceu que, no dia em que Moisés acabou de levantar o tabernáculo, ungiu-o e o santificou, e todos os seus utensílios, e o altar e todos os seus utensílios; e os ungiu e os santificou.'),
(3853, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 2, 'OT', 'Os líderes de Israel, os chefes das casas de seus pais, os príncipes das tribos, que estavam sobre os recenseados, trouxeram ofertas.'),
(3854, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 3, 'OT', 'E trouxeram a sua oferta perante o SENHOR: seis carros cobertos e doze bois; um carro para cada dois líderes e um boi para cada um; e os apresentaram diante do tabernáculo.'),
(3855, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 4, 'OT', 'E disse o SENHOR a Moisés, dizendo:'),
(3856, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 5, 'OT', 'Toma-os deles, e serão para servir no serviço da tenda da congregação; e os darás aos levitas, a cada um conforme o seu serviço.'),
(3857, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 6, 'OT', 'Moisés tomou os carros e os bois, e os deu aos levitas.'),
(3858, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 7, 'OT', 'Dois carros e quatro bois deu aos filhos de Gérson, conforme o seu serviço.'),
(3859, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 8, 'OT', 'E quatro carroças e oito bois deu aos filhos de Merari, conforme o seu serviço, sob a direção de Itamar, filho de Arão, o sacerdote.'),
(3860, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 9, 'OT', 'Mas aos filhos de Coate nada deu, porque o serviço do santuário estava sobre eles; nos ombros o levariam.'),
(3861, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 10, 'OT', 'E os líderes trouxeram a oferta de dedicação do altar no dia em que ele foi ungido; e os líderes apresentaram a sua oferta diante do altar.'),
(3862, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 11, 'OT', 'Disse o SENHOR a Moisés: Cada líder trará a sua oferta, um por dia, para a dedicação do altar.'),
(3863, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 12, 'OT', 'E aquele que apresentou a sua oferta no primeiro dia foi Naassom, filho de Aminadabe, da tribo de Judá.'),
(3864, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 13, 'OT', 'E a sua oferta foi uma prata, de cento e trinta siclos o seu peso, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de manjares.'),
(3865, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 14, 'OT', 'Uma colher de dez siclos de ouro, cheia de incenso.'),
(3866, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 15, 'OT', 'Um novilho, um carneiro, um cordeiro de um ano, para holocausto;'),
(3867, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 16, 'OT', 'Um bode para oferta pela culpa.'),
(3868, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 17, 'OT', 'E para o sacrifício pacífico: dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Naassom, filho de Aminadabe.'),
(3869, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 18, 'OT', 'No segundo dia, ofereceu Netanel, filho de Zuar, líder de Issacar.'),
(3870, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 19, 'OT', 'Ele apresentou a sua oferta: uma bandeja de prata de cento e trinta siclos, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambas cheias de flor de farinha amassada com azeite, para a oferta de cereais.'),
(3871, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 20, 'OT', 'Uma colher de dez siclos de ouro, cheia de incenso.'),
(3872, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 21, 'OT', 'Um novilho, um carneiro, um cordeiro de um ano, para holocausto;'),
(3873, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 22, 'OT', 'Um bode para oferta pela culpa.'),
(3874, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 23, 'OT', 'E para o sacrifício de paz, dois bois, cinco carneiros, cinco bodes, cinco cordeiros de um ano; esta foi a oferta de Netanel, filho de Zuar.'),
(3875, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 24, 'OT', 'No terceiro dia, o líder dos filhos de Zebulom, Eliabe, filho de Helom.'),
(3876, 4, 'GOI_Pt', 'GOI_Pt', 'pt', 'NUM', 7, 25, 'OT', 'A sua oferta foi uma bandeja de prata, de cento e trinta siclos de peso, uma bacia de prata de setenta siclos, segundo o siclo do santuário; ambos cheios de flor de farinha amassada com azeite, para oferta de manjares.'),
